  `organization` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '주관 기관 (Grammy, Chopin Institute 등)',
  `category` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '수상 부문 (Best Classical Instrumental Solo 등)',
  `ranking` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '순위 정보 (1st Prize, Gold Medal, Winner 등)',
  `source` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'Manual Entry' COMMENT '데이터 출처 (MusicBrainz, Manual Entry 등)',
  `notes` text COLLATE utf8mb4_unicode_ci COMMENT '추가 정보',
  `display_order` int DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_artist_id` (`artist_id`),
  KEY `idx_year` (`year`),
  KEY `idx_award_type` (`award_type`),
  CONSTRAINT `artist_awards_ibfk_1` FOREIGN KEY (`artist_id`) REFERENCES `artists` (`id`) ON DELETE CASCADE
