--
-- Table structure for table `artists`
--

DROP TABLE IF EXISTS `artists`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `artists` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '한글명',
  `english_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '영문명',
  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '악기/분야 (피아니스트, 바이올리니스트 등)',
  `tier` enum('S','A','B','Rising') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'B' COMMENT '티어',
  `rating` decimal(2,1) DEFAULT '0.0' COMMENT '평점 (0.0-5.0)',
  `image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '프로필 이미지 URL',
  `cover_image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '커버 이미지 URL',
  `birth_year` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '출생연도',
  `nationality` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '국적',
  `bio` text COLLATE utf8mb4_unicode_ci COMMENT '소개',
  `style` text COLLATE utf8mb4_unicode_ci COMMENT '연주 스타일',
  `concert_count` int DEFAULT '0' COMMENT '공연 횟수',
  `album_count` int DEFAULT '0' COMMENT '음반 수',
  `top_award_id` int DEFAULT NULL COMMENT '대표 수상 ID',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_category` (`category`),
  KEY `idx_tier` (`tier`),
  KEY `idx_rating` (`rating`),
  KEY `idx_top_award` (`top_award_id`)
) ENGINE=InnoDB AUTO_INCREMENT=370 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `artists`
--

LOCK TABLES `artists` WRITE;
/*!40000 ALTER TABLE `artists` DISABLE KEYS */;
INSERT INTO `artists` VALUES (186,'조성진','Seong-Jin Cho','pianist','S',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/fc/aa/00/fcaa0080-195c-188c-714e-547b50491062/pr_source.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/fc/aa/00/fcaa0080-195c-188c-714e-547b50491062/pr_source.png/1200x1200bb.jpg','1994','South Korea','조성진은 1994년 서울 출신의 피아니스트이다.\n\n2015년 제17회 쇼팽 국제 피아노 콩쿠르에서 한국인 최초로 우승하며 세계적인 명성을 얻었다. 파리 국립 고등음악원에서 미셸 베로프 교수에게 사사했으며, 이전에는 한국예술종합학교에서 박진영 교수 밑에서 공부했다.\n\n2011년 차이콥스키 국제 콩쿠르 3위, 2012년 루빈스타인 국제 피아노 콩쿠르 3위를 거쳐 2015년 쇼팽 콩쿠르 우승으로 정점에 올랐다. 도이치 그라모폰(DG)과 전속 계약을 맺고 쇼팽, 드뷔시, 라벨, 라흐마니노프 등의 앨범을 발매했다.\n\n베를린 필하모닉, 런던 심포니, 빈 필하모닉 등 세계 정상급 오케스트라와 협연하며, 카네기홀, 베를린 필하모니, 빈 무지크페라인 등 주요 콘서트홀에서 리사이틀을 개최하고 있다. 현재 전 세계를 무대로 왕성한 연주 활동을 이어가고 있다.','섬세한 터치와 시적인 서정성을 바탕으로 한 자연스러운 프레이징이 특징이며, 과장 없이 음악 그 자체를 표현하는 절제된 연주 스타일을 추구한다.',100,8,NULL,'2025-11-20 05:35:45','2025-11-20 10:24:16'),(187,'임윤찬','Yunchan Lim','pianist','S',0.0,'https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages211/v4/db/62/5f/db625fc4-b4ea-9c5d-f84b-959c70224ef2/ami-identity-e67360b56d693689824ce48374539a0c-2025-10-22T09-46-12.410Z_cropped.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages211/v4/db/62/5f/db625fc4-b4ea-9c5d-f84b-959c70224ef2/ami-identity-e67360b56d693689824ce48374539a0c-2025-10-22T09-46-12.410Z_cropped.png/1200x1200bb.jpg','2004','South Korea','임윤찬은 2004년 경기도 시흥 출신의 피아니스트이다.\n\n2022년 제16회 반 클라이번 국제 피아노 콩쿠르에서 18세의 나이로 최연소 우승을 차지하며 전 세계의 주목을 받았다. 한국예술종합학교 재학 중 우승했으며, 손민수 교수에게 사사했다.\n\n2021년 이사이 국제 피아노 콩쿠르 세미파이널 진출을 거쳐, 2022년 반 클라이번 콩쿠르에서 라흐마니노프 피아노 협주곡 3번과 베토벤 소나타로 심사위원들과 청중을 사로잡았다. 우승 후 즉시 카네기홀, 링컨센터, 베를린 필하모니 등에서 연주했다.\n\n2024년 도이치 그라모폰(DG)과 전속 계약을 맺었으며, 첫 앨범으로 쇼팽과 리스트 작품을 녹음했다. 필라델피아 오케스트라, 로스앤젤레스 필하모닉, 런던 심포니 등과 협연하며, 2024-2025 시즌에는 유럽과 미국 주요 도시에서 리사이틀 투어를 진행했다. 현재 클래식 음악계에서 가장 주목받는 젊은 피아니스트로 평가받고 있다.','압도적인 테크닉과 깊이 있는 음악적 성숙도를 동시에 보여주며, 특히 러시아 낭만파 레퍼토리에서 웅장하면서도 섬세한 표현력을 발휘한다.',100,2,NULL,'2025-11-20 05:35:45','2025-11-20 10:24:17'),(188,'김선욱','Sunwook Kim','pianist','A',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Music116/v4/d3/6d/7c/d36d7c49-f4cc-08bd-da7f-9cd29d7a8e1c/f458246f-ef1a-4229-b32d-2138492efde1.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music116/v4/d3/6d/7c/d36d7c49-f4cc-08bd-da7f-9cd29d7a8e1c/f458246f-ef1a-4229-b32d-2138492efde1.png/1200x1200bb.jpg','1988','South Korea','김선욱은 1988년 서울 출신의 피아니스트이다.\n\n2006년 제14회 리즈 국제 피아노 콩쿠르에서 18세의 나이로 우승하며 국제 무대에 데뷔했다. 한국예술종합학교를 졸업했으며, 이후 파리 국립 고등음악원에서 미셸 베로프와 파스칼 드바이용에게 사사했다.\n\n리즈 콩쿠르 우승 이후 런던 심포니, 필하모니아 오케스트라, BBC 필하모닉 등과 정기적으로 협연하며 유럽 무대에서 입지를 굳혔다. 베토벤 소나타 전곡 사이클 프로젝트를 완성했으며, 브람스, 슈베르트, 슈만 등 독일 낭만파 레퍼토리에서 높은 평가를 받고 있다.\n\nEMI 클래식스와 Onyx Classics에서 다수의 앨범을 발매했다. 서울시향, KBS교향악단 등 국내 주요 오케스트라와도 활발히 협연하며, 유럽과 아시아를 중심으로 연주 활동을 이어가고 있다. 현재 한국예술종합학교 교수로도 후학 양성에 힘쓰고 있다.','지적이고 구조적인 접근과 따뜻한 음색을 결합하며, 특히 독일 고전-낭만파 레퍼토리에서 탁월한 균형감과 깊이를 보여준다.',100,10,NULL,'2025-11-20 05:35:45','2025-11-20 10:24:18'),(189,'손열음','Yeol Eum Son','pianist','A',0.0,'https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages211/v4/7e/bf/79/7ebf79f3-fdde-465f-e0a1-5b164a9523c1/file_cropped.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages211/v4/7e/bf/79/7ebf79f3-fdde-465f-e0a1-5b164a9523c1/file_cropped.png/1200x1200bb.jpg','1986','South Korea','손열음은 1986년 강릉 출신의 피아니스트이다.\n\n2011년 제13회 반 클라이번 국제 피아노 콩쿠르에서 은상을 수상했으며, 2004년 에트링겐 국제 콩쿠르에서 우승한 경력이 있다. 한국예술종합학교를 졸업했으며, 텔아비브에서 아리에 바르디에게 사사했다.\n\n반 클라이번 콩쿠르에서 베토벤, 프로코피예프 협주곡으로 호평을 받았으며, 이후 EMI 클래식스(현 Warner Classics)와 전속 계약을 맺었다. 베토벤, 리스트, 라흐마니노프부터 현대음악까지 폭넓은 레퍼토리를 소화하며, 특히 프랑스 인상주의 작품과 현대 레퍼토리에서 독보적인 해석을 선보인다.\n\n뉴욕 필하모닉, 시카고 심포니, 런던 필하모닉 등과 협연했으며, 서울시향 상주음악가로 활동하며 국내 청중과도 긴밀한 소통을 이어가고 있다. 다수의 음반을 발매했으며, 국내외에서 왕성한 연주 활동을 펼치고 있다.','명료한 터치와 논리적인 구조감을 바탕으로 하되, 감성적 표현도 놓치지 않는 균형 잡힌 연주를 선보이며, 현대 레퍼토리에서도 뛰어난 해석력을 발휘한다.',100,15,NULL,'2025-11-20 05:35:45','2025-11-20 10:24:19'),(190,'김봄소리','Bomsori Kim','violinist','A',0.0,'https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages221/v4/d5/35/75/d5357544-57df-21e1-32d7-acba1b66e936/file_cropped.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages221/v4/d5/35/75/d5357544-57df-21e1-32d7-acba1b66e936/file_cropped.png/1200x1200bb.jpg','1989','South Korea','김봄소리는 1989년 서울 출신의 바이올리니스트이다.\n\n2016년 ARD 국제 음악 콩쿠르 바이올린 부문에서 우승했으며, 2010년 퀸 엘리자베스 콩쿠르에서 3위에 입상한 경력이 있다. 한국예술종합학교에서 김남윤 교수에게 사사했으며, 줄리어드 음악원에서 도로시 딜레이와 조셉 린에게 배웠다.\n\n1774년산 과르네리 델 제수를 연주하며, Warner Classics와 전속 계약을 맺고 있다. 차이콥스키, 브람스, 시벨리우스 바이올린 협주곡 등 낭만파 대곡에서 탁월한 해석을 보여주며, 런던 필하모닉, 도이치 심포니 베를린, NHK 교향악단 등과 협연했다.\n\n2017년 금호아트홀 상주음악가로 활동했으며, 국내외 주요 콘서트홀에서 리사이틀을 개최하고 있다. 실내악에도 적극적으로 참여하며, 다양한 음악가들과 협업하고 있다. 현재 유럽과 아시아를 중심으로 활발한 연주 활동을 이어가고 있다.','풍부한 음색과 서정적 표현력이 돋보이며, 특히 낭만파 작품에서 감성적이면서도 기교적으로 완벽한 연주를 들려준다.',100,7,NULL,'2025-11-20 05:35:45','2025-11-20 10:24:20'),(191,'강주미','Clara-Jumi Kang','violinist','A',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Music124/v4/21/78/f8/2178f8de-fbfc-7da0-bb8d-81b59c7f22d6/00028948147748.rgb.jpg/600x600ac.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music124/v4/21/78/f8/2178f8de-fbfc-7da0-bb8d-81b59c7f22d6/00028948147748.rgb.jpg/1200x1200ac.jpg','1987','South Korea','강주미(Clara-Jumi Kang)는 1987년 만하임 출신의 한국계 독일 바이올리니스트이다.\n\n2010년 인디애나폴리스 국제 바이올린 콩쿠르와 뮌헨 ARD 국제 음악 콩쿠르에서 모두 우승하며 세계적인 주목을 받았다. 만하임 음악대학에서 발레리 그라돈프에게 사사했으며, 줄리어드에서도 수학했다.\n\n1710년산 스트라디바리우스를 연주하며, Sony Classical과 전속 계약을 맺고 있다. 브람스, 베르크, 브루흐, 시벨리우스 등의 바이올린 협주곡 앨범을 발매했으며, 특히 독일 레퍼토리에서 깊이 있는 해석을 선보인다.\n\n베를린 필하모닉, 빈 필하모닉, 로열 콘세르트헤바우 등 세계 정상급 오케스트라와 정기적으로 협연하며, 유럽을 기반으로 활동하고 있다. 실내악 연주자로도 활발히 활동하며, 다양한 음악 페스티벌에 참여하고 있다.','강렬한 음악적 집중력과 정확한 테크닉을 바탕으로 현대적이면서도 깊이 있는 해석을 제시하며, 독일 음악 전통에 충실한 연주를 들려준다.',100,8,NULL,'2025-11-20 05:35:45','2025-11-20 10:24:21'),(192,'양인모','Inmo Yang','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/5b/6b/24/5b6b2477-6b64-7b4c-915c-6ac027da747a/mza_8683291312390011394.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/5b/6b/24/5b6b2477-6b64-7b4c-915c-6ac027da747a/mza_8683291312390011394.png/1200x1200bb.jpg','1986','South Korea','양인모는 1986년 출생의 한국 피아니스트이다.\n\n한국예술종합학교를 졸업했으며, 독일 하노버 음악대학에서 아리에 바르디 교수에게 사사했다. 국내 주요 콩쿠르에서 입상한 경력이 있으며, 베토벤, 슈베르트, 브람스 등 독일 고전-낭만파 레퍼토리를 중심으로 활동하고 있다.\n\n예술의전당, 롯데콘서트홀 등 국내 주요 콘서트홀에서 리사이틀을 개최했으며, 국내 오케스트라와 협연 경험을 쌓아가고 있다. 실내악 활동에도 적극적이며, 다양한 연주자들과 협업하고 있다. 진지하고 성실한 접근으로 작품의 본질을 탐구하는 연주자로 평가받고 있다.','진지하고 성실한 접근으로 작품의 본질을 탐구하며, 특히 독일 고전파 레퍼토리에서 안정적인 연주를 선보인다.',50,2,NULL,'2025-11-20 05:35:45','2025-11-28 16:39:59'),(193,'김대진','Daejin Kim','pianist','B',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music/f4/da/7a/mzi.mamsneyt.jpg/600x600ac.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music/f4/da/7a/mzi.mamsneyt.jpg/1200x1200ac.jpg','1954','South Korea','김대진은 1954년 출생의 한국 피아니스트이자 교육자이다.\n\n서울대학교와 줄리어드 음악원을 졸업했으며, 한국예술종합학교 음악원 교수로 재직하며 한국 클래식 음악 교육의 중추적 역할을 담당하고 있다. 손열음, 조성진, 김선욱, 문지영 등 세계적인 피아니스트들을 배출한 것으로 유명하다.\n\n연주자로서도 꾸준히 활동하며, 국내 주요 오케스트라와 협연하고 리사이틀을 개최하고 있다. 베토벤, 슈베르트, 브람스 등 정통 클래식 레퍼토리를 중심으로 연주하며, 특히 실내악 활동에도 적극적이다.\n\n한국 클래식 음악계의 발전에 크게 기여했으며, 후학 양성을 통해 한국 피아니스트들의 세계 진출에 중요한 역할을 하고 있다. 현재도 한국예술종합학교에서 교육 활동을 이어가고 있다.','정통 클래식 해석을 중시하며, 교육자로서의 경험이 반영된 명료하고 교훈적인 연주를 들려준다.',100,5,NULL,'2025-11-20 05:35:45','2025-11-20 10:24:24'),(194,'권형준','Hyungjun Kwon','pianist','Rising',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music211/v4/77/9e/ce/779ecea7-f149-c6a1-d001-5a048c3157a7/703.jpg/600x600ac.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music211/v4/77/9e/ce/779ecea7-f149-c6a1-d001-5a048c3157a7/703.jpg/1200x1200ac.jpg','1989','South Korea','권형준은 1989년 출생의 한국 피아니스트이다.\n\n한국예술종합학교를 졸업했으며, 국내 주요 음악 콩쿠르에서 입상한 경력이 있다. 다양한 시대의 레퍼토리를 소화하며 독주와 협주, 실내악 활동을 병행하고 있다.\n\n국내 주요 콘서트홀에서 리사이틀을 개최하며 연주 경험을 쌓아가고 있으며, 국내 오케스트라와의 협연도 점차 늘려가고 있다. 젊은 세대 피아니스트로서 꾸준히 성장하고 있으며, 다양한 음악 활동을 통해 자신만의 음악 세계를 구축해가고 있다.','진지한 태도로 작품에 접근하며, 안정적인 테크닉을 바탕으로 꾸준히 음악적 깊이를 더해가고 있다.',30,1,NULL,'2025-11-20 05:35:45','2025-11-20 10:24:25'),(195,'대니구','Danny Koo','pianist','Rising',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music126/v4/f5/9f/12/f59f1274-7ff3-1838-2ed7-94e2c3c73079/1f020646-9a9a-4b96-b83d-365066dc7b40.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music126/v4/f5/9f/12/f59f1274-7ff3-1838-2ed7-94e2c3c73079/1f020646-9a9a-4b96-b83d-365066dc7b40.png/1200x1200bb.jpg','1997','South Korea','대니구(Danny Koo)는 1997년 출생의 미국계 한국 피아니스트이다.\n\n줄리어드 음악원을 졸업했으며, 미국과 한국을 오가며 양국에서 연주 활동을 하고 있다. 국제 콩쿠르 입상 경력이 있으며, 클래식부터 현대음악까지 폭넓은 레퍼토리를 선보인다.\n\n젊은 감각의 연주와 SNS를 통한 적극적인 소통으로 젊은 세대 청중들에게 클래식 음악을 알리는 데 기여하고 있다. 미국과 한국의 주요 콘서트홀에서 리사이틀을 개최하며, 다양한 협연 기회를 통해 경력을 쌓아가고 있다.','현대적 감각과 탄탄한 기교를 결합하며, 젊은 세대의 신선한 시각으로 레퍼토리에 접근한다.',40,2,NULL,'2025-11-20 05:35:45','2025-11-20 10:24:26'),(196,'임동혁','Dong-Hyek Lim','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features125/v4/ca/21/47/ca214709-b55a-3adc-a5b1-209b186bff0c/mzl.ugmzexsw.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features125/v4/ca/21/47/ca214709-b55a-3adc-a5b1-209b186bff0c/mzl.ugmzexsw.jpg/1200x1200bb.jpg','1984','South Korea','임동혁은 1984년 서울 출생의 피아니스트이다.\n\n2001년 제14회 리즈 국제 피아노 콩쿠르에서 17세의 나이로 3위에 입상하며 국제 무대에 데뷔했다. 한국예술종합학교를 졸업했으며, 파리 국립 고등음악원에서 미셸 베로프 교수에게 사사했다.\n\n쇼팽, 리스트, 라흐마니노프 등 낭만파 레퍼토리에 강점을 보이며, 화려한 기교와 열정적인 해석으로 평가받고 있다. 런던 필하모닉, 로열 필하모닉, NHK 교향악단 등과 협연했으며, 국내외 주요 콘서트홀에서 리사이틀을 개최하고 있다.\n\n다수의 음반을 발매했으며, 국내에서는 KBS교향악단, 서울시향 등과 정기적으로 협연하고 있다. 현재 한국과 유럽을 중심으로 활발한 연주 활동을 이어가고 있다.','화려한 테크닉과 감성적 표현의 균형을 이루며, 특히 낭만파 작품에서 열정적이면서도 세련된 연주를 들려준다.',100,12,NULL,'2025-11-20 05:35:45','2025-11-20 10:24:27'),(197,'임동민','Dong-Min Lim','pianist','Rising',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music116/v4/86/54/16/865416d6-3fb9-5330-0d9b-191816711147/2bc9d5a5-0c2e-40a8-ab19-4db119782360.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music116/v4/86/54/16/865416d6-3fb9-5330-0d9b-191816711147/2bc9d5a5-0c2e-40a8-ab19-4db119782360.png/1200x1200bb.jpg','1980','South Korea','임동민은 1980년 출생의 한국 피아니스트이다.\n\n독일에서 유학하며 피아노를 전공했으며, 독주 활동 외에도 반주와 실내악 분야에서 활발히 활동하고 있다. 국내 주요 콘서트홀에서 연주하며, 다양한 음악가들과 협업하고 있다.\n\n특히 가곡 반주와 실내악 연주자로서 명성이 있으며, 국내 주요 성악가 및 기악 연주자들과 함께 무대에 서고 있다. 교육 활동도 병행하며 후학 양성에도 힘쓰고 있으며, 협업 능력이 뛰어난 연주자로 평가받고 있다.','섬세한 음악성과 협업 능력이 뛰어나며, 특히 실내악에서 조화로운 앙상블을 만들어낸다.',60,4,NULL,'2025-11-20 05:35:45','2025-11-20 10:24:28'),(198,'임효선','Hyo-Sun Lim','soprano','B',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Music118/v4/d6/3e/2f/d63e2f66-6d7c-2aa5-aafe-32b2542358b1/00028948176052.rgb.jpg/600x600ac.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music118/v4/d6/3e/2f/d63e2f66-6d7c-2aa5-aafe-32b2542358b1/00028948176052.rgb.jpg/1200x1200ac.jpg','1980','South Korea','임효선은 1980년 출생의 한국 소프라노이다.\n\n이탈리아에서 성악을 공부했으며, 유럽 오페라 무대에서 경력을 쌓았다. 주로 이탈리아 벨칸토 오페라 레퍼토리를 부르며, 로시니, 도니체티, 벨리니 작품에서 활동하고 있다.\n\n유럽의 중소 오페라 하우스에서 공연 경험을 쌓았으며, 국내에서도 리사이틀과 오페라 공연을 통해 활동하고 있다. 맑고 청아한 음색으로 벨칸토 레퍼토리에 적합한 연주를 선보이며, 국내외를 오가며 연주 활동을 이어가고 있다.','맑고 청아한 음색과 정확한 발성으로 이탈리아 벨칸토 작품에 적합한 연주를 들려준다.',50,3,NULL,'2025-11-20 05:35:45','2025-11-20 10:26:40'),(199,'조수미','Sumi Jo','soprano','A',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Music116/v4/13/26/54/1326542f-30f8-38d8-7b36-62ea161552ac/b7031400-19aa-4ed6-86f9-960857df761a.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music116/v4/13/26/54/1326542f-30f8-38d8-7b36-62ea161552ac/b7031400-19aa-4ed6-86f9-960857df761a.png/1200x1200bb.jpg','1962','South Korea','조수미는 1962년 창원 출생의 소프라노이다.\n\n로마 산타 체칠리아 음악원을 졸업했으며, 1986년 헤르베르트 폰 카라얀의 발탁으로 국제 무대에 데뷔했다. 카라얀의 추천으로 잘츠부르크 페스티벌에서 모차르트 오페라에 출연하며 세계적인 주목을 받았다.\n\n콜로라투라 소프라노로서 모차르트, 로시니, 도니체티 등의 오페라에서 탁월한 기량을 선보였다. 메트로폴리탄 오페라, 밀라노 스칼라, 빈 슈타츠오퍼, 코벤트 가든 등 세계 최고의 오페라 하우스 무대에 섰다.\n\n50장이 넘는 음반을 발매했으며, 특히 \"목련화\", \"가고파\" 등 한국 가곡을 세계에 알리는 데 기여했다. 그래미상 후보에 오르는 등 국제적인 인정을 받았으며, 한국 성악가로서는 최초로 세계적인 명성을 얻었다. 현재도 리사이틀과 오페라 공연을 통해 활발한 활동을 이어가고 있다.','화려한 콜로라투라 기교와 순수하고 맑은 음색으로 벨칸토 오페라의 정수를 보여주며, 뛰어난 표현력과 완벽한 테크닉을 겸비하고 있다.',1000,50,NULL,'2025-11-20 05:35:45','2025-11-20 10:26:41'),(200,'랑랑','Lang Lang','pianist','A',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features221/v4/60/8f/8b/608f8b18-6962-8419-ff91-51a29c76060c/mzl.qdyidtsd.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features221/v4/60/8f/8b/608f8b18-6962-8419-ff91-51a29c76060c/mzl.qdyidtsd.png/1200x1200bb.jpg','1982','중국','랑랑(Lang Lang)은 1982년 중국 선양 출생의 피아니스트이다.\n\n5세에 피아노를 시작했으며, 커티스 음악원에서 게리 그래프먼에게 사사했다. 1999년 시카고 라비니아 페스티벌에서 앙드레 와츠를 대신해 긴급 출연하며 일약 스타덤에 올랐다.\n\n2008년 베이징 올림픽 개막식 연주, 2018년 평창 올림픽 폐막식 연주 등 세계적인 행사에 참여했다. 도이치 그라모폰과 전속 계약을 맺고 쇼팽, 차이콥스키, 라흐마니노프, 베토벤 등 다양한 레퍼토리의 앨범을 발매했다.\n\n베를린 필하모닉, 빈 필하모닉, 뉴욕 필하모닉 등 세계 주요 오케스트라와 정기적으로 협연하며, 카네기홀, 로열 앨버트 홀 등에서 수많은 공연을 가졌다. 클래식 음악 대중화에 기여한 공로를 인정받아 유엔 평화 대사로도 활동하고 있다. 현재 전 세계에서 가장 많은 청중을 동원하는 피아니스트 중 한 명이다.','화려하고 극적인 연주로 청중을 사로잡으며, 뛰어난 쇼맨십과 에너지 넘치는 무대 매너가 특징이다.',1000,30,NULL,'2025-11-20 05:35:45','2025-11-20 10:26:42'),(201,'유자 왕','Yuja Wang','pianist','A',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/3e/d4/e9/3ed4e9a7-218e-a648-62cd-215c8588c994/mzl.ibyvncht.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/3e/d4/e9/3ed4e9a7-218e-a648-62cd-215c8588c994/mzl.ibyvncht.jpg/1200x1200bb.jpg','1987','중국/미국','유자 왕(Yuja Wang)은 1987년 중국 베이징 출생의 피아니스트이다.\n\n베이징 중앙음악학원에서 공부한 후, 15세에 캐나다 마운트 로열 음악원으로 유학했다. 이후 커티스 음악원에서 게리 그래프먼에게 사사하며 본격적인 연주 활동을 시작했다.\n\n2007년 보스턴 심포니와의 협연으로 주목받기 시작했으며, 압도적인 테크닉과 카리스마 넘치는 무대 매너로 전 세계 청중을 사로잡았다. 도이치 그라모폰과 전속 계약을 맺고 라흐마니노프, 프로코피예프, 라벨 등의 앨범을 발매했다.\n\n베를린 필하모닉, 빈 필하모닉, 뉴욕 필하모닉 등과 정기적으로 협연하며, 특히 러시아 레퍼토리와 현대음악에서 탁월한 해석을 보여준다. 화려한 의상과 독특한 스타일로도 유명하며, 클래식 음악의 새로운 아이콘으로 자리매김했다. 현재 세계에서 가장 바쁜 일정을 소화하는 피아니스트 중 한 명이다.','번개같이 빠른 테크닉과 정확무오한 연주, 강렬한 에너지와 카리스마가 돋보이며, 특히 러시아 낭만파와 현대 작품에서 압도적인 연주를 들려준다.',100,15,NULL,'2025-11-20 05:35:45','2025-11-20 10:26:44'),(202,'다닐 트리포노프','Daniil Trifonov','pianist','S',0.0,'https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages221/v4/39/a6/db/39a6db9b-9aa4-268e-92b8-21d9674e63ab/8dc39536-6fc5-4f5c-a52b-01a691f6d6ae_ami-identity-39b5e175df869c5789fd4a82b571a119-2024-08-29T09-49-22.696Z_cropped.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages221/v4/39/a6/db/39a6db9b-9aa4-268e-92b8-21d9674e63ab/8dc39536-6fc5-4f5c-a52b-01a691f6d6ae_ami-identity-39b5e175df869c5789fd4a82b571a119-2024-08-29T09-49-22.696Z_cropped.png/1200x1200bb.jpg','1991','러시아','다닐 트리포노프(Daniil Trifonov)는 1991년 러시아 니즈니노브고로드 출생의 피아니스트이다.\n\n2011년 루빈스타인 국제 피아노 콩쿠르와 차이콥스키 국제 콩쿠르에서 모두 우승하며 세계적인 주목을 받았다. 클리블랜드 음악원에서 세르게이 바바얀에게, 뉴욕에서 세르게이 레시체티스키에게 사사했다.\n\n도이치 그라모폰과 전속 계약을 맺고 쇼팽, 리스트, 라흐마니노프, 차이콥스키 등의 앨범을 발매했으며, 여러 음반이 그래미상 후보에 올랐다. 베를린 필하모닉, 빈 필하모닉, 뉴욕 필하모닉 등 세계 정상급 오케스트라와 정기적으로 협연하고 있다.\n\n피아니스트로서뿐만 아니라 작곡가로도 활동하며, 자신의 작품을 연주하기도 한다. 카네기홀, 빈 무지크페라인, 베를린 필하모니 등 세계 주요 콘서트홀에서 리사이틀을 개최하고 있다. 현재 세대를 대표하는 최고의 피아니스트 중 한 명으로 평가받으며, 뛰어난 음악성과 테크닉을 겸비한 연주자로 인정받고 있다.','경이로운 테크닉과 깊은 음악적 통찰력을 동시에 보여주며, 시적이면서도 강렬한 표현력으로 작품의 본질을 탐구하는 연주를 들려준다.',100,12,NULL,'2025-11-20 05:35:45','2025-11-20 10:26:45'),(203,'예핌 브론프만','Yefim Bronfman','pianist','A',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features125/v4/49/d4/0c/49d40cb5-931e-8730-332c-99de6775603e/mzl.nmytymsh.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features125/v4/49/d4/0c/49d40cb5-931e-8730-332c-99de6775603e/mzl.nmytymsh.jpg/1200x1200bb.jpg','1958','미국','예핌 브론프만(Yefim Bronfman)은 1958년 우즈베키스탄 타슈켄트 출생의 피아니스트이다.\n\n이스라엘로 이주한 후 루빈 음악 아카데미에서 공부했으며, 이후 줄리어드 음악원과 커티스 음악원에서 루돌프 피르쿠시니, 레온 플라이셔, 루돌프 제르킨에게 사사했다.\n\n1989년 그래미상을 수상했으며, 베를린 필하모닉, 빈 필하모닉, 뉴욕 필하모닉 등과 수백 회 협연했다. 특히 브람스, 프로코피예프, 바르토크 등의 피아노 협주곡에서 탁월한 해석을 보여주며, 20세기 음악 해석의 권위자로 인정받고 있다.\n\nSony Classical에서 다수의 음반을 발매했으며, 50여 년간 꾸준히 세계 무대에서 활동하고 있다. 힘있고 명료한 터치와 지적인 해석으로 평가받으며, 현재도 활발한 연주 활동을 이어가고 있다.','강력하고 명료한 터치, 지적이고 구조적인 해석이 특징이며, 특히 20세기 레퍼토리에서 권위있는 연주를 들려준다.',100,50,NULL,'2025-11-20 05:35:45','2025-11-20 10:26:46'),(204,'마르타 아르헤리치','Martha Argerich','pianist','S',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/ea/b4/d1/eab4d120-67d8-f6db-7bf5-424419106310/mzl.sfxsdhol.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/ea/b4/d1/eab4d120-67d8-f6db-7bf5-424419106310/mzl.sfxsdhol.jpg/1200x1200bb.jpg','1941','아르헨티나','마르타 아르헤리치(Martha Argerich)는 1941년 아르헨티나 부에노스아이레스 출생의 피아니스트이다.\n\n1957년 제네바 국제 콩쿠르와 부조니 콩쿠르 우승을 거쳐, 1965년 쇼팽 국제 피아노 콩쿠르에서 우승하며 세계적인 명성을 얻었다. 빈에서 프리드리히 굴다에게, 스위스에서 니키타 마갈로프에게 사사했다.\n\n라벨, 프로코피예프, 쇼팽, 리스트 등 낭만파와 20세기 작품에서 탁월한 해석을 보여주며, 특히 실내악 연주자로서도 세계 최고로 평가받는다. 도이치 그라모폰, EMI 등에서 수많은 음반을 발매했으며, 여러 그래미상을 수상했다.\n\n베를린 필하모닉, 빈 필하모닉 등과 수없이 협연했으며, 독주보다 실내악과 협주 활동을 선호하는 것으로 유명하다. 자신의 이름을 딴 루가노 페스티벌을 개최하며 젊은 음악가들을 지원하고 있다. 80대가 넘은 현재도 왕성한 활동을 이어가며, 살아있는 전설로 평가받고 있다.','폭발적인 에너지와 자발성, 열정적이면서도 시적인 표현력이 특징이며, 즉흥성과 자유로움 속에서도 완벽한 테크닉을 보여준다.',1000,150,NULL,'2025-11-20 05:35:45','2025-11-20 10:26:47'),(205,'그리고리 소콜로프','Grigory Sokolov','pianist','S',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/f7/e0/bb/f7e0bb0c-e7b5-0ab5-7e2b-8609931d6a67/mzm.nvfdlqsl.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/f7/e0/bb/f7e0bb0c-e7b5-0ab5-7e2b-8609931d6a67/mzm.nvfdlqsl.jpg/1200x1200bb.jpg','1950','러시아','그리고리 소콜로프(Grigory Sokolov)는 1950년 러시아 레닌그라드(현 상트페테르부르크) 출생의 피아니스트이다.\n\n1966년 16세의 나이로 차이콥스키 국제 콩쿠르에서 우승하며 국제 무대에 데뷔했다. 레닌그라드 음악원에서 모이세이 할프린에게 사사했으며, 소련 시절부터 국내 최고의 피아니스트로 평가받았다.\n\n서구 세계와의 교류가 제한적이던 소련 시절을 거쳐, 1990년대 이후 유럽 무대에서 본격적으로 활동하기 시작했다. 바흐부터 현대음악까지 폭넓은 레퍼토리를 소화하며, 특히 바흐, 베토벤, 슈베르트, 쇼팽, 브람스 작품에서 깊이 있는 해석을 선보인다.\n\n음반 녹음을 거의 하지 않고 라이브 공연에 집중하는 것으로 유명하며, 그의 리사이틀은 전 세계적으로 매진을 기록한다. 완벽주의자로 알려져 있으며, 한 곡 한 곡에 깊이 몰입하는 연주로 청중을 압도한다. 현존하는 최고의 피아니스트 중 한 명으로 평가받으며, 독보적인 예술 세계를 구축하고 있다.','완벽한 터치 컨트롤과 깊은 집중력, 시간을 초월한 듯한 명상적 해석이 특징이며, 모든 음에 생명을 불어넣는 듯한 연주를 들려준다.',100,10,NULL,'2025-11-20 05:35:45','2025-11-20 10:26:48'),(206,'예브게니 키신','Evgeny Kissin','pianist','S',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/52/28/93/522893ef-2f23-e193-b345-c137f51a145c/mzl.vhsganbe.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/52/28/93/522893ef-2f23-e193-b345-c137f51a145c/mzl.vhsganbe.jpg/1200x1200bb.jpg','1971','러시아/이스라엘','예브게니 키신(Evgeny Kissin)은 1971년 러시아 모스크바 출생의 피아니스트이다.\n\n신동으로 불리며 6세에 모스크바 음악원 특별 학교에 입학했으며, 안나 파블로브나 칸토르에게 평생 사사했다. 12세에 모스크바 필하모닉과 협연하며 데뷔했고, 1984년 카라얀의 초청으로 베를린 필하모닉과 협연하며 서구 무대에 진출했다.\n\n1990년 뉴욕 카네기홀 데뷔 이후 세계 최고의 피아니스트 반열에 올랐으며, 쇼팽, 리스트, 슈만, 브람스, 라흐마니노프 등 낭만파 레퍼토리에서 탁월한 해석을 보여준다. 도이치 그라모폰, RCA, EMI 등에서 다수의 음반을 발매했으며, 여러 그래미상 후보에 올랐다.\n\n베를린 필하모닉, 빈 필하모닉, 뉴욕 필하모닉 등과 정기적으로 협연하며, 세계 주요 콘서트홀에서 리사이틀을 개최하고 있다. 완벽한 테크닉과 강렬한 음악적 표현력으로 평가받으며, 현재도 세계 최정상급 피아니스트로 활동하고 있다.','압도적인 테크닉과 강렬한 감정 표현, 완벽한 음색 조절 능력이 특징이며, 특히 낭만파 작품에서 열정과 서정성을 완벽하게 균형잡는다.',100,40,NULL,'2025-11-20 05:35:45','2025-11-20 10:26:49'),(207,'마우리치오 폴리니','Maurizio Pollini','pianist','S',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/a0/78/b1/a078b1a5-f5e5-a988-1586-d5b21e16d369/mzl.rrejuzdw.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/a0/78/b1/a078b1a5-f5e5-a988-1586-d5b21e16d369/mzl.rrejuzdw.jpg/1200x1200bb.jpg','1942','이탈리아','마우리치오 폴리니(Maurizio Pollini)는 1942년 이탈리아 밀라노 출생의 피아니스트이다. 2024년 별세했다.\n\n1960년 18세의 나이로 쇼팽 국제 피아노 콩쿠르에서 우승하며 심사위원장 아르투르 루빈스타인으로부터 \"우리 중 누구보다 뛰어나다\"는 찬사를 받았다. 밀라노 음악원에서 카를로 론티에게 사사했으며, 이후 아르투로 베네데티 미켈란젤리에게도 배웠다.\n\n베토벤, 쇼팽, 슈베르트, 브람스 등 고전-낭만파 레퍼토리뿐만 아니라 쇤베르크, 베베른, 부조니, 놀로, 스톡하우젠 등 현대음악 해석에서도 최고의 권위자로 인정받았다. 도이치 그라모폰과 60년 이상 전속 계약을 유지하며 100장이 넘는 음반을 발매했다.\n\n베를린 필하모닉, 빈 필하모닉 등과 수없이 협연했으며, 특히 클라우디오 아바도와의 협업이 유명하다. 완벽주의적 접근과 지적인 해석으로 20세기 후반 최고의 피아니스트 중 한 명으로 평가받았다.','완벽한 테크닉과 지적이고 구조적인 해석, 명료하고 투명한 음색이 특징이며, 현대음악에서도 탁월한 통찰력을 보여주었다.',100,100,NULL,'2025-11-20 05:35:45','2025-11-20 10:26:50'),(208,'안드라시 쉬프','András Schiff','pianist','A',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/af/8a/4f/af8a4f35-878a-6c87-1e07-1fc15121a7db/mzl.lofzfgpc.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/af/8a/4f/af8a4f35-878a-6c87-1e07-1fc15121a7db/mzl.lofzfgpc.jpg/1200x1200bb.jpg','1953','영국/헝가리','안드라시 쉬프(András Schiff)는 1953년 헝가리 부다페스트 출생의 피아니스트이자 지휘자이다.\n\n부다페스트의 리스트 음악원에서 팔 카도사와 페렌츠 라도스에게, 런던에서 조지 말콤에게 사사했다. 1974년 차이콥스키 국제 콩쿠르에서 입상하며 국제적인 주목을 받기 시작했다.\n\n바흐, 하이든, 모차르트, 베토벤, 슈베르트, 슈만 등 고전-낭만파 레퍼토리의 권위자로 평가받으며, 특히 바흐의 평균율 클라비어곡집과 베토벤 소나타 전곡 연주로 유명하다. ECM, Decca, 테르데크 등에서 60장이 넘는 음반을 발매했다.\n\n솔로 활동 외에도 지휘자로 활동하며 오케스트라를 직접 이끌고 협주곡을 연주하기도 한다. 실내악 연주자로도 활발히 활동하며, 마스터클래스를 통해 후학 양성에도 힘쓰고 있다. 영국 시민권을 취득했으며, 현재도 세계 무대에서 왕성한 활동을 이어가고 있다.','명료하고 투명한 터치, 고전적 균형감과 구조미를 중시하며, 특히 바흐와 베토벤 해석에서 깊은 통찰력을 보여준다.',100,60,NULL,'2025-11-20 05:35:45','2025-11-20 10:26:52'),(209,'힐러리 한','Hilary Hahn','violinist','A',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/7d/a6/ef/7da6eff6-866a-444e-5646-9d9e0a46841e/mzl.iiyfmvrv.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/7d/a6/ef/7da6eff6-866a-444e-5646-9d9e0a46841e/mzl.iiyfmvrv.jpg/1200x1200bb.jpg','1979','미국','힐러리 한(Hilary Hahn)은 1979년 미국 버지니아주 렉싱턴 출생의 바이올리니스트이다.\n\n3세에 바이올린을 시작했으며, 10세에 커티스 음악원에 입학해 야샤 브로드스키에게 사사했다. 16세에 볼티모어 심포니와 협연하며 데뷔했고, 이후 세계 정상급 바이올리니스트로 자리매김했다.\n\n바흐 무반주 소나타와 파르티타, 베토벤, 브람스, 시벨리우스 바이올린 협주곡 등 정통 레퍼토리에서 탁월한 해석을 보여주며, 현대 작곡가들의 위촉 작품도 적극적으로 초연하고 있다. 도이치 그라모폰과 Sony Classical에서 다수의 음반을 발매했으며, 3개의 그래미상을 수상했다.\n\n베를린 필하모닉, 빈 필하모닉, 뉴욕 필하모닉 등과 정기적으로 협연하며, 전 세계 주요 콘서트홀에서 리사이틀을 개최하고 있다. SNS를 통해 청중과 적극적으로 소통하며 클래식 음악 대중화에도 기여하고 있다. 현재 가장 활발하게 활동하는 바이올리니스트 중 한 명이다.','완벽한 테크닉과 정확한 인토네이션, 명료하고 지적인 해석이 특징이며, 현대적 감각과 전통적 해석을 조화롭게 결합한다.',100,25,NULL,'2025-11-20 05:35:45','2025-11-20 10:26:53'),(210,'조슈아 벨','Joshua Bell','violinist','A',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features125/v4/ac/bd/0a/acbd0abc-5f22-6013-c457-4a7c78f84f50/mzl.awrrvtfj.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features125/v4/ac/bd/0a/acbd0abc-5f22-6013-c457-4a7c78f84f50/mzl.awrrvtfj.jpg/1200x1200bb.jpg','1967','미국','조슈아 벨(Joshua Bell)은 1967년 미국 인디애나주 블루밍턴 출생의 바이올리니스트이다.\n\n4세에 바이올린을 시작했으며, 인디애나 대학교에서 조셉 긴골드에게, 이후 필라델피아에서 이반 갈라미안의 제자인 조셉 푹스에게 사사했다. 14세에 리카르도 무티가 지휘하는 필라델피아 오케스트라와 협연하며 데뷔했다.\n\n1989년산 스트라디바리우스 \"Gibson ex Huberman\"을 연주하며, Sony Classical과 Warner Classics에서 40장이 넘는 음반을 발매했다. 브루흐, 멘델스존, 차이콥스키, 브람스 등 낭만파 협주곡에서 탁월한 해석을 보여준다.\n\n2007년 워싱턴 D.C. 지하철역에서 변장하고 연주한 실험으로 유명해졌으며, 영화 \"레드 바이올린\" 사운드트랙 연주로도 알려져 있다. 2011년부터 아카데미 오브 세인트 마틴 인 더 필즈의 음악 감독으로 활동하며 지휘와 독주를 병행하고 있다. 현재도 세계 무대에서 활발한 연주 활동을 이어가고 있다.','따뜻하고 풍부한 음색, 낭만적이고 감성적인 해석이 특징이며, 대중적 어필과 예술성을 모두 갖춘 연주를 들려준다.',100,40,NULL,'2025-11-20 05:35:45','2025-11-20 10:26:54'),(211,'안네 소피 무터','Anne-Sophie Mutter','violinist','S',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/f2/d8/90/f2d890a1-0950-eabd-97ca-da3d30a60ec1/mzl.qmumwois.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/f2/d8/90/f2d890a1-0950-eabd-97ca-da3d30a60ec1/mzl.qmumwois.jpg/1200x1200bb.jpg','1963','독일','안네 소피 무터(Anne-Sophie Mutter)는 1963년 독일 라인펠덴 출생의 세계적인 바이올리니스트이다.\n\n4세에 바이올린을 시작하여 13세에 헤르베르트 폰 카라얀에게 발탁되어 베를린 필하모닉 오케스트라와 데뷔한 것으로 유명하다. 뛰어난 기교와 깊이 있는 음악성으로 명성이 높으며, 특히 현대 음악 작곡가들의 작품을 초연하고 헌정받는 등 동시대 음악에 대한 헌신으로도 잘 알려져 있다.\n\n그녀는 고전 레퍼토리부터 현대 음악까지 폭넓은 스펙트럼을 소화하며, 수많은 상과 훈장을 받았다.','정교한 기교와 폭넓은 활 테크닉을 바탕으로, 감정의 깊이와 지적인 해석을 결합한 연주 스타일을 보여준다.',1000,100,NULL,'2025-11-20 05:35:45','2025-11-20 10:31:58'),(212,'야닌 얀센','Janine Jansen','violinist','A',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features115/v4/a7/cb/7b/a7cb7b51-63d9-7423-a941-907603edb778/mzl.pxhetxua.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features115/v4/a7/cb/7b/a7cb7b51-63d9-7423-a941-907603edb778/mzl.pxhetxua.jpg/1200x1200bb.jpg','1978','네덜란드','야닌 얀센(Janine Jansen)은 1978년 네덜란드 수스트 출생의 바이올리니스트이다.\n\n암스테르담 콘세르트허바우에서 데뷔했으며, 유럽과 북미의 주요 오케스트라와 협연하며 국제적인 명성을 쌓았다. 그녀의 연주는 강렬한 감정 표현과 동시에 세련되고 명료한 음색이 특징이다.\n\n주로 실내악과 협주곡 연주에 주력하며, 바흐, 베토벤, 브람스 등의 고전 레퍼토리부터 브리튼, 쇼스타코비치 등 20세기 레퍼토리까지 폭넓게 연주한다.','맑고 투명한 음색과 강렬한 감정의 대비가 돋보이며, 레퍼토리에 대한 통찰력 있는 해석을 선보인다.',500,20,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:00'),(213,'레이 첸','Ray Chen','violinist','A',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features115/v4/7e/37/2c/7e372cfa-0020-bb6b-2216-436b458f0554/mzl.snqlqyju.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features115/v4/7e/37/2c/7e372cfa-0020-bb6b-2216-436b458f0554/mzl.snqlqyju.jpg/1200x1200bb.jpg','1989','대만/호주','레이 첸(Ray Chen)은 1989년 대만에서 태어나 호주에서 성장한 바이올리니스트이다.\n\n2008년 예후디 메뉴인 국제 바이올린 콩쿠르 우승, 2009년 퀸 엘리자베스 콩쿠르 우승(공동)으로 국제적인 명성을 얻었다. 뛰어난 기교와 더불어 소셜 미디어를 통해 클래식 음악을 대중에게 알리는 데도 적극적인 아티스트이다.','화려한 기교와 카리스마 넘치는 무대 매너를 겸비하며, 정열적이고 생동감 있는 연주를 펼친다.',500,15,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:01'),(214,'막심 벤게로프','Maxim Vengerov','violinist','S',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features115/v4/de/79/48/de794876-2782-7f38-0cd0-61c79346e9a8/pr_source.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features115/v4/de/79/48/de794876-2782-7f38-0cd0-61c79346e9a8/pr_source.png/1200x1200bb.jpg','1974','이스라엘/러시아','막심 벤게로프(Maxim Vengerov)는 1974년 러시아 노보시비르스크 출생의 바이올리니스트이자 지휘자이다.\n\n1990년 칼 플레시 국제 바이올린 콩쿠르에서 1위를 차지하며 천재적인 재능을 입증했다. 세계적인 거장으로서 모든 주요 오케스트라와 협연했으며, 솔로 활동 외에도 교육자 및 지휘자로서 왕성하게 활동하고 있다.','폭발적인 에너지와 러시아 악파 특유의 뜨거운 감성, 완벽한 테크닉이 결합된 압도적인 연주가 특징이다.',1000,40,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:02'),(215,'요요 마','Yo-Yo Ma','cellist','S',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/19/f8/89/19f889ed-c7bf-5816-be62-72b9f6c2f4cb/pr_source.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/19/f8/89/19f889ed-c7bf-5816-be62-72b9f6c2f4cb/pr_source.png/1200x1200bb.jpg','1955','프랑스/미국','요요 마(Yo-Yo Ma)는 1955년 프랑스 파리에서 중국계 부모 사이에서 태어난 세계적인 첼리스트이다.\n\n1978년 레번트릿 국제 콩쿠르 우승 등 수많은 상을 받았으며, 고전 음악뿐만 아니라 탱고, 블루그래스, 실크로드 앙상블 등 다양한 장르를 아우르는 혁신적인 활동으로 유명하다.\n\n음악을 통한 문화 교류와 사회 공헌 활동에 힘쓰고 있다.','깊고 따뜻한 음색과 뛰어난 표현력으로, 동서양의 음악적 경계를 넘나드는 폭넓은 레퍼토리를 선보인다.',1000,100,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:03'),(216,'미샤 마이스키','Mischa Maisky','cellist','A',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features211/v4/30/30/a1/3030a11e-8d7e-687c-ac83-87ef330a92f5/mzl.zcetcaah.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features211/v4/30/30/a1/3030a11e-8d7e-687c-ac83-87ef330a92f5/mzl.zcetcaah.jpg/1200x1200bb.jpg','1948','라트비아/이스라엘','미샤 마이스키(Mischa Maisky)는 1948년 라트비아 리가 출생의 첼리스트이다.\n\n로스트로포비치와 피아티고르스키 모두에게 사사한 유일한 첼리스트로 알려져 있다. 1973년 카사도 국제 첼로 콩쿠르 우승을 했다. 독특하고 개성 강한 음악 해석으로 유명하며, 특히 바흐의 무반주 첼로 모음곡 연주에 깊은 통찰을 보여주었다.','낭만적이고 격정적인 감정 표현과 독특한 비브라토를 사용하며, 자유롭고 개성적인 음악적 해석을 추구한다.',500,40,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:04'),(217,'스티븐 이설리스','Steven Isserlis','cellist','A',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features114/v4/fb/19/e1/fb19e1a7-491e-b57b-083a-d612fc9a9baf/mzl.tlcatppw.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features114/v4/fb/19/e1/fb19e1a7-491e-b57b-083a-d612fc9a9baf/mzl.tlcatppw.png/1200x1200bb.jpg','1958','UK','스티븐 이설리스(Steven Isserlis)는 1958년 영국 런던 출생의 첼리스트이다.\n\n고전 레퍼토리와 현대 레퍼토리 모두에 조예가 깊으며, 특히 시대악기 연주에 큰 관심을 보였다. 그의 섬세하고 지적인 해석은 비평가들로부터 높은 평가를 받았다.\n\n솔로 활동 외에도 활발한 실내악 연주와 음악 저술 활동으로도 잘 알려져 있다.','지적이고 섬세한 해석, 깨끗하고 우아한 음색이 특징이며, 작품의 구조와 역사적 배경을 중시한다.',500,30,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:05'),(218,'구스타보 두다멜','Gustavo Dudamel','conductor','A',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/df/42/a8/df42a845-0523-bdc8-26bf-10c68613e324/mzl.pzvreeru.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/df/42/a8/df42a845-0523-bdc8-26bf-10c68613e324/mzl.pzvreeru.jpg/1200x1200bb.jpg','1981','베네수엘라','구스타보 두다멜(Gustavo Dudamel)은 1981년 베네수엘라 바르키시메토 출생의 지휘자이다.\n\n베네수엘라의 엘 시스테마(El Sistema) 교육 프로그램 출신으로, 2004년 구스타프 말러 지휘 콩쿠르에서 우승하며 세계적인 주목을 받았다. 현재 로스앤젤레스 필하모닉 음악감독 등을 역임하며 세계적인 명성을 누리고 있다.\n\n강렬한 에너지와 생동감 넘치는 해석으로 청중을 사로잡는다.','활력 넘치고 열정적인 지휘 스타일로, 특히 낭만주의 시대와 20세기 레퍼토리에서 뛰어난 표현력을 보여준다.',500,25,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:06'),(219,'야닉 네제 세갱','Yannick Nézet-Séguin','conductor','A',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/4e/27/99/4e2799ee-8c09-edd6-55c4-74055c9782ca/mzl.uexvwzsq.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/4e/27/99/4e2799ee-8c09-edd6-55c4-74055c9782ca/mzl.uexvwzsq.jpg/1200x1200bb.jpg','1975','캐나다','야닉 네제 세갱(Yannick Nézet-Séguin)은 1975년 캐나다 몬트리올 출생의 지휘자이다.\n\n필라델피아 오케스트라의 음악감독, 메트로폴리탄 오페라의 음악감독 등을 역임하며 세계적으로 활발히 활동하고 있다. 폭넓은 레퍼토리와 강한 리더십으로 높이 평가받는 거장이다.','유연하고 역동적인 지휘 스타일로, 오페라와 교향곡 모두에서 깊이 있는 음악성과 감성적인 연주를 이끌어낸다.',500,50,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:08'),(220,'사이먼 래틀','Simon Rattle','conductor','S',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/35/f0/a2/35f0a2dd-4619-1e9f-97c1-0ee8a85ca497/mzl.rhxggjrn.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/35/f0/a2/35f0a2dd-4619-1e9f-97c1-0ee8a85ca497/mzl.rhxggjrn.jpg/1200x1200bb.jpg','1955','영국/독일','사이먼 래틀 경(Sir Simon Rattle)은 1955년 영국 리버풀 출생의 세계적인 지휘자이다.\n\n2002년부터 2018년까지 베를린 필하모닉 오케스트라의 상임 지휘자를 역임하며 세계 클래식계의 거장으로 자리매김했다. 현재 바이에른 방송 교향악단 수석 지휘자로 활동하고 있다.\n\n특히 20세기 및 현대 음악 해석에 정통하다.','날카로운 분석력과 섬세한 디테일을 중시하며, 복잡한 현대 음악을 명료하게 구현하는 능력이 뛰어나다.',1000,150,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:09'),(221,'일리야 라쉬코프스키','Ilya Rashkovskiy','violinist','Rising',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music/y2005/m10/d01/h06/mzi.kdedrmbm.jpg/600x600ac.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music/y2005/m10/d01/h06/mzi.kdedrmbm.jpg/1200x1200ac.jpg','1985','Russia','일리야 라쉬코프스키(Ilya Rashkovskiy)는 1985년 러시아 출생의 피아니스트이다.\n\n하마마쓰 국제 피아노 콩쿠르 우승, 퀸 엘리자베스 콩쿠르 입상 등 다수의 국제 콩쿠르에서 수상했다. 섬세하고 깊이 있는 음악성으로 주목받고 있다.','따뜻하고 서정적인 음색을 바탕으로, 깊은 감성을 담아내는 섬세하고 시적인 연주가 특징이다.',10,5,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:10'),(223,'보리스 길트부르그','Boris Giltburg','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages116/v4/c5/78/fa/c578fabd-27cb-51ef-08ce-8b5f5f24ee3e/69825ef7-6964-4d25-8ed3-bbb3d609ec01_file_cropped.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages116/v4/c5/78/fa/c578fabd-27cb-51ef-08ce-8b5f5f24ee3e/69825ef7-6964-4d25-8ed3-bbb3d609ec01_file_cropped.png/1200x1200bb.jpg','1984','Israel','보리스 길트부르그(Boris Giltburg)는 1984년 러시아 모스크바에서 태어나 이스라엘에서 성장한 피아니스트이다.\n\n2013년 퀸 엘리자베스 콩쿠르에서 우승하며 세계적인 명성을 얻었다. 뛰어난 기교와 강렬한 표현력으로 유명하며, 특히 라흐마니노프와 프로코피예프 연주에 강점을 보인다.','견고한 타건과 압도적인 테크닉을 바탕으로, 폭발적인 에너지와 깊은 서정성을 동시에 표현한다.',100,15,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:12'),(224,'파벨 콜레스니코프','Pavel Kolesnikov','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features4/v4/0e/d0/87/0ed0879e-bd54-d9d9-39fe-c3af88390f75/mzl.voihpsdp.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features4/v4/0e/d0/87/0ed0879e-bd54-d9d9-39fe-c3af88390f75/mzl.voihpsdp.png/1200x1200bb.jpg','1989','Russia','파벨 콜레스니코프(Pavel Kolesnikov)는 1989년 러시아 노보시비르스크 출생의 피아니스트이다.\n\n2012년 호르헤 볼렛 국제 피아노 콩쿠르 우승 등 다수의 콩쿠르에서 수상했으며, 섬세하고 독창적인 해석으로 평단의 주목을 받았다. 카네기 홀 등 주요 무대에서 활약하고 있다.','색채감 있는 음색과 유려한 프레이징이 돋보이는 섬세한 연주 스타일을 지녔으며, 독창적인 시각으로 작품을 해석한다.',100,10,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:13'),(225,'알렉산드라 도브간','Alexandra Dovgan','pianist','Rising',NULL,'https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/Alexandra_Dovgan001_%2853935140906%29_%28cropped%29.jpg/500px-Alexandra_Dovgan001_%2853935140906%29_%28cropped%29.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/Alexandra_Dovgan001_%2853935140906%29_%28cropped%29.jpg/500px-Alexandra_Dovgan001_%2853935140906%29_%28cropped%29.jpg','2007','Russia','알렉산드라 도브간(Alexandra Dovgan)은 2007년 러시아 출생의 신예 피아니스트이다.\n\n2018년 모스크바 국제 그랜드 피아노 콩쿠르에서 우승하며 국제적인 주목을 받았다. 어린 나이에도 불구하고 깊이 있는 음악성과 놀라운 테크닉을 겸비했다는 평가를 받는다.','어린 나이답지 않은 성숙한 해석과 견고한 테크닉, 깨끗하고 깊은 음색을 특징으로 한다.',10,2,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:14'),(226,'루카스 드바르그','Lucas Debargue','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features112/v4/e4/ad/a2/e4ada277-69eb-c0a9-b92b-84a2c83aff54/mzl.dwqxdpsa.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features112/v4/e4/ad/a2/e4ada277-69eb-c0a9-b92b-84a2c83aff54/mzl.dwqxdpsa.jpg/1200x1200bb.jpg','1990','France','루카스 드바르그(Lucas Debargue)는 1990년 프랑스 파리 출생의 피아니스트이다.\n\n2015년 차이콥스키 국제 콩쿠르에서 4위를 차지했지만, 독창적인 음악성과 해석으로 \'모스크바 음악 비평가상\'을 수상하며 대중과 평단의 큰 주목을 받았다. 고전부터 현대에 이르는 폭넓은 레퍼토리를 자신만의 독특한 시각으로 해석한다.','자유롭고 즉흥적인 연주와 깊은 통찰력, 예민하고 독특한 음색을 특징으로 하는 개성 강한 아티스트이다.',100,10,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:16'),(227,'츠지이 노부유키','Nobuyuki Tsujii','pianist','A',0.0,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/4b/3c/0f/4b3c0f91-0964-1f65-c369-9b106c5d0d94/mzl.zqlwxoyd.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/4b/3c/0f/4b3c0f91-0964-1f65-c369-9b106c5d0d94/mzl.zqlwxoyd.jpg/1200x1200bb.jpg','1988','일본','츠지이 노부유키(Nobuyuki Tsujii)는 1988년 일본 도쿄 출생의 시각 장애인 피아니스트이다.\n\n2009년 반 클라이번 국제 피아노 콩쿠르에서 공동 우승하며 세계적인 명성을 얻었다. 그의 연주는 뛰어난 테크닉과 더불어 깊은 서정성과 감동적인 표현력으로 청중을 사로잡는다.','섬세한 터치와 풍부한 감정 표현으로 깊은 울림을 주며, 특히 낭만주의 레퍼토리에서 뛰어난 역량을 보인다.',500,30,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:17'),(228,'브루스 리우','Bruce Liu','pianist','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages221/v4/5c/51/e6/5c51e6bf-4a77-bb4d-5466-ebdbef5da612/6586f746-fc3c-482d-90ae-11d68591b2ed_ami-identity-1cdb4b796cb50ab34cf26de43cf1dd98-2024-09-09T09-05-13.482Z_cropped.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages221/v4/5c/51/e6/5c51e6bf-4a77-bb4d-5466-ebdbef5da612/6586f746-fc3c-482d-90ae-11d68591b2ed_ami-identity-1cdb4b796cb50ab34cf26de43cf1dd98-2024-09-09T09-05-13.482Z_cropped.png/1200x1200bb.jpg','1997','International','브루스 리우(Bruce Liu)는 1997년 프랑스 파리에서 태어나 캐나다에서 성장한 피아니스트이다.\n\n2021년 제18회 쇼팽 국제 피아노 콩쿠르에서 우승하며 국제적인 명성을 얻었다. 뛰어난 기교와 세련된 음악성을 겸비했으며, 우승 직후부터 전 세계를 무대로 활발하게 활동 중이다.','빼어난 기교와 날카로운 지성, 그리고 자유롭고 유려한 흐름이 조화를 이루는 세련된 연주를 선보인다.',100,5,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:18'),(229,'소리타 교헤이','Kyohei Sorita','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/ed/29/0e/ed290e98-48a5-f37f-e0e9-9d476803aaa8/mzl.dlkebjzw.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/ed/29/0e/ed290e98-48a5-f37f-e0e9-9d476803aaa8/mzl.dlkebjzw.jpg/1200x1200bb.jpg','1990','International','소리타 교헤이(Kyohei Sorita)는 1990년 일본 출생의 피아니스트이다.\n\n2021년 제18회 쇼팽 국제 피아노 콩쿠르에서 2위를 차지하며 세계적인 주목을 받았다. 일본을 넘어 국제 무대에서 활발히 활동하고 있으며, 자신이 창단한 재팬 내셔널 오케스트라를 이끌며 지휘자로도 활동 중이다.','강렬하고 역동적인 타건과 웅장한 스케일의 연주를 구사하며, 극적인 표현력을 강조한다.',100,10,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:19'),(230,'마르틴 가르시아','Martin García García','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages112/v4/9e/66/05/9e66052d-1852-3484-e7ad-7530dca70004/6a79fd7b-b65e-4e49-9695-ea26300d615c_ami-identity-ff5d6fe7afc4c8906f93da0ca4934330-2022-10-26T16-30-42.145Z_cropped.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages112/v4/9e/66/05/9e66052d-1852-3484-e7ad-7530dca70004/6a79fd7b-b65e-4e49-9695-ea26300d615c_ami-identity-ff5d6fe7afc4c8906f93da0ca4934330-2022-10-26T16-30-42.145Z_cropped.png/1200x1200bb.jpg','1996','International','마르틴 가르시아 가르시아(Martin García García)는 1996년 스페인 출생의 피아니스트이다.\n\n2021년 제18회 쇼팽 국제 피아노 콩쿠르에서 3위를 차지하며 주목받았다. 섬세한 감성과 깊이 있는 음악성으로 호평받고 있으며, 유럽과 아시아를 중심으로 국제적인 연주 활동을 이어가고 있다.','따뜻하고 서정적인 음색과 우아하고 섬세한 프레이징을 구사하며, 자연스러운 흐름을 중시한다.',100,5,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:20'),(231,'하오 라오','Hao Rao','pianist','Rising',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music221/v4/a5/c7/df/a5c7df9d-1716-9a01-8fb9-a3700614b974/4894965784459.jpg/600x600ac.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music221/v4/a5/c7/df/a5c7df9d-1716-9a01-8fb9-a3700614b974/4894965784459.jpg/1200x1200ac.jpg','2001','International','하오 라오(Hao Rao)는 2001년 중국 출생의 피아니스트이다.\n\n2021년 반 클라이번 국제 피아노 콩쿠르에서 최연소 참가자로 주목받았으며, 깊이 있는 음악성으로 호평을 받았다. 현재 국제 무대에서 활발하게 활동하며 기량을 입증하고 있다.','정확한 테크닉과 함께 섬세한 감정 표현력을 보여주며, 특히 낭만주의 레퍼토리에 능하다.',10,2,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:21'),(232,'레오노라 아르멜리니','Leonora Armellini','pianist','Rising',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music/b3/f4/9f/mzi.whwwusya.jpg/600x600ac.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music/b3/f4/9f/mzi.whwwusya.jpg/1200x1200ac.jpg','1992','International','레오노라 아르멜리니(Leonora Armellini)는 1992년 이탈리아 파도바 출생의 피아니스트이다.\n\n2021년 제18회 쇼팽 국제 피아노 콩쿠르에서 5위를 차지하며 국제적인 명성을 얻었다. 이탈리아를 대표하는 젊은 피아니스트 중 한 명으로, 고전-낭만 레퍼토리에 강점을 보인다.','이탈리아 피아니즘의 전통을 이어받아 밝고 명료한 음색과 유려한 테크닉으로 작품을 해석한다.',10,3,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:22'),(233,'제이제이 준 리 부이','J J Jun Li Bui','pianist','Rising',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music123/v4/9f/68/01/9f6801b2-5ffd-d432-5d16-4dd7bfa9d3f7/5906395034901.jpg/600x600ac.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music123/v4/9f/68/01/9f6801b2-5ffd-d432-5d16-4dd7bfa9d3f7/5906395034901.jpg/1200x1200ac.jpg','2004','International','제이제이 준 리 부이(J J Jun Li Bui)는 2004년 캐나다 토론토 출생의 피아니스트이다.\n\n2021년 제18회 쇼팽 국제 피아노 콩쿠르에서 최연소로 입상(6위)하며 주목받았다. 섬세한 터치와 음악적 깊이를 보여주는 신예이다.','섬세하고 사려 깊은 터치와 안정적인 연주력을 바탕으로, 음악적 구조와 서정성을 조화시킨다.',10,1,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:24'),(234,'정경화','Kyung Wha Chung','violinist','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/d4/03/77/d40377f6-ffba-b4d9-2ef0-76c5f6afc4d2/mzl.zsfgbbhp.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/d4/03/77/d40377f6-ffba-b4d9-2ef0-76c5f6afc4d2/mzl.zsfgbbhp.jpg/1200x1200bb.jpg','1948','South Korea','정경화(Kyung Wha Chung)는 1948년 대한민국 출생의 세계적인 바이올리니스트이다.\n\n1967년 에드거 레벤트릿 콩쿠르에서 우승하며 국제 무대에 데뷔했다. 카리스마 넘치는 연주와 깊은 표현력으로 20세기 후반 최고의 바이올리니스트 중 한 명으로 인정받는다. 솔로 및 정 트리오 멤버로 활동하며 세계적인 명성을 쌓았다.','강렬한 몰입감과 폭발적인 에너지, 그리고 깊고 뜨거운 감성을 담아내는 한국의 거장 바이올리니스트이다.',1000,50,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:25'),(235,'정명훈','Myung-Whun Chung','conductor','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music116/v4/d4/80/09/d48009e3-68dd-1711-b15f-5c5463b8958b/2f497c7e-a19a-4e65-bcb6-159d1a93db5c.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music116/v4/d4/80/09/d48009e3-68dd-1711-b15f-5c5463b8958b/2f497c7e-a19a-4e65-bcb6-159d1a93db5c.png/1200x1200bb.jpg','1953','South Korea','정명훈(Myung-Whun Chung)은 1953년 대한민국 출생의 세계적인 지휘자이자 피아니스트이다.\n\n1974년 차이콥스키 국제 콩쿠르 피아노 부문 2위 입상으로 주목받았으며, 이후 지휘자로 전향하여 아시아인 최초로 세계적인 명성을 얻었다. 파리 바스티유 오페라, 로마 산타 체칠리아 오케스트라, 도쿄 필하모닉 오케스트라 등 주요 단체의 상임 지휘자를 역임했다.','부드럽고 유려한 지휘 스타일과 깊은 통찰력으로 오케스트라를 이끌며, 특히 낭만주의 레퍼토리와 오페라 해석에 탁월하다.',1000,80,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:26'),(236,'권헤이든','Haydn Kwon','pianist','Rising',NULL,NULL,NULL,'2001','South Korea','권헤이든(Haydn Kwon)은 2001년 대한민국 출생의 신예 피아니스트이다.\n\n국내외 콩쿠르에서 두각을 나타내며 차세대 피아니스트로 성장하고 있다. 섬세한 감성과 탁월한 기교를 겸비했다.','섬세하고 서정적인 터치와 깔끔한 해석을 바탕으로, 고전 및 낭만주의 레퍼토리를 주로 연주한다.',10,1,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:27'),(237,'백민경','Minkyung Baek','violinist','Rising',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features/02/8b/12/dj.lebfmdhi.jpg/600x600ac.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features/02/8b/12/dj.lebfmdhi.jpg/1200x1200ac.jpg','1998','South Korea','백민경(Minkyung Baek)은 1998년 대한민국 출생의 바이올리니스트이다.\n\n다수의 국내외 콩쿠르에서 수상하며 연주자로서의 경력을 쌓고 있다. 안정적인 기량과 풍부한 표현력으로 주목받고 있다.','균형 잡힌 테크닉과 따뜻한 음색으로, 대중에게 편안하면서도 깊이 있는 음악을 전달한다.',10,1,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:28'),(238,'나두리','Doori Na','violinist','Rising',NULL,'https://upload.wikimedia.org/wikipedia/commons/d/db/Laxmikant_Pyarelal.jpg','https://upload.wikimedia.org/wikipedia/commons/d/db/Laxmikant_Pyarelal.jpg','1995','South Korea','나두리(Doori Na)는 1995년 대한민국 출생의 바이올리니스트이다.\n\n솔로 활동뿐만 아니라 오케스트라 악장, 실내악 등 다양한 분야에서 활동하는 젊은 연주자이다. 폭넓은 음악적 스펙트럼을 소화한다.','정교하고 명료한 연주 스타일을 지녔으며, 작품에 대한 학구적인 접근을 통해 해석의 깊이를 더한다.',10,1,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:29'),(239,'김준찬','Junchan Kim','pianist','Rising',NULL,'https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages211/v4/db/62/5f/db625fc4-b4ea-9c5d-f84b-959c70224ef2/ami-identity-e67360b56d693689824ce48374539a0c-2025-10-22T09-46-12.410Z_cropped.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages211/v4/db/62/5f/db625fc4-b4ea-9c5d-f84b-959c70224ef2/ami-identity-e67360b56d693689824ce48374539a0c-2025-10-22T09-46-12.410Z_cropped.png/1200x1200bb.jpg','2003','South Korea','김준찬(Junchan Kim)은 2003년 대한민국 출생의 신예 피아니스트이다.\n\n어린 나이부터 국내외 콩쿠르에서 두각을 나타내며 큰 기대를 모으고 있다. 잠재력 있는 젊은 거장으로 성장 중이다.','역동적인 에너지와 섬세한 감수성이 공존하는 연주를 선보이며, 깊은 울림을 전달한다.',10,1,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:30'),(240,'황준호','David Hwang','pianist','B',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music122/v4/48/12/93/48129386-a5cf-68a8-08a1-3d7fb925843c/artwork.jpg/600x600ac.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music122/v4/48/12/93/48129386-a5cf-68a8-08a1-3d7fb925843c/artwork.jpg/1200x1200ac.jpg','1980','South Korea','황준호(David Hwang)는 1980년 대한민국 출생의 피아니스트이다.\n\n국내외에서 활발한 연주 및 교육 활동을 펼치고 있으며, 다양한 레퍼토리를 소화하는 실력파 아티스트이다. 특히 실내악 분야에서도 활발하게 활동한다.','견고한 기본기와 안정적인 연주력을 바탕으로, 클래식 음악의 정통성을 추구하는 스타일이다.',100,5,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:32'),(242,'송현아','Hyun-Ah Song','soprano','B',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features114/v4/e7/7f/32/e77f3229-c96d-0889-fd8f-b1d607128fca/pr_source.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features114/v4/e7/7f/32/e77f3229-c96d-0889-fd8f-b1d607128fca/pr_source.png/1200x1200bb.jpg','1985','South Korea','송현아(Hyun-Ah Song)는 1985년 대한민국 출생의 소프라노이다.\n\n국내외 오페라 무대와 콘서트에서 활발하게 활동하고 있다. 맑고 풍부한 음색과 뛰어난 연기력으로 호평받는다.','섬세한 감정선과 깨끗한 고음을 바탕으로, 특히 이탈리아 오페라 레퍼토리에 강점을 보인다.',100,5,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:34'),(243,'김태현','Taehyun Kim','violinist','Rising',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music71/v4/48/e8/ae/48e8ae0e-255b-854e-8187-55fadb01a8d0/886446154855.jpg/600x600ac.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music71/v4/48/e8/ae/48e8ae0e-255b-854e-8187-55fadb01a8d0/886446154855.jpg/1200x1200ac.jpg','2000','South Korea','김태현(Taehyun Kim)은 2000년 대한민국 출생의 바이올리니스트이다.\n\n젊은 나이에 국내외 콩쿠르에서 두각을 나타내며 주목받고 있다. 탄탄한 기본기와 개성 있는 음악 해석을 겸비했다.','뛰어난 테크닉과 음악적 해석의 깊이를 통해 고전과 낭만주의 작품을 세련되게 소화한다.',10,1,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:35'),(244,'이지윤','Ji-Yoon Lee','pianist','Rising',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music124/v4/2d/15/8b/2d158b12-e012-733f-3a64-ec7f3e698118/5060189560790.jpg/600x600ac.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music124/v4/2d/15/8b/2d158b12-e012-733f-3a64-ec7f3e698118/5060189560790.jpg/1200x1200ac.jpg','1997','South Korea','이지윤(Ji-Yoon Lee)은 1997년 대한민국 출생의 피아니스트이다.\n\n유럽 등 국제 무대에서 솔로 및 실내악 연주자로 활동하며 커리어를 쌓고 있다. 섬세하고 통찰력 있는 음악성을 보여준다.','명료한 타건과 지적인 해석이 돋보이며, 작품의 형식과 구조를 명확하게 표현하는 연주를 구사한다.',10,1,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:36'),(245,'배희철','Hee-Chul Bae','pianist','B',NULL,'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/Forestella%2C_Seoul_concert%2C_2019-07-21.jpg/500px-Forestella%2C_Seoul_concert%2C_2019-07-21.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/Forestella%2C_Seoul_concert%2C_2019-07-21.jpg/500px-Forestella%2C_Seoul_concert%2C_2019-07-21.jpg','1970','South Korea','배희철(Hee-Chul Bae)은 1970년 대한민국 출생의 피아니스트이다.\n\n국내 대학에서 후학을 양성하며, 활발한 연구 및 연주 활동을 병행하고 있다. 폭넓은 레퍼토리를 소화한다.','전통적이고 안정적인 연주 스타일을 지녔으며, 작품의 깊이 있는 감동을 전달하는 데 주력한다.',100,5,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:37'),(246,'김진희','Jinhee Kim','pianist','B',NULL,'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/Psy_performing_Gangnam_Style_at_the_Future_Music_Festival_2013.jpg/500px-Psy_performing_Gangnam_Style_at_the_Future_Music_Festival_2013.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/Psy_performing_Gangnam_Style_at_the_Future_Music_Festival_2013.jpg/500px-Psy_performing_Gangnam_Style_at_the_Future_Music_Festival_2013.jpg','1978','South Korea','김진희(Jinhee Kim)는 1978년 대한민국 출생의 피아니스트이다.\n\n국내외에서 솔로와 실내악 연주를 활발하게 펼치고 있다. 뛰어난 기교와 섬세한 표현력을 갖춘 연주자로 평가받는다.','유려한 테크닉과 더불어 풍부하고 다채로운 음색을 사용하여 작품의 낭만적 감성을 극대화한다.',100,5,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:38'),(247,'이택기','Taek Gi Lee','cellist','B',NULL,'https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/T.O.P_-_0.TO.10_in_Seoul_-_2.jpg/500px-T.O.P_-_0.TO.10_in_Seoul_-_2.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/T.O.P_-_0.TO.10_in_Seoul_-_2.jpg/500px-T.O.P_-_0.TO.10_in_Seoul_-_2.jpg','1985','South Korea','이택기(Taek Gi Lee)는 1985년 대한민국 출생의 첼리스트이다.\n\n유럽 등지에서 유학 후 국내외 무대에서 활동 중이다. 첼로의 깊고 풍부한 음색을 잘 살려내는 연주자이다.','따뜻하고 서정적인 톤과 안정적인 연주력을 바탕으로, 고전 및 낭만주의 첼로 레퍼토리를 소화한다.',100,5,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:39'),(248,'김문성','Mun-Sung Kim','violinist','B',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music211/v4/15/56/c1/1556c100-a20d-b569-1b92-bd1503c6766e/8809958969191_cover.jpg/600x600ac.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music211/v4/15/56/c1/1556c100-a20d-b569-1b92-bd1503c6766e/8809958969191_cover.jpg/1200x1200ac.jpg','1973','South Korea','김문성(Mun-Sung Kim)은 1973년 대한민국 출생의 바이올리니스트이다.\n\n국내 주요 오케스트라와의 협연 및 솔로 활동을 통해 관객과 소통하고 있다. 폭넓은 레퍼토리를 소화하는 숙련된 연주자이다.','정통적인 해석과 숙련된 테크닉을 바탕으로, 작품의 완성도와 음악적 균형을 중시하는 연주를 한다.',100,5,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:41'),(249,'이고르 레비트','Igor Levit','pianist','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages221/v4/7f/58/2f/7f582fc7-19f3-b7ee-3d0d-e9818c331427/96ac001f-33c4-4c2a-bbc6-9ad12e60a731_ami-identity-b8ef49662490d61e09b1b7e700149a1e-2024-09-26T15-58-23.412Z_cropped.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages221/v4/7f/58/2f/7f582fc7-19f3-b7ee-3d0d-e9818c331427/96ac001f-33c4-4c2a-bbc6-9ad12e60a731_ami-identity-b8ef49662490d61e09b1b7e700149a1e-2024-09-26T15-58-23.412Z_cropped.png/1200x1200bb.jpg','1987','Russia','이고르 레비트(Igor Levit)는 1987년 러시아 니즈니 노브고로드 출생의 피아니스트이다.\n\n2005년 루빈슈타인 국제 피아노 마스터 콩쿠르에서 2위 및 특별상을 수상했다. 특히 베토벤 소나타 전곡 연주와 난해한 현대 레퍼토리 해석에 탁월한 능력을 보여주며 평단의 극찬을 받았다.\n\n사회적 메시지를 담은 라이브 연주와 온라인 활동으로도 큰 영향력을 발휘하고 있다.','지적이고 혁신적인 해석, 완벽한 테크닉을 바탕으로, 작품의 구조와 철학적 깊이를 탐구하는 연주를 한다.',500,20,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:42'),(250,'머레이 페라이아','Murray Perahia','pianist','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/ba/b5/0b/bab50ba4-2931-28d2-352f-211ef2b7e9fe/mzl.rcjgzkgh.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/ba/b5/0b/bab50ba4-2931-28d2-352f-211ef2b7e9fe/mzl.rcjgzkgh.jpg/1200x1200bb.jpg','1947','USA','머레이 페라이아(Murray Perahia)는 1947년 미국 뉴욕 출생의 피아니스트이다.\n\n1972년 리즈 국제 피아노 콩쿠르에서 우승하며 세계적인 명성을 얻었다. 모차르트, 베토벤, 쇼팽, 슈만 등 고전 및 낭만주의 레퍼토리의 권위자로 손꼽힌다.\n\n지적이고 우아한 연주 스타일로 수많은 명반을 남겼으며, 그래미상을 여러 차례 수상했다.','맑고 섬세한 터치, 유려한 프레이징, 그리고 깊이 있는 서정성을 겸비한 우아하고 고전적인 연주를 구사한다.',1000,170,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:43'),(251,'표트르 안데르셰프스키','Piotr Anderszewski','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/1d/d0/9c/1dd09c2b-6eea-59b3-f9f2-e2fd513c758d/mzl.gmefymam.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/1d/d0/9c/1dd09c2b-6eea-59b3-f9f2-e2fd513c758d/mzl.gmefymam.jpg/1200x1200bb.jpg','1969','Poland','표트르 안데르셰프스키(Piotr Anderszewski)는 1969년 폴란드 바르샤바 출생의 피아니스트이다.\n\n1990년 리즈 국제 피아노 콩쿠르에서 결선 도중 연주를 중단하고 기권한 사건으로 유명해졌으며, 이후 독창적인 해석과 강한 개성으로 평단의 주목을 받았다. 특히 바흐, 베토벤, 슈만, 쇼팽 등에서 독자적인 영역을 구축했다.','강한 개성과 지적인 통찰을 바탕으로, 예측 불가능하면서도 논리적인 구조를 갖춘 독창적인 연주를 펼친다.',500,35,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:44'),(252,'라두 루푸','Radu Lupu','pianist','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/91/fb/f6/91fbf6cf-8092-5b83-0419-6d4f54bf3fac/mzl.ybxzpqun.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/91/fb/f6/91fbf6cf-8092-5b83-0419-6d4f54bf3fac/mzl.ybxzpqun.jpg/1200x1200bb.jpg','1945','Romania','라두 루푸(Radu Lupu)는 1945년 루마니아 갈라치 출생의 피아니스트이다.\n\n1966년 반 클라이번 국제 피아노 콩쿠르 우승, 1967년 조르주 에네스쿠 국제 콩쿠르 우승, 1969년 리즈 국제 피아노 콩쿠르 우승 등 최고의 콩쿠르를 석권했다. 은둔적인 사생활과 달리 깊고 서정적인 연주로 추앙받았다.\n\n특히 슈베르트, 모차르트, 브람스 연주에 있어 독보적인 해석을 보여주었다.','깊고 따뜻한 음색과 고요하면서도 강렬한 서정성을 바탕으로, 작품의 본질을 파고드는 철학적인 연주가 특징이다.',1000,40,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:45'),(253,'마르크 앙드레 아멜린','Marc-André Hamelin','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features114/v4/6a/cf/d1/6acfd1b1-ad0d-f778-0f0a-797d4a505cb8/mzl.zlrocpgv.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features114/v4/6a/cf/d1/6acfd1b1-ad0d-f778-0f0a-797d4a505cb8/mzl.zlrocpgv.png/1200x1200bb.jpg','1961','Canada','마르크 앙드레 아멜린(Marc-André Hamelin)은 1961년 캐나다 몬트리올 출생의 피아니스트이다.\n\n놀라운 기교와 폭넓은 레퍼토리, 특히 기술적으로 난해하거나 잘 알려지지 않은 작품들을 발굴하여 연주하는 것으로 유명하다. 하이페리온 레이블을 통해 수많은 음반을 발매했다.','경이적인 테크닉과 지적인 정확성을 바탕으로, 일반적인 레퍼토리부터 초절기교의 작품까지 완벽하게 소화한다.',500,140,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:46'),(254,'벤자민 그로스브너','Benjamin Grosvenor','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/4e/46/ac/4e46ac8d-2b69-ba3a-15b7-d128b9b75cb8/pr_source.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/4e/46/ac/4e46ac8d-2b69-ba3a-15b7-d128b9b75cb8/pr_source.png/1200x1200bb.jpg','1992','UK','벤자민 그로스브너(Benjamin Grosvenor)는 1992년 영국 출생의 피아니스트이다.\n\n2004년 BBC 영 뮤지션 오브 더 이어(Young Musician of the Year)에서 최연소 우승하며 주목받았다. 섬세한 터치와 서정적인 표현력이 돋보이는 연주로 세계 무대에서 활약하고 있다.','맑고 투명한 음색과 우아한 프레이징을 바탕으로, 낭만주의 레퍼토리에서 특히 뛰어난 감수성을 발휘한다.',100,25,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:47'),(255,'알렉산드르 멜니코프','Alexander Melnikov','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/46/eb/81/46eb8197-308b-ab24-ed62-a962d223cc42/mzl.dgdsnzmb.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/46/eb/81/46eb8197-308b-ab24-ed62-a962d223cc42/mzl.dgdsnzmb.jpg/1200x1200bb.jpg','1973','Russia','알렉산드르 멜니코프(Alexander Melnikov)는 1973년 러시아 모스크바 출생의 피아니스트이다.\n\n클라우디오 아바도의 초청으로 루체른 페스티벌에 데뷔했으며, 고전부터 현대까지의 방대한 레퍼토리를 시대악기와 현대악기를 오가며 연주하는 것으로 유명하다.','날카로운 지성과 학구적인 해석을 바탕으로, 역사적 고증을 중요시하는 동시에 생동감 있는 연주를 선보인다.',100,30,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:48'),(256,'비킹구르 올라프손','Víkingur Ólafsson','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages211/v4/3e/8c/7e/3e8c7ec4-7dbc-0a5d-7a9e-fef89f518660/ami-identity-201461d531a03d616263622fc83fd950-2025-10-15T07-43-36.782Z_cropped.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages211/v4/3e/8c/7e/3e8c7ec4-7dbc-0a5d-7a9e-fef89f518660/ami-identity-201461d531a03d616263622fc83fd950-2025-10-15T07-43-36.782Z_cropped.png/1200x1200bb.jpg','1984','IS','비킹구르 올라프손(Víkingur Ólafsson)은 1984년 아이슬란드 출생의 피아니스트이다.\n\n바흐, 모차르트 등 고전주의 레퍼토리를 독창적으로 재해석하여 큰 성공을 거두었으며, 도이치 그라모폰을 통해 발매한 앨범들로 전 세계적인 명성을 얻었다.','명료한 터치와 섬세한 페달링, 독창적인 프로그램 구성과 해석으로 현대적인 감각의 클래식을 선보인다.',100,40,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:50'),(257,'얀 리시에츠키','Jan Lisiecki','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features221/v4/fe/75/80/fe758056-0641-ea18-adc4-474fb5e06e40/mzl.zxdzbjed.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features221/v4/fe/75/80/fe758056-0641-ea18-adc4-474fb5e06e40/mzl.zxdzbjed.jpg/1200x1200bb.jpg','1995','Canada','얀 리시에츠키(Jan Lisiecki)는 1995년 캐나다 앨버타 출생의 폴란드계 피아니스트이다.\n\n어린 나이부터 세계적인 오케스트라와 협연하며 주목받았다. 특히 쇼팽과 모차르트 연주에 깊은 통찰을 보여주며, 도이치 그라모폰의 전속 아티스트로 활동하고 있다.','맑고 깨끗한 음색과 자연스러운 호흡을 바탕으로, 기교보다는 음악적 서정성을 강조하는 연주를 한다.',100,10,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:51'),(258,'킷 암스트롱','Kit Armstrong','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music125/v4/de/da/5b/deda5b37-9ddb-900a-3095-82fabc5a6226/pr_source.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music125/v4/de/da/5b/deda5b37-9ddb-900a-3095-82fabc5a6226/pr_source.png/1200x1200bb.jpg','1992','USA','킷 암스트롱(Kit Armstrong)은 1992년 미국 로스앤젤레스 출생의 피아니스트이자 작곡가이다.\n\n수학, 과학, 음악 등 다방면에 걸쳐 천재성을 보였으며, 알프레드 브렌델의 가르침을 받았다. 바흐와 모차르트 해석에 특히 정평이 나 있으며, 지적이고 사려 깊은 연주로 알려져 있다.','극도로 정교하고 분석적인 해석을 바탕으로, 작품의 구조와 논리를 명확하게 드러내는 학구적인 연주를 구사한다.',100,10,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:52'),(259,'프란체스코 피에몬테시','Francesco Piemontesi','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages126/v4/39/ad/f5/39adf507-b96f-68eb-f873-2e0e8379ece8/72b5ef2f-7bfd-400c-bb27-16d2d96318db_ami-identity-68dc49b42f30c5543dd93645f5022296-2023-03-21T09-36-01.931Z_cropped.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages126/v4/39/ad/f5/39adf507-b96f-68eb-f873-2e0e8379ece8/72b5ef2f-7bfd-400c-bb27-16d2d96318db_ami-identity-68dc49b42f30c5543dd93645f5022296-2023-03-21T09-36-01.931Z_cropped.png/1200x1200bb.jpg','1983','Switzerland','프란체스코 피에몬테시(Francesco Piemontesi)는 1983년 스위스 출생의 피아니스트이다.\n\n퀸 엘리자베스 콩쿠르 입상 후 국제적인 활동을 시작했으며, 특히 모차르트와 슈만 해석에 뛰어난 재능을 보여준다. 섬세한 터치와 깊은 서정성을 겸비했다.','섬세하고 투명한 음색을 바탕으로, 구조적인 명료함과 낭만적인 감수성을 조화시키는 연주를 선보인다.',100,20,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:53'),(260,'폴 루이스','Paul Lewis','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/4d/3c/83/4d3c8341-d009-628b-eee1-64ab1a5bff73/pr_source.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/4d/3c/83/4d3c8341-d009-628b-eee1-64ab1a5bff73/pr_source.png/1200x1200bb.jpg','1972','UK','폴 루이스(Paul Lewis)는 1972년 영국 리버풀 출생의 피아니스트이다.\n\n알프레드 브렌델의 제자로, 특히 베토벤 소나타 전곡 연주로 세계적인 명성을 얻었다. 그의 연주는 지적이고 깊이 있는 해석과 더불어 뛰어난 서정성이 특징이다.','지적이고 사려 깊은 해석, 깨끗하고 명료한 터치로, 고전 레퍼토리의 구조적 아름다움과 깊이를 표현한다.',500,40,NULL,'2025-11-20 05:35:45','2025-11-20 10:32:54'),(261,'스티븐 허프','Stephen Hough','pianist','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/d2/bf/18/d2bf1843-fd75-15ed-53f5-1df5388d85fb/mzl.bumevzyo.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/d2/bf/18/d2bf1843-fd75-15ed-53f5-1df5388d85fb/mzl.bumevzyo.png/1200x1200bb.jpg','1961','UK','스티븐 허프(Stephen Hough)는 1961년 영국 출생의 피아니스트, 작곡가, 작가이다.\n\n1983년 나움부르크 국제 피아노 콩쿠르 우승을 차지하며 국제적인 명성을 얻었다. 엄청난 기교와 더불어 지적이고 깊이 있는 해석으로 유명하며, 특히 잘 알려지지 않은 낭만주의 시대 레퍼토리 발굴에 힘쓰고 있다.\n\n맥아더 펠로우십 수상자이며, 여러 대학교에서 교수로 재직하고 있다.','완벽한 테크닉과 폭넓은 레퍼토리를 바탕으로, 지적이고 시대를 초월하는 독특한 해석을 선보인다.',1000,100,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:05'),(262,'장 에플람 바부제','Jean-Efflam Bavouzet','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/7d/95/f0/7d95f0ae-52b2-b680-1806-bcc2271fd02c/mzl.omzlvdsu.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/7d/95/f0/7d95f0ae-52b2-b680-1806-bcc2271fd02c/mzl.omzlvdsu.jpg/1200x1200bb.jpg','1962','France','장 에플람 바부제(Jean-Efflam Bavouzet)는 1962년 프랑스 출생의 피아니스트이다.\n\n1986년 쾰른 국제 피아노 콩쿠르 우승으로 주목받기 시작했다. 특히 드뷔시와 라벨 등 프랑스 레퍼토리와 베토벤, 하이든 같은 고전주의 레퍼토리 해석에 정평이 나 있다.\n\n솔로 활동 외에도 지휘자, 교육자로도 활발하게 활동하고 있다.','명쾌하고 깔끔한 터치, 그리고 작품의 구조와 색채를 섬세하게 드러내는 프랑스적인 연주 스타일을 지녔다.',500,65,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:06'),(263,'베르트랑 샤마유','Bertrand Chamayou','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/1a/81/a2/1a81a234-f96a-b8d4-5154-95544e73a049/mzl.hhdzwcsj.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/1a/81/a2/1a81a234-f96a-b8d4-5154-95544e73a049/mzl.hhdzwcsj.jpg/1200x1200bb.jpg','1981','France','베르트랑 샤마유(Bertrand Chamayou)는 1981년 프랑스 툴루즈 출생의 피아니스트이다.\n\n뛰어난 기교와 감수성으로 프랑스를 대표하는 젊은 피아니스트로 손꼽힌다. 쇼팽, 리스트, 라벨 등 다양한 레퍼토리에서 깊이 있는 해석을 보여주었다.\n\n프랑스 비크투아르 드 라 뮤지크 클래식 상을 여러 차례 수상했다.','강렬한 표현력과 화려한 테크닉을 구사하며, 특히 낭만주의와 프랑스 레퍼토리에서 다채로운 음색을 구현한다.',100,20,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:08'),(264,'레오니다스 카바코스','Leonidas Kavakos','violinist','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/2a/97/0d/2a970dab-e99b-e929-4d91-97f452a25224/mzl.qfdykcey.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/2a/97/0d/2a970dab-e99b-e929-4d91-97f452a25224/mzl.qfdykcey.jpg/1200x1200bb.jpg','1967','Greece','레오니다스 카바코스(Leonidas Kavakos)는 1967년 그리스 아테네 출생의 바이올리니스트이다.\n\n1985년 시벨리우스 국제 바이올린 콩쿠르 우승, 1988년 파가니니 국제 바이올린 콩쿠르 우승을 차지하며 세계적인 거장으로 인정받았다. 날카로운 지성과 완벽한 기교를 겸비했다.\n\n지휘자로도 활동하며 주요 오케스트라와 협연하고 있다.','정교하고 지적인 해석, 깨끗하고 밀도 높은 음색을 특징으로 하며, 특히 현대적인 통찰력이 돋보인다.',500,45,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:09'),(265,'야닌 얀센','Janine Jansen','violinist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features115/v4/a7/cb/7b/a7cb7b51-63d9-7423-a941-907603edb778/mzl.pxhetxua.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features115/v4/a7/cb/7b/a7cb7b51-63d9-7423-a941-907603edb778/mzl.pxhetxua.jpg/1200x1200bb.jpg','1978','Netherlands','야닌 얀센(Janine Jansen)은 1978년 네덜란드 수스트 출생의 바이올리니스트이다.\n\n(212번 항목과 중복된 정보이나, 요청에 따라 재작성한다.) 그녀의 연주는 강렬한 감정 표현과 동시에 세련되고 명료한 음색이 특징이다. 바흐부터 20세기 레퍼토리까지 폭넓게 소화한다.','맑고 투명한 음색과 강렬한 감정의 대비가 돋보이며, 레퍼토리에 대한 통찰력 있는 해석을 선보인다.',500,20,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:10'),(266,'미도리','Midori Goto','violinist','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/ca/74/30/ca7430d0-221c-3808-be71-3abac8946196/mzl.mcgapdca.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/ca/74/30/ca7430d0-221c-3808-be71-3abac8946196/mzl.mcgapdca.jpg/1200x1200bb.jpg','1971','Japan','미도리 고토(Midori Goto)는 1971년 일본 오사카 출생의 바이올리니스트이다.\n\n11세에 뉴욕 필하모닉과 데뷔하며 천재적인 재능으로 주목받았다. 이후 깊이 있는 음악성과 사회 공헌 활동을 병행하며 세계적인 명성을 유지하고 있다.\n\n특히 교육과 커뮤니티 활동에 헌신하는 것으로 잘 알려져 있다.','뛰어난 기교와 집중력을 바탕으로, 지적이고 섬세하며 감정의 절제를 통해 깊은 울림을 전달하는 연주를 한다.',1000,30,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:11'),(267,'이츠하크 펄만','Itzhak Perlman','violinist','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features221/v4/b6/a7/0d/b6a70dde-8ffd-3f74-f242-4a1eede509c9/mzl.mwmxmtgb.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features221/v4/b6/a7/0d/b6a70dde-8ffd-3f74-f242-4a1eede509c9/mzl.mwmxmtgb.png/1200x1200bb.jpg','1945','USA','이츠하크 펄만(Itzhak Perlman)은 1945년 이스라엘 텔아비브 출생의 바이올리니스트이자 지휘자이다.\n\n1964년 레번트릿 국제 콩쿠르 우승을 차지하며 세계적인 명성을 확립했다. 20세기 후반을 대표하는 바이올린의 거장 중 한 명으로, 따뜻하고 풍부한 음색, 완벽한 기교, 그리고 대중적인 인기를 동시에 겸비했다.\n\n음악 교육과 장애인 권익 향상에도 헌신하고 있다.','따뜻하고 인간적인 음색과 완벽한 기교, 그리고 깊은 서정성을 바탕으로 한 낭만적인 연주가 특징이다.',1000,370,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:12'),(268,'제임스 에인스','James Ehnes','violinist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/bf/99/e5/bf99e519-9eec-d7fe-b504-d23a8f0ffc55/mzl.qsnfqqto.jpeg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/bf/99/e5/bf99e519-9eec-d7fe-b504-d23a8f0ffc55/mzl.qsnfqqto.jpeg/1200x1200bb.jpg','1976','Canada','제임스 에인스(James Ehnes)는 1976년 캐나다 출생의 바이올리니스트이다.\n\n1994년 쉬프재단 영 아티스트 상(Young Artists Award)을 수상하며 주목받았다. 고전과 현대 레퍼토리 모두에 능하며, 특히 바흐의 무반주 소나타와 파르티타 연주로 호평을 받았다.\n\n다수의 그래미상과 주노상을 수상했다.','정확하고 깔끔한 기교와 투명한 음색을 바탕으로, 작품에 대한 학구적인 접근과 섬세한 표현을 결합한 연주를 한다.',500,85,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:13'),(269,'제니퍼 코','Jennifer Koh','violinist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features125/v4/1b/ee/97/1bee975e-82c3-1e69-b9ce-b870f9c86a4f/mzl.owvekfzk.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features125/v4/1b/ee/97/1bee975e-82c3-1e69-b9ce-b870f9c86a4f/mzl.owvekfzk.jpg/1200x1200bb.jpg','1976','USA','제니퍼 코(Jennifer Koh)는 1976년 미국 출생의 바이올리니스트이다.\n\n1994년 차이콥스키 국제 콩쿠르에서 은메달을 수상하며 주목받았다. 특히 현대 음악에 대한 깊은 헌신으로 알려져 있으며, 수많은 현대 작곡가들의 작품을 초연하고 위촉했다.\n\n자신이 직접 기획하는 프로젝트를 통해 클래식 음악의 경계를 넓히고 있다.','지적이고 열정적인 해석과 뛰어난 기교를 바탕으로, 특히 현대 음악의 복잡한 구조를 명확하게 드러낸다.',100,30,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:14'),(270,'다니엘 호프','Daniel Hope','violinist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages221/v4/6a/23/4d/6a234d39-8003-fd16-dd3d-955ba9fef980/file_cropped.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages221/v4/6a/23/4d/6a234d39-8003-fd16-dd3d-955ba9fef980/file_cropped.png/1200x1200bb.jpg','1974','UK','다니엘 호프(Daniel Hope)는 1974년 남아프리카 공화국 더반 출생의 바이올리니스트이다.\n\n메뉴힌에게 사사했으며, 베토벤, 브람스 등 주요 레퍼토리 외에도 잘 알려지지 않은 작품과 현대 작곡가들의 작품을 적극적으로 발굴하여 연주한다.\n\n크로노스 콰르텟의 멤버로 활동하기도 했으며, 2020년부터 취리히 오페라의 음악감독으로 활동하고 있다.','따뜻한 음색과 유려한 프레이징으로 깊은 서정성을 보여주며, 음악과 이야기를 결합하는 스토리텔링 능력이 뛰어나다.',500,50,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:16'),(271,'닝 펑','Ning Feng','violinist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features123/v4/35/55/15/355515ee-beab-0479-669f-78fa38d39cde/mzl.nmplnafc.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features123/v4/35/55/15/355515ee-beab-0479-669f-78fa38d39cde/mzl.nmplnafc.jpg/1200x1200bb.jpg','1981','China','닝 펑(Ning Feng)은 1981년 중국 출생의 바이올리니스트이다.\n\n2006년 파가니니 국제 바이올린 콩쿠르에서 우승하며 국제적인 명성을 얻었다. 그의 연주는 정교한 기교와 함께 동양적인 서정성이 융합된 것이 특징이다.\n\n현재 베를린에 거주하며 유럽과 아시아를 중심으로 활발히 활동하고 있다.','명료한 기교와 섬세한 감수성을 겸비했으며, 특히 낭만주의 협주곡에서 뛰어난 통찰력을 발휘한다.',100,10,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:17'),(272,'바이바 스크리데','Baiba Skride','violinist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features124/v4/b9/23/76/b9237665-b30c-3fe6-79a4-22bd9cdb73d8/mzl.rtiosnlm.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features124/v4/b9/23/76/b9237665-b30c-3fe6-79a4-22bd9cdb73d8/mzl.rtiosnlm.jpg/1200x1200bb.jpg','1981','LV','바이바 스크리데(Baiba Skride)는 1981년 라트비아 출생의 바이올리니스트이다.\n\n2001년 퀸 엘리자베스 콩쿠르 2위 입상을 통해 국제적인 경력을 쌓기 시작했다. 고전 레퍼토리부터 20세기 레퍼토리까지 폭넓은 음악적 스펙트럼을 소화한다.\n\n그녀의 두 여동생인 라우마와 라우나 역시 유명한 연주자이다.','정확하고 힘있는 연주와 깊은 음악적 성숙함을 보여주며, 균형감 있는 해석으로 정평이 나 있다.',100,25,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:18'),(273,'아우구스틴 하델리히','Augustin Hadelich','violinist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features115/v4/4c/44/3c/4c443c23-99a3-0210-dbf3-376a050e4101/mzl.dulefjkl.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features115/v4/4c/44/3c/4c443c23-99a3-0210-dbf3-376a050e4101/mzl.dulefjkl.jpg/1200x1200bb.jpg','1984','Germany','아우구스틴 하델리히(Augustin Hadelich)는 1984년 독일 출생의 바이올리니스트이다.\n\n2006년 인디애나폴리스 국제 바이올린 콩쿠르에서 우승하며 주목받았다. 서정적이면서도 지적인 해석, 뛰어난 기교로 전 세계 주요 오케스트라와 협연하고 있다.\n\n2016년 그래미상을 수상했다.','깨끗하고 투명한 음색과 뛰어난 테크닉, 그리고 섬세하고 사려 깊은 음악성을 결합한 연주가 특징이다.',100,25,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:19'),(274,'알리나 이브라기모바','Alina Ibragimova','violinist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/db/eb/bc/dbebbc3b-9b1a-d5e1-cbf7-80f1b67e79ef/mzl.kicprzae.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/db/eb/bc/dbebbc3b-9b1a-d5e1-cbf7-80f1b67e79ef/mzl.kicprzae.png/1200x1200bb.jpg','1985','Russia','알리나 이브라기모바(Alina Ibragimova)는 1985년 러시아 출생의 바이올리니스트이다.\n\n시대악기 연주와 현대 레퍼토리 모두에 능하며, 특히 바흐의 무반주 작품 해석에 정평이 나 있다. 지적이고 금욕적인 연주 스타일로 유명하다.\n\n솔로 활동 외에도 활발한 실내악 연주를 하고 있다.','정제되고 지적인 해석, 그리고 순수한 음색을 바탕으로 작품의 구조적 아름다움을 강조하는 연주를 한다.',100,20,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:20'),(275,'빌데 프랑','Vilde Frang','violinist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features221/v4/87/73/94/87739479-2ecc-f3d0-a083-2837c2c8ff13/mzl.bgbdvdjc.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features221/v4/87/73/94/87739479-2ecc-f3d0-a083-2837c2c8ff13/mzl.bgbdvdjc.jpg/1200x1200bb.jpg','1986','Norway','빌데 프랑(Vilde Frang)은 1986년 노르웨이 출생의 바이올리니스트이다.\n\n2012년 크레디트 스위스 영 아티스트 어워드(Credit Suisse Young Artist Award)를 수상하며 주목받았다. 스칸디나비아 악파 특유의 서정성과 냉철한 분석력을 겸비했다.\n\nEMI 클래식 레이블을 통해 다수의 음반을 발매했다.','강렬한 몰입감과 정제된 기교, 그리고 스칸디나비아의 정서를 담은 깊은 서정적인 연주를 선보인다.',100,30,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:21'),(276,'솔 가베타','Sol Gabetta','cellist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages211/v4/99/69/64/9969645c-93c0-199b-d069-745465e74b06/ami-identity-c253bb80ff647e42b6cd7bdbbf5fbdeb-2025-10-15T11-29-00.539Z_cropped.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages211/v4/99/69/64/9969645c-93c0-199b-d069-745465e74b06/ami-identity-c253bb80ff647e42b6cd7bdbbf5fbdeb-2025-10-15T11-29-00.539Z_cropped.png/1200x1200bb.jpg','1981','Argentina','솔 가베타(Sol Gabetta)는 1981년 아르헨티나 출생의 첼리스트이다.\n\n2004년 크레디트 스위스 영 아티스트 어워드를 수상하며 국제적인 주목을 받았다. 열정적인 연주와 아름다운 음색으로 전 세계 주요 오케스트라와 협연하고 있다.\n\n바로크 시대부터 현대 음악까지 폭넓은 레퍼토리를 소화한다.','활력 넘치고 열정적인 표현력과 따뜻하고 풍부한 첼로 음색을 극대화하는 낭만적인 연주가 특징이다.',100,20,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:22'),(277,'고티에 카푸송','Gautier Capuçon','cellist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features211/v4/2f/5c/b7/2f5cb7d2-229b-7720-be2d-f43ec181784e/mzl.kliupirj.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features211/v4/2f/5c/b7/2f5cb7d2-229b-7720-be2d-f43ec181784e/mzl.kliupirj.png/1200x1200bb.jpg','1981','France','고티에 카푸송(Gautier Capuçon)은 1981년 프랑스 출생의 첼리스트이다.\n\n프랑스를 대표하는 첼리스트 중 한 명으로, 그의 형인 르노 카푸송(Renaud Capuçon, 바이올리니스트)과 함께 활발한 실내악 활동을 펼쳤다. 세련되고 우아한 연주 스타일로 유명하다.','우아하고 세련된 프레이징과 깊고 풍부한 톤을 구사하며, 프랑스적인 감각의 서정성을 담은 연주를 한다.',100,25,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:23'),(278,'알반 게르하르트','Alban Gerhardt','cellist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features124/v4/c0/f7/d8/c0f7d8f1-6708-7ac7-fae0-d2debb5afc6e/mzl.dofyrqaj.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features124/v4/c0/f7/d8/c0f7d8f1-6708-7ac7-fae0-d2debb5afc6e/mzl.dofyrqaj.png/1200x1200bb.jpg','1969','Germany','알반 게르하르트(Alban Gerhardt)는 1969년 독일 출생의 첼리스트이다.\n\n1993년 레벤탈 콩쿠르(Lievenskonskors) 우승을 차지하며 주목받았다. 현대 음악에 대한 깊은 이해를 바탕으로 다양한 작품을 연주하며, 사회 참여적인 활동에도 적극적이다.','강렬한 몰입감과 섬세한 표현력을 겸비했으며, 고전부터 현대까지의 복잡한 레퍼토리를 능숙하게 소화한다.',100,20,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:25'),(279,'셰쿠 카네 메이슨','Sheku Kanneh-Mason','cellist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/ba/7c/bd/ba7cbd77-e6e2-4112-24a0-6dbadd2533bd/mzl.duffoemy.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/ba/7c/bd/ba7cbd77-e6e2-4112-24a0-6dbadd2533bd/mzl.duffoemy.jpg/1200x1200bb.jpg','1999','UK','셰쿠 카네 메이슨(Sheku Kanneh-Mason)은 1999년 영국 출생의 첼리스트이다.\n\n2016년 BBC 영 뮤지션 오브 더 이어(BBC Young Musician of the Year)에서 우승하며 주목받았으며, 해리 왕자와 메건 마클의 결혼식에서 연주하며 세계적인 인기를 얻었다.','따뜻하고 매력적인 음색과 깊은 서정성을 바탕으로, 클래식 음악의 대중적인 매력을 잘 보여주는 연주를 한다.',100,5,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:26'),(280,'장 기앙 케라스','Jean-Guihen Queyras','cellist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features211/v4/af/d6/45/afd6456d-5395-fc4b-897c-c51657de5108/mzl.clfnfdfz.jpeg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features211/v4/af/d6/45/afd6456d-5395-fc4b-897c-c51657de5108/mzl.clfnfdfz.jpeg/1200x1200bb.jpg','1967','France','장 기앙 케라스(Jean-Guihen Queyras)는 1967년 프랑스 출생의 첼리스트이다.\n\n고전 레퍼토리와 더불어 현대 음악, 시대악기 연주에 이르기까지 폭넓은 활동을 펼치고 있다. 지적이고 성찰적인 연주로 유명하며, 실내악과 솔로 활동을 병행한다.','정교하고 지적인 해석, 그리고 유연한 톤 변화를 통해 작품의 미묘한 뉘앙스를 탁월하게 표현한다.',500,65,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:27'),(281,'요하네스 모저','Johannes Moser','cellist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features115/v4/31/7c/44/317c44cd-d32a-fb2d-9d61-93656f799210/pr_source.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features115/v4/31/7c/44/317c44cd-d32a-fb2d-9d61-93656f799210/pr_source.png/1200x1200bb.jpg','1979','Germany','요하네스 모저(Johannes Moser)는 1979년 독일 출생의 첼리스트이다.\n\n2002년 차이콥스키 국제 콩쿠르에서 2위를 차지하며 국제적인 주목을 받았다. 강렬하고 카리스마 넘치는 연주 스타일로 유명하다.\n\n고전과 낭만주의 레퍼토리 외에도 20세기와 현대 음악 작품을 적극적으로 연주한다.','화려하고 역동적인 기교와 강렬한 표현력을 바탕으로, 작품에 대한 깊은 몰입과 개성적인 해석을 보여준다.',100,15,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:28'),(282,'트룰스 뫼르크','Truls Mørk','cellist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features112/v4/7d/63/90/7d6390c6-856a-78a4-f28b-60ea2ba5a8c7/mzl.wwoxaipu.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features112/v4/7d/63/90/7d6390c6-856a-78a4-f28b-60ea2ba5a8c7/mzl.wwoxaipu.jpg/1200x1200bb.jpg','1961','Norway','트룰스 뫼르크(Truls Mørk)는 1961년 노르웨이 출생의 첼리스트이다.\n\n1982년 차이콥스키 국제 콩쿠르 6위 등 다수의 국제 콩쿠르에서 수상했다. 북유럽 특유의 서정성과 깊이 있는 음악성을 겸비한 연주로 유명하다.','깊고 풍부한 첼로의 음색과 서정적인 감수성을 바탕으로, 특히 드보르자크, 쇼스타코비치 등 낭만/현대 레퍼토리에 강하다.',500,60,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:29'),(283,'키안 솔타니','Kian Soltani','cellist','Rising',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music115/v4/fa/fb/e3/fafbe389-cc25-042d-22cd-7c500d81a7fa/pr_source.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music115/v4/fa/fb/e3/fafbe389-cc25-042d-22cd-7c500d81a7fa/pr_source.png/1200x1200bb.jpg','1992','Austria','키안 솔타니(Kian Soltani)는 1992년 오스트리아 출생의 이란계 첼리스트이다.\n\n2017년 크레디트 스위스 영 아티스트 어워드를 수상하며 주목받았다. 솔로 및 실내악, 그리고 지휘자로도 활동하며 젊은 거장으로 성장하고 있다.','뛰어난 테크닉과 동양적인 서정성을 겸비했으며, 폭넓은 음역대와 감정 표현을 통해 강렬한 인상을 남긴다.',10,5,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:30'),(284,'카미유 토마','Camille Thomas','cellist','Rising',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features211/v4/14/6b/ec/146becfa-c716-fd5a-e488-bf1d03935639/mzl.sebbcivw.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features211/v4/14/6b/ec/146becfa-c716-fd5a-e488-bf1d03935639/mzl.sebbcivw.jpg/1200x1200bb.jpg','1988','France','카미유 토마(Camille Thomas)는 1988년 프랑스 출생의 첼리스트이다.\n\n독일에서 유학하며 경력을 쌓았고, 우아하고 섬세한 연주 스타일로 주목받고 있다. 특히 프랑스 레퍼토리와 낭만주의 작품에 강점을 보인다.','부드럽고 유려한 프레이징과 맑은 음색을 특징으로 하며, 여성 첼리스트 특유의 섬세한 감성을 표현한다.',10,5,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:31'),(285,'크리스티안 틸레만','Christian Thielemann','conductor','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/52/4c/38/524c38ee-679e-9232-636a-62b4e5b62556/mzl.qgavkovw.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/52/4c/38/524c38ee-679e-9232-636a-62b4e5b62556/mzl.qgavkovw.jpg/1200x1200bb.jpg','1959','Germany','크리스티안 틸레만(Christian Thielemann)은 1959년 독일 베를린 출생의 지휘자이다.\n\n특히 독일 낭만주의 레퍼토리, 바그너, 리하르트 슈트라우스 해석에 있어 현존하는 최고의 권위자로 손꼽힌다. 바이로이트 페스티벌과 빈 필하모닉 오케스트라 등 세계적인 무대에서 활동해 왔다.\n\n2025년부터 베를린 국립 오페라의 음악 총감독을 맡을 예정이다.','정통적인 독일 악파의 해석을 추구하며, 웅장하고 깊이 있는 사운드와 철학적인 통찰력을 통해 작품을 구현한다.',500,50,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:33'),(286,'안토니오 파파노','Antonio Pappano','conductor','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/b5/fb/0b/b5fb0b99-8fca-eb2e-8b0b-4dde9def549c/mzm.gkjcckin.jpeg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/b5/fb/0b/b5fb0b99-8fca-eb2e-8b0b-4dde9def549c/mzm.gkjcckin.jpeg/1200x1200bb.jpg','1959','UK','안토니오 파파노 경(Sir Antonio Pappano)은 1959년 영국 출생의 지휘자이다.\n\n로열 오페라 하우스 코번트 가든의 음악감독, 로마 산타 체칠리아 오케스트라의 음악감독 등을 역임한 오페라 및 오케스트라 지휘의 거장이다. 특히 이탈리아 오페라와 베르디, 푸치니 해석에 정평이 나 있다.','오페라 지휘 경험을 바탕으로 드라마틱하고 감성적인 표현이 풍부하며, 오케스트라로부터 뜨거운 에너지를 이끌어낸다.',1000,120,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:34'),(287,'이반 피셔','Iván Fischer','conductor','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/ee/9c/c6/ee9cc6fa-3194-532c-69ab-e4fbbad0a90a/mzl.lihjmcmh.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/ee/9c/c6/ee9cc6fa-3194-532c-69ab-e4fbbad0a90a/mzl.lihjmcmh.jpg/1200x1200bb.jpg','1951','Hungary','이반 피셔(Iván Fischer)는 1951년 헝가리 부다페스트 출생의 지휘자이자 작곡가이다.\n\n1983년 부다페스트 페스티벌 오케스트라를 공동 설립하고 이끌면서 세계적인 명성을 얻었다. 그의 지휘는 독창적인 해석과 앙상블의 섬세한 조율로 유명하다.','섬세한 디테일과 유머러스함을 겸비한 독창적인 해석이 특징이며, 특히 고전주의와 낭만주의 레퍼토리에서 깊이를 보여준다.',500,95,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:35'),(288,'마리스 얀손스','Mariss Jansons','conductor','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/7f/f8/68/7ff8688f-a422-d084-0da7-9baf1b6ccc45/mzl.zjqqofxf.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/7f/f8/68/7ff8688f-a422-d084-0da7-9baf1b6ccc45/mzl.zjqqofxf.jpg/1200x1200bb.jpg','1943','LV','마리스 얀손스(Mariss Jansons)는 1943년 라트비아 리가 출생의 지휘자이다.\n\n오슬로 필하모닉, 로열 콘세르트허바우 오케스트라, 바이에른 방송 교향악단 등 세계 최정상 오케스트라의 수석 지휘자를 역임하며 명성을 쌓았다. 특히 러시아와 낭만주의 레퍼토리에 강하다.','정교하고 균형 잡힌 해석, 그리고 강렬한 추진력을 바탕으로 오케스트라의 역동적인 사운드를 이끌어내는 거장이다.',1000,300,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:36'),(289,'발레리 게르기예프','Valery Gergiev','conductor','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/9e/43/f3/9e43f3fb-b670-3f5f-3038-d372009ce11f/mzl.qcgonpmf.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/9e/43/f3/9e43f3fb-b670-3f5f-3038-d372009ce11f/mzl.qcgonpmf.png/1200x1200bb.jpg','1953','Russia','발레리 게르기예프(Valery Gergiev)는 1953년 러시아 모스크바 출생의 지휘자이다.\n\n마린스키 극장의 예술 및 총감독을 역임하며 러시아 음악계를 이끌었다. 폭발적인 에너지와 카리스마 넘치는 지휘 스타일로 유명하며, 특히 러시아 오페라와 교향곡 해석에 정통하다.','강렬하고 즉흥적인 에너지, 그리고 러시아 음악 특유의 격정적인 감성을 극대화하는 카리스마 넘치는 지휘가 특징이다.',1000,150,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:37'),(290,'리카르도 샤이','Riccardo Chailly','conductor','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/66/df/f3/66dff301-00fd-131c-3d11-b2ecac744033/mzl.ebvqblor.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/66/df/f3/66dff301-00fd-131c-3d11-b2ecac744033/mzl.ebvqblor.png/1200x1200bb.jpg','1953','Italy','리카르도 샤이(Riccardo Chailly)는 1953년 이탈리아 밀라노 출생의 지휘자이다.\n\n베를린 방송 교향악단, 로열 콘세르트허바우 오케스트라, 라이프치히 게반트하우스 오케스트라 등 주요 오케스트라의 수석 지휘자를 역임했다. 오페라와 교향곡 모두에 능하며, 특히 말러, 브루크너 해석에 깊은 통찰을 보여준다.','정교하고 명확한 지휘와 더불어 이탈리아적인 감수성을 겸비했으며, 작품의 구조와 역동성을 섬세하게 표현한다.',1000,260,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:38'),(291,'키릴 페트렌코','Kirill Petrenko','conductor','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music123/v4/16/12/79/161279ae-d698-6164-5991-500bf3e3ceff/pr_source.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music123/v4/16/12/79/161279ae-d698-6164-5991-500bf3e3ceff/pr_source.png/1200x1200bb.jpg','1972','Russia','키릴 페트렌코(Kirill Petrenko)는 1972년 러시아 옴스크 출생의 지휘자이다.\n\n현재 베를린 필하모닉 오케스트라의 상임 지휘자를 맡고 있으며, 뛰어난 음악적 성숙함과 깊은 해석으로 현존하는 최고의 지휘자 중 한 명으로 평가받는다. 언론 노출을 극도로 꺼리는 것으로도 유명하다.','철저한 악보 분석과 디테일한 표현을 통해 오케스트라를 완벽하게 통제하며, 강렬한 몰입감과 깊이를 선사한다.',500,10,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:39'),(292,'프랑수아 자비에 로트','François-Xavier Roth','conductor','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/d5/a6/c4/d5a6c423-2683-35e1-d547-67729806a770/mzl.iutfymul.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/d5/a6/c4/d5a6c423-2683-35e1-d547-67729806a770/mzl.iutfymul.jpg/1200x1200bb.jpg','1971','France','프랑수아 자비에 로트(François-Xavier Roth)는 1971년 프랑스 파리 출생의 지휘자이다.\n\n현대 음악 전문 앙상블인 레 시에클(Les Siècles)을 창단하여 시대악기와 현대악기를 오가며 연주하는 혁신적인 접근을 시도하고 있다. 특히 프랑스 레퍼토리 해석에 정평이 나 있다.','역동적이고 혁신적인 지휘를 통해 작품의 역사적 맥락과 현대적 감각을 동시에 살려내는 실험적인 해석이 특징이다.',100,80,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:40'),(293,'안드리스 넬손스','Andris Nelsons','conductor','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/a0/f8/2f/a0f82f72-7315-560c-961e-60c6c86f0e27/mzl.efcqcwdt.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/a0/f8/2f/a0f82f72-7315-560c-961e-60c6c86f0e27/mzl.efcqcwdt.jpg/1200x1200bb.jpg','1978','LV','안드리스 넬손스(Andris Nelsons)는 1978년 라트비아 리가 출생의 지휘자이다.\n\n보스턴 심포니 오케스트라와 라이프치히 게반트하우스 오케스트라의 음악감독을 겸임하고 있다. 특히 브루크너, 말러, 쇼스타코비치 등 낭만주의 후기 레퍼토리에서 뛰어난 역량을 보여준다.','열정적이고 에너지 넘치는 지휘 스타일과 유려한 팔동작이 특징이며, 오케스트라로부터 웅장하고 깊은 사운드를 이끌어낸다.',500,95,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:42'),(294,'디아나 담라우','Diana Damrau','soprano','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features211/v4/91/f4/36/91f436b2-9c4c-ae2d-c8e3-9e8324b11c0d/mzl.akntcaic.jpeg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features211/v4/91/f4/36/91f436b2-9c4c-ae2d-c8e3-9e8324b11c0d/mzl.akntcaic.jpeg/1200x1200bb.jpg','1971','Germany','디아나 담라우(Diana Damrau)는 1971년 독일 출생의 소프라노이다.\n\n현존하는 최고의 리릭 콜로라투라 소프라노 중 한 명으로, 모차르트, 도니제티, 베르디 등 오페라 레퍼토리에서 완벽한 기교와 섬세한 연기력을 보여준다. 특히 밤의 여왕 역으로 유명하다.','완벽한 테크닉과 맑고 풍부한 음색, 그리고 무대를 장악하는 뛰어난 연기력을 겸비한 오페라의 여왕이다.',500,25,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:43'),(295,'르네 플레밍','Renée Fleming','soprano','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/64/ef/a7/64efa7fa-e8ab-ae47-0fbe-93e1a5e2c95e/mzl.tphhbxwh.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/64/ef/a7/64efa7fa-e8ab-ae47-0fbe-93e1a5e2c95e/mzl.tphhbxwh.png/1200x1200bb.jpg','1959','USA','르네 플레밍(Renée Fleming)은 1959년 미국 출생의 소프라노이다.\n\n현존하는 리릭 소프라노의 여왕으로 불리며, 모차르트, 리하르트 슈트라우스, 이탈리아 오페라 등 폭넓은 레퍼토리를 소화한다. 그녀의 따뜻하고 풍부한 목소리는 전 세계적으로 사랑받았다.','따뜻하고 벨벳 같은 음색과 우아하고 섬세한 프레이징을 바탕으로, 깊은 서정성과 음악적 성숙함을 보여준다.',1000,100,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:44'),(296,'프리티 옌데','Pretty Yende','soprano','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features124/v4/0a/4f/1d/0a4f1d82-4fec-8159-aa2d-7b082fde0b0a/mzl.crsouvrs.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features124/v4/0a/4f/1d/0a4f1d82-4fec-8159-aa2d-7b082fde0b0a/mzl.crsouvrs.jpg/1200x1200bb.jpg','1985','South Africa','프리티 옌데(Pretty Yende)는 1985년 남아프리카 공화국 출생의 소프라노이다.\n\n비오티 국제 콩쿠르 우승 등 다수의 국제 콩쿠르에서 수상하며 주목받았다. 메트로폴리탄 오페라, 라 스칼라 등 주요 오페라 극장에서 활약하며, 콜로라투라 레퍼토리에 강점을 보인다.','화려한 기교와 맑고 청아한 음색, 그리고 폭발적인 에너지를 바탕으로 오페라 무대에서 강렬한 인상을 남긴다.',100,10,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:45'),(297,'사비네 드비엘헤','Sabine Devieilhe','soprano','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/cf/8a/e8/cf8ae871-e523-1fac-dc6b-428980f7807e/mzl.msdwxxuq.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/cf/8a/e8/cf8ae871-e523-1fac-dc6b-428980f7807e/mzl.msdwxxuq.jpg/1200x1200bb.jpg','1985','France','사비네 드비엘헤(Sabine Devieilhe)는 1985년 프랑스 출생의 소프라노이다.\n\n프랑스 레퍼토리와 모차르트 오페라에서 탁월한 기량을 보여주는 콜로라투라 소프라노이다. 그녀의 섬세하고 가벼운 음색은 바로크와 초기 낭만주의 작품에 적합하다.','맑고 가벼운 음색과 뛰어난 콜로라투라 기교를 바탕으로, 특히 프랑스 바로크와 모차르트 작품에서 독보적인 영역을 구축했다.',100,25,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:46'),(298,'알렉산드라 쿠르작','Aleksandra Kurzak','soprano','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features125/v4/61/24/2c/61242c4a-c827-bf12-4a67-5a584e6fc1b1/mzl.jhfqigyr.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features125/v4/61/24/2c/61242c4a-c827-bf12-4a67-5a584e6fc1b1/mzl.jhfqigyr.jpg/1200x1200bb.jpg','1977','Poland','알렉산드라 쿠르작(Aleksandra Kurzak)은 1977년 폴란드 출생의 소프라노이다.\n\n메트로폴리탄 오페라, 로열 오페라 하우스 등 세계 주요 오페라 극장에서 주역으로 활약하고 있다. 벨칸토 및 이탈리아 오페라 레퍼토리에 강점을 보인다.','화려하고 유연한 콜로라투라 기교와 따뜻한 리릭 음색을 겸비했으며, 특히 도니제티와 푸치니 작품에서 뛰어나다.',100,10,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:47'),(299,'마리아 아그레스타','Maria Agresta','soprano','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music211/v4/ce/c3/e9/cec3e98b-7f18-b0f0-bc6e-04de36b3939c/196871960489.jpg/600x600ac.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music211/v4/ce/c3/e9/cec3e98b-7f18-b0f0-bc6e-04de36b3939c/196871960489.jpg/1200x1200ac.jpg','1975','Italy','마리아 아그레스타(Maria Agresta)는 1975년 이탈리아 출생의 소프라노이다.\n\n이탈리아를 대표하는 리릭 소프라노 중 한 명으로, 라 스칼라, 메트로폴리탄 오페라 등 주요 무대에서 베르디, 푸치니 등 이탈리아 오페라의 주역을 맡고 있다.','풍부하고 드라마틱한 리릭 음색과 뜨거운 감정 표현을 바탕으로, 특히 베르디와 푸치니 오페라에서 압도적인 존재감을 드러낸다.',100,10,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:48'),(300,'요나스 카우프만','Jonas Kaufmann','tenor','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/7d/7e/76/7d7e76c2-65b0-febd-6e2d-96238d7997d5/pr_source.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/7d/7e/76/7d7e76c2-65b0-febd-6e2d-96238d7997d5/pr_source.png/1200x1200bb.jpg','1969','Germany','요나스 카우프만(Jonas Kaufmann)은 1969년 독일 뮌헨 출생의 테너이다.\n\n현존하는 최고의 테너 중 한 명으로 평가받으며, 이탈리아, 프랑스, 독일 레퍼토리를 아우르는 폭넓은 스펙트럼을 소화한다. 그의 어둡고 풍부한 음색과 뛰어난 연기력은 독보적이다.','어둡고 풍부한 음색과 드라마틱한 표현력, 그리고 완벽한 발음과 연기력을 겸비한 드라마틱 테너의 표본이다.',500,60,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:50'),(301,'후안 디에고 플로레스','Juan Diego Flórez','tenor','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features125/v4/65/30/60/653060a0-e67b-d223-5a1b-260576b6a421/mzl.vqxwbgoc.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features125/v4/65/30/60/653060a0-e67b-d223-5a1b-260576b6a421/mzl.vqxwbgoc.jpg/1200x1200bb.jpg','1973','PE','후안 디에고 플로레스(Juan Diego Flórez)는 1973년 페루 리마 출생의 테너이다.\n\n로시니, 도니제티, 벨리니 등 벨칸토 레퍼토리의 권위자로, 특히 하이 C(고음 C)를 완벽하게 소화하는 콜로라투라 기교로 유명하다. 현존하는 최고의 레제로 테너로 손꼽힌다.','맑고 경쾌한 음색과 놀라운 콜로라투라 기교를 바탕으로, 벨칸토 오페라에서 독보적인 영역을 구축했다.',500,30,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:51'),(302,'피오트르 베차와','Piotr Beczała','tenor','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features125/v4/d9/01/be/d901be1f-15b2-a7fa-0df0-2793a744a27d/pr_source.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features125/v4/d9/01/be/d901be1f-15b2-a7fa-0df0-2793a744a27d/pr_source.png/1200x1200bb.jpg','1969','Poland','피오트르 베차와(Piotr Beczała)는 1969년 폴란드 출생의 테너이다.\n\n세계 주요 오페라 극장에서 이탈리아와 프랑스 오페라의 주역으로 활약하고 있다. 그의 따뜻하고 서정적인 리릭 테너 음색은 전 세계적으로 사랑받고 있다.','따뜻하고 서정적인 리릭 테너 음색과 우아하고 정확한 발성을 바탕으로, 벨칸토와 낭만주의 오페라에 강점을 보인다.',500,20,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:52'),(303,'마이클 파비아노','Michael Fabiano','tenor','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features113/v4/58/5c/5a/585c5a19-8727-e75b-a609-5f88cad69069/mzl.rudotdli.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features113/v4/58/5c/5a/585c5a19-8727-e75b-a609-5f88cad69069/mzl.rudotdli.jpg/1200x1200bb.jpg','1984','USA','마이클 파비아노(Michael Fabiano)는 1984년 미국 출생의 테너이다.\n\n도밍고 국제 성악 콩쿠르 우승 등 주요 콩쿠르에서 수상하며 주목받았다. 강렬한 에너지와 뛰어난 가창력으로 이탈리아 오페라의 주역으로 활약하고 있다.','역동적이고 힘있는 목소리와 드라마틱한 표현력을 바탕으로, 이탈리아 낭만주의 오페라에서 깊은 인상을 남긴다.',100,5,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:53'),(304,'하비에르 카마레나','Javier Camarena','tenor','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features124/v4/57/82/6b/57826b9a-e249-0e3d-949e-bf4bfad2ba98/mzl.gvmsdrna.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features124/v4/57/82/6b/57826b9a-e249-0e3d-949e-bf4bfad2ba98/mzl.gvmsdrna.jpg/1200x1200bb.jpg','1976','Mexico','하비에르 카마레나(Javier Camarena)는 1976년 멕시코 출생의 테너이다.\n\n콜로라투라 테너로, 후안 디에고 플로레스의 뒤를 잇는 벨칸토 오페라의 전문가로 평가받는다. 특히 하이 C를 비롯한 고음을 쉽게 소화하는 뛰어난 기교를 지녔다.','맑고 날카로운 음색과 놀라운 고음 처리 능력을 바탕으로, 로시니와 도니제티 등 벨칸토 레퍼토리의 최고봉이다.',100,5,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:54'),(305,'엠마누엘 파위','Emmanuel Pahud','flutist','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/c6/79/63/c67963df-a1e1-d3f6-7a14-4be182d68082/mzl.eqvnobqi.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/c6/79/63/c67963df-a1e1-d3f6-7a14-4be182d68082/mzl.eqvnobqi.jpg/1200x1200bb.jpg','1970','Switzerland','엠마누엘 파위(Emmanuel Pahud)는 1970년 스위스 제네바 출생의 플루티스트이다.\n\n1992년 제네바 국제 음악 콩쿠르 우승을 차지했으며, 22세의 나이에 베를린 필하모닉 오케스트라의 수석 플루티스트로 임명되며 세계적인 명성을 얻었다. 솔로이스트로도 활발히 활동하고 있다.','맑고 우아하며 완벽한 테크닉을 바탕으로, 플루트 특유의 섬세함과 화려함을 동시에 구현하는 연주를 한다.',500,70,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:55'),(306,'샤론 베잘리','Sharon Bezaly','flutist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features122/v4/44/6a/9f/446a9f93-13ef-ac10-c69c-26dfc7930c27/mzl.rdkbthqp.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features122/v4/44/6a/9f/446a9f93-13ef-ac10-c69c-26dfc7930c27/mzl.rdkbthqp.png/1200x1200bb.jpg','1972','Israel','샤론 베잘리(Sharon Bezaly)는 1972년 이스라엘 텔아비브 출생의 플루티스트이다.\n\nBIS 레이블을 통해 수많은 음반을 발매했으며, 특히 현대 작곡가들의 작품을 위촉하고 초연하는 등 현대 음악에 대한 공헌도가 높다.','강렬한 표현력과 따뜻한 음색을 바탕으로, 고전부터 현대까지의 다양한 레퍼토리를 섬세하게 해석한다.',100,45,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:56'),(307,'알브레히트 마이어','Albrecht Mayer','oboist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/93/9f/29/939f292c-6cbf-bd04-b814-c0c8f150971d/mzl.nwxaitqh.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/93/9f/29/939f292c-6cbf-bd04-b814-c0c8f150971d/mzl.nwxaitqh.jpg/1200x1200bb.jpg','1965','Germany','알브레히트 마이어(Albrecht Mayer)는 1965년 독일 에를랑겐 출생의 오보이스트이다.\n\n베를린 필하모닉 오케스트라의 수석 오보이스트로 활동하며 세계적인 명성을 얻었다. 오보에를 독주 악기로서 대중화하는 데 기여했다.','오보에의 따뜻하고 감미로운 음색을 극대화하며, 깊은 서정성과 유려한 표현력이 돋보이는 연주를 한다.',100,35,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:58'),(308,'마르틴 프뢰스트','Martin Fröst','clarinetist','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features125/v4/a9/c2/a2/a9c2a239-a19a-4159-0b31-a3567a72e826/mzl.vtzrcqul.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features125/v4/a9/c2/a2/a9c2a239-a19a-4159-0b31-a3567a72e826/mzl.vtzrcqul.jpg/1200x1200bb.jpg','1970','Sweden','마르틴 프뢰스트(Martin Fröst)는 1970년 스웨덴 출생의 클라리네티스트이다.\n\n세계적인 독주자로 활발히 활동하며, 클라리넷 독주 레퍼토리의 지평을 넓혔다는 평가를 받는다. 무대 연출과 퍼포먼스를 결합한 혁신적인 공연으로도 유명하다.','놀라운 기교와 다채로운 음색, 그리고 연극적인 요소를 결합하여 클라리넷 연주의 새로운 가능성을 보여준다.',500,40,NULL,'2025-11-20 05:35:45','2025-11-20 10:34:59'),(309,'자비네 마이어','Sabine Meyer','clarinetist','S',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/7d/b2/72/7db27289-bcf8-5fc2-6b40-1284071d4f18/mzl.cyqtylfr.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features126/v4/7d/b2/72/7db27289-bcf8-5fc2-6b40-1284071d4f18/mzl.cyqtylfr.jpg/1200x1200bb.jpg','1959','Germany','자비네 마이어(Sabine Meyer)는 1959년 독일 출생의 클라리네티스트이다.\n\n베를린 필하모닉 오케스트라의 수석 클라리네티스트를 역임하며 여성 관악기 연주자로서 세계적인 명성을 얻었다. 솔로이스트로서도 활발히 활동하며 클라리넷 레퍼토리 확장에 기여했다.','맑고 깨끗한 음색과 완벽한 기교, 그리고 고전주의 레퍼토리에서 깊이 있는 통찰력을 보여주는 정통 연주자이다.',1000,60,NULL,'2025-11-20 05:35:45','2025-11-20 10:35:00'),(310,'바딤 홀로덴코','Vadym Kholodenko','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/9b/e3/18/9be31808-7a61-262b-acf7-049d34fcf3f5/mzl.fbvqelob.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features116/v4/9b/e3/18/9be31808-7a61-262b-acf7-049d34fcf3f5/mzl.fbvqelob.jpg/1200x1200bb.jpg','1986','Ukraine','바딤 홀로덴코(Vadym Kholodenko)는 1986년 우크라이나 출생의 피아니스트이다.\n\n2013년 반 클라이번 국제 피아노 콩쿠르에서 우승하며 국제적인 명성을 얻었다. 그의 연주는 뛰어난 기교와 더불어 깊이 있는 음악성을 겸비했다는 평가를 받는다.','강렬한 타건과 폭발적인 에너지, 그리고 러시아 악파 특유의 뜨거운 감성을 담아내는 역동적인 연주를 한다.',100,10,NULL,'2025-11-20 05:35:45','2025-11-20 10:35:01'),(311,'베아트리체 라나','Beatrice Rana','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features211/v4/11/b0/59/11b059d1-5488-9bb7-a776-4bd9de763b21/mzl.tzfuebvh.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features211/v4/11/b0/59/11b059d1-5488-9bb7-a776-4bd9de763b21/mzl.tzfuebvh.jpg/1200x1200bb.jpg','1993','Italy','베아트리체 라나(Beatrice Rana)는 1993년 이탈리아 출생의 피아니스트이다.\n\n2011년 몬트리올 국제 콩쿠르 우승, 2013년 반 클라이번 국제 피아노 콩쿠르에서 은메달을 수상하며 주목받았다. 이탈리아를 대표하는 젊은 거장 중 한 명으로 손꼽힌다.','뛰어난 테크닉과 섬세한 감수성을 바탕으로, 고전과 낭만주의 레퍼토리를 지적이면서도 열정적으로 해석한다.',100,10,NULL,'2025-11-20 05:35:45','2025-11-20 10:35:02'),(312,'하오첸 장','Haochen Zhang','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features122/v4/4b/9f/ed/4b9fedd2-9cb3-b243-2cc9-bb6c615e32f6/mzl.ecgtlncz.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features122/v4/4b/9f/ed/4b9fedd2-9cb3-b243-2cc9-bb6c615e32f6/mzl.ecgtlncz.png/1200x1200bb.jpg','1990','China','하오첸 장(Haochen Zhang)은 1990년 중국 상하이 출생의 피아니스트이다.\n\n2009년 반 클라이번 국제 피아노 콩쿠르에서 공동 우승하며 국제적인 명성을 얻었다. 그의 연주는 깊이 있는 통찰력과 놀라운 기교를 겸비했다.','정확하고 명료한 터치와 더불어 깊은 서정성을 보여주며, 작품에 대한 학구적인 접근을 통해 균형 잡힌 연주를 한다.',100,10,NULL,'2025-11-20 05:35:45','2025-11-20 10:35:03'),(313,'드미트리 마슬레예프','Dmitri Masleev','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music122/v4/05/1e/ee/051eee53-c6d1-67a8-c76a-00d85ad2768e/pr_source.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music122/v4/05/1e/ee/051eee53-c6d1-67a8-c76a-00d85ad2768e/pr_source.png/1200x1200bb.jpg','1987','Russia','드미트리 마슬레예프(Dmitri Masleev)는 1987년 러시아 울란우데 출생의 피아니스트이다.\n\n2015년 차이콥스키 국제 콩쿠르에서 우승하며 국제적인 명성을 얻었다. 그의 연주는 뛰어난 기교와 풍부한 음악성, 그리고 러시아 피아니즘의 전통을 잇는 것으로 평가받는다.','화려하고 압도적인 테크닉과 폭발적인 에너지, 그리고 러시아 악파 특유의 뜨거운 감성을 결합한 연주가 특징이다.',100,10,NULL,'2025-11-20 05:35:45','2025-11-20 10:35:58'),(314,'조지 리','George Li','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features114/v4/38/9e/7a/389e7ab5-6a73-4fc6-6e87-ef966ec51450/mzl.jgrpjxoi.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features114/v4/38/9e/7a/389e7ab5-6a73-4fc6-6e87-ef966ec51450/mzl.jgrpjxoi.jpg/1200x1200bb.jpg','1995','USA','조지 리(George Li)는 1995년 미국 보스턴 출생의 피아니스트이다.\n\n2015년 차이콥스키 국제 콩쿠르에서 은메달을 수상하며 주목받았다. 명석하고 깔끔한 해석과 뛰어난 테크닉을 겸비한 젊은 거장이다.','정확하고 지적인 해석, 그리고 청명하고 깨끗한 음색을 바탕으로 고전주의와 낭만주의 레퍼토리에 강점을 보인다.',100,5,NULL,'2025-11-20 05:35:45','2025-11-20 10:35:59'),(315,'루카시 본드라체크','Lukáš Vondráček','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Music/de/7f/ea/mzi.ymuwanxs.jpg/600x600ac.jpg','https://is1-ssl.mzstatic.com/image/thumb/Music/de/7f/ea/mzi.ymuwanxs.jpg/1200x1200ac.jpg','1986','Czech Republic','루카시 본드라체크(Lukáš Vondráček)는 1986년 체코 출생의 피아니스트이다.\n\n2016년 퀸 엘리자베스 콩쿠르에서 우승하며 국제적인 명성을 확립했다. 일찍이 신동으로 불렸으며, 강렬한 에너지와 깊이 있는 음악성을 겸비했다.','파워풀하고 거침없는 타건과 함께 깊은 서정성을 표현하며, 광범위한 레퍼토리를 자유자재로 구사한다.',100,10,NULL,'2025-11-20 05:35:45','2025-11-20 10:36:00'),(316,'에릭 루','Eric Lu','pianist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages116/v4/0f/b5/3f/0fb53f9c-07db-5aef-56e7-6af8241a5ccb/90e4caee-091d-490d-89e5-7041071e565d_file_cropped.png/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/AMCArtistImages116/v4/0f/b5/3f/0fb53f9c-07db-5aef-56e7-6af8241a5ccb/90e4caee-091d-490d-89e5-7041071e565d_file_cropped.png/1200x1200bb.jpg','1997','USA','에릭 루(Eric Lu)는 1997년 미국 출생의 피아니스트이다.\n\n2018년 리즈 국제 피아노 콩쿠르에서 우승하며 세계적인 주목을 받았다. 절제된 감정과 깊이 있는 해석으로 호평받는다.','명징하고 깊이 있는 터치, 그리고 고전주의적인 절제미를 바탕으로 작품의 구조와 통찰력을 드러내는 연주를 한다.',100,5,NULL,'2025-11-20 05:35:45','2025-11-20 10:36:01'),(317,'티안와 양','Tianwa Yang','violinist','A',NULL,'https://is1-ssl.mzstatic.com/image/thumb/Features125/v4/21/4a/c5/214ac54d-07ae-58c2-1eba-b032606d2bfc/mzl.qpifdsnr.jpg/600x600bb.jpg','https://is1-ssl.mzstatic.com/image/thumb/Features125/v4/21/4a/c5/214ac54d-07ae-58c2-1eba-b032606d2bfc/mzl.qpifdsnr.jpg/1200x1200bb.jpg','1987','China','티안와 양(Tianwa Yang)은 1987년 중국 베이징 출생의 바이올리니스트이다.\n\n13세에 중국 중앙 음악원에서 최연소로 입학했으며, 파가니니의 카프리스 전곡 녹음 등 어려운 레퍼토리를 완벽하게 소화하여 주목받았다.','정확하고 화려한 기교를 바탕으로, 특히 고난도의 테크닉이 요구되는 작품에서 뛰어난 역량을 보여준다.',100,20,NULL,'2025-11-20 05:35:45','2025-11-20 10:36:02'),(318,'베를린 필하모닉 오케스트라','Berlin Philharmonic Orchestra','orchestra','S',0.0,'https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse1.mm.bing.net%2Fth%2Fid%2FOIP.5uxAHcrPbZgeNmJIBZW2swHaD4%3Fpid%3DApi&f=1&ipt=6e1a8b0d3810c1f22f6004560b6ca513c05c7bd015707de3e4641e9f5c958963&ipo=images','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse1.mm.bing.net%2Fth%2Fid%2FOIP.ICvFrLFxuCUZbH_0EcSargHaEK%3Fpid%3DApi&f=1&ipt=14cc64a587eb476bc38b85780dadb507694a91e264e7b3b6ec86434c788f2702&ipo=images','1882','Germany','베를린 필하모닉 오케스트라(Berlin Philharmonic Orchestra, BPO)는 1882년 독일 베를린에서 창단된 세계 최정상급 오케스트라이다.\n\n헤르베르트 폰 카라얀, 클라우디오 아바도, 사이먼 래틀 등 세계적인 거장들을 상임 지휘자로 배출했다. 독일 고전주의 및 낭만주의 레퍼토리 해석에 있어 독보적인 존재이다.','금관악기 그룹이 특히 발달하여 웅장하고 풍부한 \'베를린 필하모닉 사운드\'로 알려져 있으며, 강렬한 표현력과 유연한 앙상블을 자랑한다.',10000,1000,NULL,'2025-11-20 05:35:47','2025-11-20 11:15:05'),(319,'빈 필하모닉 오케스트라','Vienna Philharmonic Orchestra','orchestra','S',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Wiener_Philharmoniker_logo.svg/500px-Wiener_Philharmoniker_logo.svg.png','https://i.namu.wiki/i/fD-WIN2aD_JLecTELWDqqae-MYK4N0j8zxCgxRYSqeOsz4xsNdi_G7I9xOQYw9mYD5ssygz9NEMB5_ZDGvXziVX5ca-bDluICReYAFYTAt36n5wwpGJYfjg0SZBi_kD2xGUlj28XRss2R-q-TNi_mg.webp','1842','Austria','빈 필하모닉 오케스트라(Vienna Philharmonic Orchestra, VPO)는 1842년 오스트리아 빈에서 창단된 세계 최정상급 오케스트라이다.\n\n오케스트라 단원들이 빈 국립 오페라 극장의 단원으로만 구성되는 독특한 시스템을 유지하고 있다. 빈 특유의 섬세하고 우아한 사운드로 유명하며, 특히 모차르트, 베토벤, 브람스 등 오스트리아-독일 레퍼토리에 강하다.','현악기의 섬세하고 유려한 음색이 특징이며, 우아하고 자연스러운 프레이징으로 빈 전통의 낭만주의적 사운드를 구현한다.',10000,1000,NULL,'2025-11-20 05:35:47','2025-11-20 11:15:50'),(320,'런던 심포니 오케스트라','London Symphony Orchestra','orchestra','A',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/London_Barbican_Hall_LSO_b.jpg/500px-London_Barbican_Hall_LSO_b.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/London_Barbican_Hall_LSO_b.jpg/500px-London_Barbican_Hall_LSO_b.jpg','1904','UK','런던 심포니 오케스트라(London Symphony Orchestra, LSO)는 1904년 영국 런던에서 창단된 세계적인 오케스트라이다.\n\n영국의 대표적인 교향악단 중 하나로, 영화 음악 녹음 등 다양한 활동을 통해 대중적인 인지도가 높다. 혁신적인 프로그램과 유연한 연주력으로 유명하다.','유연하고 다재다능한 연주 스타일을 지녔으며, 특히 20세기 이후의 근대/현대 음악과 영화 음악에서 뛰어난 역량을 보인다.',10000,500,NULL,'2025-11-20 05:35:47','2025-11-20 11:16:06'),(321,'로열 콘세르트허바우 오케스트라','Royal Concertgebouw Orchestra','orchestra','S',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Concertgebouw_in_Amsterdam_April_2015.jpg/500px-Concertgebouw_in_Amsterdam_April_2015.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Concertgebouw_in_Amsterdam_April_2015.jpg/500px-Concertgebouw_in_Amsterdam_April_2015.jpg','1888','Netherlands','로열 콘세르트허바우 오케스트라(Royal Concertgebouw Orchestra, RCO)는 1888년 네덜란드 암스테르담에서 창단된 세계 최정상급 오케스트라이다.\n\n콘세르트허바우 홀의 뛰어난 음향과 결합하여 풍부하고 유기적인 사운드를 자랑한다. 특히 말러 해석의 권위 있는 악단 중 하나이다.','따뜻하고 부드러운 현악 앙상블과 깊이 있는 사운드가 특징이며, 유려하고 유기적인 흐름을 강조하는 연주를 한다.',10000,500,NULL,'2025-11-20 05:35:47','2025-11-20 11:16:18'),(322,'뉴욕 필하모닉','New York Philharmonic','orchestra','S',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/New_York_Philharmonic_at_Avery_Fisher_Hall_%287230083424%29_%28cropped%29.jpg/500px-New_York_Philharmonic_at_Avery_Fisher_Hall_%287230083424%29_%28cropped%29.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/New_York_Philharmonic_at_Avery_Fisher_Hall_%287230083424%29_%28cropped%29.jpg/500px-New_York_Philharmonic_at_Avery_Fisher_Hall_%287230083424%29_%28cropped%29.jpg','1842','USA','뉴욕 필하모닉(New York Philharmonic)은 1842년 미국 뉴욕에서 창단된 미국에서 가장 오래된 오케스트라이다.\n\n구스타프 말러, 레너드 번스타인 등 거장들이 상임 지휘자를 역임했다. 강렬하고 역동적인 사운드를 특징으로 하며, 미국의 \'빅 5\' 오케스트라 중 하나이다.','역동적이고 화려하며 공격적인 사운드가 특징이며, 특히 낭만주의 후기와 20세기 레퍼토리에서 강점을 보인다.',10000,500,NULL,'2025-11-20 05:35:47','2025-11-20 11:16:31'),(323,'시카고 심포니 오케스트라','Chicago Symphony Orchestra','orchestra','S',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Chicago_Symphony_Orchestra_2005.jpg/500px-Chicago_Symphony_Orchestra_2005.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Chicago_Symphony_Orchestra_2005.jpg/500px-Chicago_Symphony_Orchestra_2005.jpg','1891','USA','시카고 심포니 오케스트라(Chicago Symphony Orchestra, CSO)는 1891년 미국 시카고에서 창단된 세계적인 오케스트라이다.\n\n게오르그 솔티, 다니엘 바렌보임 등 거장 지휘자들이 이끌었다. 금관악기의 강력한 사운드로 유명하며, 미국의 \'빅 5\' 오케스트라 중 하나이다.','금관악기와 타악기의 강력하고 압도적인 사운드가 특징이며, 정교함과 엄청난 파워가 결합된 연주를 자랑한다.',10000,500,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(324,'보스턴 심포니 오케스트라','Boston Symphony Orchestra','orchestra','S',0.0,'https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse1.mm.bing.net%2Fth%2Fid%2FOIP.o_JDETvkFklqmcMg7-AFuQHaE7%3Fpid%3DApi&f=1&ipt=dbc356a318a3fead4cecda2d288a0323d647aa46f4714676e507653bbabc885d&ipo=images','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse1.mm.bing.net%2Fth%2Fid%2FOIP.o_JDETvkFklqmcMg7-AFuQHaE7%3Fpid%3DApi&f=1&ipt=dbc356a318a3fead4cecda2d288a0323d647aa46f4714676e507653bbabc885d&ipo=images','1881','USA','보스턴 심포니 오케스트라(Boston Symphony Orchestra, BSO)는 1881년 미국 보스턴에서 창단된 미국의 \'빅 5\' 오케스트라 중 하나이다.\n\n세르주 쿠세비츠키, 샤를 뮌슈 등 프랑스 악파 지휘자들이 이끌어 프랑스적인 우아함과 세련된 음색을 갖추었다.','프랑스적인 우아함과 유려한 현악 사운드가 특징이며, 특히 인상주의 음악과 20세기 레퍼토리 해석에 강점을 보인다.',10000,500,NULL,'2025-11-20 05:35:47','2025-11-20 11:18:04'),(325,'바이에른 방송 교향악단','Bavarian Radio Symphony Orchestra','orchestra','S',0.0,'https://upload.wikimedia.org/wikipedia/commons/1/1f/Sergiu_Celibidache_1966.png','https://upload.wikimedia.org/wikipedia/commons/1/1f/Sergiu_Celibidache_1966.png','1949','Germany','바이에른 방송 교향악단(Bavarian Radio Symphony Orchestra, BRSO)은 1949년 독일 뮌헨에서 창단된 세계적인 오케스트라이다.\n\n주요 독일 악단 중 하나로, 라파엘 쿠벨릭, 마리스 얀손스 등 명지휘자들이 이끌었다. 독일 낭만주의 레퍼토리 해석에 정평이 나 있다.','정통 독일 악파의 깊고 풍부한 사운드와 함께 유연하고 섬세한 앙상블을 겸비했으며, 특히 낭만주의 후기 레퍼토리에 강하다.',5000,300,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(326,'드레스덴 슈타츠카펠레','Dresden Staatskapelle','orchestra','S',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/HFBK_Dresden_2024_Luftbild_Toni_Klemm_2500px.jpg/500px-HFBK_Dresden_2024_Luftbild_Toni_Klemm_2500px.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/HFBK_Dresden_2024_Luftbild_Toni_Klemm_2500px.jpg/500px-HFBK_Dresden_2024_Luftbild_Toni_Klemm_2500px.jpg','1548','Germany','드레스덴 슈타츠카펠레(Dresden Staatskapelle)는 1548년 독일 드레스덴에서 창단된 세계에서 가장 오래된 오케스트라 중 하나이다.\n\n리하르트 슈트라우스, 카를 뵘 등 역사적인 거장들이 이끌었다. 독일 낭만주의, 특히 리하르트 슈트라우스와 바그너 해석에 독보적인 전통을 가지고 있다.','깊고 어두우며 유기적인 사운드와 오랜 역사에서 비롯된 전통적인 해석을 자랑하며, 낭만주의 레퍼토리에 특히 강하다.',10000,500,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(327,'라이프치히 게반트하우스 오케스트라','Leipzig Gewandhaus Orchestra','orchestra','S',0.0,'https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse2.mm.bing.net%2Fth%2Fid%2FOIP.YwOfvkggv0Yz8Q4j8-OyOQHaFe%3Fpid%3DApi&f=1&ipt=1dbbe2ec0e37f8408826d1d8fbe66740f559a0cbd65c668e633df8c6e6d83c9f&ipo=images','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse2.mm.bing.net%2Fth%2Fid%2FOIP.YwOfvkggv0Yz8Q4j8-OyOQHaFe%3Fpid%3DApi&f=1&ipt=1dbbe2ec0e37f8408826d1d8fbe66740f559a0cbd65c668e633df8c6e6d83c9f&ipo=images','1743','Germany','라이프치히 게반트하우스 오케스트라(Leipzig Gewandhaus Orchestra, GHO)는 1743년 독일 라이프치히에서 창단된 유서 깊은 오케스트라이다.\n\n펠릭스 멘델스존, 아르투르 니키슈 등 거장들이 이끌었다. 바흐, 베토벤, 브람스 등 독일 고전-낭만 레퍼토리의 정통성을 유지하고 있다.','맑고 투명하며 균형 잡힌 사운드가 특징이며, 고전주의와 초기 낭만주의 레퍼토리에서 깊이 있는 해석을 보여준다.',10000,500,NULL,'2025-11-20 05:35:47','2025-11-20 11:18:34'),(328,'서울시향','Seoul Philharmonic Orchestra','orchestra','A',0.0,'https://upload.wikimedia.org/wikipedia/en/thumb/b/b6/Seoul-Sejong.Art.Center-01.jpg/500px-Seoul-Sejong.Art.Center-01.jpg','https://upload.wikimedia.org/wikipedia/en/thumb/b/b6/Seoul-Sejong.Art.Center-01.jpg/500px-Seoul-Sejong.Art.Center-01.jpg','1948','South Korea','서울시향(Seoul Philharmonic Orchestra, SPO)은 1948년 대한민국 서울에서 창단된 국내 최고 수준의 오케스트라이다.\n\n정명훈 등 세계적인 지휘자들을 음악감독으로 맞이하며 아시아 정상급 오케스트라로 성장했다. 국내 클래식 음악계의 중심 역할을 수행하고 있다.','정교한 앙상블과 폭넓은 레퍼토리를 소화하는 능력을 갖추었으며, 역동적이면서도 세련된 사운드를 추구한다.',5000,50,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(329,'KBS 교향악단','KBS Symphony Orchestra','orchestra','A',0.0,'https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse4.mm.bing.net%2Fth%2Fid%2FOIP.a58lTUmOGgvBaEOo7NLKAAHaHa%3Fpid%3DApi&f=1&ipt=5315c411b47ee99898a3e6e7bfca57c7a591d18402d967a7dceecf7ffc4ead78&ipo=images','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse1.mm.bing.net%2Fth%2Fid%2FOIP.OoyiqbY6oouhSf2J8leZ6QHaEn%3Fpid%3DApi&f=1&ipt=325301916522109eacaca684b011c002359c11fe66e35dedd9deb38bf2fd7a9d&ipo=images','1956','South Korea','KBS 교향악단(KBS Symphony Orchestra, KBS SO)은 1956년 대한민국 서울에서 창단된 국내 대표적인 오케스트라이다.\n\nKBS 소속으로 공영 방송을 통해 클래식 음악을 대중에게 전달하는 역할을 수행한다. 안정적인 연주력과 폭넓은 활동 범위를 자랑한다.','전통적이고 균형 잡힌 사운드를 추구하며, 특히 독일 낭만주의 레퍼토리에서 탄탄한 연주력을 보여준다.',5000,30,NULL,'2025-11-20 05:35:47','2025-11-20 11:19:45'),(330,'코리안 심포니 오케스트라','Korean Symphony Orchestra','orchestra','A',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Andr%C3%A9_Previn.jpg/500px-Andr%C3%A9_Previn.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Andr%C3%A9_Previn.jpg/500px-Andr%C3%A9_Previn.jpg','1985','South Korea','코리안 심포니 오케스트라(Korean Symphony Orchestra, KSO)는 1985년 대한민국 서울에서 창단된 오케스트라이다.\n\n국립 오페라단, 국립 발레단 등과 함께 예술의전당 상주 오케스트라로서 공연 예술 분야에 기여하고 있다. 폭넓은 레퍼토리를 소화한다.','오페라 및 발레 반주에 강점을 보이며, 극적인 표현과 유연한 앙상블을 중요시하는 연주를 한다.',3000,10,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(331,'부천필하모닉오케스트라','Bucheon Philharmonic Orchestra','orchestra','B',0.0,'https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse4.mm.bing.net%2Fth%2Fid%2FOIP._EK9wuFJcPSzb7iaPOC-ewHaE7%3Fpid%3DApi&f=1&ipt=7b6d80cd357713d5c0b141217ec9d4755b937c25a1a71247309828ca832360c0&ipo=images','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse4.mm.bing.net%2Fth%2Fid%2FOIP._EK9wuFJcPSzb7iaPOC-ewHaE7%3Fpid%3DApi&f=1&ipt=7b6d80cd357713d5c0b141217ec9d4755b937c25a1a71247309828ca832360c0&ipo=images','1988','South Korea','부천필하모닉오케스트라(Bucheon Philharmonic Orchestra)는 1988년 경기도 부천에서 창단된 대한민국의 시립 오케스트라이다.\n\n임헌정 지휘자의 말러 교향곡 전곡 연주 등 도전적인 기획으로 국내 클래식계에서 독자적인 영역을 구축했다.','진지하고 깊이 있는 해석을 바탕으로, 특히 낭만주의 후기 대형 레퍼토리에서 강한 집중력과 에너지를 보여준다.',1000,10,NULL,'2025-11-20 05:35:47','2025-11-20 11:20:15'),(332,'대전시향','Daejeon Philharmonic Orchestra','orchestra','B',0.0,'https://dpo.artdj.kr/images/dpo/common/t_logo.png','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse3.mm.bing.net%2Fth%2Fid%2FOIP.upMWZl_InrJmXSudkEOnogHaEC%3Fpid%3DApi&f=1&ipt=da46fb3e0e80bd50f67d3d833675a6132aee89eba294faf1239eda6f42ab46fa&ipo=images','1984','South Korea','대전시향(Daejeon Philharmonic Orchestra)은 1984년 대한민국 대전에서 창단된 시립 오케스트라이다.\n\n지역 문화 예술 발전에 기여하며, 국내외 연주 활동을 통해 역량을 키워나가고 있다.','화려함보다는 견실하고 안정적인 연주를 추구하며, 대중적인 레퍼토리를 폭넓게 소화한다.',1000,5,NULL,'2025-11-20 05:35:47','2025-11-20 11:21:07'),(333,'부산시향','Busan Philharmonic Orchestra','orchestra','B',0.0,'https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse1.mm.bing.net%2Fth%2Fid%2FOIP.XI14xn5yiRF1UzugVxi-NAHaE8%3Fpid%3DApi&f=1&ipt=33937f9dbf8165ef7c50fecc931c1c431897b73ced45ce6f100886bd77360538&ipo=images','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse1.mm.bing.net%2Fth%2Fid%2FOIP.XI14xn5yiRF1UzugVxi-NAHaE8%3Fpid%3DApi&f=1&ipt=33937f9dbf8165ef7c50fecc931c1c431897b73ced45ce6f100886bd77360538&ipo=images','1962','South Korea','부산시향(Busan Philharmonic Orchestra)은 1962년 대한민국 부산에서 창단된 시립 오케스트라이다.\n\n부산을 대표하는 교향악단으로, 아시아와 유럽 등 해외 투어를 통해 국제적인 인지도를 높이고 있다.','활기차고 역동적인 연주와 함께 폭넓은 시대의 작품을 소화하며, 지역 음악계의 중심 역할을 한다.',1000,5,NULL,'2025-11-20 05:35:47','2025-11-20 11:21:44'),(334,'인천시향','Incheon Philharmonic Orchestra','orchestra','B',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3f/Lang_Lang_-_World_Economic_Forum_Annual_Meeting_2010_Davos_cropped_%28cropped%29.jpg/500px-Lang_Lang_-_World_Economic_Forum_Annual_Meeting_2010_Davos_cropped_%28cropped%29.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/3/3f/Lang_Lang_-_World_Economic_Forum_Annual_Meeting_2010_Davos_cropped_%28cropped%29.jpg/500px-Lang_Lang_-_World_Economic_Forum_Annual_Meeting_2010_Davos_cropped_%28cropped%29.jpg','1966','South Korea','인천시향(Incheon Philharmonic Orchestra)은 1966년 대한민국 인천에서 창단된 시립 오케스트라이다.\n\n역사가 오래된 시향 중 하나로, 다양한 기획 연주와 교육 프로그램을 통해 인천 지역 문화 발전에 기여하고 있다.','균형 잡힌 앙상블과 안정적인 연주력을 바탕으로, 대중 친화적인 레퍼토리부터 대작까지 폭넓게 선보인다.',1000,5,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(335,'광주시향','Gwangju Symphony Orchestra','orchestra','B',0.0,'https://gjart.gwangju.go.kr/sites/gjart/gso/images/common/201712210149443391.png','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse1.mm.bing.net%2Fth%2Fid%2FOIP.NYEE4zsRorn-mScqh2TBwwHaE8%3Fpid%3DApi&f=1&ipt=7cdc8fc966200902d3fbe7adc64cf92540cb907c8d5b27c0ada959d18f789913&ipo=images','1976','South Korea','광주시향(Gwangju Symphony Orchestra)은 1976년 대한민국 광주에서 창단된 시립 오케스트라이다.\n\n광주 지역의 클래식 음악을 대표하며, 5.18 민주화운동 기념 음악회 등 지역의 역사와 연관된 특별 공연도 선보인다.','힘있고 진중한 사운드를 특징으로 하며, 특히 한국 창작 음악과 해외 현대 음악 연주에도 적극적이다.',1000,5,NULL,'2025-11-20 05:35:47','2025-11-20 11:22:20'),(336,'수원시향','Suwon Philharmonic Orchestra','orchestra','B',0.0,'https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse2.mm.bing.net%2Fth%2Fid%2FOIP.LxjvBaiTIXAcjzSmL8KnlAHaE8%3Fpid%3DApi&f=1&ipt=9bc37ee4cb0548a7c215c8119ac8beb67be91636f4d33c60fd4c66b843848d9c&ipo=images','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse2.mm.bing.net%2Fth%2Fid%2FOIP.LxjvBaiTIXAcjzSmL8KnlAHaE8%3Fpid%3DApi&f=1&ipt=9bc37ee4cb0548a7c215c8119ac8beb67be91636f4d33c60fd4c66b843848d9c&ipo=images','1982','South Korea','수원시향(Suwon Philharmonic Orchestra)은 1982년 경기도 수원에서 창단된 시립 오케스트라이다.\n\n젊고 유능한 지휘자들을 중심으로 활발하게 활동하며 국내외에서 인지도를 쌓고 있다.','유연하고 세련된 앙상블을 추구하며, 특히 낭만주의 시대의 다채로운 색채를 잘 표현하는 연주를 한다.',1000,5,NULL,'2025-11-20 05:35:47','2025-11-20 11:22:48'),(337,'로열 필하모닉 오케스트라','Royal Philharmonic Orchestra','orchestra','A',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/7/70/Cadogan_Hall%2C_Sloane_Terrace%2C_SW1_-_interior_-_geograph.org.uk_-_1805137.jpg/500px-Cadogan_Hall%2C_Sloane_Terrace%2C_SW1_-_interior_-_geograph.org.uk_-_1805137.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/7/70/Cadogan_Hall%2C_Sloane_Terrace%2C_SW1_-_interior_-_geograph.org.uk_-_1805137.jpg/500px-Cadogan_Hall%2C_Sloane_Terrace%2C_SW1_-_interior_-_geograph.org.uk_-_1805137.jpg','1946','UK','로열 필하모닉 오케스트라(Royal Philharmonic Orchestra, RPO)는 1946년 영국 런던에서 토머스 비첨 경에 의해 창단되었다.\n\n영국 런던의 4대 오케스트라 중 하나로, 활발한 녹음 활동과 대중적인 인지도를 가지고 있다.','화려하고 따뜻한 사운드가 특징이며, 폭넓은 레퍼토리를 소화하는 다재다능한 연주를 자랑한다.',5000,500,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(338,'필하모니아 오케스트라','Philharmonia Orchestra','orchestra','A',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Gulsin_Onay_with_conductor_Esa_Pekka_Salonen.jpg/500px-Gulsin_Onay_with_conductor_Esa_Pekka_Salonen.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Gulsin_Onay_with_conductor_Esa_Pekka_Salonen.jpg/500px-Gulsin_Onay_with_conductor_Esa_Pekka_Salonen.jpg','1945','UK','필하모니아 오케스트라(Philharmonia Orchestra)는 1945년 영국 런던에서 월터 레그에 의해 창단되었다.\n\n초창기부터 카라얀, 클렘페러 등 세계적인 지휘자들과 함께 작업하며 명성을 쌓았다. 영국 런던의 주요 오케스트라 중 하나이다.','정교하고 지적인 해석, 그리고 현대적인 사운드를 추구하며, 20세기 레퍼토리에서 특히 강점을 보인다.',5000,500,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(339,'BBC 심포니 오케스트라','BBC Symphony Orchestra','orchestra','A',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/Orchestra_Simfonica_Bucure%C8%99ti.jpg/500px-Orchestra_Simfonica_Bucure%C8%99ti.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/Orchestra_Simfonica_Bucure%C8%99ti.jpg/500px-Orchestra_Simfonica_Bucure%C8%99ti.jpg','1930','UK','BBC 심포니 오케스트라(BBC Symphony Orchestra, BBC SO)는 1930년 영국 런던에서 BBC에 의해 창단되었다.\n\nBBC 프롬스(Proms)의 핵심 악단으로, 폭넓은 레퍼토리, 특히 현대 음악 초연에 중요한 역할을 한다.','유연하고 실험적인 연주 스타일을 지녔으며, 현대 음악을 명료하고 정확하게 구현하는 능력이 뛰어나다.',5000,300,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(340,'뮌헨 필하모닉','Munich Philharmonic','orchestra','S',0.0,'https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse2.mm.bing.net%2Fth%2Fid%2FOIP.RpZsMnBEkvgunQswiZk04QHaEc%3Fpid%3DApi&f=1&ipt=c28b1915b773e6a1da6a84c70366259d075d77672add9ec9912be626f146dce7&ipo=images','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse4.mm.bing.net%2Fth%2Fid%2FOIP.Wtn3M6oyC_yxJhzHtrJahQHaEK%3Fpid%3DApi&f=1&ipt=dccf06f452d47b11d8978d4d6c2d27c407dd6359fe0d3f23d8cd738539c38952&ipo=images','1893','Germany','뮌헨 필하모닉(Munich Philharmonic)은 1893년 독일 뮌헨에서 창단된 오케스트라이다.\n\n말러가 자신의 교향곡을 초연하는 등 역사적으로 중요한 역할을 수행했다. 독일 낭만주의 레퍼토리 해석에 깊은 전통을 가지고 있다.','깊고 웅장하며 따뜻한 사운드가 특징이며, 특히 브루크너와 말러 등 독일 낭만주의 대곡에서 강점을 보인다.',10000,300,NULL,'2025-11-20 05:35:47','2025-11-20 11:24:12'),(341,'WDR 교향악단','WDR Symphony Orchestra','orchestra','A',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/7/70/Cadogan_Hall%2C_Sloane_Terrace%2C_SW1_-_interior_-_geograph.org.uk_-_1805137.jpg/500px-Cadogan_Hall%2C_Sloane_Terrace%2C_SW1_-_interior_-_geograph.org.uk_-_1805137.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/7/70/Cadogan_Hall%2C_Sloane_Terrace%2C_SW1_-_interior_-_geograph.org.uk_-_1805137.jpg/500px-Cadogan_Hall%2C_Sloane_Terrace%2C_SW1_-_interior_-_geograph.org.uk_-_1805137.jpg','1947','Germany','WDR 교향악단(WDR Symphony Orchestra)은 1947년 독일 쾰른에서 서독일 방송국(WDR) 소속으로 창단되었다.\n\n20세기와 현대 음악 레퍼토리 연주에 적극적이며, 방송 오케스트라로서의 안정적인 활동을 이어가고 있다.','깨끗하고 명료한 앙상블을 바탕으로, 현대 음악과 낯선 레퍼토리를 과감하게 소화하는 능력을 보여준다.',5000,100,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(342,'NDR 엘프필하모닉 오케스트라','NDR Elbphilharmonie Orchestra','orchestra','A',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/NDR_Elbphilharmonie_Orchester_Logo_2018.svg/500px-NDR_Elbphilharmonie_Orchester_Logo_2018.svg.png','https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/NDR_Elbphilharmonie_Orchester_Logo_2018.svg/500px-NDR_Elbphilharmonie_Orchester_Logo_2018.svg.png','1945','Germany','NDR 엘프필하모닉 오케스트라(NDR Elbphilharmonie Orchestra)는 1945년 독일 함부르크에서 창단된 북독일 방송국(NDR) 소속 오케스트라이다.\n\n함부르크 엘프필하모니 콘서트홀을 거점으로 하며, 활력 넘치고 세련된 연주로 주목받고 있다.','역동적이고 세련된 사운드와 유연한 앙상블을 추구하며, 20세기와 현대 레퍼토리에 강점을 보인다.',5000,100,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(343,'파리 오케스트라','Orchestre de Paris','orchestra','A',0.0,'https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse3.mm.bing.net%2Fth%2Fid%2FOIP.RtLjdqRvyDwqHcI_Q0gN2QHaFC%3Fpid%3DApi&f=1&ipt=6fa5286f46609db560c17f8cb1bf41a3a41b72b1b72e4de8437a3d18267d19dc&ipo=images','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse3.mm.bing.net%2Fth%2Fid%2FOIP.3rK-58G-8AI-60R6G9MnqQHaGP%3Fpid%3DApi&f=1&ipt=493a817a89126bba0638f4892cef3d57f331bcd6d74f870b11965fb17541876b&ipo=images','1967','France','파리 오케스트라(Orchestre de Paris)는 1967년 프랑스 파리에서 샤를 뮌슈에 의해 창단되었다.\n\n프랑스 음악의 전통을 계승하며, 20세기 프랑스 레퍼토리 해석에 있어 중요한 위치를 차지하고 있다.','화려하고 다채로운 음색, 그리고 프랑스 특유의 섬세하고 세련된 프레이징을 강조하는 연주를 한다.',5000,300,NULL,'2025-11-20 05:35:47','2025-11-20 11:24:58'),(344,'프랑스 국립 오케스트라','Orchestra National de France','orchestra','A',0.0,'https://upload.wikimedia.org/wikipedia/commons/f/fc/Su-a_Lee_%28musician%29.jpeg','https://upload.wikimedia.org/wikipedia/commons/f/fc/Su-a_Lee_%28musician%29.jpeg','1934','France','프랑스 국립 오케스트라(Orchestre National de France)는 1934년 프랑스에서 창단된 프랑스 국영 라디오 소속의 오케스트라이다.\n\n프랑스 음악, 특히 드뷔시와 라벨 등 인상주의 작품 해석에 깊은 전통을 가지고 있다.','맑고 투명하며 풍부한 색채를 지닌 사운드가 특징이며, 프랑스 음악 특유의 우아함과 감각적인 표현을 보여준다.',5000,300,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(345,'상트페테르부르크 필하모닉','St. Petersburg Philharmonic','orchestra','S',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Winter_Palace_Panorama_3.jpg/500px-Winter_Palace_Panorama_3.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Winter_Palace_Panorama_3.jpg/500px-Winter_Palace_Panorama_3.jpg','1882','Russia','상트페테르부르크 필하모닉(St. Petersburg Philharmonic)은 1882년 러시아 상트페테르부르크에서 창단된 러시아를 대표하는 오케스트라이다.\n\n므라빈스키 등 전설적인 지휘자들이 이끌었으며, 차이콥스키, 쇼스타코비치 등 러시아 레퍼토리 해석에 있어 독보적인 전통을 가지고 있다.','힘있고 어두우며 강렬한 표현력이 특징이며, 러시아 낭만주의와 20세기 대작에서 탁월한 몰입감을 선사한다.',10000,300,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(346,'마린스키 극장 오케스트라','Mariinsky Theatre Orchestra','orchestra','S',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6b/Valery_Gergiev_David_Shankbone_2010.jpg/500px-Valery_Gergiev_David_Shankbone_2010.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/6/6b/Valery_Gergiev_David_Shankbone_2010.jpg/500px-Valery_Gergiev_David_Shankbone_2010.jpg','1783','Russia','마린스키 극장 오케스트라(Mariinsky Theatre Orchestra)는 1783년 러시아 상트페테르부르크에서 창단된 러시아 최고의 오페라 및 발레 극장 오케스트라이다.\n\n발레리 게르기예프의 지휘 아래 세계적인 명성을 얻었으며, 러시아 오페라와 발레 음악 해석에 있어 최고 권위를 가진다.','드라마틱하고 감성적인 표현이 풍부하며, 오페라와 발레 음악에 최적화된 유연하고 화려한 사운드를 자랑한다.',10000,300,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(347,'산타 체칠리아 국립 아카데미','Accademia Nazionale di Santa Cecilia','orchestra','A',0.0,'https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse1.mm.bing.net%2Fth%2Fid%2FOIP.RYIeOXxoA5qnMnqPOUkskAAAAA%3Fpid%3DApi&f=1&ipt=bf9a5faf2262e63412bb0c24d30333d24530fada6f4e70acbee57a5eaddadc76&ipo=images','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse1.mm.bing.net%2Fth%2Fid%2FOIP.6B0v_cAy69o6MzKOm63CuQHaE8%3Fpid%3DApi&f=1&ipt=1189b20c7078c82a88bdab73df6be3f9499cc222612014515cf73d69b28a873b&ipo=images','1908','Italy','산타 체칠리아 국립 아카데미 오케스트라(Accademia Nazionale di Santa Cecilia)는 1908년 이탈리아 로마에서 창단되었다.\n\n이탈리아를 대표하는 교향악단으로, 베르디, 푸치니 등 이탈리아 오페라와 교향곡 레퍼토리에서 깊은 전통을 가지고 있다.','풍부하고 따뜻한 음색과 유연한 앙상블을 바탕으로, 이탈리아 음악 특유의 선율미와 드라마틱한 요소를 강조한다.',5000,100,NULL,'2025-11-20 05:35:47','2025-11-20 11:27:06'),(348,'체코 필하모닉','Czech Philharmonic','orchestra','A',0.0,'https://external-content.duckduckgo.com/ip3/www.ceskafilharmonie.cz.ico','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse1.mm.bing.net%2Fth%2Fid%2FOIP.A-ALqqcdaZ5GEfngAB3bKAHaHa%3Fpid%3DApi&f=1&ipt=f2ebad4e7849a6015e4038ee43a0d26c9818c79c367f4c08fbabe6b7881bf815&ipo=images','1896','Czech Republic','체코 필하모닉(Czech Philharmonic)은 1896년 체코 프라하에서 창단된 체코를 대표하는 오케스트라이다.\n\n드보르자크, 야나체크 등 체코 작곡가들의 작품 해석에 있어 독보적인 위치를 차지하며, 슬라브적인 서정성을 가진다.','따뜻하고 인간적인 현악 사운드와 풍부한 서정성을 바탕으로, 특히 체코 및 슬라브 민족주의 레퍼토리에 강하다.',5000,300,NULL,'2025-11-20 05:35:47','2025-11-20 11:28:18'),(349,'오슬로 필하모닉','Oslo Philharmonic','orchestra','A',0.0,'https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse1.mm.bing.net%2Fth%2Fid%2FOIP.3kY1Vl-sKWvobmgGUwpyIgHaFj%3Fpid%3DApi&f=1&ipt=6defa8fa50f26367d4869c02593f6613911fbd18be3e35143dfe2ef2206f48a2&ipo=images','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse4.mm.bing.net%2Fth%2Fid%2FOIP.ziiHc7PmR_7IvFDXRXKBcQHaE8%3Fpid%3DApi&f=1&ipt=8556676b40a11f784b30c512125e0e33106dabf2dffe46103152d517b8107493&ipo=images','1919','Norway','오슬로 필하모닉(Oslo Philharmonic)은 1919년 노르웨이 오슬로에서 창단된 노르웨이를 대표하는 오케스트라이다.\n\n마리스 얀손스 등 세계적인 지휘자들을 배출하며 북유럽을 넘어 국제적인 명성을 쌓았다. 시벨리우스, 그리그 등 북유럽 레퍼토리에 강점을 보인다.','맑고 깨끗한 음색과 역동적인 에너지를 갖추었으며, 북유럽 특유의 서정성과 광활한 스케일을 표현한다.',5000,100,NULL,'2025-11-20 05:35:47','2025-11-20 11:28:54'),(350,'NHK 교향악단','NHK Symphony Orchestra','orchestra','A',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/The_Premiere_of_Symphony_No._9.jpg/500px-The_Premiere_of_Symphony_No._9.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/The_Premiere_of_Symphony_No._9.jpg/500px-The_Premiere_of_Symphony_No._9.jpg','1926','Japan','NHK 교향악단(NHK Symphony Orchestra, NHK SO)은 1926년 일본 도쿄에서 창단된 일본의 대표적인 오케스트라이다.\n\n일본 NHK 방송국 소속으로, 일본 클래식 음악계의 중심 역할을 수행하며 아시아 정상급의 연주력을 자랑한다.','정교하고 섬세한 앙상블과 안정적인 연주력을 바탕으로, 독일과 러시아 낭만주의 레퍼토리를 주로 연주한다.',5000,300,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(351,'도쿄 도립 교향악단','Tokyo Metropolitan Symphony Orchestra','orchestra','A',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/James_Levine_2013.jpg/500px-James_Levine_2013.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/James_Levine_2013.jpg/500px-James_Levine_2013.jpg','1965','Japan','도쿄 도립 교향악단(Tokyo Metropolitan Symphony Orchestra, TMSO)은 1965년 일본 도쿄도(都) 소속으로 창단된 오케스트라이다.\n\n도쿄 예술 문화의 발전에 기여하며, 특히 현대 일본 작곡가들의 작품 초연에 적극적인 역할을 한다.','현대적이면서도 균형 잡힌 사운드를 추구하며, 역동적인 연주력과 폭넓은 레퍼토리 소화 능력을 갖추었다.',3000,100,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(352,'요미우리 일본 교향악단','Yomiuri Nippon Symphony Orchestra','orchestra','A',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/Yoshiki_at_Hollywood_TCL_Theatre_on_January_9%2C_2024.png/500px-Yoshiki_at_Hollywood_TCL_Theatre_on_January_9%2C_2024.png','https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/Yoshiki_at_Hollywood_TCL_Theatre_on_January_9%2C_2024.png/500px-Yoshiki_at_Hollywood_TCL_Theatre_on_January_9%2C_2024.png','1962','Japan','요미우리 일본 교향악단(Yomiuri Nippon Symphony Orchestra, YNSO)은 1962년 일본 요미우리 신문사 소속으로 창단된 오케스트라이다.\n\n일본의 주요 민간 교향악단 중 하나로, 정기적인 연주회와 해외 투어를 통해 활발하게 활동하고 있다.','화려하고 유려한 사운드를 바탕으로, 특히 러시아 낭만주의와 프랑스 레퍼토리에 강점을 보인다.',3000,100,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(353,'싱가포르 교향악단','Singapore Symphony Orchestra','orchestra','A',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/Esplanade_Concert_Hall_Interior.jpg/500px-Esplanade_Concert_Hall_Interior.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/Esplanade_Concert_Hall_Interior.jpg/500px-Esplanade_Concert_Hall_Interior.jpg','1979','Singapore','싱가포르 교향악단(Singapore Symphony Orchestra, SSO)은 1979년 싱가포르에서 창단된 오케스트라이다.\n\n아시아를 대표하는 오케스트라 중 하나로, 동서양의 음악적 전통을 아우르는 레퍼토리를 소화한다.','깨끗하고 정교한 앙상블을 바탕으로, 동양적인 서정성과 서양의 웅장함을 조화시키는 연주를 한다.',1000,50,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(354,'홍콩 필하모닉','Hong Kong Philharmonic','orchestra','A',0.0,'https://duckduckgo.com/i/052f8dff.png','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Fcloudimages.broadwayworld.com%2Fcolumnpiccloud%2F750-The-Hong-Kong-Philharmonic-Orchestra-Concludes-its-Singapore-and-Europe-Tour-1711520325.jpg&f=1&nofb=1&ipt=ccf5c041fec32bfc9c2142ed868c8d4f2cf9bb544cdac0d8968cfabca1b8cf5e','1947','Hong Kong','홍콩 필하모닉(Hong Kong Philharmonic Orchestra, HK Phil)은 1947년 홍콩에서 창단된 오케스트라이다.\n\n아시아에서 가장 역동적인 오케스트라 중 하나로, 동서양 음악을 아우르는 프로그램과 뛰어난 연주력을 자랑한다.','유연하고 다재다능한 연주력을 바탕으로, 다양한 시대와 장르의 음악을 소화하는 능력이 뛰어나다.',1000,50,NULL,'2025-11-20 05:35:47','2025-11-20 11:29:45'),(355,'차이나 필하모닉','China Philharmonic Orchestra','orchestra','A',0.0,'https://duckduckgo.com/i/75a6c8b4cd935c63.jpg','https://duckduckgo.com/i/75a6c8b4cd935c63.jpg','2000','China','차이나 필하모닉 오케스트라(China Philharmonic Orchestra, CPO)는 2000년 중국 베이징에서 창단된 중국을 대표하는 오케스트라이다.\n\n중국 음악과 서양 클래식 대작 모두를 연주하며 국제적인 명성을 빠르게 쌓고 있다.','힘있고 웅장한 사운드와 함께 중국 특유의 선율적 감수성을 겸비했으며, 낭만주의 레퍼토리에 강하다.',1000,50,NULL,'2025-11-20 05:35:47','2025-11-20 11:30:14'),(356,'상하이 교향악단','Shanghai Symphony Orchestra','orchestra','A',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Shanghai_Symphony_Hall_%2820191021080658%29.jpg/500px-Shanghai_Symphony_Hall_%2820191021080658%29.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Shanghai_Symphony_Hall_%2820191021080658%29.jpg/500px-Shanghai_Symphony_Hall_%2820191021080658%29.jpg','1879','China','상하이 교향악단(Shanghai Symphony Orchestra, SSO)은 1879년 중국 상하이에서 창단된 아시아에서 가장 오래된 오케스트라이다.\n\n중국 클래식 음악의 발전에 중요한 역할을 했으며, 현재 아시아의 주요 오케스트라 중 하나로 인정받는다.','역동적이고 세련된 사운드를 바탕으로, 전통적인 서양 클래식과 중국 현대 음악을 균형 있게 소화한다.',1000,50,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(357,'필라델피아 오케스트라','Philadelphia Orchestra','orchestra','S',0.0,'https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse2.mm.bing.net%2Fth%2Fid%2FOIP.QMUjWEMnKgv8OddZrVFb-AAAAA%3Fpid%3DApi&f=1&ipt=c9c1aab4456824d6e33369cd8d0b27e1167842c9596bb7bc429db9f72656ffbe&ipo=images','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse3.mm.bing.net%2Fth%2Fid%2FOIP.8HVbafYQlg5odhPBxIdOuAHaFS%3Fpid%3DApi&f=1&ipt=0d79eb4d7f53bbed6f0ad69ab6b60af85e2efdb4128ba9bf4d67dd1ebbc33328&ipo=images','1900','USA','필라델피아 오케스트라(Philadelphia Orchestra)는 1900년 미국 필라델피아에서 창단된 미국의 \'빅 5\' 오케스트라 중 하나이다.\n\n레오폴드 스토코프스키의 지휘 아래 \'필라델피아 사운드\'라 불리는 독특한 현악 사운드를 구축했다.','따뜻하고 풍부하며 벨벳 같은 현악 사운드가 특징이며, 낭만주의 시대 레퍼토리 해석에 있어 독보적인 전통을 가지고 있다.',10000,500,NULL,'2025-11-20 05:35:47','2025-11-20 11:30:54'),(358,'클리블랜드 오케스트라','Cleveland Orchestra','orchestra','S',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/The_Cleveland_Orchestra_being_conducted_by_Daniel_Reith_at_Severance_Hall_January_15th_2023.jpg/500px-The_Cleveland_Orchestra_being_conducted_by_Daniel_Reith_at_Severance_Hall_January_15th_2023.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/The_Cleveland_Orchestra_being_conducted_by_Daniel_Reith_at_Severance_Hall_January_15th_2023.jpg/500px-The_Cleveland_Orchestra_being_conducted_by_Daniel_Reith_at_Severance_Hall_January_15th_2023.jpg','1918','USA','클리블랜드 오케스트라(Cleveland Orchestra)는 1918년 미국 클리블랜드에서 창단된 미국의 \'빅 5\' 오케스트라 중 하나이다.\n\n조지 셀의 지휘 아래 정교하고 명확한 앙상블로 세계적인 명성을 얻었다. 특히 고전주의와 20세기 레퍼토리에 강하다.','정교하고 명료하며 지적인 사운드가 특징이며, 깔끔한 앙상블과 완벽한 균형을 자랑하는 연주를 한다.',10000,500,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(359,'샌프란시스코 심포니','San Francisco Symphony','orchestra','A',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/San_Francisco%2C_Oct-2021_%28cropped%29_%28cropped%29.jpg/500px-San_Francisco%2C_Oct-2021_%28cropped%29_%28cropped%29.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/San_Francisco%2C_Oct-2021_%28cropped%29_%28cropped%29.jpg/500px-San_Francisco%2C_Oct-2021_%28cropped%29_%28cropped%29.jpg','1911','USA','샌프란시스코 심포니(San Francisco Symphony, SFS)는 1911년 미국 샌프란시스코에서 창단된 미국의 주요 오케스트라 중 하나이다.\n\n마이클 틸슨 토마스 등의 지휘 아래 혁신적인 프로그램과 현대적인 연주로 주목받았다.','활력 넘치고 유연한 연주 스타일을 지녔으며, 특히 20세기와 현대 음악 레퍼토리에서 뛰어난 적응력을 보여준다.',5000,300,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(360,'로스앤젤레스 필하모닉','Los Angeles Philharmonic','orchestra','S',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Yunchan_Lim_with_the_Los_Angeles_Philharmonic_in_concert_at_the_Hollywood_Bowl.jpg/500px-Yunchan_Lim_with_the_Los_Angeles_Philharmonic_in_concert_at_the_Hollywood_Bowl.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Yunchan_Lim_with_the_Los_Angeles_Philharmonic_in_concert_at_the_Hollywood_Bowl.jpg/500px-Yunchan_Lim_with_the_Los_Angeles_Philharmonic_in_concert_at_the_Hollywood_Bowl.jpg','1919','USA','로스앤젤레스 필하모닉(Los Angeles Philharmonic, LA Phil)은 1919년 미국 로스앤젤레스에서 창단된 오케스트라이다.\n\n구스타보 두다멜 등 혁신적인 지휘자들과 함께하며 현대 음악과 새로운 프로그램에 적극적이다. 미국의 주요 오케스트라 중 하나이다.','밝고 화려하며 역동적인 사운드가 특징이며, 현대적인 감각의 해석과 폭넓은 실험 정신을 보여준다.',5000,300,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(361,'메트로폴리탄 오페라 오케스트라','Metropolitan Opera Orchestra','orchestra','S',0.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/James_Levine_2013.jpg/500px-James_Levine_2013.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/James_Levine_2013.jpg/500px-James_Levine_2013.jpg','1883','USA','메트로폴리탄 오페라 오케스트라(Metropolitan Opera Orchestra)는 1883년 미국 뉴욕의 메트로폴리탄 오페라 극장 소속으로 창단된 세계 최고의 오페라 오케스트라 중 하나이다.\n\n오페라와 함께 교향곡 콘서트도 정기적으로 연주한다. 오페라 반주에 있어 독보적인 능력을 갖추었다.','드라마틱하고 유연한 앙상블을 바탕으로, 성악과 무대 연출에 최적화된 섬세하고 힘있는 연주를 한다.',10000,500,NULL,'2025-11-20 05:35:47','2025-11-20 11:17:04'),(362,'피츠버그 심포니','Pittsburgh Symphony Orchestra','orchestra','A',0.0,'https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse3.mm.bing.net%2Fth%2Fid%2FOIP.zhozgXevJtaIFpEL3FY5fgHaJA%3Fpid%3DApi&f=1&ipt=5bfd36eb8af2d8dac0b78d3871ae7a4a988820d351782afcc38dfe63343b5a70&ipo=images','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse2.mm.bing.net%2Fth%2Fid%2FOIP.xMJHW5o-GZTandDoLKdLwAHaE8%3Fpid%3DApi&f=1&ipt=1f984a493db79c77e167c03c31e61902005e2d1c97e4e8055f7bc678d9567e96&ipo=images','1895','USA','피츠버그 심포니 오케스트라(Pittsburgh Symphony Orchestra, PSO)는 1895년 미국 펜실베이니아주 피츠버그에서 창단된 오케스트라이다.\n\n프리츠 라이너 등 명지휘자들의 지휘 아래 탄탄한 연주력을 갖추었으며, 미국의 주요 오케스트라 중 하나이다.','균형 잡힌 사운드와 정교한 앙상블을 바탕으로, 고전부터 낭만주의에 이르는 다양한 레퍼토리를 소화한다.',5000,100,NULL,'2025-11-20 05:35:47','2025-11-20 11:31:44'),(363,'토론토 심포니','Toronto Symphony Orchestra','orchestra','A',0.0,'https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse1.mm.bing.net%2Fth%2Fid%2FOIP.KvzxkkBturG4-RzbTXSUHAHaFj%3Fpid%3DApi&f=1&ipt=ae54435504e7c288b0b78ef6e5700bf16e999b91a541dd1aa5160264369f7dd8&ipo=images','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse3.mm.bing.net%2Fth%2Fid%2FOIP.4DDyNEDGi2adeX3h5nZYIwHaEK%3Fpid%3DApi&f=1&ipt=6f35c0abc0038e5b7f8f64a38ecbb17767523e557de9abdb687a124cb8741c7b&ipo=images','1922','Canada','토론토 심포니 오케스트라(Toronto Symphony Orchestra, TSO)는 1922년 캐나다 토론토에서 창단된 캐나다를 대표하는 오케스트라이다.\n\n캐나다 국내외에서 활발하게 활동하며 북미의 주요 오케스트라 중 하나로 인정받는다.','활기차고 역동적인 연주 스타일을 지녔으며, 고전부터 현대 캐나다 작품까지 폭넓은 레퍼토리를 소화한다.',5000,100,NULL,'2025-11-20 05:35:47','2025-11-20 11:32:13'),(364,'몬트리올 심포니','Montreal Symphony Orchestra','orchestra','A',0.0,'https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse2.mm.bing.net%2Fth%2Fid%2FOIP.jDFTsSzY8f2owhEyVzHmpQAAAA%3Fpid%3DApi&f=1&ipt=8b426845cd320021ff115c4ed495b2bbb445bf3303f7ad64bb1f9e800aa3b562&ipo=images','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse3.mm.bing.net%2Fth%2Fid%2FOIP.C8HXddnrmd3n7fEb3lO3tgHaEK%3Fpid%3DApi&f=1&ipt=dcd8a859e0dd3818cf10d1e5381e94b6fe5d82b15e6dd603188ff0efd1ffed56&ipo=images','1935','Canada','몬트리올 심포니 오케스트라(Montreal Symphony Orchestra, OSM)는 1935년 캐나다 몬트리올에서 창단되었다.\n\n샤를 뒤투아의 지휘 아래 프랑스 레퍼토리 해석에 있어 세계적인 명성을 얻었다. 캐나다를 대표하는 주요 악단이다.','맑고 섬세하며 세련된 사운드가 특징이며, 특히 프랑스 음악 특유의 다채로운 색채를 아름답게 표현한다.',5000,100,NULL,'2025-11-20 05:35:47','2025-11-20 11:32:55'),(365,'세르게이 타라소프','Sergei Tarasov','피아니스트','A',4.0,'https://mblogthumb-phinf.pstatic.net/MjAxODAxMTJfMTA0/MDAxNTE1NzE5MzM3Nzk4.r0IfUXNQsl2Rwb7hzgqZH8EP2xQbZ3oqZMYYbWfwHekg.MGWzB1TLnQNf_LRGCy_X_Um7dr6BfJzS8yBZAQpFMJwg.PNG.gsorchestra/%EC%84%B8%EB%A5%B4%EA%B2%8C%EC%9D%B4_%ED%83%80%EB%9D%BC%EC%86%8C%ED%94%84.png?type=w800','https://mblogthumb-phinf.pstatic.net/MjAxODAxMTJfMTA0/MDAxNTE1NzE5MzM3Nzk4.r0IfUXNQsl2Rwb7hzgqZH8EP2xQbZ3oqZMYYbWfwHekg.MGWzB1TLnQNf_LRGCy_X_Um7dr6BfJzS8yBZAQpFMJwg.PNG.gsorchestra/%EC%84%B8%EB%A5%B4%EA%B2%8C%EC%9D%B4_%ED%83%80%EB%9D%BC%EC%86%8C%ED%94%84.png?type=w800','1971','러시아','러시아 모스크바 차이콥스키 국립 음악원 출신의 세계적인 비르투오소 피아니스트이다. 권위높은 피아노 교육자 레프 나우모프를 사사하며 정통 러시아 피아니즘의 계보를 잇고 있다. 세계 최고 권위의 국제 콩쿠르들을 연이어 석권하며 \'콩쿠르의 제왕\', \'그랜드 슬래머\'라는 별명을 가지고 있다. \n\n현재는 한국 대구의 계명대학교 교수로 재직하며 후학 양성과 연주 활동을 병행하고 있어 한국 클래식 팬들에게도 매우 친숙한 피아니스트이다.\n','강철 같은 타건과 웅장한 사운드를 자랑한다. 러시아 피아니스트 특유의 힘과 기교가 완벽하게 조화됐다. ',1000,13,NULL,'2025-11-28 16:19:15','2025-11-28 16:19:15'),(366,'크리스티안 짐머만','Krystian Zimerman','피아니스트','S',4.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/8/81/Krystian_Zimerman_2018.jpg/250px-Krystian_Zimerman_2018.jpg','https://i.namu.wiki/i/O7WR2MyFQowoTJBVAhAbeq5t4J_eRR8J66CwJV3Qwb3qsTu7OKrXInkYRDdf2587JDiB3680eyxG6uGCMWDsz2kGGL9M3_dD62h_JZQ7ooh4LKiKOBDgBsn2sUhsFLitacOqBq3j4i_tA1Z5SvzERw.webp','1956','폴란드','크리스티안 지메르만은 폴란드의 콘서트 피아니스트이자 지휘자로, 당대 최고의 피아니스트 중 한 명으로 알려져 있다. 1975년에는 IX 국제 쇼팽 피아노 콩쿠르에서 우승했다.\n\nZimerman은 폴란드 자브제에서 태어나 카토비체에서 공부했다. 그의 국제적인 경력은 1975년 바르샤바 쇼팽 피아노 콩쿠르에서 우승하면서 시작되었다. 그는 1976년 블롬슈테트가 지휘한 베를린 필하모닉과 함께 연주했다. 그는 1979년 뉴욕 필하모닉과 함께 미국에서 데뷔했다. 그는 광범위하게 여행했으며 많은 녹음을 했다. 1996년부터 그는 스위스 바젤에 있는 음악 아카데미에서 피아노를 가르쳤다. 1999년, 쇼팽의 서거 150주년을 기념하기 위해 폴란드 페스티벌 오케스트라를 창단했다. \n\n현재는 도이치 그라모폰(DG)과 평생 전속 계약을 맺고 베토벤, 브람스, 쇼팽, 드뷔시, 라흐마니노프 등 수많은 명반을 발매했다. 특히 레너드 번스타인, 헤르베르트 폰 카라얀 등 전설적인 지휘자들과 역사적인 명연주를 남겼으며, 루토스와프스키 피아노 협주곡을 헌정 받아 초연하기도 했다.\n베를린 필하모닉, 빈 필하모닉 등 세계 최정상급 오케스트라와 협연하지만, 완벽한 퀄리티 유지를 위해 연간 연주 횟수를 엄격히 제한한다. 최상의 음향을 위해 자신의 전용 피아노 액션을 직접 가지고 다니며 조립할 정도로 소리에 대한 집착과 완벽주의가 강한 것으로 유명하다.\n','철저하게 계산된 완벽한 구조미와 수정처럼 맑고 명료한 타건, 그리고 폭발적인 에너지와 섬세한 뉘앙스를 완벽하게 통제하는 지적이고 분석적인 연주 스타일을 보여준다.',100,30,NULL,'2025-11-28 17:13:51','2025-11-30 11:10:32'),(367,'블라디미르 호로비츠','Vladimir Samoylovych Horowitz','피아니스트','S',4.0,'https://i.namu.wiki/i/_liZDluMzI4tZtQMfKZ3FGPOiSsphOaGh_Irt_SH11B_hOoWKYi0gt4ERMxYHsXMeDmPhzoXRpdX1JSs4eZv4v2FG9DN2U00zw6IgyYIBYhVWJKAzgdqQlaJe1IgNo28QLyRvN68aR0nfynNiXuB-A.webp','https://i.namu.wiki/i/_liZDluMzI4tZtQMfKZ3FGPOiSsphOaGh_Irt_SH11B_hOoWKYi0gt4ERMxYHsXMeDmPhzoXRpdX1JSs4eZv4v2FG9DN2U00zw6IgyYIBYhVWJKAzgdqQlaJe1IgNo28QLyRvN68aR0nfynNiXuB-A.webp','1903','우크라이나','키에프 태생으로, 키에프 음악원에서 블루멘펠트예게서 가르침을 받고, 소년 시절부터 범상치 않은 천재적 재능을 발휘하였다. \n\n제1차 세계 대전 및 러시아 혁명 직후의 혼란기에 고국을 탈출, 1923년 독일 제국 바이에른주 뮌헨에서 피아니스트로 데뷔하였으며 이듬해 1924년 독일 제국 베를린에서 정식 데뷔하였고, 이후 영국 런던과 프랑스 파리에서 압도적인 호평을 받았다. 1928년 도미하여 성공적으로 데뷔하고, 곧 명지휘자 토스카니니에게 전폭적인 지지를 받았으며, 결국 그의 딸 완다와 결혼까지 하게 된다. \n\n그 후 구미에서 활약했으나 건강이 좋지 못하게 되어, 1953년에는 완전히 무대에서 물러났다. 하지만 1965년 5월에는 카네기 홀에서 부활 독주회를 개최하여 무대에 다시 복귀하였다. 그는 몸이 다소 허약하였지만 손가락 끝은 날카로워 명확한 터치에 능하고, 다이내믹하다는 평을 들었다. 또 옥타브의 연속, 세련되면서도 박력있는 음악적 효과를 빚어내는데도 뛰어난 재능을 보였다. 하지만 한 작곡가의 작품에 몰입하여 작품을 연주하지 않은 것은 그의 약점으로 항상 지적받았다. 템포, 리듬은 빈틈없이 꼼꼼했지만, 후기에는 건강 상태 때문에 점차로 음악에 주관이 강한 낭만적 기분이 강렬하게 나타나, 과거의 확고한 템포나 리듬이 자유로이 다뤄지는 경향이 점점 심해졌다. \n\n명연주는 쇼팽의 〈스케르초 1번〉, 〈바르카롤>, <소나타 2번>, 〈마주르카〉, 리스트의 <피아노 소나타 B단조>와 〈오베르만의 골짜기〉, 슈만의 〈어린이의 정경〉, 라흐마니노프의 <피아노 협주곡 제3번>과 <피아노 소나타 2번>, 스크랴빈의 <연습곡>, <전주곡> 및 〈시곡〉과 〈소나타 9번〉, 스카를라티의 소나타 등이다. ','손가락을 펴고 치는 독특한 주법에서 나오는 다이내믹과 악마적인 기교, 그리고 몽환적이고 다채로운 음색으로 청중을 압도하는 카리스마 넘치는 연주 스타일을 갖고 있다.',20,50,NULL,'2025-11-28 17:33:07','2025-11-28 17:33:07'),(368,'아르투르 루빈스타인','Artur Rubinstein','피아니스트','S',4.0,'https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Optreden_Arthur_Rubinstein_in_Concertgebouw%2C_Bestanddeelnr_913-5228.jpg/500px-Optreden_Arthur_Rubinstein_in_Concertgebouw%2C_Bestanddeelnr_913-5228.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Optreden_Arthur_Rubinstein_in_Concertgebouw%2C_Bestanddeelnr_913-5228.jpg/500px-Optreden_Arthur_Rubinstein_in_Concertgebouw%2C_Bestanddeelnr_913-5228.jpg','1887','폴란드','아르투르 루빈스타인은 1887년 폴란드 우치 출신의 피아니스트이다. 1982년 타계하기 전까지 쇼팽 음악의 가장 권위 있는 해석자이자 \'행복한 피아니스트\'의 상징으로 사랑받았다.\n\n요제프 요아힘의 후원을 받으며 베를린에서 공부했고, 신동으로 일찍 데뷔했다. 젊은 시절에는 천재성에 의존해 방탕한 생활을 하며 기교적 완성도가 떨어진다는 비판도 받았으나, 결혼 후 중년에 접어들며 맹렬한 연습 끝에 완벽한 거장으로 재탄생했다. 이는 음악사에서 보기 드문 \'대기만성형\' 천재의 사례로 꼽힌다.\n\nRCA 레드 씰(Red Seal) 레이블의 간판 아티스트로서 역사상 가장 방대한 양의 레코딩을 남겼다. 쇼팽의 거의 모든 피아노 곡을 녹음하여 현대 쇼팽 해석의 기준을 정립했으며, 90세에 가까운 나이까지 전 세계를 누비며 시력을 거의 잃을 때까지 무대에 섰던 진정한 \'철인\'이자 애주가, 미식가, 그리고 삶을 사랑한 예술가였다.\n\n루빈스타인은 자신의 삶과 음악에 대해 다음과 같이 회고했다.\n\n“음악은 단순히 내 삶이다. 나는 그것을 살고, 숨쉬며, 이야기한다. 나는 거의 무의식적으로 음악을 느낀다. 아니, 그것을 당연하게 여긴다는 뜻은 아니다. 하나님의 어떤 선물도 당연하게 여겨서는 안 된다. 하지만 음악은 내 팔, 다리와 같이 내 일부이다. 한편, 책, 그림, 언어, 사람들은 내 열정이며, 언제나 배양해야 할 대상이다. 여행도 마찬가지다. 나는 길 위에서 많은 시간을 보낼 수 있는 직업을 가진 행운아다. 기차나 비행기 안에서 나는 독서를 할 시간이 있다. 그래서 피아노 연주자가 된 것이 행운이다. 피아노는 멋진 악기다. 크기가 딱 맞아서 어디로든 가지고 다닐 수 없다. 그래서 연습 대신 독서를 할 수 있다. 정말 운이 좋은 사람이 아닌가?\"','물 흐르듯 자연스러운 프레이징과 황금의 톤이라 불리는 따뜻하고 윤기 있는 음색을 바탕으로, 과도한 감상주의를 배제한 고귀하고 남성적이며 생동감 넘치는 연주를 들려준다.',100,120,NULL,'2025-11-28 17:37:35','2025-11-28 17:37:35'),(369,'안나 페도로바','Anna Fedorova','피아니스트','A',4.0,'https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse3.mm.bing.net%2Fth%2Fid%2FOIP.diH2wkDG6mUsEwo7kwlEfAHaLD%3Fpid%3DApi&f=1&ipt=73bdcbbd8a5655d8c4ae4527510a5d445967bd4d6591025ef4620e46ccb0df56&ipo=images','https://external-content.duckduckgo.com/iu/?u=https%3A%2F%2Ftse3.mm.bing.net%2Fth%2Fid%2FOIP.diH2wkDG6mUsEwo7kwlEfAHaLD%3Fpid%3DApi&f=1&ipt=73bdcbbd8a5655d8c4ae4527510a5d445967bd4d6591025ef4620e46ccb0df56&ipo=images','1990','우크라이나','안나 보리시브나 페도로바는 우크라이나의 콘서트 피아니스트이다. 페도로바는 네덜란드, 독일, 프랑스, 이탈리아 영국 등 여러 나라의 주요 콘서트홀에서 솔리스트, 실내약 연주자, 심포니 오케스트라와 함께 연주하고 있다. 페도로바는 데이비드 영 피아노상 수상자이며, 소아레 도르 상과 키보드 트러스트의 지원을 받고 있다.\n\n페도로바는 우크라이나에서 태어났으며, 2살 때부터 항상 피아니스트가 되고 싶어 했다. 페도로바는 다섯 살 때 연주를 시작했고, 여섯 살 때 첫 공개 리사이틀을 열고 일곱 살 때 우크라이나 국립 필하모닉 협회에서 국민 데뷔 무대를 가졌다.\n어린 시절에 대해 페도로바는 부모님 두 분다 전문 피아니스트였기에 항상 \"집 안에는 피아노 소리\"가 있었다고 말했다. 부모님이 페도로바에게 레슨을 가르쳐 주었고, 페도로바는 부모님이 내 음악적 성장에 결정적인 역할을 했다고 전한다.\n\n페도로바는 수많은 국제 음악 축제에 출연했으며, 이탈리아, 그리스, 독일, 슬로바키아, 에스토니아, 체코에서 최고상을 수상했다. ','언제나 섬세하고, 시적이며, 세련되는 연주를 들려준다.',50,0,NULL,'2025-12-03 10:09:49','2025-12-03 10:25:23');
