  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_composer_piece` (`composer_id`,`piece_id`),
  KEY `idx_composer_id` (`composer_id`),
  KEY `idx_piece_id` (`piece_id`),
  CONSTRAINT `composer_major_pieces_ibfk_1` FOREIGN KEY (`composer_id`) REFERENCES `composers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `composer_major_pieces_ibfk_2` FOREIGN KEY (`piece_id`) REFERENCES `pieces` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
