DROP TABLE IF EXISTS `composers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `composers` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '한글명',
  `full_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '전체 한글명',
  `english_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '영문명',
  `period` enum('바로크','고전주의','낭만주의','근현대') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '시대',
  `tier` enum('S','A','B','C') COLLATE utf8mb4_unicode_ci DEFAULT 'B' COMMENT '티어',
  `birth_year` int NOT NULL,
  `death_year` int DEFAULT NULL,
  `nationality` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '국적',
  `avatar_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '아바타 이미지 URL',
  `cover_image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '커버 이미지 URL',
  `bio` text COLLATE utf8mb4_unicode_ci COMMENT '소개',
  `style` text COLLATE utf8mb4_unicode_ci COMMENT '음악 스타일',
  `influence` text COLLATE utf8mb4_unicode_ci COMMENT '영향력',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_period` (`period`),
  KEY `idx_tier` (`tier`),
  KEY `idx_birth_year` (`birth_year`)
) ENGINE=InnoDB AUTO_INCREMENT=117 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
