--
-- Table structure for table `concert_boxoffice_rankings`
--

DROP TABLE IF EXISTS `concert_boxoffice_rankings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `concert_boxoffice_rankings` (
  `id` int NOT NULL AUTO_INCREMENT,
  `concert_id` int NOT NULL COMMENT '공연 ID',
  `kopis_genre_code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'KOPIS 장르 코드 (AAAA=연극, GGGA=뮤지컬, CCCA=클래식 등)',
  `genre_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '장르명 (연극, 뮤지컬, 클래식, 오페라, 무용, 국악, 복합)',
  `kopis_area_code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'KOPIS 지역 코드 (11=서울, 28=인천 등)',
  `area_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '지역명 (서울, 경기, 인천 등)',
  `ranking` int NOT NULL COMMENT '순위 (1-3만 저장)',
  `seat_scale` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '좌석규모 (100, 300, 500, 1000, 5000, 10000)',
  `performance_count` int DEFAULT '0' COMMENT '상연횟수 (prfdtcnt)',
  `venue_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '공연장명 캐시 (prfplcnm)',
  `seat_count` int DEFAULT NULL COMMENT '좌석수 (seatcnt)',
  `sync_start_date` date NOT NULL COMMENT 'KOPIS 조회 시작일 (stdate)',
  `sync_end_date` date NOT NULL COMMENT 'KOPIS 조회 종료일 (eddate)',
  `synced_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '동기화 시각',
  `is_featured` tinyint(1) DEFAULT '1' COMMENT '주목 공연 여부 (TOP 3는 항상 true)',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_ranking_slot` (`kopis_genre_code`,`kopis_area_code`,`ranking`),
  KEY `idx_concert_id` (`concert_id`),
  KEY `idx_genre_area` (`kopis_genre_code`,`kopis_area_code`),
  KEY `idx_ranking` (`ranking`),
  KEY `idx_sync_dates` (`sync_start_date`,`sync_end_date`),
  KEY `idx_featured` (`is_featured`),
  CONSTRAINT `concert_boxoffice_rankings_ibfk_1` FOREIGN KEY (`concert_id`) REFERENCES `concerts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=153 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='KOPIS 예매상황판 TOP 3 공연 순위 정보';
/*!40101 SET character_set_client = @saved_cs_client */;

