--
-- Table structure for table `concert_images`
--

DROP TABLE IF EXISTS `concert_images`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `concert_images` (
  `id` int NOT NULL AUTO_INCREMENT,
  `concert_id` int NOT NULL COMMENT '공연 ID',
  `image_url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '이미지 URL (styurl)',
  `image_type` enum('introduction','poster','other') COLLATE utf8mb4_unicode_ci DEFAULT 'introduction' COMMENT '이미지 타입',
  `display_order` int DEFAULT '0' COMMENT '표시 순서',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_concert_id` (`concert_id`),
  KEY `idx_image_type` (`image_type`),
  CONSTRAINT `concert_images_ibfk_1` FOREIGN KEY (`concert_id`) REFERENCES `concerts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5704 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='공연 소개 이미지 테이블 (KOPIS styurls)';
/*!40101 SET character_set_client = @saved_cs_client */;

