--
-- Table structure for table `concert_ticket_vendors`
--

DROP TABLE IF EXISTS `concert_ticket_vendors`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `concert_ticket_vendors` (
  `id` int NOT NULL AUTO_INCREMENT,
  `concert_id` int NOT NULL COMMENT '공연 ID',
  `vendor_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '예매처명 (relatenm)',
  `vendor_url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '예매처 URL (relateurl)',
  `display_order` int DEFAULT '0' COMMENT '표시 순서',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_concert_id` (`concert_id`),
  CONSTRAINT `concert_ticket_vendors_ibfk_1` FOREIGN KEY (`concert_id`) REFERENCES `concerts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7744 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='공연 예매처 정보 테이블 (KOPIS relates)';
/*!40101 SET character_set_client = @saved_cs_client */;

