--
-- Table structure for table `concerts`
--

DROP TABLE IF EXISTS `concerts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `concerts` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '공연 제목',
  `composer_info` text COLLATE utf8mb4_unicode_ci COMMENT '작곡가/곡목',
  `venue_id` int NOT NULL COMMENT '공연장 ID',
  `start_date` date NOT NULL COMMENT '공연 시작일 (prfpdfrom)',
  `concert_time` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '공연 시간 (예: 목요일(19:30))',
  `price_info` text COLLATE utf8mb4_unicode_ci COMMENT '가격 정보 (pcseguidance) - 상세 좌석별 가격 포함',
  `poster_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '포스터 이미지 URL',
  `program` text COLLATE utf8mb4_unicode_ci COMMENT '프로그램 상세',
  `is_recommended` tinyint(1) DEFAULT '0' COMMENT '추천 공연 여부',
  `status` enum('upcoming','ongoing','completed','cancelled','공연예정','공연중','공연완료') COLLATE utf8mb4_unicode_ci DEFAULT 'upcoming' COMMENT '공연 상태 (영문/한글 혼용)',
  `rating` decimal(2,1) DEFAULT '0.0' COMMENT '평균 평점 (0.0-5.0)',
  `rating_count` int DEFAULT '0' COMMENT '평점 개수',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `end_date` date DEFAULT NULL COMMENT '공연 종료일 (prfpdto)',
  `kopis_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'KOPIS 공연ID (mt20id, 예: PF123456)',
  `kopis_updated_at` datetime DEFAULT NULL COMMENT 'KOPIS 최종수정일 (updatedate)',
  `data_source` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'MANUAL' COMMENT '데이터 출처 (KOPIS, MANUAL)',
  `venue_kopis_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'KOPIS 공연시설ID (mt10id) - venues.kopis_id 참조용',
  `genre` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '공연 장르명 (genrenm)',
  `area` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '공연 지역 (area)',
  `facility_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '공연시설명 캐시 (fcltynm)',
  `is_open_run` tinyint(1) DEFAULT '0' COMMENT '오픈런 여부 (openrun: Y/N)',
  `cast` text COLLATE utf8mb4_unicode_ci COMMENT '공연 출연진 (prfcast)',
  `crew` text COLLATE utf8mb4_unicode_ci COMMENT '공연 제작진 (prfcrew)',
  `runtime` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '공연 런타임 (prfruntime, 예: 1시간 30분)',
  `age_restriction` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '관람 연령 (prfage, 예: 만 12세 이상)',
  `synopsis` text COLLATE utf8mb4_unicode_ci COMMENT '줄거리/소개 (sty)',
  `performance_schedule` text COLLATE utf8mb4_unicode_ci COMMENT '공연 시간 상세 (dtguidance)',
  `production_company` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '기획제작사 (entrpsnm)',
  `production_company_plan` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '제작사 (entrpsnmP)',
  `production_company_agency` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '기획사 (entrpsnmA)',
  `production_company_host` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '주최 (entrpsnmH)',
  `production_company_sponsor` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '주관 (entrpsnmS)',
  `is_visit` tinyint(1) DEFAULT '0' COMMENT '내한공연 여부 (visit: Y/N)',
  `is_child` tinyint(1) DEFAULT '0' COMMENT '아동공연 여부 (child: Y/N)',
  `is_daehakro` tinyint(1) DEFAULT '0' COMMENT '대학로공연 여부 (daehakro: Y/N)',
  `is_festival` tinyint(1) DEFAULT '0' COMMENT '축제공연 여부 (festival: Y/N)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `kopis_id` (`kopis_id`),
  KEY `venue_id` (`venue_id`),
  KEY `idx_concert_date` (`start_date`),
  KEY `idx_status` (`status`),
  KEY `idx_recommended` (`is_recommended`),
  KEY `idx_rating` (`rating`),
  KEY `idx_start_date` (`start_date`),
  KEY `idx_end_date` (`end_date`),
  KEY `idx_kopis_id` (`kopis_id`),
  KEY `idx_data_source` (`data_source`),
  KEY `idx_venue_kopis_id` (`venue_kopis_id`),
  KEY `idx_genre` (`genre`),
  KEY `idx_area` (`area`),
  KEY `idx_is_open_run` (`is_open_run`),
  KEY `idx_is_visit` (`is_visit`),
  KEY `idx_is_child` (`is_child`),
  KEY `idx_is_daehakro` (`is_daehakro`),
  KEY `idx_is_festival` (`is_festival`),
  KEY `idx_title` (`title`),
  KEY `idx_facility_name` (`facility_name`),
  KEY `idx_composer_info` (`composer_info`(255)),
  CONSTRAINT `concerts_ibfk_1` FOREIGN KEY (`venue_id`) REFERENCES `venues` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=5057 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `concerts`
--

