--
-- Table structure for table `halls`
--

DROP TABLE IF EXISTS `halls`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `halls` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '공연홀 ID',
  `venue_id` int NOT NULL COMMENT '공연장 ID',
  `kopis_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'KOPIS 공연홀 ID (예: PA0001)',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '공연홀명',
  `seats` int DEFAULT NULL COMMENT '좌석수',
  `is_active` tinyint(1) DEFAULT '1' COMMENT '운영 여부',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '생성일시',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '수정일시',
  PRIMARY KEY (`id`),
  UNIQUE KEY `kopis_id` (`kopis_id`),
  KEY `idx_venue_id` (`venue_id`),
  KEY `idx_kopis_id` (`kopis_id`),
  CONSTRAINT `halls_ibfk_1` FOREIGN KEY (`venue_id`) REFERENCES `venues` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4894 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='공연홀 정보 테이블 (한 공연장 내 여러 홀)';
/*!40101 SET character_set_client = @saved_cs_client */;

