DROP TABLE IF EXISTS `performance_sectors`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `performance_sectors` (
  `id` int NOT NULL AUTO_INCREMENT,
  `piece_id` int NOT NULL,
  `sector_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '섹터명 (예: 1악장, 빠른 템포, 라이브 버전)',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '섹터 설명',
  `display_order` int DEFAULT '0' COMMENT '표시 순서',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_piece_id` (`piece_id`),
  KEY `idx_display_order` (`display_order`),
  KEY `idx_piece_sector_order` (`piece_id`,`display_order`),
  CONSTRAINT `performance_sectors_ibfk_1` FOREIGN KEY (`piece_id`) REFERENCES `pieces` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='연주 섹터/악장 테이블 - 곡의 섹터별 연주 그룹화';
/*!40101 SET character_set_client = @saved_cs_client */;

