INSERT INTO `performance_sectors` VALUES (1,10,'1악장','ㅁㄴㅇㄹㅁㄴㅇㄹ',0,'2025-11-27 08:09:05','2025-11-27 08:09:05'),(2,10,'2악장','asdf',0,'2025-11-27 08:09:42','2025-11-27 08:09:42'),(3,10,'3악장','123',0,'2025-11-27 08:52:43','2025-11-27 08:52:43'),(4,103,'11','11',0,'2025-11-27 13:37:40','2025-11-27 13:37:40'),(5,103,'22','22',0,'2025-11-27 13:37:44','2025-11-27 13:37:44'),(7,129,'서주 & 제1주제 (Introduction & 1st Theme)','곡의 시작인 Largo의 무거운 옥타브와, 뒤이어 나오는 Moderato의 슬픈 멜로디가 감상의 포인트이다. 첫 음의 무게감과 멜로디의 한을 표현하는 방식이 연주자마다 천차만별이다.',1,'2025-11-28 17:07:12','2025-11-28 17:07:12'),(8,129,'제 2주제 (Second Theme, Meno mosso)','격정적인 1주제가 지나고, 분위기가 완전히 바뀌어 Eb 장조의 꿈꾸는 듯한 멜로디가 나오는 부분이다. 쇼팽 발라드 1번에서 가장 아름다운 구간으로 꼽힌다.',1,'2025-11-28 17:52:53','2025-11-28 17:52:53'),(9,129,'코다(Coda, Presto con fuoco)','\"Il più forte possibile\" (가능한 한 크게)라는 지시어와 함께 폭발적인 화음이 나온 뒤, 잠시 숨을 고르고 미친듯이 질주하는 구간이다.',3,'2025-11-28 18:10:53','2025-11-28 18:10:53'),(11,225,'1악장','라흐마니노프 피아노 협주곡1 악장',0,'2025-12-03 10:00:48','2025-12-03 10:00:48'),(12,225,'2악장','라흐마니노프 피아노 협주곡 2악장',0,'2025-12-03 10:01:04','2025-12-03 10:01:04'),(13,225,'3악장','라흐마니노프 피아노 협주곡 3악장',0,'2025-12-03 10:01:15','2025-12-03 10:01:15'),(14,226,'1악장 카덴챠','1악장 카덴챠로 오시아 버전과 오리지널 버전을 연주자마다 선택해 연주하기 때문에, 비교에 좋다.',0,'2025-12-05 07:17:19','2025-12-05 07:17:19'),(17,226,'2악장','2악장 하이라이트 비교',1,'2025-12-05 07:43:20','2025-12-05 07:43:20'),(18,226,'3악장 - 클라이맥스','2악장 클라이맥스부터 3악장 피날레까지',3,'2025-12-05 07:55:33','2025-12-05 07:55:33'),(19,226,'3악장 - 도입부','2악장 도입부',3,'2025-12-05 08:05:37','2025-12-05 08:05:37');
/*!40000 ALTER TABLE `performance_sectors` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `performances`
