DROP TABLE IF EXISTS `performances`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `performances` (
  `id` int NOT NULL AUTO_INCREMENT,
  `piece_id` int NOT NULL,
  `sector_id` int NOT NULL,
  `artist_id` int NOT NULL,
  `video_platform` enum('youtube','vimeo','other') COLLATE utf8mb4_unicode_ci DEFAULT 'youtube',
  `video_id` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '플랫폼별 비디오 ID',
  `start_time` int DEFAULT '0' COMMENT '시작 시간 (초)',
  `end_time` int DEFAULT '0' COMMENT '종료 시간 (초)',
  `characteristic` text COLLATE utf8mb4_unicode_ci COMMENT '연주 특징',
  `view_count` int DEFAULT '0' COMMENT '조회수',
  `rating` decimal(2,1) DEFAULT '0.0' COMMENT '평점',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_piece_id` (`piece_id`),
  KEY `idx_artist_id` (`artist_id`),
  KEY `idx_rating` (`rating`),
  KEY `idx_sector_id` (`sector_id`),
  KEY `idx_piece_sector` (`piece_id`,`sector_id`),
  CONSTRAINT `fk_performances_sector` FOREIGN KEY (`sector_id`) REFERENCES `performance_sectors` (`id`) ON DELETE CASCADE,
  CONSTRAINT `performances_ibfk_1` FOREIGN KEY (`piece_id`) REFERENCES `pieces` (`id`) ON DELETE CASCADE,
  CONSTRAINT `performances_ibfk_2` FOREIGN KEY (`artist_id`) REFERENCES `artists` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=44 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

