INSERT INTO `performances` VALUES (3,10,1,326,'youtube','9sat8K5iCg0',30,90,'123123',0,0.0,'2025-11-27 08:09:35','2025-11-27 08:11:21'),(4,103,4,187,'youtube','9sat8K5iCg0',10,70,NULL,0,0.0,'2025-11-27 13:38:03','2025-11-27 13:38:03'),(5,103,4,202,'youtube','9sat8K5iCg0',30,60,'Asdf',0,0.0,'2025-11-27 13:38:18','2025-11-27 13:38:18'),(6,103,4,187,'youtube','9sat8K5iCg0',100,110,NULL,0,0.0,'2025-11-27 13:38:39','2025-11-27 13:38:39'),(7,129,7,366,'youtube','YYUu4Rl7EdE',5,187,'숨 막힐 듯한 정적과 계산된 타건',0,0.0,'2025-11-28 17:27:07','2025-11-28 17:51:38'),(8,129,7,186,'youtube','taY5oHleS4I',5,195,'서주부터 매우 서정적이며, 1주제에서 건반을 이루어만지듯 노래한다.',0,0.0,'2025-11-28 17:28:08','2025-11-28 17:50:53'),(9,129,7,367,'youtube','eG1Olvh7vCU',0,167,'다소 투박하고 무심한 듯 툭 던지는 첫 음이 인상적이다.',0,0.0,'2025-11-28 17:44:14','2025-11-28 17:50:05'),(10,129,7,368,'youtube','l7GtUKE-Ju0',0,170,'과장 없이 담백하고 거전적인 품격을 보여준다.',0,0.0,'2025-11-28 17:45:33','2025-11-28 17:49:13'),(11,129,7,206,'youtube','SlJEjza0-FQ',2,198,'첫 음부터 깊고 웅장한 울림을 만들어내며 진행한다.',0,0.0,'2025-11-28 17:46:51','2025-11-28 17:48:03'),(12,129,8,366,'youtube','YYUu4Rl7EdE',189,280,'유리알처럼 투명하고 영롱한 음색이 돋보인다.',0,0.0,'2025-11-28 17:59:06','2025-11-28 18:01:54'),(13,129,8,186,'youtube','taY5oHleS4I',196,293,'템포를 충분히 늦춰 꿈속을 거니는 듯한 낭만성을 극대화한다.',0,0.0,'2025-11-28 18:01:41','2025-11-28 18:01:41'),(14,129,8,367,'youtube','eG1Olvh7vCU',183,256,'낭만적이지만 절대 질질 끌지 않으며, 흐름을 유려하게 이어간다.',0,0.0,'2025-11-28 18:03:28','2025-11-28 18:03:28'),(15,129,8,368,'youtube','l7GtUKE-Ju0',170,270,'따뜻하고 인간적인 음색으로 관객에게 말을 건네는 듯하다.',0,0.0,'2025-11-28 18:04:55','2025-11-28 18:04:55'),(16,129,8,206,'youtube','SlJEjza0-FQ',200,308,'섬세하면서도 심지가 굳은, 흔들리지 않는 서정을 보여준다.',0,0.0,'2025-11-28 18:06:23','2025-11-28 18:06:23'),(17,129,9,366,'youtube','YYUu4Rl7EdE',470,563,'빠른 템포 속에서도 흐트러짐 없이 모든 음이 명료하게 들리는 교과서적인 완벽함',0,0.0,'2025-11-28 18:13:49','2025-11-28 18:27:50'),(18,129,9,186,'youtube','taY5oHleS4I',470,577,'젊은 거장의 패기가 느껴지는 폭발적인 타건과 격정적인 질주가 돋보이는 드라마틱한 해석',0,0.0,'2025-11-28 18:15:10','2025-11-28 18:28:09'),(19,129,9,367,'youtube','eG1Olvh7vCU',429,517,'미스터치마저 예술로 승화시키는 악마적인 속도와 광기 어린 다이내믹의 절정',0,0.0,'2025-11-28 18:16:24','2025-11-28 18:28:30'),(20,129,9,368,'youtube','l7GtUKE-Ju0',465,550,'급하게 서두르지 않고 묵직한 타건으로 건반 깊숙이 소리를 뽑아내는 웅장한 남성미',0,0.0,'2025-11-28 18:17:39','2025-11-28 18:28:46'),(21,129,9,206,'youtube','SlJEjza0-FQ',480,587,'강철 같은 손가락으로 피아노를 부술 듯 내리꽂는 압도적인 파워와 흔들림 없는 리듬',0,0.0,'2025-11-28 18:18:49','2025-11-28 18:29:03'),(23,225,11,369,'youtube','rEGOihjqO9w',328,445,NULL,0,0.0,'2025-12-03 10:10:37','2025-12-03 10:10:37'),(24,225,11,186,'youtube','YviN1tuXbzc',358,473,NULL,0,0.0,'2025-12-03 10:11:25','2025-12-03 10:11:25'),(25,225,11,201,'youtube','NsqXCO0ADwM',315,420,NULL,0,0.0,'2025-12-03 10:12:53','2025-12-03 10:12:53'),(26,225,12,369,'youtube','rEGOihjqO9w',1335,1375,NULL,0,0.0,'2025-12-03 10:13:44','2025-12-03 10:13:44'),(27,225,12,186,'youtube','YviN1tuXbzc',1356,1402,NULL,0,0.0,'2025-12-03 10:14:17','2025-12-03 10:14:17'),(28,225,12,201,'youtube','NsqXCO0ADwM',1241,1280,NULL,0,0.0,'2025-12-03 10:14:40','2025-12-03 10:14:40'),(29,225,13,369,'youtube','rEGOihjqO9w',2069,2147,NULL,0,0.0,'2025-12-03 10:15:22','2025-12-03 10:19:46'),(30,225,13,186,'youtube','YviN1tuXbzc',2050,2127,NULL,0,0.0,'2025-12-03 10:15:44','2025-12-03 10:24:31'),(31,225,13,201,'youtube','NsqXCO0ADwM',1894,1961,NULL,0,0.0,'2025-12-03 10:16:16','2025-12-03 10:19:18'),(32,226,14,187,'youtube','DPJL488cfRw',670,771,'오리지널 카덴챠',0,0.0,'2025-12-05 07:19:34','2025-12-05 07:22:07'),(33,226,14,200,'youtube','KUbi0nEnUi4',672,820,'오시아 카덴챠',0,0.0,'2025-12-05 07:20:55','2025-12-05 07:21:57'),(34,226,14,201,'youtube','5bX_yRzCuM4',672,764,'오리지널 카덴챠',0,0.0,'2025-12-05 07:23:52','2025-12-05 07:23:52'),(35,226,17,187,'youtube','DPJL488cfRw',1429,1515,NULL,0,0.0,'2025-12-05 07:43:22','2025-12-05 07:43:22'),(36,226,17,201,'youtube','5bX_yRzCuM4',1417,1516,NULL,0,0.0,'2025-12-05 07:43:23','2025-12-05 07:43:23'),(37,226,17,200,'youtube','KUbi0nEnUi4',1114,1214,NULL,0,0.0,'2025-12-05 07:43:24','2025-