/*!40000 ALTER TABLE `performances` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `pieces`
--

DROP TABLE IF EXISTS `pieces`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pieces` (
  `id` int NOT NULL AUTO_INCREMENT,
  `composer_id` int NOT NULL,
  `title` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '곡 제목',
  `title_en` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '곡 영문 제목',
  `type` enum('album','song') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'song' COMMENT '곡 타입 (album: 앨범/모음집, song: 단일곡)',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '곡 설명',
  `opus_number` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Opus 번호',
  `composition_year` int DEFAULT NULL COMMENT '작곡 연도',
  `difficulty_level` int DEFAULT NULL COMMENT '난이도 (1-10)',
  `duration_minutes` int DEFAULT NULL COMMENT '연주 시간 (분)',
  `spotify_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Spotify 링크',
  `apple_music_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Apple Music 링크',
  `youtube_music_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'YouTube Music 링크',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_composer_id` (`composer_id`),
  KEY `idx_difficulty_level` (`difficulty_level`),
  KEY `idx_type` (`type`),
  CONSTRAINT `pieces_ibfk_1` FOREIGN KEY (`composer_id`) REFERENCES `composers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=461 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `pieces`
--

LOCK TABLES `pieces` WRITE;
/*!40000 ALTER TABLE `pieces` DISABLE KEYS */;
INSERT INTO `pieces` VALUES (10,4,'평균율 클라비어곡집 (1권&2권)','The Well-Tempered Clavier (Books 1 & 2)','album','\'음악의 구약성서\'로 불린다. 모든 24개의 장/단조로 작곡된 프렐류드와 푸가 모음곡이다. 모든 조를 사용할 수 있게 조율된 \'평균율\'의 가능성을 탐구한 기념비적인 작품이다.','BWV 846–893',1,8,4,'https://open.spotify.com/album/5NqQLA1NCo6hP2GHiHxip5','https://music.apple.com/us/album/bach-the-well-tempered-clavier-books-i-ii-bwv-846-893/557314205',NULL,'2025-11-15 03:10:43','2025-11-18 07:33:16'),(11,4,'골든베르크 변주곡','Goldberg Variations','album','불면증에 시달리던 카이절링 백작을 위해 작곡되었다는 일화로 유명하다. 하나의 아리아(주제)를 바탕으로 30개의 정교하고 화려한 변주가 펼쳐지는 바흐 건반 음악의 최고 걸작 중 하나이다.','BWV 988',1741,10,1,'https://open.spotify.com/album/1aCpHSQE5ghxibsQ5gkBe0','https://music.apple.com/us/album/bach-goldberg-variations-bwv-988-the-1955-1981-recordings/594521223',NULL,'2025-11-15 04:37:08','2025-11-18 07:33:18'),(12,4,'무반주 첼로 모음곡','Cello Suites','album','첼로 독주곡의 \'성서\'로 불린다. 첼로라는 악기 하나만으로 풍부한 화성과 대위법적 선율을 표현해낸 작품이다. 각 모음곡은 프렐류드와 여러 춤곡(알르망드, 쿠랑트, 사라방드, 지그 등)으로 구성된다.','BWV 1007–1012',1717,9,2,'https://open.spotify.com/album/79Rf5HqOCOiNdNhHySN5MZ','https://music.apple.com/us/album/j-s-bach-cello-suites-bwv-1007-1012/1452330111',NULL,'2025-11-15 05:20:53','2025-11-18 07:33:20'),(13,4,'무반주 바이올린 소나타와 파르티타','Sonatas and Partitas for Solo Violin','album','바이올린 독주곡의 정점이다. 특히 파르티타 2번의 마지막 곡 \'샤콘(Chaconne)\'은 단일 악장으로서는 가장 위대한 바이올린 곡 중 하나로 꼽힌다. 4개의 현으로 복잡한 화음과 대위법을 연주해야 한다.','BWV 1001–1006',1720,10,2,'https://open.spotify.com/album/7DD3JOUPtmlQqkVjFXZh4u','https://music.apple.com/us/album/bach-sonatas-and-partitas-for-solo-violin-bwv-1001-1006/277622927',NULL,'2025-11-15 05:24:50','2025-11-18 07:33:22'),(14,4,'브란덴부르크 협주곡','Brandenburg Concertos','album','브란덴부르크 변경백에게 헌정된 6개의 협주곡 모음이다. 다양한 악기 조합(독주 악기군)과 오케스트라가 대비를 이루는 \'합주 협주곡(콘체르토 그로소)\' 양식의 최고 걸작이다.','BWV 1046–1051',1721,9,1,'https://open.spotify.com/album/3tocyBfVMKxWzgxWOMlNDF','https://music.apple.com/us/album/bach-cello-suites-nos-1-6-bwv-1007-1012-2009-remaster/381515547',NULL,'2025-11-15 05:26:44','2025-11-18 07:33:24'),(15,4,'마태 수난곡','St. Matthew Passion','album','신약성서의 마태복음을 바탕으로 예수의 수난과 죽음을 다룬 거대한 규모의 오라토리오(종교 극음악)이다. 서양 음악사상 가장 위대한 종교 음악 작품으로 꼽힌다.','BWV 244',1727,10,2,'https://open.spotify.com/album/3GEgTdKwNgbNm1eyZm47bZ','https://music.apple.com/us/album/bach-st-matthew-passion-bwv-244/1452138402',NULL,'2025-11-15 05:28:18','2025-11-18 07:33:26'),(16,4,'토카타와 푸가 D단조','Toccata and Fugue in D minor','song','\"빰~ 빠바바밤~\" 하는 압도적인 도입부로 유명한, 바흐의 오르간 곡 중 가장 대중적인 작품이다. 극적인 토카타(즉흥 연주풍) 부분과 치밀한 푸가 부분이 결합되어 있다.','BWV 565',1704,8,10,'https://open.spotify.com/track/7hipIGAakhd6TIWfUv41Fu','https://music.apple.com/us/album/toccata-and-fugue-in-d-minor-bwv-565/1849657189?i=1849657208',NULL,'2025-11-15 05:30:26','2025-11-18 07:33:28'),(17,5,'오르페오','L\'Orfeo','album','몬테베르디의 첫 오페라이자, 음악사상 최초의 위대한 오페라로 꼽히는 작품이다. 그리스 신화의 오르페우스 이야기를 다루며, 사랑하는 아내 에우리디체를 되찾기 위해 지옥으로 향하는 여정을 그린다.','SV 318',1607,10,1,'https://open.spotify.com/album/4Jg7W8l7VQNhxJzsdvhV7w','https://music.apple.com/us/album/claudio-monteverdi-lorfeo/996012010',NULL,'2025-11-16 04:18:15','2025-11-18 07:33:30'),(18,5,'성모 마리아의 저녁기도','Vespro della Beata Vergine','album','몬테베르디가 베네치아 산 마르코 대성당 악장직에 지원하기 위해 작곡한 기념비적인 종교 음악이다. 독창, 합창, 오케스트라가 결합된 웅장한 규모와 극적인 표현력이 돋보인다.','SV 206',1610,10,1,'https://open.spotify.com/album/2vDo3uvmYcIqRd4sNC2mN1','https://music.apple.com/us/album/monteverdi-vespers-of-1610/916325650',NULL,'2025-11-16 04:20:01','2025-11-18 07:33:32'),(19,5,'님프의 탄식','Lamento della Ninfa','song','마드리갈 8권 <전쟁과 사랑의 마드리갈>에 수록된 곡 중 가장 유명한 곡이다. 버림받은 님프의 슬픔을 독창(소프라노)과 남성 3중창의 대조를 통해 극적으로 그렸다. 반복되는 베이스라인(그라운드 베이스) 위에서 탄식하는 멜로디가 인상적이다.','SV 163',1638,8,6,'https://open.spotify.com/track/7tWqMDmmO2w21QqFpuJcu8','https://music.apple.com/us/album/lamento-della-ninfa-sv-163-amor-amor/1073636736?i=1073637195',NULL,'2025-11-16 04:21:32','2025-11-18 07:33:34'),(20,5,'포페아의 대관','L\'incoronazione di Poppea','album','몬테베르디의 마지막 오페라이자 그의 오페라 작곡법이 정점에 달한 걸작. 로마 황제 네로네(네로)와 그의 연인 포페아가 권력을 위해 온갖 악행을 저지르고 결국 황후가 된다는, 당시로서는 파격적인 역사적 사실을 다뤘다. \'Pur ti miro, pur ti godo(그대를 보네, 그대를 즐기네)\' 이중창이 유명하다.','SV 308',1643,10,3,'https://open.spotify.com/album/6UwbdopAwSKkkqRPCVcTEB','https://music.apple.com/us/album/monteverdi-lincoronazione-di-poppea-complete/1452166881',NULL,'2025-11-16 04:23:04','2025-11-18 07:33:36'),(21,6,'오라토리오 <메시아>','Oratorio <Messiah>','album','헨델의 가장 위대한 종교 음악이자 인류 역사상 가장 유명한 오라토리오이다. 예수의 생애(탄생, 수난, 부활)를 다루며, 특히 2부의 \'할렐루야(Hallelujah)\' 합창이 가장 유명하다.','HWV 56',1741,10,2,'https://open.spotify.com/album/3qQ7B3x7uzvQrULPQcQ86E','https://music.apple.com/us/album/handel-messiah-hwv-56/577092343',NULL,'2025-11-16 04:33:14','2025-11-18 07:33:38'),(22,6,'수상 음악','Water Music','album','영국 템스강 위에서 열린 왕실 뱃놀이 연회를 위해 작곡된 관현악 모음곡이다. \'알라 혼파이프(Alla Hornpipe)\' 악장이 특히 유명하며, 화려하고 활기찬 분위기가 특징이다.','HWV 348-350',1717,8,50,'https://open.spotify.com/album/3c62bjFFOdOuk39h6TF4X3','https://music.apple.com/us/album/h%C3%A4ndel-water-music-hwv-348-350-suite-from-il-pastor/987459737',NULL,'2025-11-16 04:34:55','2025-11-18 07:33:40'),(23,6,'왕궁의 불꽃놀이','Music for the Royal Fireworks','album','오스트리아 왕위 계승 전쟁 종결을 축하하는 대규모 불꽃놀이를 위해 작곡된 곡이다. 웅장한 서곡(Overture)이 유명하며, 본래 수많은 관악기와 타악기로만 연주되도록 설계되었다.','HWV 351',1749,8,20,'https://open.spotify.com/album/3c2JgjG1KUU6Xw8GYV1Cbh','https://music.apple.com/us/album/handel-messiah-hwv-56/577092343',NULL,'2025-11-16 04:37:37','2025-11-18 07:33:42'),(24,6,'오페라 <리날도> 중 \"울게 하소서\"','\"Lascia ch\'io pianga\" (from Opera <Rinaldo>)','song','헨델이 런던에서 큰 성공을 거둔 첫 오페라 <리날도>에 나오는 아리아이다. 여주인공 알미레나가 포로로 잡혀 자신의 신세를 한탄하며 부르는 비탄에 잠긴 멜로디가 매우 아름답다.','HWV 7',1711,9,5,'https://open.spotify.com/track/6U6Wdf34FBmRr7EZbuFs4w','https://music.apple.com/us/album/hwv-7/1576746580?i=1576746583',NULL,'2025-11-16 04:40:12','2025-11-18 07:33:45'),(25,6,'오페라 <세르세> 중 \"그리운 나무 그늘이여\"','\"Ombra mai fù\" (from Opera <Serse>)','song','페르시아의 왕 세르세(크세르크세스)가 플라타너스 나무 그늘에 감탄하며 부르는 아리아이다. 평화롭고 장엄한 멜로디 덕분에 \'헨델의 라르고\'라는 이름으로 더 널리 알려졌다.','HWV 40',1738,8,3,'https://open.spotify.com/track/43yUdaNXF9VDwQxX4B93mN','https://music.apple.com/us/album/xerxes-hwv-40-largo-ombra-mai-fu/305698710?i=305698886',NULL,'2025-11-16 04:42:09','2025-11-18 07:33:47'),(26,6,'오라토리오 <솔로몬> 중 \"시바 여왕의 도착\"','\"The Arrival of the Queen of Sheba\" (from Oratorio <Solomon>)','song','오라토리오 3막의 시작을 알리는 화려하고 장엄한 기악곡이다. 시바 여왕이 솔로몬 왕을 알현하러 오는 행렬을 묘사하며, 축전적인 분위기 덕분에 결혼식 등에서 자주 연주된다.','HWV 67',1748,7,3,'https://open.spotify.com/track/6Ntsj2X8cjYHoG9ykImLsT','https://music.apple.com/us/album/solomon-hwv-67-symphony-the-arrival-of-the-queen-of-sheba/330152121?i=330152250',NULL,'2025-11-16 04:43:55','2025-11-18 07:33:49'),(27,6,'대관식 찬가 <사제 차독>','Coronation Anthem <Zadok the Priest>','song','영국 국왕 조지 2세의 대관식을 위해 작곡된 4개의 찬가 중 첫 번째 곡이다. 오케스트라의 장엄한 서주에 이어 터져 나오는 합창이 압도적인 분위기를 연출한다. 이후 모든 영국 국왕의 대관식에서 연주되는 전통이 생겼다. (UEFA 챔피언스리그 주제가의 원곡이기도 하다.)','HWV 258',1727,9,5,'https://open.spotify.com/track/30bQxViotttoZ7x2iUP2L9','https://music.apple.com/us/album/zadok-the-priest-hwv-258/1631888905?i=1631888906',NULL,'2025-11-16 04:46:09','2025-11-18 07:33:51'),(28,7,'사계','The Four Seasons','album','비발디의 바이올린 협주곡 작품집 <화성과 창의의 시도>(Op. 8) 중 첫 4곡이다. 각 계절의 풍경과 느낌을 소네트(시)를 바탕으로 묘사한 표제음악의 걸작이다.','Op. 8, No. 1-4 (RV 269, 315, 293, 297)',1723,9,40,'https://open.spotify.com/album/3Pr4IqIrBfGEZRE30TS0xS','https://music.apple.com/us/album/vivaldi-the-four-seasons-op-8-nos-1-4/1558610249',NULL,'2025-11-16 04:57:46','2025-11-18 07:33:53'),(29,7,'조화의 영감','L\'estro armonico','album','12개의 협주곡으로 구성된 작품집. 1, 2, 4대의 바이올린을 위한 다양한 협주곡이 포함되어 있으며, 유럽 전역에 비발디의 명성을 떨치게 한 출세작이다. 바흐가 이 중 6곡을 편곡했다.','Op. 3',1711,8,1,'https://open.spotify.com/album/6jmHFE5TZyozYLTsabZeES','https://music.apple.com/us/album/vivaldi-gold-classics/1182017184',NULL,'2025-11-16 04:59:10','2025-11-18 07:33:55'),(30,7,'글로리아 D장조','Gloria in D major','album','비발디의 종교 성악곡 중 가장 유명하고 널리 연주되는 작품이다. 피에타 여학교의 합창단과 오케스트라를 위해 작곡되었으며, 12개의 악장으로 구성된 화려하고 축전적인 곡이다.','RV 589',1715,9,30,'https://open.spotify.com/album/0jkM5CrTfhifTAyqYr8VSD','https://music.apple.com/us/album/vivaldi/527820708',NULL,'2025-11-16 05:01:17','2025-11-18 07:33:57'),(31,7,'만돌린 협주곡 C장조','Mandolin Concerto in C major','album','비발디가 작곡한 2개의 만돌린 협주곡 중 하나. 만돌린 특유의 청아하고 반짝이는 트레몰로 주법이 돋보이는 사랑스러운 곡이다. 1악장이 특히 유명하다.','RV 425',1725,8,8,'https://open.spotify.com/album/7AdJwAtKQ7BPnaqjJhU165','https://music.apple.com/us/album/vivaldi/527820708',NULL,'2025-11-16 05:03:10','2025-11-18 07:33:59'),(32,7,'두 대의 트럼펫을 위한 협주곡 C장조','Concerto for Two Trumpets in C major','album','두 대의 트럼펫이 화려하게 기량을 겨루는 곡으로, 바로크 트럼펫(내추럴 트럼펫)의 밝고 웅장한 음색이 매력적이다.','RV 537',1720,9,8,'https://open.spotify.com/album/3AkuZCa4ndmCs8Wwl3ALXu','https://music.apple.com/us/album/vivaldi/527820708',NULL,'2025-11-16 05:05:40','2025-11-18 07:34:01'),(33,7,'바이올린 협주곡 A단조','Violin Concerto in A minor','album','<조화의 영감>(Op. 3)에 수록된 6번째 곡으로, 바이올린 학습자들이 가장 많이 연주하는 비발디의 표준적인 협주곡 중 하나이다. 1악장과 3악장의 힘찬 리듬이 인상적이다.','Op. 3, No. 6 (RV 356)',1711,6,8,'https://open.spotify.com/album/0TGLNp0dFwjCCAN5DBI48P','https://music.apple.com/us/album/vivaldi-the-four-seasons/693711974',NULL,'2025-11-16 05:07:13','2025-11-18 12:02:22'),(34,8,'오페라 <디도와 아이네이아스>','Opera <Dido and Aeneas>','album','퍼셀의 유일한 통작(through-composed) 오페라이자 영국 오페라의 최고 걸작. 트로이의 영웅 아이네이아스와 카르타고의 여왕 디도의 비극적인 사랑을 그린다.','Z 626',1688,9,1,'https://open.spotify.com/album/17MwlmVmOPrbWEoQUF6mwe','https://music.apple.com/us/album/purcell-dido-aeneas-z-626/1266747721',NULL,'2025-11-16 05:12:31','2025-11-18 07:34:05'),(35,8,'<디도와 아이네이아스> 중 \"내가 땅 속에 누울 때 (디도의 탄식)\"','\"When I am laid in earth (Dido\'s Lament)\" (from Dido and Aeneas)','song','디다와 아이네이아스 오페라의 마지막에 여왕 디도가 아이네이아스에게 버림받고 죽음을 앞두고 부르는 비탄의 아리아. 반음계적으로 하행하는 \'그라운드 베이스\' 위에서 펼쳐지는 처절하고 아름다운 멜로디가 압권이다.','Z 626',1688,10,5,'https://open.spotify.com/track/06O078Zw6xX8iMh4lpWn01','https://music.apple.com/us/album/dido-and-aeneas-z-626-act-iii-didos-lament-arr-diluka/1788286944?i=1788287073',NULL,'2025-11-16 05:14:04','2025-11-18 07:34:07'),(36,8,'세미 오페라 <요정 여왕>','Semi-Opera <The Fairy-Queen>','album','셰익스피어의 <한여름 밤의 꿈>을 각색한 \'세미 오페라(대사와 연극이 포함된 극음악)\'. 원작의 줄거리와 직접적인 관련은 없으나, 각 막의 끝에 화려한 음악과 춤, 무대장치가 어우러진 \'마스크(Masque)\'가 삽입된다.','Z 629',1692,9,3,'https://open.spotify.com/album/5ymkAOwpDR7Wl4QU1ncd5m','https://music.apple.com/us/album/purcell-the-fairy-queen-z-629-if-loves-a-sweet-passion-single/1852213444',NULL,'2025-11-16 05:15:24','2025-11-18 07:34:09'),(37,8,'메리 여왕의 장례식 음악','Music for the Funeral of Queen Mary','album','자신을 아껴주었던 메리 2세 여왕의 장례식을 위해 작곡한 웅장하고 비통한 음악이다. 트럼펫과 트롬본의 장엄한 팡파르와 합창이 인상적이며, 아이러니하게도 몇 달 뒤 퍼셀 자신의 장례식에서도 연주되었다.','Z 860',1695,8,20,'https://open.spotify.com/album/17MwlmVmOPrbWEoQUF6mwe','https://music.apple.com/us/album/purcell-sacred-music-funeral-sentences-for-queen-mary/720804296',NULL,'2025-11-16 05:17:12','2025-11-18 07:34:11'),(38,8,'<압델라자르> 모음곡','Abdelazer Suite','album','동명 연극을 위한 부수 음악. 이 중 \'론도(Rondeau)\' 악장은 20세기 작곡가 벤저민 브리튼이 <청소년을 위한 관현악 입문>의 주제 선율로 사용하여 더욱 유명해졌다.','Z 570',1695,6,12,'https://open.spotify.com/album/5VOd26mK3cOLkRXrwfvRt9','https://music.apple.com/us/album/purcell-complete-chamber-music/700318897',NULL,'2025-11-16 05:18:20','2025-11-18 07:34:13'),(39,9,'소나타 E장조 행렬','Sonata in E major \"Cortège\"','song','\"행렬(Cortège)\" 또는 \"산책\"이라는 별명으로 알려져 있다. 팡파르를 연상시키는 장엄하고 밝은 주제가 특징이며, 스페인 궁정의 화려한 행진을 묘사하는 듯하다.','Kk. 380 (L. 23)',1754,6,5,'https://open.spotify.com/track/6nOHsFZRP7DIEoBMHykw3H','https://music.apple.com/us/album/sonata-in-e-major-kk-380-l-23/251031212?i=251031377',NULL,'2025-11-16 05:22:47','2025-11-18 12:02:23'),(40,9,'소나타 C장조 사냥','Sonata in C major \"La Caccia\"','song','\"사냥(La Caccia)\"이라는 별명으로 유명하며, 사냥 나팔 소리를 모방한 듯한 쾌활하고 리드미컬한 주제가 특징이다. 스카를라티의 소나타 중 가장 대중적으로 사랑받는 곡 중 하나이다.','Kk. 159 (L. 104)',1752,7,3,'https://open.spotify.com/track/7MTidbkNaqbKiZQNxOmRkV','https://music.apple.com/us/album/suite-bergamasque-l-75-iii-clair-de-lune/862972382?i=862972529',NULL,'2025-11-16 05:24:06','2025-11-18 12:02:25'),(41,9,'소나타 B단조','Sonata in B minor','song','스카를라티의 가장 유명한 소나타 중 하나로, 몽환적이고 명상적인 분위기를 자아낸다. 두 손이 서로 교차하며(cross-hand) 연주하는 기법이 두드러지며, 스페인 기타의 울림을 연상시킨다.','Kk. 27 (L. 449)',1738,8,4,'https://open.spotify.com/track/7uoClo2Y2mi2Ke1sBV1qp5','https://music.apple.com/us/album/nocturne-in-d-flat-major-op-27-no-2/1023324548?i=1023324574',NULL,'2025-11-16 05:25:53','2025-11-18 12:02:26'),(42,9,'소나타 D단조','Sonata in D minor','song','스페인 기타의 \'라스게아도(rasgueado)\' 주법을 모방한 듯한 격렬한 트레몰로(빠른 반복음)와 아르페지오가 특징인 곡이다. 극도의 비르투오시티를 요구하며, 피아니스트들에게 도전적인 레퍼토리로 인기가 높다.','Kk. 141 (L. 422)',1749,10,4,'https://open.spotify.com/track/0EAjYax8qDoHi8C1yFIWge','https://music.apple.com/us/album/sonata-in-d-minor-k-141-l-422-live/1090090086?i=1090090825',NULL,'2025-11-16 05:27:01','2025-11-18 12:02:27'),(43,9,'소나타 F단조','Sonata in F minor','song','Kk. 27과 함께 스카를라티의 가장 서정적이고 내성적인 소나타 중 하나로 꼽힌다. 애상적이고 아름다운 선율이 특징이며, 낭만주의적인 감수성마저 엿보인다.','Kk. 466 (L. 118)',1756,7,6,'https://open.spotify.com/track/3vRAZ8MAPfwK7XdEJHRdBy','https://music.apple.com/us/album/suite-bergamasque-l-75-iii-clair-de-lune/862972382?i=862972529',NULL,'2025-11-16 05:28:09','2025-11-18 12:02:28'),(44,9,'소나타 D단조 파스토랄레','Sonata in D minor \"Pastorale\"','song','\"파스토랄레(목가풍)\"라는 별명으로 자주 불리는 소나타이다. 서정적이고 평화로운 멜로디가 특징이며, 스카를라티의 소나타 중 비교적 접근하기 쉬우면서도 아름다운 곡으로 인기가 높다.','Kk. 9 (L. 413)',1738,5,4,'https://open.spotify.com/track/4hh3PfP0bG6yXYZKRzcANS','https://music.apple.com/us/album/sonata-in-d-minor-kk-9-l-413-pastorale/476590991?i=476592103',NULL,'2025-11-16 05:29:20','2025-11-18 12:02:29'),(45,9,'소나타 D단조','Sonata in D minor','song','커크패트릭 카탈로그의 1번 곡이자, 스카를라티가 1738년에 출판한 첫 소나타 연습곡집(Essercizi per Gravicembalo)의 첫 곡이다. 그의 초기 스타일을 보여주는 우아하고 정돈된 곡이다.','Kk. 1 (L. 366)',1738,5,3,'https://open.spotify.com/track/5D5gdt9H7FkqjswNYU9n22','https://music.apple.com/us/album/trois-gymnop%C3%A9dies-no-1-lent-et-douloureux-transcr-for/1676631061?i=1676631063',NULL,'2025-11-16 05:31:39','2025-11-18 12:02:30'),(46,10,'오페라-발레 <우아한 인도의 나라들>','Opéra-Ballet <Les Indes galantes>','album','라모의 가장 유명한 오페라-발레. \'이국적인\' 네 개의 다른 이야기(터키, 페루, 페르시아, 아메리카)를 옴니버스 식으로 묶었다. 특히 4막의 \'야만인들의 춤(Danse des Sauvages)\'이 매우 유명하다.','RCT 44',1735,9,3,'https://open.spotify.com/album/53xVxcQd78vFoxrG9cRWPi','https://music.apple.com/us/album/rameau-le-grand-th%C3%A9%C3%A2tre-de-lamour/730794438',NULL,'2025-11-16 05:37:20','2025-11-18 07:34:29'),(47,10,'클라브생 모음곡 중 \"탕부랭\"','\"Tambourin\" (from Pièces de clavecin)','song','그의 두 번째 클라브생 곡집(1724)에 수록된 곡. \'탕부랭\'이라는 프로방스 지방의 작은 북 리듬을 모방한 활기차고 경쾌한 춤곡이다. 라모의 건반 작품 중 가장 유명한 곡 중 하나이다.','RCT 3',1724,7,2,'https://open.spotify.com/track/55MKF4WkMkVUcvJUr9SUP5','https://music.apple.com/us/album/pi%C3%A8ces-de-clavessin-rct-3-no-1-les-tendres-plaintes-rondeau/1698676298?i=1698676302',NULL,'2025-11-16 05:39:14','2025-11-18 07:34:32'),(48,10,'클라브생 모음곡 중 \"가보트와 6개의 변주\"','\"Gavotte et six doubles\" (from Nouvelles suites de pièces de clavecin)','song','1728년경 출판된 <새 클라브생 모음곡> A단조 모음곡의 마지막을 장식하는 곡이다. 우아한 가보트 주제와 이어지는 6개의 화려하고 기교적인 변주(Double)로 구성된다.','RCT 5-6',1728,9,10,'https://open.spotify.com/track/55MKF4WkMkVUcvJUr9SUP5','https://music.apple.com/us/album/nouvelles-suites-de-pi%C3%A8ces-de-clavecin-rct-5-no/1698676298?i=1698676401',NULL,'2025-11-16 05:41:03','2025-11-18 07:34:34'),(49,10,'클라브생 모음곡 중 \"암탉\"','\"La Poule\" (from Nouvelles suites de pièces de clavecin)','song','<새 클라브생 모음곡> G장조 모음곡에 포함된 곡. \'꼬꼬댁\'거리는 암탉의 울음소리와 몸짓을 건반악기로 유쾌하고 정교하게 묘사한 \'캐릭터 피스(묘사적 소품)\'의 걸작이다.','RCT 5-6',1728,8,4,'https://open.spotify.com/track/55MKF4WkMkVUcvJUr9SUP5','https://music.apple.com/us/album/nouvelles-suites-de-pi%C3%A8ces-de-clavecin-rct-5-no/1698676298?i=1698676401',NULL,'2025-11-16 05:41:55','2025-11-18 07:34:35'),(50,10,'오페라 <카스토르와 폴뤽스>','Opera <Castor et Pollux>','album','라모의 대표적인 \'서정 비극(Tragédie en musique)\'으로, 그의 오페라 중 최고 걸작 중 하나로 꼽힌다. 쌍둥이 형제인 카스토르(필멸자)와 폴뤽스(불멸자)의 우애와 사랑을 다룬다.','RCT 32',1737,10,2,'https://open.spotify.com/album/3YFwHOCDJ4e8HowT4Wcb45','https://music.apple.com/us/album/rameau-castor-pollux-rct-32/1114127691',NULL,'2025-11-16 05:44:55','2025-11-18 07:34:37'),(51,10,'오페라 <이폴리트와 아리시>','Opera <Hippolyte et Aricie>','album','라모가 50세에 발표한 충격적인 첫 번째 오페라. 라신느의 비극 <페드르>를 기반으로 한다. 당시 륄리의 음악에 익숙했던 청중들에게 라모의 대담한 화성과 관현악법이 충격을 주며 \'륄리파 vs 라모파\' 논쟁을 일으킨 문제작이자 걸작이다.','RCT 43',1733,10,2,'https://open.spotify.com/album/1pvXtnqy0WvrTFbfd2duVK','https://music.apple.com/us/album/rameau-le-grand-th%C3%A9%C3%A2tre-de-lamour/730794438',NULL,'2025-11-16 05:46:47','2025-11-18 07:34:39'),(52,11,'타펠무지크','Tafelmusik (Musique de Table)','album','\"식탁 음악\"이라는 뜻으로, 텔레만이 출판한 대규모 기악 모음집이다. 총 3개의 \'프로덕션(Production)\'으로 구성되며, 각 프로덕션은 서곡, 협주곡, 4중주, 3중주, 독주 소나타 등을 포함하는 \'종합선물세트\' 같은 작품이다.','TWV 50-55',1733,9,4,'https://open.spotify.com/album/43j5ZByQWUcDIePeOlEXrH',NULL,NULL,'2025-11-16 05:52:11','2025-11-18 07:34:41'),(53,11,'비올라 협주곡 G장조','Viola Concerto in G major','album','역사상 최초의 본격적인 솔로 비올라 협주곡 중 하나로 간주되는 매우 중요한 작품이다. 비올라 특유의 따뜻하고 우아한 음색을 잘 살렸으며, 오늘날 모든 비올라 전공자의 핵심 레퍼토리이다.','TWV 51:G9',1716,8,15,'https://open.spotify.com/album/5lJiA3WLiHKl6xK9bNsnyL','https://music.apple.com/us/album/telemann-viola-concerto-in-g-major-twv-51-g9-live-ep/1438655894',NULL,'2025-11-16 05:54:07','2025-11-18 07:34:43'),(54,11,'리코더와 현을 위한 모음곡 A단조','Suite in A minor for Recorder and Strings','album','알토 리코더(또는 플루트)를 위한 협주곡풍의 모음곡(Suite)이다. 프랑스풍 서곡과 다양한 춤곡으로 구성되며, 특히 마지막 \'레르(Air à l\'Italien)\' 악장과 \'폴로네즈(Polonoise)\'가 유명하다.','TWV 55:a2',1710,8,30,'https://open.spotify.com/album/6DlxRazO2p7MgHT4s4aeSg','https://music.apple.com/us/album/telemann-violin-concertos-overture-suite-fantasie/1823706569',NULL,'2025-11-16 05:55:30','2025-11-18 07:34:45'),(55,11,'돈키호테 풍자극','Burlesque de Quixotte','album','세르반테스의 소설 <돈키호테>의 여러 장면을 현악 합주로 묘사한 표제음악적 모음곡이다. \'풍차와의 싸움\', \'산초의 당나귀\' 등 재치 있는 묘사가 돋보인다.','TWV 55:G10',1725,7,20,'https://open.spotify.com/album/1iTmIWpP79rZclqBs5XzEw','https://music.apple.com/us/album/telemann-recorder-suite-in-a-minor-viola-concerto/516997994',NULL,'2025-11-16 05:57:25','2025-11-18 07:34:47'),(56,11,'파리 4중주','Paris Quartets','album','텔레만이 1730년대 파리 방문을 전후하여 작곡한 12개의 4중주곡집이다. 플루트, 바이올린, 비올라 다 감바(또는 첼로), 하프시코드로 구성되며, 프랑스와 이탈리아 양식이 절묘하게 조화된 실내악의 걸작으로 꼽힌다.','TWV 43',1730,9,2,'https://open.spotify.com/album/2msX4mNyfqw0bFgZ6De4sM','https://music.apple.com/us/album/telemann-string-concertos/1452231132',NULL,'2025-11-16 05:59:08','2025-11-18 07:34:49'),(57,12,'합주 협주곡 G단조 Op. 6, No. 8 \"크리스마스 협주곡\"','Concerto Grosso in G minor \"Christmas Concerto\"','song','코렐리의 작품 중 가장 유명한 곡. 그의 합주 협주곡 12곡 모음(Op. 6) 중 8번째 곡이다. 성탄절 밤을 위해 작곡되었다는 표시가 있으며, 특히 마지막 악장인 \'파스토랄레(Pastorale, 목가풍)\'의 평화롭고 아름다운 선율이 매우 유명하다.','Op. 6, No. 8',1690,8,15,'https://open.spotify.com/track/17gz8bmRy8HDUf6AZBnD5K','https://music.apple.com/us/album/concerto-grosso-no-8-in-g-minor-op-6-christmas-concerto/339006385?i=339006690',NULL,'2025-11-16 06:03:36','2025-11-18 12:02:31'),(58,12,'바이올린 소나타 D단조 Op. 5, No. 12 \"라 폴리아\"','Violin Sonata in D minor \"La Folia\"','song','코렐리의 바이올린 소나타 12곡 모음(Op. 5) 중 마지막 곡. 당시 유행하던 \'폴리아\'라는 춤곡 선율을 주제로 한 23개의 화려한 변주곡이다. 코렐리의 바이올린 기교가 정점에 달한 작품이자, \'라 폴리아\' 변주곡의 가장 대표적인 사례로 꼽힌다.','Op. 5, No. 12',1700,10,12,'https://open.spotify.com/track/2JQYXM1XMiLxw6MCLK4do2','https://music.apple.com/us/album/follia-op-5-no-12/253079424?i=253079486',NULL,'2025-11-16 06:04:52','2025-11-18 12:02:33'),(59,12,'12개의 합주 협주곡','12 Concerti Grossi','album','코렐리의 작품 활동을 집대성하는 그의 마지막 작품집이다. 2대의 바이올린과 첼로로 구성된 소규모 그룹(콘체르티노)과 전체 오케스트라(리피에노 또는 투티)가 대비를 이루는 \'콘체르토 그로소\' 양식의 정점을 보여준다. \"크리스마스 협주곡\"이 여기에 포함된다.','Op. 6',1714,8,2,'https://open.spotify.com/album/5emNyTE3FAXRUgeOVujFLv','https://music.apple.com/us/album/corelli-12-concerti-grossi-op-6/1452236740',NULL,'2025-11-16 06:06:29','2025-11-18 12:02:34'),(60,12,'3성부 교회 소나타','12 Trio Sonatas (Sonate da chiesa)','album','코렐리의 트리오 소나타 중 가장 유명한 작품집. 2대의 바이올린과 첼로, 오르간(바소 콘티누오) 편성이다. \'교회 소나타(Sonata da chiesa)\'의 전형으로, 4악장(느림-빠름-느림-빠름) 구성을 확립했으며, 진지하고 장엄한 분위기가 특징이다.','Op. 3',1689,7,1,'https://open.spotify.com/album/4CduyO5tTYdq3tBdUWoLMO','https://music.apple.com/us/album/corelli-sonate-da-chiesa-op-1-3/266419633',NULL,'2025-11-16 06:09:29','2025-11-18 12:02:35'),(61,21,'오페라 <오르페오와 에우리디체>','Opera <Orfeo ed Euridice>','album','글루크의 \'오페라 개혁\'이 최초로 적용된 가장 중요하고 유명한 작품이다. 기존 오페라 세리아의 불필요한 기교 과시(다 카포 아리아)를 없애고, 음악이 극의 내용에 충실하도록 작곡했다. 그리스 신화 속 오르페우스의 이야기를 다룬다.','Wq. 30',1762,9,90,'https://open.spotify.com/album/0lj3aGVd1VbKi0806VpzAh','https://music.apple.com/us/album/gluck-orfeo-ed-euridice-wq-30/1777841415',NULL,'2025-11-17 02:50:48','2025-11-18 07:35:00'),(62,21,'<오르페오와 에우리디체> 중 \"정령들의 춤\"','\"Dance of the Blessed Spirits\" (from Orfeo ed Euridice)','song','위 오페라 2막에 나오는 유명한 발레 음악. 오르페오가 천국 엘리시움에 도달했을 때 정령들이 추는 춤을 묘사한다. 플루트의 청아하고 아름다운 멜로디가 매우 유명하여 독립적으로도 자주 연주된다.','Wq. 30',1762,7,7,'https://open.spotify.com/track/24cgBBhZD1cWekUqaYuqTB','https://music.apple.com/us/album/orfeo-ed-euridice-wq-30-melodie-arr-sgambati/1478136124?i=1478136125',NULL,'2025-11-17 02:50:48','2025-11-18 07:35:02'),(63,21,'<오르페오와 에우리디체> 중 \"에우리디체 없이 어찌하리\"','\"Che farò senza Euridice?\" (from Orfeo ed Euridice)','song','위 오페라 3막에서, 금기를 어기고 뒤를 돌아보는 바람에 아내 에우리디체를 두 번째로 잃은 오르페오가 부르는 절망적인 아리아이다. 글루크의 \'고귀한 단순함\'이 집약된 비극적이고 아름다운 선율로 유명하다.','Wq. 30',1762,9,5,'https://open.spotify.com/track/24cgBBhZD1cWekUqaYuqTB','https://music.apple.com/us/album/orfeo-ed-euridice-wq-30-melodie-arr-sgambati/1478136124?i=1478136125',NULL,'2025-11-17 02:50:48','2025-11-18 07:35:04'),(64,21,'오페라 <알체스테>','Opera <Alceste>','album','<오르페오>의 뒤를 잇는 글루크의 두 번째 개혁 오페라. 남편 아드메토스 왕을 대신해 죽기로 결심한 알체스테 여왕의 고귀한 희생을 다룬다. 이 오페라의 서문은 글루크의 \'오페라 개혁\' 이념을 밝힌 선언문으로 매우 유명하다.','Wq. 37',1767,10,150,'https://open.spotify.com/album/0lj3aGVd1VbKi0806VpzAh','https://music.apple.com/us/album/gluck-orfeo-ed-euridice-wq-30/1777841415',NULL,'2025-11-17 02:50:48','2025-11-18 07:35:06'),(65,21,'오페라 <타우리데의 이피제니>','Opera <Iphigénie en Tauride>','album','글루크의 개혁 오페라 중 최고 걸작으로 꼽히는 작품. 파리에서 작곡되었으며, 그리스 비극을 바탕으로 극적인 긴장감과 음악적 통일성이 완벽에 가깝게 구현되었다.','Wq. 46',1779,10,120,'https://open.spotify.com/album/2lQ6lY1UDe826YwWsJooCI','https://music.apple.com/us/album/gluck-iphig%C3%A9nie-en-tauride-wq-46/421477678',NULL,'2025-11-17 02:50:48','2025-11-18 07:35:08'),(66,14,'아이네 클라이네 나흐트무지크','Eine kleine Nachtmusik','album','모차르트의 가장 유명한 기악곡 중 하나. \'소야곡(Serenade)\'이라는 뜻으로, 경쾌하고 우아한 멜로디가 특징이다. 1악장이 특히 유명하다.','K. 525',1787,6,18,'https://open.spotify.com/album/7mNfU1GNFiIvbFQ6j6DpG5','https://music.apple.com/us/album/mozart-eine-kleine-nachtmusik-k-525-divertimentos-k-136-138/1724247504',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:36'),(67,14,'교향곡 40번 G단조','Symphony No. 40 in G minor','album','모차르트의 3대 교향곡 중 하나로, 비극적이면서도 열정적인 1악장 주제가 매우 유명하다. 낭만주의적 감수성이 엿보이는 걸작이다.','K. 550',1788,8,30,'https://open.spotify.com/album/5ftkdxmHWSA3H7c8E8tVat','https://music.apple.com/us/album/mozart-symphony-no-40-in-g-minor-k-550/1452216750',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:37'),(68,14,'교향곡 41번 C장조 \"주피터\"','Symphony No. 41 in C major \"Jupiter\"','album','모차르트가 작곡한 마지막 교향곡. 고전주의 교향곡의 정점으로, 특히 마지막 4악장의 화려하고 장엄한 푸가 기법이 압권이다.','K. 551',1788,9,35,'https://open.spotify.com/album/5NkJMC9njCOYqV8XuESdty','https://music.apple.com/us/album/mozart/494863852',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:38'),(69,14,'오페라 <피가로의 결혼>','Opera <Le nozze di Figaro>','album','시대를 앞서간 천재적인 희극 오페라(오페라 부파). 귀족의 특권(초야권)에 맞서는 하인 피가로의 기지를 유쾌하게 그렸다. 유명한 서곡부터 모든 아리아가 걸작으로 꼽힌다.','K. 492',1786,10,180,'https://open.spotify.com/album/3CzXgB9e6cAiQRu7ovAwIS','https://music.apple.com/us/album/mozart-le-nozze-di-figaro-k-492/1452269658',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:40'),(70,14,'오페라 <마술피리>','Opera <Die Zauberflöte>','album','모차르트가 죽기 직전에 완성한 마지막 오페라. 독일어로 된 \'징슈필(Singspiel)\'이며, 프리메이슨의 사상을 담은 동화적이고 철학적인 작품이다. \'밤의 여왕 아리아\'가 유명하다.','K. 620',1791,10,150,'https://open.spotify.com/album/4og780tVtVCHZH3EFTkDFf','https://music.apple.com/us/album/mozart-die-zauberfl%C3%B6te-k-620/1452393307',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:41'),(71,14,'레퀴엠 D단조','Requiem in D minor','album','모차르트의 미완성 유작. 정체불명의 의뢰인이 주문한 진혼 미사곡으로, 자신의 죽음을 예감하며 작곡했다는 전설이 있다. 제자 쥐스마이어가 완성했다.','K. 626',1791,10,50,'https://open.spotify.com/album/5pq2RfYxLtcTlqAGj87HY1','https://music.apple.com/us/album/mozart-allegro-in-d-major-k-626b-16/1549662057',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:42'),(72,14,'피아노 협주곡 20번 D단조','Piano Concerto No. 20 in D minor','album','모차르트의 피아노 협주곡 중 가장 극적이고 낭만적인 작품 중 하나. 베토벤이 특히 좋아하여 직접 카덴차를 작곡하기도 했다.','K. 466',1785,9,32,'https://open.spotify.com/album/2zs2VEQyfjqG2UBAnaoYaQ','https://music.apple.com/us/album/mozart-piano-concerto-no-25-in-c-major-k-503-piano/1452626745',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:43'),(73,14,'피아노 소나타 11번 A장조 \"터키 행진곡\"','Piano Sonata No. 11 in A major','album','3악장 \'터키풍 론도(Alla Turca)\'가 매우 유명하여 \'터키 행진곡\'이라는 별명으로 불린다. 피아노 학습자들에게도 인기가 높은 곡이다.','K. 331',1783,7,24,'https://open.spotify.com/album/2CaBqd2ZKbZUE9Y9W44ydP','https://music.apple.com/us/album/mozart-piano-sonatas-k-457-k-331-and-fantasias-k-475-k-397/1452553528',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:44'),(74,14,'클라리넷 협주곡 A장조','Clarinet Concerto in A major','album','모차르트가 마지막으로 완성한 협주곡. 클라리넷이라는 악기의 아름다움을 극한까지 표현한 걸작으로, 2악장 아다지오가 유명하다.','K. 622',1791,9,28,'https://open.spotify.com/album/5lVpqdphsuwj66PEEdDX6v','https://music.apple.com/us/album/mozart-clarinet-concerto-in-a-major-k-622-clarinet/1724250180',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:45'),(75,15,'교향곡 5번 C단조 \"운명\"','Symphony No. 5 in C minor \"Destiny\"','album','\'빠바바밤~\'하는 유명한 동기로 시작하는, 서양 음악사상 가장 유명한 교향곡. \'고뇌를 넘어 환희로\'라는 베토벤의 음악 세계를 압축적으로 보여준다.','Op. 67',1808,9,35,'https://open.spotify.com/album/3BjtNi6R5KbaEHnuwhbRsr','https://music.apple.com/us/album/beethoven-symphony-no-5-in-c-minor-op-67-ep/904500487',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:47'),(76,15,'교향곡 9번 D단조 \"합창\"','Symphony No. 9 in D minor \"Choral\"','album','베토벤의 마지막 교향곡. 4악장에 최초로 성악 합창(실러의 \'환희의 송가\')을 도입한 혁명적인 작품이다. 인류애와 화합의 메시지를 담고 있다.','Op. 125',1824,10,70,'https://open.spotify.com/album/2XF4GhKOvsWt1viozHlx8a','https://music.apple.com/us/album/beethoven-symphony-no-9-in-d-minor-op-125-choral-live/1744137424',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:48'),(77,15,'교향곡 3번 E♭장조 \"영웅\"','Symphony No. 3 in E♭ major \"Eroica\"','album','본래 나폴레옹에게 헌정하려 했으나, 그가 황제에 즉위하자 분노하여 헌사를 찢어버렸다는 일화로 유명하다. 고전주의 교향곡의 틀을 깨뜨린 거대한 규모의 작품이다.','Op. 55',1804,9,50,'https://open.spotify.com/album/0Jt9gzq3JV6UZwMCdVgYPQ','https://music.apple.com/us/album/beethoven-symphony-no-3-in-e-flat-major-op-55-eroica/344778843',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:49'),(78,15,'피아노 소나타 14번 C#단조 \"월광\"','Piano Sonata No. 14 in C# minor \"Moonlight\"','album','베토벤의 피아노 소나타 중 가장 유명한 곡. 특히 몽환적인 1악장이 유명하며, \'월광\'이라는 별명은 베토벤 사후에 시인 렐슈타프가 붙였다.','Op. 27, No. 2',1801,7,15,'https://open.spotify.com/album/5oFks9ZFUYBv8Ia3pkmtuX','https://music.apple.com/us/album/beethoven-piano-sonata-no-14-in-c-sharp-minor-op-27/1438033166',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:50'),(79,15,'피아노 소나타 8번 C단조 \"비창\"','Piano Sonata No. 8 in C minor \"Pathétique\"','album','베토벤 초기 소나타의 걸작. 비극적이면서도 장엄한 1악장 서주와 정열적인 멜로디로 큰 인기를 얻었다.','Op. 13',1798,8,19,'https://open.spotify.com/album/3xsm3PYh1W3WrLiUdTqdBy','https://music.apple.com/us/album/beethoven-piano-sonata-no-14-in-c-sharp-minor-op-27/1438033166',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:51'),(80,15,'피아노 협주곡 5번 E♭장조 \"황제\"','Piano Concerto No. 5 in E♭ major \"Emperor\"','album','베토벤의 마지막 피아노 협주곡. 교향곡과 맞먹는 웅장한 규모와 화려한 피아노 기교가 특징이며, \'황제\'라는 별명에 걸맞은 위풍당당함을 보여준다.','Op. 73',1809,10,40,'https://open.spotify.com/album/6zQ3TAOuJ1iIXiXGycCpYQ','https://music.apple.com/us/album/beethoven-piano-concerto-no-5-in-e-flat-major-op-73-emperor/1005051226',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:52'),(81,15,'바이올린 협주곡 D장조','Violin Concerto in D major','album','베토벤의 유일한 바이올린 협주곡. 멘델스존, 브람스의 협주곡과 함께 3대 바이올린 협주곡으로 꼽히며, 장대하고 고귀한 아름다움을 지녔다.','Op. 61',1806,10,43,'https://open.spotify.com/album/4J6lGlZRjK1Hfwrz9qqQbh','https://music.apple.com/us/album/beethoven-violin-concerto-in-d-major-op-61/1452501833',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:53'),(82,15,'엘리제를 위하여','Für Elise','song','베토벤이 남긴 바가텔(Bagatelle, 소품) 중 전 세계적으로 가장 유명한 피아노곡. \'엘리제\'가 누구인지는 여전히 논쟁거리로 남아있다.','WoO 59',1810,4,3,'https://open.spotify.com/track/0H2VhGUC3P3hvwz8rdGIpC','https://music.apple.com/us/album/bagatelle-no-25-in-a-minor-woo-59-f%C3%BCr-elise/1764844357?i=1764844361',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:55'),(83,16,'교향곡 94번 G장조 \"놀람\"','Symphony No. 94 in G major \"Surprise\"','album','하이든의 \'런던 교향곡\' 중 하나. 조용하게 연주되던 2악장 도중 갑자기 큰 소리(팀파니와 모든 악기)가 터져 나와 청중을 놀라게 한 일화로 유명하다.','Hob. I:94',1791,7,23,'https://open.spotify.com/album/0RFlfwookedHmEYnyeAhPn','https://music.apple.com/us/album/haydn-symphony-no-94-in-g-major-hob-i-94-surprise-tchaikovsky/1494021177',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:56'),(84,16,'교향곡 101번 D장조 \"시계\"','Symphony No. 101 in D major \"The Clock\"','album','2악장에서 바순과 현악기들이 \'똑딱\'거리는 시계추 소리를 리드미컬하게 묘사하여 \'시계\'라는 별명이 붙었다.','Hob. I:101',1794,8,28,'https://open.spotify.com/album/5Sp8qIVK91jhHM7vVdbjf2','https://music.apple.com/us/album/haydn-symphony-in-d-major-hob-i-101-the-clock/459074011',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:57'),(85,16,'교향곡 45번 F#단조 \"고별\"','Symphony No. 45 in F# minor \"Farewell\"','album','휴가를 받지 못한 단원들을 위해 하이든이 작곡한 재치 있는 곡. 마지막 4악장에서 연주자들이 하나둘씩 촛불을 끄고 퇴장하는 퍼포먼스로 유명하다.','Hob. I:45',1772,8,25,'https://open.spotify.com/album/42ThsZUyrAKUrHRiY6t15g','https://music.apple.com/us/album/haydn-j-symphonies-nos-hob-i-81-hob-i-45-farewell/1452168204',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:58'),(86,16,'현악 4중주 C장조 \"황제\"','String Quartet in C major \"Emperor\"','album','2악장에서 하이든이 오스트리아 국가로 작곡한 선율(\'황제 찬가\')을 주제로 한 변주곡이 사용된다. 이 선율은 훗날 독일 국가의 선율이 되었다.','Hob. III:77',1797,8,24,'https://open.spotify.com/album/1YbJiQvalOgHokwViCb00S','https://music.apple.com/us/album/haydn-string-quartet-no-63-in-d-major-hob-iii-brahms/1712877504',NULL,'2025-11-17 07:21:40','2025-11-18 12:02:59'),(87,16,'오라토리오 <천지창조>','Oratorio <The Creation>','album','하이든의 최고 걸작 중 하나. 헨델의 <메시아>에 감명을 받아 작곡했으며, 구약성서의 천지창조 7일간의 과정을 웅장하고 생생하게 묘사했다.','Hob. XXI:2',1798,9,105,'https://open.spotify.com/album/7dbKlBPRFgxS6fckRf4GXS','https://music.apple.com/us/album/haydn-die-sch%C3%B6pfung-hob-xxi-2-live/1789447098',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:01'),(88,16,'트럼펫 협주곡 E♭장조','Trumpet Concerto in E♭ major','album','새롭게 발명된 \'키 트럼펫\'을 위해 작곡된 최초의 위대한 협주곡. 트럼펫의 화려한 기교와 서정성을 모두 보여주는, 트럼펫 연주자들의 표준 레퍼토리이다.','Hob. VIIe:1',1796,9,15,'https://open.spotify.com/album/0yl7Csi1x7yP9GGPuhNw3I','https://music.apple.com/us/album/haydn-trumpet-concerto-hob-viie-1-single/1452560550',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:02'),(89,17,'오페라 <다나이드>','Opera <Les Danaïdes>','album','본래 글루크와 공동 작업으로 시작했으나, 글루크의 건강 악화로 살리에리가 완성했다. 파리에서 큰 성공을 거두며 글루크의 \'오페라 개혁\' 후계자로 인정받게 한 작품이다.',NULL,1784,9,100,'https://open.spotify.com/album/5EimbmEq59nDfc6httH9e7',NULL,NULL,'2025-11-17 07:21:40','2025-11-18 07:35:57'),(90,17,'오페라 <타라르>','Opera <Tarare>','album','보마르셰(피가로의 결혼 원작자)의 대본으로 작곡한, 살리에리의 가장 야심 찬 오페라 중 하나. 프랑스 혁명 직전의 파리에서 큰 성공을 거두었다.',NULL,1787,9,180,'https://open.spotify.com/album/7IqxxwBk1r8VIJE1c5N9oF',NULL,NULL,'2025-11-17 07:21:40','2025-11-18 07:35:59'),(91,17,'오페라 <팔스타프>','Opera <Falstaff>','album','셰익스피어의 <윈저의 명랑한 아낙네들>을 원작으로 한 희극 오페라. (훗날 베르디가 작곡한 동명의 오페라와는 다른 작품이다.)',NULL,1799,8,130,'https://open.spotify.com/album/1wHxJlPhFU5qyH9QUcXVkn',NULL,NULL,'2025-11-17 07:21:40','2025-11-18 07:36:01'),(92,17,'신포니아 D장조 \"베네치아의 날\"','Sinfonia in D major \"Il giorno onomastico\"','album','살리에리의 교향곡 중 가장 유명하고 활기찬 작품. 그의 기악 작곡가로서의 면모를 보여준다.',NULL,1775,7,18,'https://open.spotify.com/album/4uevsYSWOoHJuJ9uimaHPN','https://music.apple.com/us/album/antonio-salieri-sinfonia-in-d-major-il-giorno/425820781',NULL,'2025-11-17 07:21:40','2025-11-18 07:36:03'),(93,18,'30개의 새로운 테크닉 연습곡 (체르니 30번)','30 New Studies in Technics','album','한국에서 \'체르니 30번\'으로 알려진 연습곡집. 피아노의 기초적인 테크닉을 완성하기 위한 필수적인 연습곡들로 구성되어 있다.','Op. 849',1854,5,30,'https://open.spotify.com/album/5Y2E25HFP3l2EVT94X48tZ','https://music.apple.com/us/album/czerny-op-849-piano-etudes-for-piano-lessons-classical/1665412335',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:03'),(94,18,'숙달을 위한 연습곡 (체르니 40번)','The School of Velocity','album','한국에서 \'체르니 40번\'으로 불린다. 30번보다 높은 수준의 속도(Velocity)와 기교를 훈련하기 위한 40개의 연습곡 모음이다.','Op. 299',1833,6,60,'https://open.spotify.com/album/4Okv3htBjfuBgu4emxcDkJ','https://music.apple.com/us/album/czerny-the-school-of-velocity-op-299-6-octave-studies-op-553/1589457741',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:04'),(95,18,'손가락의 기교 (체르니 50번)','The Art of Finger Dexterity','album','한국에서 \'체르니 50번\'으로 불린다. 피아니스트가 갖추어야 할 거의 모든 종류의 화려한 기교를 집대성한 상급 연습곡집이다.','Op. 740',1844,8,90,'https://open.spotify.com/album/2dcgsuoHmNBJOr9FvlQjI1','https://music.apple.com/us/album/carl-czerny-etudes-for-piano-op-740/1591230564',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:05'),(96,18,'100개의 점진적인 연습곡','100 Progressive Studies','album','한국에서 \'체르니 100번\'으로 불리며, 피아노 초급자들이 처음 접하는 연습곡집 중 하나이다.','Op. 139',1829,3,80,'https://open.spotify.com/album/06WhvHKa5WRMYPiCPtku4j','https://music.apple.com/us/album/carl-czerny-100-progressive-studies-op-139-for-piano/1209747642',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:06'),(97,19,'장난감 교향곡','Toy Symphony','album','뻐꾸기, 트럼펫, 북 등 장난감 악기들이 오케스트라와 함께 연주되는 재치 있는 교향곡이다. (오랫동안 하이든의 작품으로 오인되기도 했다.)',NULL,1760,4,10,'https://open.spotify.com/album/4L6qPYPZR4YnvBJAMIeOuf','https://music.apple.com/us/album/new-year-concerto/1020234353',NULL,'2025-11-17 07:21:40','2025-11-18 07:36:13'),(98,19,'트럼펫 협주곡 D장조','Trumpet Concerto in D major','album','바로크에서 고전주의로 넘어가는 과도기적 스타일을 보여주는 트럼펫 협주곡. 2악장의 느린 선율이 유명하다.','MWV IX:13',1762,8,12,'https://open.spotify.com/album/4fYVRN0xLtr6dJBk61ls5T','https://music.apple.com/us/album/ludwig-g%C3%BCttler-festliche-kl%C3%A4nge-aus-dresden/515111779',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:07'),(99,19,'알토 트롬본 협주곡 D장조','Concerto for Alto Trombone in D major','album','당시 흔치 않았던 알토 트롬본을 독주 악기로 내세운 협주곡이다. 오늘날 트롬본 연주자들에게 중요한 레퍼토리이다.','MWV IX:18',1756,9,15,'https://open.spotify.com/album/4fYVRN0xLtr6dJBk61ls5T','https://music.apple.com/us/album/ludwig-g%C3%BCttler-festliche-kl%C3%A4nge-aus-dresden/515111779',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:09'),(100,20,'현악 5중주 E장조 중 \"미뉴에트\"','\"Minuet\" from String Quintet in E major','song','보케리니의 모든 작품 중 가장 유명한 곡. 우아하고 서정적인 선율로 인해 영화나 광고에서 널리 사용되었다.','Op. 11, No. 5',1771,4,4,'https://open.spotify.com/track/6e85fziCk6MwZUxWyG6Ijm','https://music.apple.com/us/album/string-quintet-in-e-major-op-11-no-5-g-275-iii-minuet/339006385?i=339006517',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:10'),(101,20,'첼로 협주곡 9번 B♭장조','Cello Concerto No. 9 in B♭ major','album','보케리니의 첼로 협주곡 중 가장 유명한 작품. (단, 오늘날 연주되는 것은 19세기 첼리스트 그뤼츠마허가 편곡한 버전인 경우가 많다.)','G. 482',1771,9,22,'https://open.spotify.com/album/7o2ZRN6qHlygPg9Z4gAlAu','https://music.apple.com/us/album/luigi-boccherini-cello-concerto-no-9-in-b-flat-major/1044016112',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:11'),(102,20,'기타 5중주 4번 D장조 \"판당고\"','Guitar Quintet No. 4 in D major \"Fandango\"','album','스페인 궁정에서 활동했던 보케리니가 스페인의 춤곡 \'판당고\' 리듬을 사용하여 작곡한 활기 넘치는 실내악곡이다.','G. 448',1798,8,18,'https://open.spotify.com/album/3idJK2ACE3Tj2c7i29SEjZ','https://music.apple.com/us/album/boccherini-la-musica-notturna-delle-strade-di-madrid/448884336',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:12'),(103,22,'솔페지에토 C단조','Solfeggietto in C minor','song','C.P.E. 바흐의 가장 유명한 피아노(클라비어) 소품. 양손이 빠르게 교차하며 아르페지오를 연주하는 기교적인 연습곡이다.','H. 220, Wq. 117/2',1766,6,1,'https://open.spotify.com/track/3g75Q4eLFvCxyBrT08Sszl','https://music.apple.com/us/album/solfegietto-c-minor-h-220-wq-117-2/1169518262?i=1169518565',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:13'),(104,22,'첼로 협주곡 A단조','Cello Concerto in A minor','album','\'감정과다 양식\'의 특징인 격렬한 감정의 대비가 잘 드러나는 협주곡. 바로크의 리듬감과 고전주의의 드라마가 공존한다.','Wq. 170',1750,9,25,'https://open.spotify.com/album/1qtiEqVHZthcNYYOK45FMh','https://music.apple.com/us/album/carl-philipp-emanuel-bach-cello-concertos-wq-170-172/1756295655',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:14'),(105,22,'플루트 협주곡 D단조','Flute Concerto in D minor','album','그의 아버지 J.S. 바흐의 영향이 느껴지면서도, 질풍노도와 같은 격렬함이 돋보이는 C.P.E. 바흐의 대표적인 플루트 협주곡이다.','Wq. 22',1747,9,22,'https://open.spotify.com/album/0vME0i5JZPrVCBvBBvBhro','https://music.apple.com/us/album/c-p-e-bach-flute-concerto-wq-22-arr-for-alto-recorder/1782168535',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:16'),(106,22,'마니피카트 D장조','Magnificat in D major','album','J.S. 바흐의 장엄한 종교 음악을 계승하면서도, 고전주의적인 명료함과 극적인 표현을 더한 그의 대표적인 성악곡이다.','Wq. 215',1749,9,40,'https://open.spotify.com/album/4oNe2aK7vFfIHhMhX0n6Xp','https://music.apple.com/us/album/c-p-e-bach-magnificat-wq-215/803001251',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:17'),(107,23,'신포니아 B♭장조 Op. 18, No. 2','Sinfonia in B♭ major \"Lucio Silla\"','album','\'런던의 바흐\'다운 우아하고 경쾌한 갈랑 양식의 교향곡. 모차르트의 오페라 <루치오 실라>의 서곡으로도 알려져 있다.','Op. 18, No. 2',1774,7,12,'https://open.spotify.com/album/7i83TEHhrYpSdiemOVqajE','https://music.apple.com/us/album/j-c-bach-grand-overture-in-b-flat-major-op-18-no-2-w-g9-single/576448213',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:18'),(108,23,'신포니아 콘체르탄테 C장조','Sinfonia Concertante in C major','album','두 대의 바이올린과 첼로가 오케스트라와 어우러지는 협주 교향곡. 어린 모차르트가 이 장르에 영향을 받았다.','W.C 34',1770,8,20,'https://open.spotify.com/album/638fM7ibl3YWInMONVwmse','https://music.apple.com/us/album/bach-sons-piano-concertos/478520266',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:19'),(109,23,'비올라 협주곡 C단조 (카자드쉬 위작)','Viola Concerto in C minor (spurious, by Casadesus)','album','J.C. 바흐의 작품으로 알려져 널리 연주되었으나, 실제로는 20세기 프랑스 첼리스트 앙리 카자드쉬의 위작(僞作)으로 밝혀졌다. 그럼에도 불구, 여전히 인기 있는 비올라 레퍼토리이다.','W.C 77 (spurious)',1947,8,16,'https://open.spotify.com/album/55wLtZCsd5gVKrmzLDeSH6',NULL,NULL,'2025-11-17 07:21:40','2025-11-18 07:36:37'),(110,24,'클라리넷 협주곡 B♭장조','Clarinet Concerto in B♭ major','album','클라리넷을 위한 최초의 위대한 협주곡 중 하나. 클라리넷의 기교와 서정성을 훌륭하게 보여주며, 만하임 악파의 스타일이 잘 드러난다.','KaiS 55',1754,9,17,'https://open.spotify.com/album/7LRHQ8UtFtbCv48csgo1hd',NULL,NULL,'2025-11-17 07:21:40','2025-11-18 12:03:20'),(111,24,'신포니아 D장조 \"만하임\"','Symphony in D major','album','슈타미츠와 만하임 악파의 특징인 \'만하임 크레센도\'(점점 커지는 소리)와 \'만하임 로켓\'(상승하는 아르페지오)이 잘 나타나는 초기 교향곡의 걸작이다.','Op. 3, No. 2',1750,7,15,'https://open.spotify.com/album/3h1yeo8Vl0x0aJSwiiWwQc','https://music.apple.com/us/album/unusual-chamber-music-for-clarinet-unusual-chamber/1757901909',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:21'),(112,24,'트럼펫 협주곡 D장조','Trumpet Concerto in D major','album','하이든 이전에 작곡된 트럼펫 협주곡. 바로크의 영향이 남아있지만, 고전주의적인 활기찬 에너지가 돋보이는 작품이다.','KaiS 49',1750,8,16,'https://open.spotify.com/album/7LRHQ8UtFtbCv48csgo1hd',NULL,NULL,'2025-11-17 07:21:40','2025-11-18 12:03:22'),(113,25,'소나티네 Op. 36 (1~6번)','Sonatinas','album','전 세계 피아노 학습자들이 체르니 이전에 반드시 거쳐 가는 교재. 고전주의 형식미와 피아노의 기초 테크닉을 익히는 데 가장 널리 쓰이는 곡이다.','Op. 36',1797,4,20,'https://open.spotify.com/album/1rsb9rlNsrSBIbsJzTS8zd','https://music.apple.com/us/album/6-piano-sonatinas-op-36/1617823545',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:24'),(114,25,'그라두스 아드 파르나숨','Gradus ad Parnassum','album','\'파르나수스(음악의 천국)로 가는 계단\'이라는 뜻의 100개의 연습곡집. 근대 피아노 테크닉의 교과서로, 드뷔시가 이 곡을 패러디하기도 했다.','Op. 44',1817,9,240,'https://open.spotify.com/album/1rsb9rlNsrSBIbsJzTS8zd','https://music.apple.com/us/album/clementi-sonatina-no-1-in-c-major-op-36-single/1513597055',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:25'),(115,25,'피아노 소나타 G단조 \"버림받은 디도\"','Piano Sonata in G minor \"Didone abbandonata\"','album','클레멘티의 가장 극적이고 낭만적인 소나타. 베르길리우스의 서사시 속, 버림받은 디도의 비극을 묘사한 표제음악적 작품이다.','Op. 50, No. 3',1821,9,25,'https://open.spotify.com/album/6p0yYNF5L1wDjkgehFQQ6g','https://music.apple.com/us/album/clementi-3-piano-sonatas-op-37-ep/1632317670',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:26'),(116,26,'연가곡집 <겨울나그네>','Song Cycle <Winterreise>','album','슈베르트가 죽기 직전에 작곡한 24곡의 연가곡집. 사랑에 실패하고 눈보라 속을 방황하는 청년의 절망을 그린, 독일 가곡의 최고봉이다.','D. 911',1827,10,70,'https://open.spotify.com/album/7xQz99zOfxC5p2GoHw1mz7','https://music.apple.com/us/album/schubert-100-supreme-classical-masterpieces-rise-of/422602965',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:27'),(117,26,'가곡 <마왕>','Erlkönig','song','슈베르트가 18세에 작곡한 천재적인 가곡. 괴테의 시를 바탕으로, 해설자, 아버지, 아들, 마왕 4명의 목소리를 한 명의 가수가 연기하며, 피아노는 말발굽 소리를 묘사한다.','D. 328',1815,9,4,'https://open.spotify.com/track/0hES7IYAQSwBAPXJeLKcGN','https://music.apple.com/us/album/erlk%C3%B6nig-d-328-op-1-wer-reitet-so-sp%C3%A4t/1452518907?i=1452519165',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:28'),(118,26,'피아노 5중주 A장조 \"송어\"','Piano Quintet in A major \"Trout\"','album','자신의 가곡 <송어>(Die Forelle)의 선율을 4악장 변주곡의 주제로 사용한 실내악곡. 피아노와 현악 4중주의 편성이 독특하고(더블베이스 포함), 밝고 유쾌한 분위기가 특징이다.','D. 667',1819,8,38,'https://open.spotify.com/album/5fwIs9k26bAwbgyIUQbiHf','https://music.apple.com/us/album/schubert-100-supreme-classical-masterpieces-rise-of/422602965',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:29'),(119,26,'교향곡 8번 B단조 \"미완성\"','Symphony No. 8 in B minor \"Unfinished\"','album','슈베르트의 교향곡 중 가장 유명한 작품. 2악장까지만 완성되었음에도 불구하고 그 자체로 완벽한 걸작으로 평가받는다. 낭만주의 교향곡의 시작을 알린 작품이다.','D. 759',1822,8,25,'https://open.spotify.com/album/6gWNH1C08CPMoiOgW1HyiK','https://music.apple.com/us/album/schubert-100-supreme-classical-masterpieces-rise-of/422602965',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:30'),(120,26,'현악 4중주 14번 D단조 \"죽음과 소녀\"','String Quartet No. 14 in D minor \"Death and the Maiden\"','album','자신의 가곡 <죽음과 소녀>의 선율을 2악장 변주곡의 주제로 사용했다. 슈베르트의 실내악 중 가장 극적이고 강렬한 비극미를 보여주는 걸작이다.','D. 810',1824,10,40,'https://open.spotify.com/album/7jkPGApdpaWZimiYWpWB24','https://music.apple.com/us/album/schubert-100-supreme-classical-masterpieces-rise-of/422602965',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:32'),(121,26,'즉흥곡 Op. 90','Impromptus','album','슈베르트의 피아노 소품 중 가장 유명한 곡집. 4개의 곡으로 이루어져 있으며, 특히 3번 G♭장조의 서정적인 선율이 유명하다.','D. 899',1827,8,25,'https://open.spotify.com/album/0d4aPBSYgISMbfKaUzgkVB','https://music.apple.com/us/album/schubert/1452125184',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:33'),(122,27,'바이올린 협주곡 E단조','Violin Concerto in E minor','album','베토벤, 브람스의 협주곡과 함께 낭만주의 3대 바이올린 협주곡으로 꼽힌다. 1악장 시작과 동시에 독주 바이올린이 주제를 연주하는 혁신적인 구성을 가졌다.','Op. 64',1844,10,28,'https://open.spotify.com/album/0Oopx6trV1Sq7oYRFJfG7u','https://music.apple.com/us/album/mendelssohn-violin-concerto-op-64-piano-trio-op-49/1452381555',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:34'),(123,27,'<한여름 밤의 꿈> 부수음악','A Midsummer Night\'s Dream','album','셰익스피어의 희극을 위한 음악. 17세에 작곡한 서곡(Op. 21)과 훗날 추가한 부수음악(Op. 61)으로 구성된다. 특히 \'결혼 행진곡(Wedding March)\'이 전 세계적으로 유명하다.','Opp. 21 & 61',1826,8,45,'https://open.spotify.com/album/4Fevw5QZz2C68rCuZoficI','https://music.apple.com/us/album/the-ultimate-christmas-collection/1156933666',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:35'),(124,27,'교향곡 4번 A장조 \"이탈리아\"','Symphony No. 4 in A major \"Italian\"','album','멘델스존이 이탈리아를 여행하며 받은 영감으로 작곡한 교향곡. 눈부신 햇살과 푸른 하늘을 연상시키는 1악장과, 격렬한 4악장 \'살타렐로\'(이탈리아 춤곡)가 유명하다.','Op. 90',1833,8,30,'https://open.spotify.com/album/4aQjU47ZUwhpFgiIqv5Jqi','https://music.apple.com/us/album/mendelssohn-symphony-no-4-op-90-italian-the-hebrides/1392035820',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:36'),(125,27,'무언가 (선집)','Songs Without Words (Lieder ohne Worte)','album','\'가사 없는 노래\'라는 뜻의 피아노 소품집. 총 8권(Opp. 19b, 30, 38, 53, 62, 67, 85, 102)으로 구성되어 있으며, \'봄의 노래\', \'베네치아의 뱃노래\' 등이 유명하다.','Opp. 19b-102',1845,6,90,'https://open.spotify.com/album/1gO4yXWqgAcGx7sZ2Av2LZ','https://music.apple.com/us/album/the-ultimate-christmas-collection/1156933666',NULL,'2025-11-17 07:21:40','2025-11-18 07:37:10'),(126,27,'<핑갈의 동굴> 서곡','The Hebrides Overture \"Fingal\'s Cave\"','song','스코틀랜드 헤브리디스 제도를 여행하며, 파도가 몰아치는 핑갈의 동굴에서 영감을 받아 작곡한 연주회용 서곡. 풍경 묘사가 뛰어난 표제 음악의 걸작이다.','Op. 26',1830,8,11,'https://open.spotify.com/track/3Hcn3NlLeDU4uQf0qJaaMt','https://music.apple.com/us/album/the-hebrides-op-26-fingals-cave/1452513835?i=1452513961',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:37'),(127,28,'연습곡 Op. 10, No. 12 \"혁명\"','Étude \"Revolutionary\"','song','쇼팽이 조국 폴란드가 러시아에 점령당했다는 소식을 듣고 격분하여 작곡했다는 일화로 유명하다. 왼손의 격렬한 아르페지오가 특징이다.','Op. 10, No. 12',1831,9,3,'https://open.spotify.com/track/0S9j30JErDLPpfjucVkXre','https://music.apple.com/us/album/12-%C3%A9tudes-op-10-no-3-in-e-major-tristesse/1440734550?i=1440734559',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:39'),(128,28,'즉흥 환상곡','Fantaisie-Impromptu','song','쇼팽의 피아노곡 중 가장 대중적인 인기를 누리는 곡 중 하나. 격렬한 도입부/종결부와 감미로운 서정성이 돋보이는 중간 부분이 극적인 대비를 이룬다.','Op. 66',1834,9,5,'https://open.spotify.com/track/7xqAYjYWXIJNVNhHjIkbQq','https://music.apple.com/us/album/fantasie-impromptu-in-c-sharp-minor-op-66/158732692?i=158732789',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:40'),(129,28,'발라드 1번 G단조','Ballade No. 1 in G minor','song','쇼팽이 \'발라드\'라는 장르를 피아노 독주곡으로 승화시킨 첫 번째 작품. 서사적이고 극적인 전개로 쇼팽의 작품 중 최고 걸작 중 하나로 꼽힌다.','Op. 23',1835,10,10,'https://open.spotify.com/track/6BuzrWo5KIfL1Uf4nDxI1t','https://music.apple.com/us/album/ballade-no-1-in-g-minor-op-23-b-66/1613558117?i=1613558120',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:41'),(130,28,'폴로네즈 6번 A♭장조 \"영웅\"','Polonaise No. 6 in A♭ major \"Heroic\"','song','폴란드의 민속 춤곡인 폴로네즈를 장엄하고 영웅적인 교향악적 규모로 확장시킨 작품. 쇼팽의 애국심과 기상을 보여준다.','Op. 53',1842,10,7,'https://open.spotify.com/track/2SV1Y16ep8CdhVTWncAo6P','https://music.apple.com/us/album/polonaise-in-a-flat-major-op-53-heroic-classical-session/1725522850?i=1725522855',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:42'),(131,28,'녹턴 E♭장조','Nocturne in E♭ major','song','쇼팽의 녹턴(야상곡) 중 가장 유명한 곡. 감미롭고 서정적인 멜로디가 특징이며, 수많은 영화와 드라마에 삽입되었다.','Op. 9, No. 2',1830,5,5,'https://open.spotify.com/track/1VNvsvEsUpuUCbHpVop1vo','https://music.apple.com/us/album/nocturnes-op-9-no-2-in-e-flat-major/594180316?i=594180660',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:43'),(132,28,'피아노 협주곡 1번 E단조','Piano Concerto No. 1 in E minor','album','쇼팽이 조국 폴란드를 떠나기 직전에 작곡한 곡. 오케스트라는 다소 빈약하다는 평을 받지만, 피아노 파트의 시적인 아름다움과 화려함은 압도적이다.','Op. 11',1830,10,40,'https://open.spotify.com/album/6N22adsrbRjMRYPi0wMNN6','https://music.apple.com/us/album/chopin-nocturnes/594180316',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:44'),(133,28,'왈츠 6번 D♭장조 \"강아지 왈츠\"','Waltz in D♭ major \"Minute Waltz\"','song','쇼팽이 자신의 꼬리를 무는 강아지를 보고 작곡했다는 일화가 전해진다. \'Minute(미닛, 1분)\' 왈츠로도 불리나, 1분 안에 연주하기는 매우 어렵다.','Op. 64, No. 1',1847,7,2,'https://open.spotify.com/track/4VvLXb6GRHQpBjX1s1lpne','https://music.apple.com/us/album/waltz-in-c-sharp-minor-op-64-no-2-tempo-giusto/555161874?i=555162040',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:45'),(134,29,'연가곡집 <시인의 사랑>','Song Cycle <Dichterliebe>','album','슈만이 클라라와 결혼한 \'가곡의 해(1840)\'에 작곡한 대표적인 연가곡집. 하이네의 시를 바탕으로, 사랑의 기쁨과 고뇌, 실연의 아픔을 그렸다.','Op. 48',1840,9,30,'https://open.spotify.com/album/5En6DGCjjYAZqLZ39egU8A','https://music.apple.com/us/album/schumann-dichterliebe-op-48-12-gedichte-op-35-and-others/1452214965',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:47'),(135,29,'피아노 모음곡 <어린이의 정경>','Kinderszenen','album','어린 시절을 회상하며 쓴 13개의 피아노 소품 모음곡. 어른을 위한 작품이다. 이 중 7번 \'트로이메라이(Träumerei, 꿈)\'가 매우 유명하다.','Op. 15',1838,6,18,'https://open.spotify.com/album/3dtyRuctasvglDB28bijNg','https://music.apple.com/us/album/schumann-kinderszenen-op-15-no-7-tr%C3%A4umerei-remastered/968494708',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:48'),(136,29,'피아노 협주곡 A단조','Piano Concerto in A minor','album','낭만주의 피아노 협주곡의 걸작. 오케스트라와 피아노가 교향악처럼 긴밀하게 융합되며, 슈만의 열정적인 면모와 서정성이 조화를 이룬다.','Op. 54',1845,10,32,'https://open.spotify.com/album/2OaqPHMDcGemoHAnzpKebC','https://music.apple.com/us/album/schumann-piano-concerto-in-a-minor-op-54-bruckner/1722636734',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:49'),(137,29,'교향곡 3번 E♭장조 \"라인\"','Symphony No. 3 in E♭ major \"Rhenish\"','album','슈만이 라인강의 풍경과 쾰른 대성당의 장엄함에서 영감을 받아 작곡한 교향곡. 5악장 구성이 독특하며, 낭만주의적 활기로 가득 차 있다.','Op. 97',1850,8,33,'https://open.spotify.com/album/0ZSZUADImCrIH5czVBfn38','https://music.apple.com/us/album/schumann-symphony-no-3-in-e-flat-major-op-97-rhenish/459077300',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:50'),(138,29,'피아노 모음곡 <카니발>','Carnaval','album','가면무도회(카니발)에 등장하는 인물들(피에로, 할리퀸)과 자신의 내면(플로레스탄, 오이제비우스), 쇼팽, 파가니니 등을 음악으로 묘사한 21개의 캐릭터 피스 모음곡이다.','Op. 9',1835,9,30,'https://open.spotify.com/album/3obNSPodoeli9yawITvwdT','https://music.apple.com/us/album/schumann-carnaval-op-9-fantasiest%C3%BCcke-op-12/1173650731',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:51'),(139,30,'사랑의 꿈 3번 A♭장조','Liebestraum No. 3 in A♭ major','song','리스트의 피아노 소품 중 쇼팽의 녹턴과 함께 가장 사랑받는 곡. 본래 가곡으로 작곡했던 것을 피아노 독주곡으로 편곡한 것으로, 감미로운 멜로디가 특징이다.','S. 541/3',1850,7,5,'https://open.spotify.com/track/4IsoCqXixbkRFLnIv0K2WY','https://music.apple.com/us/album/liebestraum-no-3-in-a-flat-major-s-541-3/447288052?i=447288075',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:52'),(140,30,'파가니니 주제에 의한 대연습곡 3번 \"라 캄파넬라\"','Grandes études de Paganini \"La Campanella\"','song','파가니니의 바이올린 협주곡 2번 3악장 \'종(La Campanella)\'의 주제를 바탕으로 작곡한 피아노 연습곡. 종소리를 모방한 화려한 고음부 기교가 특징이다.','S. 141/3',1851,10,5,'https://open.spotify.com/track/6Y2ID5LrizFmT8FL0BQEgG','https://music.apple.com/us/album/grandes-%C3%A9tudes-de-paganini-s-141-3/1766637326?i=1766637347',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:54'),(141,30,'헝가리 광시곡 2번','Hungarian Rhapsody No. 2 in C# minor','song','리스트의 19개의 헝가리 광시곡 중 가장 유명한 곡. 집시(롬족) 음악의 즉흥적인 도입부(라산)와 격렬하게 빨라지는 후반부(프리스카)의 대비가 인상적이다.','S. 244/2',1847,9,10,'https://open.spotify.com/track/7CIoJE0JfVFcmmUY3fFojH','https://music.apple.com/us/album/hungarian-rhapsody-no-2-in-c-sharp-minor-s-244-2/429662830?i=429662942',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:55'),(142,30,'교향시 <전주곡>','Symphonic Poem <Les Préludes>','song','리스트가 창시한 \'교향시\' 장르의 대표작. \'인생은 죽음을 향한 전주곡\'이라는 라마르틴의 시를 바탕으로, 삶의 여러 단면(사랑, 투쟁, 승리 등)을 묘사했다.','S. 97',1854,8,16,'https://open.spotify.com/track/52EPKwqnrf8sgYvJOAdgvE','https://music.apple.com/us/album/les-pr%C3%A9ludes-s-97-pt-2-transc-lenaerts/1579909770?i=1579910287',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:56'),(143,30,'초절기교 연습곡 4번 D단조 \"마제파\"','Transcendental Étude No. 4 in D minor \"Mazeppa\"','song','리스트의 초인적인 기교를 보여주는 12개의 연습곡 중 하나. 말에 묶여 황야를 달리는 영웅 마제파의 모습을 묘사한 격렬하고 영웅적인 곡이다.','S. 139/4',1852,10,8,'https://open.spotify.com/track/4W1RUx1NufSR1Oc7KsBBIm','https://music.apple.com/us/album/transcendental-etudes-s-139-no-4-mazeppa/1736941026?i=1736941031',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:57'),(144,31,'오페라 <발퀴레> 중 \"발퀴레의 기행\"','\"Ride of the Valkyries\" (from Opera <Die Walküre>)','song','4부작 오페라 <니벨룽의 반지>의 두 번째 작품 <발퀴레> 3막의 도입부. 영화 <지옥의 묵시록>에 사용되어 압도적인 인지도를 얻었다.','WWV 86B',1856,8,6,'https://open.spotify.com/track/63ZSow0dnUhOr175IbNZa2','https://music.apple.com/us/album/die-walk%C3%BCre-wwv-86b-act-iii-hojotoho-heiaha-ride-of/1639323056?i=1639323080',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:58'),(145,31,'오페라 <트리스탄과 이졸데>','Opera <Tristan und Isolde>','album','서양 음악사의 흐름을 바꾼 혁명적인 오페라. \'트리스탄 화음\'이라 불리는 모호한 화성을 통해, 해소되지 않는 사랑의 갈망을 표현하며 조성 붕괴의 시작을 알렸다.','WWV 90',1859,10,225,'https://open.spotify.com/album/1Dy1fAj73Udh23CN3dBnaA','https://music.apple.com/us/album/wagner-liszt/1287054017',NULL,'2025-11-17 07:21:40','2025-11-18 12:03:59'),(146,31,'오페라 <로엔그린> 중 \"혼례의 합창\"','\"Bridal Chorus\" (from Opera <Lohengrin>)','song','3막에 나오는 \'결혼 행진곡\'으로, 멘델스존의 결혼 행진곡과 함께 오늘날 전 세계 결혼식장에서 가장 많이 사용되는 곡이다.','WWV 75',1848,7,5,'https://open.spotify.com/track/6xF4xSD18EjuOD7vXYXFnD','https://music.apple.com/us/album/lohengrin-wwv-75-act-iii-prelude/1761708194?i=1761708621',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:00'),(147,31,'오페라 <탄호이저> 서곡','Opera <Tannhäuser> Overture','song','바그너의 초기 낭만주의 오페라의 걸작. \'순례자의 합창\'으로 대표되는 경건한 주제와 \'베누스베르크\'의 관능적인 주제가 대비를 이루는 화려한 서곡이다.','WWV 70',1845,8,15,'https://open.spotify.com/track/5dBHELm9dGc3kKsPeYIYKd','https://music.apple.com/us/album/tannh%C3%A4user-wie-todesahnung-o-du-mein-holder-abendstern/1452199904?i=1452200253',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:02'),(148,32,'오페라 <라 트라비아타>','Opera <La traviata>','album','베르디의 가장 유명하고 사랑받는 오페라. 파리 사교계의 여성 비올레타와 순진한 청년 알프레도의 비극적인 사랑을 그린다. \'축배의 노래\' 등이 유명하다.',NULL,1853,10,130,'https://open.spotify.com/album/56wRW64Pb6yVU8NIC2Ywgq','https://music.apple.com/us/album/%EC%8B%A0%EC%83%9D%EC%95%84%EB%A5%BC-%EC%9C%84%ED%95%9C-%ED%8F%AC%EA%B7%BC%ED%95%9C-%ED%81%B4%EB%9E%98%EC%8B%9D-%EC%9E%90%EC%9E%A5%EA%B0%80-35-%EB%B2%A0%EB%A5%B4%EB%94%94-%EB%9D%BC-%ED%8A%B8%EB%9D%BC%EB%B9%84%EC%95%84%ED%83%80-%EC%95%84-%EA%B7%B8%EB%8C%80%EC%98%80%EB%8D%98%EA%B0%80-single/1563135847',NULL,'2025-11-17 07:21:40','2025-11-18 07:37:58'),(149,32,'오페라 <리골레토>','Opera <Rigoletto>','album','베르디 중기 3대 걸작의 하나. 꼽추 광대 리골레토의 비극을 그렸다. 아리아 \'여자의 마음(La donna è mobile)\'이 전 세계적으로 유명하다.',NULL,1851,10,120,'https://open.spotify.com/album/36GWY5pcnu2ubklWR8vlSV','https://music.apple.com/us/album/verdi-operak%C3%B3rusok-1-hungaroton-classics/457634506',NULL,'2025-11-17 07:21:40','2025-11-18 07:38:00'),(150,32,'오페라 <아이다>','Opera <Aida>','album','수에즈 운하 개통을 기념하여 작곡된 스펙터클 오페라. 고대 이집트를 배경으로, 적국 에티오피아의 공주 아이다와 이집트 장군 라다메스의 비극적 사랑을 그렸다. \'개선 행진곡\'이 유명하다.',NULL,1871,10,150,'https://open.spotify.com/album/5omHC0CJ6ArHPXz4yEUpCJ','https://music.apple.com/us/album/%EC%8B%A0%EC%83%9D%EC%95%84-%EC%9E%98-%EC%9E%AC%EC%9B%8C%EC%A3%BC%EB%8A%94-%ED%8E%B8%EC%95%88%ED%95%9C-%EC%9E%90%EC%9E%A5%EA%B0%80-15-%EC%95%84%EC%9D%B4%EB%8B%A4-%EC%84%9C%EA%B3%A1-single/1550075238',NULL,'2025-11-17 07:21:40','2025-11-18 07:38:02'),(151,32,'오페라 <나부코> 중 \"히브리 노예들의 합창\"','\"Chorus of the Hebrew Slaves\" (Va, pensiero) from <Nabucco>','song','바빌론에 포로로 잡혀온 히브리 노예들이 고향을 그리워하며 부르는 합창곡. 당시 오스트리아의 지배를 받던 이탈리아인들에게 \'제2의 국가\'처럼 불리며 베르디를 국민 영웅으로 만들었다.',NULL,1842,8,5,'https://open.spotify.com/track/5MZhQIC0PGSVrBerfRfaJz','https://music.apple.com/us/album/giuseppe-verdi-nabucco-va-pensiero-sull-ali-dorate/335250010?i=335250272',NULL,'2025-11-17 07:21:40','2025-11-18 07:38:04'),(152,32,'레퀴엠','Messa da Requiem','album','베르디가 존경했던 문호 만초니를 추모하기 위해 작곡한 진혼 미사곡. 종교 음악임에도 불구하고 \'오페라적인\' 격렬한 드라마와 감정 표현이 특징이며, 특히 \'진노의 날(Dies Irae)\' 부분이 압도적이다.',NULL,1874,10,85,'https://open.spotify.com/album/6tecdWVuOMEmcJBay9nS0I','https://music.apple.com/us/album/verdi-messa-da-requiem/393935836',NULL,'2025-11-17 07:21:40','2025-11-18 07:38:06'),(153,33,'교향곡 1번 C단조','Symphony No. 1 in C minor','album','브람스가 20년 이상 공들여 완성한 첫 교향곡. 베토벤의 9번 교향곡과 유사한 C단조에서 C장조로의 \'투쟁과 승리\' 구도를 계승하여 \'베토벤의 10번 교향곡\'이라는 찬사를 받았다.','Op. 68',1876,10,45,'https://open.spotify.com/album/7kZ5Z6eATF6eVl5m51zjI2','https://music.apple.com/us/album/brahms-symphony-no-1-in-c-minor-op-68/1846606963',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:03'),(154,33,'교향곡 3번 F장조','Symphony No. 3 in F major','album','브람스의 교향곡 중 가장 서정적이고 낭만적인 작품. 3악장 \'포코 알레그레토\'의 애수 어린 멜로디가 매우 유명하며, 영화, 드라마에 자주 사용된다.','Op. 90',1883,9,35,'https://open.spotify.com/album/3obNSPodoeli9yawITvwdT','https://music.apple.com/us/album/brahms-symphony-no-3-in-f-op-90-tragic-overture-op-81/1452326460',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:04'),(155,33,'헝가리 무곡 5번 G단조','Hungarian Dance No. 5 in G minor','song','브람스의 21개의 헝가리 무곡(본래 피아노 연탄곡) 중 가장 유명한 곡. 집시 풍의 격렬한 리듬과 애수 어린 멜로디가 특징이다.','WoO 1',1869,6,3,'https://open.spotify.com/track/6iso1N9RU88upCFV02Clyg','https://music.apple.com/us/album/21-hungarian-dances-woo-1-no-5-in-g-minor-allegro-orch/1853615030?i=1853615472',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:05'),(156,33,'바이올린 협주곡 D장조','Violin Concerto in D major','album','베토벤의 협주곡과 함께 낭만주의 바이올린 협주곡의 양대 산맥으로 꼽힌다. 교향악적이고 장대한 규모와 남성적인 스케일이 특징이다.','Op. 77',1878,10,40,'https://open.spotify.com/album/0zXYmGACZoy8QU6YpwpnDL','https://music.apple.com/us/album/brahms-violin-concerto-op-77/922412963',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:06'),(157,33,'독일 레퀴엠','A German Requiem','album','전통적인 라틴어 레퀴엠(죽은 자를 위한 미사)이 아닌, 브람스가 직접 루터 성서에서 발췌한 독일어 가사로 작곡한 \'살아있는 자들을 위로하기 위한\' 레퀴엠이다.','Op. 45',1868,9,70,'https://open.spotify.com/album/27PK36RZlWhz7wckARsLau','https://music.apple.com/us/album/brahms-ein-deutsches-requiem-op-45/1440780787',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:07'),(158,34,'교향곡 6번 B단조 \"비창\"','Symphony No. 6 in B minor \"Pathétique\"','album','차이콥스키의 마지막 교향곡이자 최고 걸작. 전통적인 \'환희의\' 종결이 아닌, 극도로 절망적이고 비통한 아다지오(느린 악장)로 끝나는 파격적인 구성이 특징이다.','Op. 74',1893,9,46,'https://open.spotify.com/album/2GNopL4mowvbriuz6Vzwo4','https://music.apple.com/us/album/tchaikovsky-the-nutcracker-op-71/292623901',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:08'),(159,34,'피아노 협주곡 1번 B♭단조','Piano Concerto No. 1 in B♭ minor','album','낭만주의 피아노 협주곡 중 가장 유명한 곡. 장엄하고 화려한 도입부의 멜로디는 누구나 한 번쯤 들어봤을 정도로 압도적인 인지도를 자랑한다.','Op. 23',1875,10,35,'https://open.spotify.com/album/50FrZDRaKSyVMnHd8Eh8Ww','https://music.apple.com/us/album/tchaikovsky-the-nutcracker-op-71/292623901',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:10'),(160,34,'바이올린 협주곡 D장조','Violin Concerto in D major','album','베토벤, 멘델스존, 브람스의 협주곡과 함께 낭만주의 4대 바이올린 협주곡으로 꼽힌다. 러시아 특유의 애수 어린 멜로디와 화려한 기교가 특징이다.','Op. 35',1878,10,33,'https://open.spotify.com/album/4VW8KshlqwaioobZQRzgKk','https://music.apple.com/us/album/tchaikovsky-violin-concerto-in-d-major-op-35/442744438',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:11'),(161,34,'발레 <호두까기 인형>','Ballet <The Nutcracker>','album','차이콥스키의 3대 발레 중 하나로, 크리스마스를 배경으로 한 동화적인 작품이다. \'꽃의 왈츠\', \'사탕 요정의 춤\' 등 모음곡(Suite)이 특히 유명하다.','Op. 71',1892,8,85,'https://open.spotify.com/album/14vK0AGj65BvSU64pQyNxb','https://music.apple.com/us/album/tchaikovsky-the-nutcracker-op-71/292623901',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:12'),(162,34,'발레 <백조의 호수>','Ballet <Swan Lake>','album','차이콥스키의 3대 발레 중 첫 작품이자, 고전 발레의 대명사. 저주에 걸려 백조가 된 공주 오데트의 이야기를 그린다. \'정경(Scene)\'의 주제 선율이 유명하다.','Op. 20',1876,9,150,'https://open.spotify.com/album/5Tl7H13s3o3j7272rGHFto','https://music.apple.com/us/album/tchaikovsky-swan-lake-op-20-th-12/1362935219',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:13'),(163,34,'1812년 서곡','1812 Overture','song','나폴레옹의 러시아 원정 실패를 기념하기 위해 작곡된 표제 음악. 실제 대포(Cannon) 소리와 종소리가 사용되는 웅장한 피날레로 유명하다.','Op. 49',1880,7,16,'https://open.spotify.com/track/6oWacAPUt8LMXqRkEk2MNg','https://music.apple.com/us/album/wiegenlied-op-49-no-4-lullaby-arr-for-cello-and-piano/1009467298?i=1009467584',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:14'),(164,35,'24개의 카프리스','24 Caprices for Solo Violin','album','바이올린 독주를 위한 연습곡집으로, \'바이올린의 신약성서\'라 불린다. 바이올린이 표현할 수 있는 모든 기교가 집약되어 있다. 마지막 24번 A단조가 가장 유명하다.','Op. 1',1817,10,75,'https://open.spotify.com/album/07aS2IC15MgQEafWXi10Lk','https://music.apple.com/us/album/paganini-24-caprices-op-1/1025548870',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:15'),(165,35,'바이올린 협주곡 2번 B단조 \"라 캄파넬라\"','Violin Concerto No. 2 in B minor \"La Campanella\"','album','3악장 론도 \'라 캄파넬라(종)\'가 특히 유명하다. 종소리를 모방하는 바이올린의 화려한 플래절렛(하모닉스) 기교가 특징이며, 리스트가 피아노곡으로 편곡했다.','Op. 7',1826,10,30,'https://open.spotify.com/album/1MaE1wcPr9hjnE90EIk4xD','https://music.apple.com/us/album/paganini-24-caprices-for-solo-violin-op-1/201284931',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:17'),(166,35,'바이올린 협주곡 1번 D장조','Violin Concerto No. 1 in D major','album','파가니니의 협주곡 중 가장 널리 연주되는 곡. 바이올린의 화려한 기교와 이탈리아 오페라풍의 아리아 선율이 결합되어 있다.','Op. 6',1816,10,35,'https://open.spotify.com/album/2HekOEAkLKzPD0yn2i5fnR','https://music.apple.com/us/album/paganini-violin-concerto-in-d-major-op-6-by-michael-rabin/1611725184',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:18'),(167,36,'오페라 <세비야의 이발사>','Opera <The Barber of Seville>','album','로시니의 최고 걸작 희극 오페라(오페라 부파). 재치 넘치는 이발사 피가로의 활약을 그린다. \'나는 이 거리의 만능 재주꾼(Largo al factotum)\' 아리아가 유명하다.',NULL,1816,10,150,'https://open.spotify.com/album/2Bti3XM36AyxSYUwCFanak','https://music.apple.com/us/album/rossini-for-cello/1529947037',NULL,'2025-11-17 07:21:40','2025-11-18 07:38:36'),(168,36,'서곡 <윌리엄 텔>','William Tell Overture','song','로시니의 마지막 오페라 <윌리엄 텔>의 서곡. 4개의 부분으로 나뉘며, 특히 마지막 \'스위스 군대의 행진\'(경쾌한 말발굽 소리) 부분이 매우 유명하다.',NULL,1829,8,12,'https://open.spotify.com/track/1ISbc05WTtcVh7q7QOXuu4','https://music.apple.com/us/album/william-tell-overture/574932264?i=574932792',NULL,'2025-11-17 07:21:40','2025-11-18 07:38:38'),(169,36,'서곡 <도둑 까치>','La gazza ladra Overture','song','작은 북(스네어 드럼)의 독특한 리듬으로 시작하는 로시니의 유명한 오페라 서곡 중 하나이다.',NULL,1817,7,10,'https://open.spotify.com/track/5o4pgCR3JIeIbzwqBfjmtn','https://music.apple.com/us/album/la-gazza-ladra-overture/1683682692?i=1683683261',NULL,'2025-11-17 07:21:40','2025-11-18 07:38:40'),(170,37,'환상 교향곡','Symphonie fantastique','album','베를리오즈의 출세작이자 표제 음악의 걸작. 실연당한 예술가가 아편에 취해 꾸는 5개의 환상을 묘사했다. 사랑하는 여인을 상징하는 \'고정 악상(Idée fixe)\'이 전 악장에 등장한다.','Op. 14',1830,9,50,'https://open.spotify.com/album/4MGdY1hGi1FhQAHB2t3rbu','https://music.apple.com/us/album/berlioz-symphony-fantastique-op-14/456243649',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:19'),(171,37,'<파우스트의 겁벌> 중 \"헝가리 행진곡\"','\"Hungarian March\" (Rákóczi March) from <La damnation de Faust>','song','괴테의 <파우스트>를 바탕으로 한 오페라적 전설(극적 칸타타). 그 중 \'헝가리 행진곡(라코치 행진곡)\'이 화려한 관현악법으로 유명해져 단독으로 자주 연주된다.','Op. 24',1846,8,5,'https://open.spotify.com/track/5KPsnjScCNMPN7mHQxTVcE','https://music.apple.com/us/album/la-damnation-de-faust-op-24-h-111-pt-ii-sc%C3%A8ne-vii/1779101241?i=1779103044',NULL,'2025-11-17 07:21:40','2025-11-18 07:38:44'),(172,37,'서곡 <로마의 사육제>','Roman Carnival Overture','song','자신의 오페라 <벤베누토 첼리니>의 선율을 바탕으로 작곡한 화려한 연주회용 서곡. 로마의 사육제(카니발)의 열광적인 분위기를 묘사했다.','Op. 9',1844,8,9,'https://open.spotify.com/track/1Q6NaTxg6XM2OexhKQuegh','https://music.apple.com/us/album/overture-le-carnaval-romain-op-9/1452143225?i=1452143483',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:20'),(173,38,'오페라 <루슬란과 류드밀라> 서곡','Opera <Ruslan and Lyudmila> Overture','song','글린카의 두 번째 오페라의 서곡. 러시아 음악 특유의 질주하는 듯한 리듬과 활기찬 에너지로 가득 차 있으며, 오케스트라의 단골 레퍼토리이다.',NULL,1842,8,5,'https://open.spotify.com/track/2pt2QSlJcW2c6hllKa2uac','https://music.apple.com/us/album/ruslan-and-lyudmila-overture/1378541975?i=1378541977',NULL,'2025-11-17 07:21:40','2025-11-18 07:38:48'),(174,38,'오페라 <황제를 위한 삶>','Opera <A Life for the Tsar>','album','러시아 최초의 국민 오페라. 러시아 농부 이반 수사닌이 폴란드 군대로부터 황제를 구하기 위해 자신을 희생한다는 애국적인 내용을 담고 있다.',NULL,1836,9,180,'https://open.spotify.com/album/3eN7f0dD2dRfQ7Rhw0jErE','https://music.apple.com/us/album/%EC%9C%A0%EC%95%84%EB%A5%BC-%EC%9C%84%ED%95%9C-%ED%8F%AC%EA%B7%BC%ED%95%9C-%ED%81%B4%EB%9E%98%EC%8B%9D-%EC%9E%90%EC%9E%A5%EA%B0%80-42-6%EA%B0%9C%EC%9D%98-%ED%91%B8%EA%B0%80-%ED%91%B8%EA%B0%80-2%EB%B2%88-%EA%B0%80%EB%8B%A8%EC%A1%B0-single/1590823068',NULL,'2025-11-17 07:21:40','2025-11-18 07:38:50'),(175,38,'가곡 <종달새>','The Lark (L\'Alouette)','song','글린카의 가곡 중 가장 유명한 곡. 종달새의 지저귐을 묘사한 아름다운 선율로, 발라키레프가 피아노 독주곡으로 편곡하여 더욱 유명해졌다.',NULL,1840,5,4,'https://open.spotify.com/track/1DCby1TycXAql59CJOQhxg','https://music.apple.com/us/album/the-lark-lalouette-arr-by-mily-balkirev-live/1735619233?i=1735619421',NULL,'2025-11-17 07:21:40','2025-11-18 07:38:52'),(176,39,'피아노 3중주 G단조','Piano Trio in G minor','album','클라라 슈만의 실내악 작품 중 최고 걸작으로 꼽힌다. 남편 로베르트 슈만의 영향이 보이면서도 그녀 고유의 서정성과 탄탄한 구성미가 돋보인다.','Op. 17',1846,8,29,'https://open.spotify.com/album/05tmSTxvthlg6gvRykWpk5','https://music.apple.com/us/album/c-schumann-piano-trio-in-g-minor-op-17-schubert-string/1712879091',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:21'),(177,39,'피아노 협주곡 A단조','Piano Concerto in A minor','album','16세의 나이에 완성한 야심 찬 작품. 쇼팽과 동시대 낭만주의 비르투오소의 면모와 깊은 서정성을 동시에 보여준다.','Op. 7',1836,9,22,'https://open.spotify.com/album/05tmSTxvthlg6gvRykWpk5','https://music.apple.com/us/album/c-schumann-piano-concerto-op-7-piano-trio-op-17-3-romanzen/330068046',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:22'),(178,39,'3개의 로망스 (바이올린과 피아노를 위한)','Three Romances for Violin and Piano','album','그녀의 후기 작품으로, 절친한 친구였던 바이올리니스트 요아힘을 위해 작곡했다. 깊고 내밀한 낭만적 감수성이 돋보인다.','Op. 22',1853,7,10,'https://open.spotify.com/album/3q0ogG562Nocti3uDkZmAP','https://music.apple.com/us/album/clara-schumann-three-romances-for-violin-piano-op-22/1554501922',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:23'),(179,40,'바이올린 소나타 A장조','Violin Sonata in A major','album','프랑크의 가장 유명하고 사랑받는 실내악곡. 바이올리니스트 외젠 이자이의 결혼 선물로 작곡되었다. 4개의 악장이 하나의 주제(순환 형식)로 유기적으로 연결되어 있다.','FWV 8',1886,10,28,'https://open.spotify.com/album/1PVBaGkd73VgJMZxK0A0fh','https://music.apple.com/us/album/cesar-franck-sonata-for-piano-and-violin-ernest/1226868354',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:25'),(180,40,'교향곡 D단조','Symphony in D minor','album','19세기 후반 프랑스를 대표하는 교향곡. 바그너의 반음계적 화성과 오르간적인 웅장함, 그리고 \'순환 형식\'이 특징인 걸작이다.','FWV 48',1888,9,40,'https://open.spotify.com/album/2fUzxu81BSVoDIvoKu4akR','https://music.apple.com/us/album/franck-symphony-in-d-minor-fwv-48/1706536142',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:26'),(181,40,'생명의 양식','Panis angelicus (Messe à trois voix)','song','본래 3성부 미사(Op. 12)에 포함된 곡이었으나, \'생명의 양식\'이라는 제목의 독창곡으로 편곡되어 널리 알려졌다. 경건하고 아름다운 선율이 특징이다.','Op. 12',1872,4,4,'https://open.spotify.com/track/3r21CDDf54CNOwy1pNggOk','https://music.apple.com/us/album/fantasiest%C3%BCcke-op-12-iii-warum/1112570149?i=1112570408',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:27'),(182,41,'교향곡 4번 E♭장조 \"낭만적\"','Symphony No. 4 in E♭ major \"Romantic\"','album','브루크너의 교향곡 중 가장 인기가 많은 작품. 중세의 숲, 성, 기사의 모습을 그린 표제음악적 성격을 띠고 있으며, 1악장의 호른 독주가 유명하다.','WAB 104',1874,9,68,'https://open.spotify.com/album/3TvUkuLcmDplNvmNOLclS6','https://music.apple.com/us/album/bruckner-symphony-no-4-wab-104/963268549',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:28'),(183,41,'교향곡 7번 E장조','Symphony No. 7 in E major','album','브루크너에게 처음으로 큰 성공을 안겨준 교향곡. 2악장 아다지오는 그가 존경했던 바그너의 죽음을 추모하며 쓴 장엄하고 비통한 음악이다.','WAB 107',1883,9,65,'https://open.spotify.com/album/5oeKn90Xxhh7WEDtwn9ymJ','https://music.apple.com/us/album/bruckner-symphony-no-7-in-e-major-wab-107/1778293139',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:29'),(184,41,'모테트 \"이 장소는 하느님이 만드셨다\"','Motet <Locus iste>','song','브루크너의 아카펠라(무반주 합창) 모테트 중 가장 유명한 곡. 린츠 대성당 헌당식을 위해 작곡되었으며, 신비롭고 경건한 화성이 돋보인다.','WAB 23',1869,6,3,'https://open.spotify.com/track/4XgeF0uI3ndjXyquX4M4ty','https://music.apple.com/us/album/locus-iste-wab-23/1726582442?i=1726582444',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:30'),(185,42,'왈츠 <아름답고 푸른 도나우>','Waltz <The Blue Danube>','song','오스트리아 빈을 상징하는 \'제2의 국가\'와도 같은 왈츠. 빈 신년 음악회의 단골 앙코르 곡이며, 전 세계적으로 가장 유명한 왈츠이다.','Op. 314',1866,6,10,'https://open.spotify.com/track/4J0e4gEqaLQlG5EM0wws1K','https://music.apple.com/us/album/the-blue-danube-waltz-op-314-from-true-lies/30104967?i=30104948',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:31'),(186,42,'오페레타 <박쥐> 서곡','Operetta <Die Fledermaus> Overture','song','\'왈츠의 왕\' 슈트라우스의 가장 성공한 오페레타(희극 오페라) <박쥐>의 서곡. 오페레타에 등장하는 유쾌하고 활기찬 선율들이 집약되어 있다.','Op. 367',1874,7,8,'https://open.spotify.com/track/4LSIibpcefV7UCuKbcnLgV','https://music.apple.com/us/album/on-the-beautiful-blue-danube-op-314/339006385?i=339006497',NULL,'2025-11-17 07:21:40','2025-11-18 07:39:15'),(187,42,'폴카 <천둥과 번개>','Polka <Thunder and Lightning>','song','천둥(팀파니)과 번개(심벌즈)를 묘사한 빠르고 격렬한 폴카. 빈 신년 음악회의 단골 레퍼토리이다.','Op. 324',1868,7,3,'https://open.spotify.com/track/7d9xh4Ob0IUTMZckYQueFE','https://music.apple.com/us/album/unter-donner-und-blitz-polka-op-324/1452135456?i=1452135703',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:33'),(188,42,'왈츠 <빈 숲 속의 이야기>','Waltz <Tales from the Vienna Woods>','song','아름답고 푸른 도나우와 함께 빈 왈츠의 정수로 꼽히는 작품. 빈 숲의 정경과 민속악기 치터(Zither)의 독주가 인상적이다.','Op. 325',1868,6,12,'https://open.spotify.com/track/5MgFtZLbPJVprSiSmrMZl1','https://music.apple.com/us/album/geschichten-aus-dem-wienerwald-op-325/1452135456?i=1452135699',NULL,'2025-11-17 07:21:40','2025-11-18 12:04:34'),(189,43,'피아노 모음곡 <전람회의 그림>','Pictures at an Exhibition','album','요절한 친구 화가 하르트만의 유작 전시회를 보고, 10개의 그림을 음악으로 묘사한 피아노 모음곡. \'프롬나드(Promenade)\'라는 주제가 그림 사이를 연결한다.',NULL,1874,9,35,'https://open.spotify.com/album/1b2aoeaYZZBWmJoavOQhnd','https://music.apple.com/us/album/mussorgsky-pictures-at-an-exhibition-the-works/1467961780',NULL,'2025-11-17 07:21:40','2025-11-18 07:39:21'),(190,43,'<전람회의 그림> (라벨 편곡 관현악 버전)','Pictures at an Exhibition (Orch. by Ravel)','album','무소르크스키의 원곡 피아노 모음곡을 \'관현악의 마술사\' 라벨이 천재적인 감각으로 편곡한 버전. 오늘날에는 원곡보다 더 자주 연주되며, 특히 마지막 \'키예프의 대문\'이 압도적이다.',NULL,1922,9,35,'https://open.spotify.com/album/2Y209Dl3EHXRycbwMfBeDx','https://music.apple.com/us/album/mussorgsky-pictures-at-an-exhibition-orch-ravel-dawn/1609150375',NULL,'2025-11-17 07:21:40','2025-11-18 07:39:23'),(191,43,'교향시 <민둥산의 하룻밤>','Symphonic Poem <Night on Bald Mountain>','song','성 요한 축일 전야에 민둥산에 마녀와 악마들이 모여 광란의 축제를 벌이는 모습을 묘사한 곡. 림스키코르사코프의 편곡 버전이 유명하다.',NULL,1867,8,12,'https://open.spotify.com/track/7jgf3r9Xawaqa2hqAYBL17','https://music.apple.com/us/album/symphonic-poem-night-on-bald-mountain/1536374472?i=1536374475',NULL,'2025-11-17 07:21:40','2025-11-18 07:39:25'),(192,43,'오페라 <보리스 고두노프>','Opera <Boris Godunov>','album','러시아 국민 오페라의 최고 걸작. 황제를 살해하고 왕위에 오른 보리스 고두노프의 죄의식과 몰락, 그리고 러시아 민중의 고통을 사실적으로 그렸다.',NULL,1874,10,180,'https://open.spotify.com/album/2ClfpvpB70e3sp2NYv1MnR','https://music.apple.com/us/album/mussorgsky-boris-godunov-1872-version/1467924248',NULL,'2025-11-17 07:21:40','2025-11-18 07:39:27'),(193,44,'오페라 <카르멘>','Opera <Carmen>','album','서양 오페라 역사상 가장 인기 있는 작품 중 하나. 집시 여인 카르멘의 자유분방한 사랑과 비극적 죽음을 그린다. \'하바네라\', \'투우사의 노래\' 등 모든 아리아가 유명하다.','WD 31',1875,10,160,'https://open.spotify.com/album/7BnIMUlBiRaItLDC2ZaFvz','https://music.apple.com/us/album/bizet-carmen-wd-31/1452745203',NULL,'2025-11-17 07:21:40','2025-11-18 07:39:29'),(194,44,'<아를의 여인> 모음곡 1, 2번','L\'Arlésienne Suites No. 1 & 2','album','알퐁스 도데의 희곡 <아를의 여인>을 위해 작곡한 부수 음악. 연극은 실패했으나 음악이 큰 인기를 얻어 2개의 관현악 모음곡으로 편곡되었다. \'파랑돌\', \'미뉴에트\' 등이 유명하다.','WD 28',1872,8,30,'https://open.spotify.com/album/7gjg92DaufcSiyFU5zeyAN','https://music.apple.com/us/album/bizet-symphony-in-c-larlesienne-suites-nos-1-2/696714672',NULL,'2025-11-17 07:21:40','2025-11-18 07:39:31'),(195,44,'오페라 <진주조개잡이> 중 \"신성한 사원에서\"','Au fond du temple saint (from <Les pêcheurs de perles>)','song','비제의 초기 오페라 <진주조개잡이>(WD 13)에 나오는 테너와 바리톤의 2중창. 한 여자를 사랑한 두 남자의 우정을 노래하는 아름다운 선율로 유명하다.','WD 13',1863,8,6,'https://open.spotify.com/track/1Eq8p4OHjhVrSW0Wa815B1','https://music.apple.com/us/album/les-p%C3%AAcheurs-de-perles-gb-4-wd-13-je-crois-entendre/1656977663?i=1656977678',NULL,'2025-11-17 07:21:40','2025-11-18 07:39:33'),(196,44,'교향곡 C장조','Symphony in C major','album','비제가 17세 학생 시절에 작곡한 교향곡. 하이든과 모차르트의 영향을 받은 고전주의 스타일의 작품으로, 밝고 재치 넘치는 에너지가 특징이다.','WD 33',1855,7,30,'https://open.spotify.com/album/5dXwfzjDZOrMItV85BbMwd','https://music.apple.com/us/album/bizet-symphony-no-1-in-c-major-offenbach-ga%C3%AEt%C3%A9-parisienne/261173601',NULL,'2025-11-17 07:21:40','2025-11-18 07:39:35'),(197,45,'교향곡 9번 E단조 \"신세계로부터\"','Symphony No. 9 in E minor \"From the New World\"','album','드보르자크가 미국 뉴욕에서 작곡한 그의 최고 걸작. 흑인 영가와 아메리카 원주민 음악에서 영감을 받았으며, 2악장의 라르고(Goin\' Home) 선율이 유명하다.','Op. 95, B. 178',1893,9,45,'https://open.spotify.com/album/6FMu88LoghMcmme2aDkK3S','https://music.apple.com/us/album/dvor%C3%A1k-symphony-no-9-in-e-minor-op-95-from-the-new-world/1191184130',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:35'),(198,45,'첼로 협주곡 B단조','Cello Concerto in B minor','album','낭만주의 시대 첼로 협주곡 중 최고 걸작으로 꼽히는 작품. 첼로의 기교와 깊은 서정성, 교향악적인 웅장함이 결합되어 있다.','Op. 104, B. 191',1895,10,40,'https://open.spotify.com/album/5s5XcfwXMzrSObV4RrmkO7','https://music.apple.com/us/album/dvor%C3%A1k-cello-concerto-in-b-minor-op-104-haydn-cello/696896682',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:36'),(199,45,'슬라브 무곡 (1권, 2권)','Slavonic Dances (Op. 46 & Op. 72)','album','드보르자크에게 국제적인 명성을 안겨준 작품. 체코 보헤미아의 민속 춤곡을 바탕으로 한 활기차고 다채로운 관현악곡 모음이다.','Op. 46 & 72',1878,8,70,'https://open.spotify.com/album/5Yb3w5oRyYY5pO6DfPpDbu','https://music.apple.com/us/album/dvo%C5%99%C3%A1k-slavonic-dances-opp-46-72/1452683406',NULL,'2025-11-17 07:28:28','2025-11-18 07:39:41'),(200,45,'현악 4중주 12번 F장조 \"아메리카\"','String Quartet No. 12 in F major \"American\"','album','미국에서 <신세계 교향곡>과 함께 작곡된 실내악곡. 흑인 영가풍의 5음계 선율과 이국적인 리듬이 특징이다.','Op. 96, B. 179',1893,8,28,'https://open.spotify.com/album/6ujA1bLGS0CQcegSm1IQ9W','https://music.apple.com/us/album/anton%C3%ADn-dvo%C5%99%C3%A1k-string-quartet-no-12-in-f-major-op-96/1153313102',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:37'),(201,45,'유모레스크 7번 G♭장조','Humoresque No. 7 in G♭ major','song','8개의 유모레스크 모음(Op. 101) 중 7번째 곡으로, 드보르자크의 모든 소품 중 가장 유명하고 대중적으로 사랑받는 멜로디이다.','Op. 101, No. 7',1894,5,3,'https://open.spotify.com/track/77Z7bTYU8zFYMDbbSMkevF','https://music.apple.com/us/album/8-humoresques-op-101-no-7-in-g-flat-major-poco-lento-e-grazioso/730959307?i=730959369',NULL,'2025-11-17 07:28:28','2025-11-18 07:39:46'),(202,46,'교향시 <셰헤라자데>','Symphonic Suite <Scheherazade>','album','<천일야화>를 바탕으로 술탄에게 이야기를 들려주는 셰헤라자데(솔로 바이올린)의 모습을 그린 교향악 모음곡. 화려한 관현악법의 극치를 보여준다.','Op. 35',1888,9,45,'https://open.spotify.com/album/3o4ng43mfCwXZ8h2HpTkYc','https://music.apple.com/us/album/rimsky-korsakov-scheherazade-op-35/1598603284',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:38'),(203,46,'왕벌의 비행 (오페라 <술탄 황제의 이야기>)','Flight of the Bumblebee (from <The Tale of Tsar Saltan>)','song','오페라 3막에 나오는 간주곡. 왕자가 왕벌로 변신해 날아가는 모습을 묘사한, 숨 쉴 틈 없이 빠른 패시지로 유명한 곡이다.','Op. 57 (Opera)',1900,10,2,'https://open.spotify.com/track/6j7Sqj4wznqYuSlp8fh4SR','https://music.apple.com/us/album/the-tsar-of-saltan-op-57-flight-of-the-bumblebee/960538450?i=960539769',NULL,'2025-11-17 07:28:28','2025-11-18 07:39:50'),(204,46,'스페인 기상곡','Capriccio Espagnol','album','스페인 민속 선율과 리듬을 바탕으로 작곡한 5악장의 관현악곡. 현란한 오케스트레이션과 독주 악기들의 화려한 기교가 돋보인다.','Op. 34',1887,8,16,'https://open.spotify.com/album/3o4ng43mfCwXZ8h2HpTkYc','https://music.apple.com/us/album/nikolay-rimsky-korsakov-capriccio-espagnol-op-34-russian/1510453652',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:39'),(205,46,'러시아 부활절 축제 서곡','Russian Easter Festival Overture','song','러시아 정교회의 부활절 축제의 분위기와 성가를 바탕으로 작곡한 장엄하고 화려한 연주회용 서곡이다.','Op. 36',1888,8,15,'https://open.spotify.com/track/0TJ5YDihBnRvQTPbAEWsdU','https://music.apple.com/us/album/russian-easter-overture-op-36/254372417?i=254372661',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:41'),(206,47,'레퀴엠','Requiem','album','전통적인 레퀴엠과 달리 \'진노의 날(Dies Irae)\'을 생략하고, 죽음을 평화로운 안식으로 그린 작품. 특히 4악장 \'피에 예수(Pie Jesu)\'가 유명하다.','Op. 48',1890,8,35,'https://open.spotify.com/album/1gRfCVWCeB8VOKYmZ5JMOM','https://music.apple.com/us/album/faur%C3%A9-requiem-op-48-pavane-op-50/1485291850',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:42'),(207,47,'파반느','Pavane','song','느리고 우아한 옛 스페인 궁정 춤곡인 파반느를 바탕으로 작곡한 관현악곡. 몽환적이고 감미로운 선율로 큰 사랑을 받고 있다.','Op. 50',1887,5,6,'https://open.spotify.com/track/17pUZPj6AfqwNmWXP8qRnf','https://music.apple.com/us/album/pavane-op-50/339006385?i=339006539',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:43'),(208,47,'시칠리엔','Sicilienne','song','본래 <펠레아스와 멜리장드> 모음곡에 삽입된 곡으로, 시칠리아의 목가적인 춤곡풍 멜로디가 특징이다. 플루트나 첼로 독주로 자주 연주된다.','Op. 78',1893,6,4,'https://open.spotify.com/track/2nCFDJGlZVYcTbtgxgKSDH','https://music.apple.com/us/album/sicilienne-op-78/1766801138?i=1766801454',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:44'),(209,47,'가곡 <꿈을 꾼 후에>','Après un rêve','song','포레의 수많은 가곡(멜로디) 중 가장 유명한 곡. 꿈에서 연인과 재회한 기쁨과, 꿈에서 깬 뒤의 슬픔을 노래한 서정적인 작품이다.','Op. 7, No. 1',1877,5,3,'https://open.spotify.com/track/518hKWxnCK1L1fsYRl0OB5','https://music.apple.com/us/album/apr%C3%A8s-un-r%C3%AAve-op-7-no-1-arr-for-cello-and-piano/1009467298?i=1009467590',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:45'),(210,48,'오페라 <라 보엠>','Opera <La Bohème>','album','푸치니의 가장 큰 성공작 중 하나. 파리 뒷골목 가난한 예술가들(미미와 로돌포)의 가슴 아픈 사랑 이야기를 그린다. \'그대의 찬 손\', \'내 이름은 미미\' 등이 유명하다.',NULL,1896,10,110,'https://open.spotify.com/album/5b1dUxE8wWIGTyBX5h8CEp','https://music.apple.com/us/album/1920s-opera-legend/821306604',NULL,'2025-11-17 07:28:28','2025-11-18 07:40:04'),(211,48,'오페라 <투란도트> 중 \"공주는 잠 못 이루고\"','\"Nessun Dorma\" (from Opera <Turandot>)','song','푸치니의 미완성 유작 <투란도트>에 나오는 아리아. 칼라프 왕자가 공주의 수수께끼를 풀고 부르는 승리의 노래로, \'빈체로(Vincerò, 승리하리라)\' 부분이 압권이다.',NULL,1924,9,3,'https://open.spotify.com/track/03swCbYTa7qbATzbQcVGpv','https://music.apple.com/us/album/turandot-act-1-signore-ascolta-li%C3%B9/890296872?i=890299996',NULL,'2025-11-17 07:28:28','2025-11-18 07:40:06'),(212,48,'오페라 <토스카>','Opera <Tosca>','album','가수 토스카와 그녀의 연인 카바라도시, 그리고 이들을 파멸로 이끄는 경시총감 스카르피아의 비극을 그린 오페라. \'별은 빛나건만\', \'노래에 살고 사랑에 살고\'가 유명하다.',NULL,1900,10,120,'https://open.spotify.com/album/7jJ69AFSMTAQavq64DxYll','https://music.apple.com/us/album/1920s-opera-legend/821306604',NULL,'2025-11-17 07:28:28','2025-11-18 07:40:08'),(213,48,'오페라 <나비부인>','Opera <Madama Butterfly>','album','일본 나가사키를 배경으로, 미국 해군 장교 핑커톤에게 버림받은 게이샤 초초상의 비극적인 사랑을 그린다. \'어떤 개인 날\'이 유명하다.',NULL,1904,10,140,'https://open.spotify.com/album/23W9Axn8o18Lyz7twID47Q','https://music.apple.com/us/album/solfeggio-piano-639hz/1656197284',NULL,'2025-11-17 07:28:28','2025-11-18 07:40:10'),(214,48,'오페라 <잔니 스키키> 중 \"오 사랑하는 나의 아버지\"','\"O mio babbino caro\" (from Opera <Gianni Schicchi>)','song','푸치니의 유일한 희극 오페라 <잔니 스키키>에 나오는 아리아. 아버지를 설득해 사랑하는 사람과 결혼하게 해달라고 조르는 딸 라우레타의 노래이다.',NULL,1918,7,3,'https://open.spotify.com/track/1utyEW4Qf1F5jeqhJSLT6g','https://music.apple.com/us/album/a-room-with-a-view-gianni-schicci-o-mio-babbino-caro-puccini/336959500?i=336959552',NULL,'2025-11-17 07:28:28','2025-11-18 07:40:12'),(215,49,'교향곡 2번 C단조 \"부활\"','Symphony No. 2 in C minor \"Resurrection\"','album','말러의 교향곡 중 가장 인기가 높은 곡 중 하나. 거대한 규모와 \'죽음과 부활\'이라는 철학적 주제를 다루며, 5악장에서 합창이 등장한다.',NULL,1894,10,85,'https://open.spotify.com/album/4UjX26dOuRDnQ6Gm1Ly5lL','https://music.apple.com/us/album/mahler-symphony-no-2-in-c-minor-resurrection/1724246458',NULL,'2025-11-17 07:28:28','2025-11-18 07:40:14'),(216,49,'교향곡 5번 C#단조','Symphony No. 5 in C# minor','album','장례 행진곡풍의 1악장으로 시작하여 환희의 피날레로 끝나는 교향곡. 특히 현악기와 하프만으로 연주되는 4악장 \'아다지에토(Adagietto)\'가 매우 유명하다.',NULL,1902,10,70,'https://open.spotify.com/album/0YoGfbTUjWkljxkIEVqg7H','https://music.apple.com/us/album/mahler-symphony-no-5/1727068880',NULL,'2025-11-17 07:28:28','2025-11-18 07:40:16'),(217,49,'교향곡 1번 D장조 \"거인\"','Symphony No. 1 in D major \"Titan\"','album','말러가 20대에 작곡한 첫 교향곡. 자연의 소리와 민요풍의 선율, 장례 행진곡 등이 혼합된 청년 말러의 야심작이다.',NULL,1888,9,55,'https://open.spotify.com/album/30NSVil1gtWgjsRkMSXV4g','https://music.apple.com/us/album/mahler-symphony-no-1-in-d-major-live/1080375453',NULL,'2025-11-17 07:28:28','2025-11-18 07:40:18'),(218,49,'교향곡 8번 E♭장조 \"천인 교향곡\"','Symphony No. 8 in E♭ major \"Symphony of a Thousand\"','album','연주에 1000명에 가까운 인원(대규모 오케스트라, 8명의 독창, 3개의 합창단)이 필요하여 \'천인 교향곡\'이라 불린다. 말러의 작품 중 가장 긍정적인 메시지를 담고 있다.',NULL,1906,10,80,'https://open.spotify.com/album/2HkJe2nY1PQnc6hhb8e6XO',NULL,NULL,'2025-11-17 07:28:28','2025-11-18 07:40:20'),(219,49,'대지의 노래','Das Lied von der Erde','album','이태백(이백) 등의 중국 시를 바탕으로 한 6악장의 \'가곡 교향곡\'. 교향곡 9번에 대한 징크스로 \'교향곡 9번\'이라 부르지 않았다. 말러의 가장 염세적이고 심오한 걸작 중 하나이다.',NULL,1909,10,65,'https://open.spotify.com/album/1aDYZ8TScdkpM0zVy49kKf','https://music.apple.com/us/album/mahler-das-lied-von-der-erde/1452204299',NULL,'2025-11-17 07:28:28','2025-11-18 07:40:22'),(220,50,'달빛 (베르가마스크 모음곡 중)','Clair de lune (from Suite bergamasque)','song','<베르가마스크 모음곡> 4곡 중 3번째 곡. 드뷔시의 모든 피아노곡 중 가장 유명하며, \'인상주의\' 음악의 대명사처럼 쓰이는 몽환적이고 아름다운 곡이다.','L. 75',1890,6,5,'https://open.spotify.com/track/1cmigB9I6IRpFqjIbzvSQB','https://music.apple.com/us/album/suite-bergamesque-l-75-iii-clair-de-lune/1764844357?i=1764844467',NULL,'2025-11-17 07:28:28','2025-11-18 07:40:24'),(221,50,'목신의 오후에의 전주곡','Prélude à l\'après-midi d\'un faune','song','말라르메의 상징주의 시를 바탕으로, 나른한 오후 목신의 꿈을 그린 교향시. \'인상주의 음악\'의 시작을 알린 기념비적인 작품이다.','L. 86',1894,9,10,'https://open.spotify.com/track/4eY2bxGE2ykwefZ3adjetE','https://music.apple.com/us/album/prelude-a-lapres-midi-dun-faune-l-86/1394216776?i=1394218629',NULL,'2025-11-17 07:28:28','2025-11-18 07:40:26'),(222,50,'바다 (3개의 교향적 스케치)','La mer, trois esquisses symphoniques','album','바다의 시시각각 변하는 풍경과 색채를 3악장(\'바다 위의 새벽에서 정오까지\' 등)에 걸쳐 묘사한, 드뷔시 관현악곡의 최고 걸작이다.','L. 109',1905,9,24,'https://open.spotify.com/album/0gXQvx55A1qDtDAZnpRIAq','https://music.apple.com/us/album/clair-de-lune-single/444967120',NULL,'2025-11-17 07:28:28','2025-11-18 07:40:28'),(223,50,'어린이 차지 (모음곡)','Children\'s Corner','album','자신의 딸 엠마를 위해 작곡한 6개의 피아노 소품 모음곡. \'골리워그의 케이크워크\' 악장이 유명하며, 바그너의 \'트리스탄 화음\'을 장난스럽게 인용했다.','L. 113',1908,7,18,'https://open.spotify.com/album/12wFb2Hh1SclBx0V9sLASp','https://music.apple.com/us/album/clair-de-lune-single/444967120',NULL,'2025-11-17 07:28:28','2025-11-18 07:40:30'),(224,50,'아라베스크 1번','Arabesque No. 1','song','2개의 아라베스크(L. 66) 중 첫 번째 곡. 드뷔시 초기 스타일의 우아하고 서정적인 선율이 특징인 피아노 소품이다.','L. 66',1888,6,4,'https://open.spotify.com/track/53PgJq41PXYlgzDBsIhC4r','https://music.apple.com/us/album/deux-arabesques-l-66-no-1-in-e-major-andantino-con-moto/1764844357?i=1764844466',NULL,'2025-11-17 07:28:28','2025-11-18 07:40:32'),(225,51,'피아노 협주곡 2번 C단조','Piano Concerto No. 2 in C minor','album','라흐마니노프의 최고 걸작이자 낭만주의 피아노 협주곡의 대명사. 깊은 우수와 폭발적인 열정, 감미로운 멜로디로 전 세계적인 사랑을 받고 있다.','Op. 18',1901,10,34,'https://open.spotify.com/album/6DxaPwCdGQ6Eu8xkWm4swA','https://music.apple.com/us/album/rachmaninoff-piano-concerto-no-2-in-c-minor-op-18-liszt/1170126265',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:46'),(226,51,'피아노 협주곡 3번 D단조','Piano Concerto No. 3 in D minor','album','피아니스트에게 극한의 기교와 지구력을 요구하는, 가장 어렵기로 소문난 협주곡 중 하나. 영화 <샤인>을 통해 대중적으로도 유명해졌다.','Op. 30',1909,10,40,'https://open.spotify.com/album/4no6O3D7VpSoyf6mzM1FZJ','https://music.apple.com/us/album/rachmaninoff-piano-concerto-no-3-in-d-minor-op-30-ii/1806547683',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:48'),(227,51,'파가니니 주제에 의한 광시곡','Rhapsody on a Theme of Paganini','album','파가니니의 카프리스 24번 주제를 바탕으로 작곡한 피아노와 오케스트라를 위한 변주곡. 특히 18번 변주(주제를 뒤집은 멜로디)가 매우 유명하다.','Op. 43',1934,10,24,'https://open.spotify.com/album/2aRSulmVokzkDQvJ6lmlcv','https://music.apple.com/us/album/rachmaninoff-rhapsody-on-a-theme-of-paganini-op-43/1678110322',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:49'),(228,51,'보칼리제','Vocalise','song','14개의 가곡집(Op. 34) 중 마지막 곡. 가사 없이 모음(아)으로만 부르는 슬프고 아름다운 선율로, 다양한 악기로 편곡되어 연주된다.','Op. 34, No. 14',1915,6,6,'https://open.spotify.com/track/0JfRiRNWRSoomPMSvPlRGs','https://music.apple.com/us/album/14-romances-op-34-no-14-vocalise/339006385?i=339006701',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:50'),(229,51,'전주곡 C#단조 \"모스크바의 종\"','Prelude in C# minor \"The Bells of Moscow\"','song','23세에 작곡하여 세계적인 명성을 안겨준 피아노 소품. 크렘린의 종소리를 연상시키는 장엄하고 어두운 화음이 특징이다.','Op. 3, No. 2',1892,8,4,'https://open.spotify.com/track/5GqPJoNDOSldbyrC08rnwh','https://music.apple.com/us/album/morceaux-de-fantaisie-op-3-no-2-pr%C3%A9lude-in-c-sharp-minor/1440566024?i=1440566037',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:51'),(230,52,'볼레로','Boléro','song','단 하나의 리듬과 두 개의 멜로디가 악기 편성을 바꿔가며 15분간 반복되다가 장엄한 피날레로 끝나는, 라벨의 가장 유명한 실험적 관현악곡이다.','M. 81',1928,7,15,'https://open.spotify.com/track/6B1mmlGh7xnFAeSUHHBGiy','https://music.apple.com/us/album/bol%C3%A9ro-m-81/881327340?i=881327381',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:52'),(231,52,'죽은 왕녀를 위한 파반느','Pavane pour une infante défunte','song','옛 스페인 궁정에서 어린 왕녀가 추었을 법한 춤곡을 상상하며 쓴 피아노곡(이후 관현악 편곡). 고풍스럽고 우아한 멜로디로 큰 사랑을 받고 있다.','M. 19',1899,6,6,'https://open.spotify.com/track/4m8kcJtYjwUeHwfQfP3Grz','https://music.apple.com/us/album/pavane-pour-une-infante-d%C3%A9funte-m-19/691711986?i=691712202',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:53'),(232,52,'물의 유희','Jeux d\'eau','song','물이 뿜어져 나오고 반짝이는 모습을 묘사한 피아노곡. 드뷔시보다 앞서 \'물\'을 소재로 인상주의 피아노 기법의 시작을 알린 혁신적인 작품이다.','M. 30',1901,9,5,'https://open.spotify.com/track/5ecYIBzLGMydPa5IFWq4AT','https://music.apple.com/us/album/jeux-deau-m-30/1068269518?i=1068269724',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:54'),(233,52,'피아노 협주곡 G장조','Piano Concerto in G major','album','라벨이 미국 여행에서 접한 재즈의 영향을 받아 작곡한 경쾌하고 재치 넘치는 협주곡. 2악장 아다지오의 아름다운 피아노 솔로가 유명하다.','M. 83',1931,9,22,'https://open.spotify.com/album/217TRsYD0YRrUhEsK5qNa0','https://music.apple.com/us/album/ravel-the-complete-solo-piano-works/1779059876',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:56'),(234,52,'발레 <다프니스와 클로에> 모음곡 2번','Ballet <Daphnis et Chloé> Suite No. 2','album','라벨의 가장 거대하고 화려한 발레 음악. 그 중 2번 모음곡(\'새벽\', \'판토마임\', \'전체 춤\')은 그의 관현악법의 정수를 보여준다.','M. 57b',1913,9,17,'https://open.spotify.com/album/4CsiXVG7G9QbmVB0LH0dWf','https://music.apple.com/us/album/ravel-bol%C3%A9ro-m-81-daphnis-et-chlo%C3%A9-suite-no-2-m-57b/1617192816',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:57'),(235,53,'오페라 <마탄의 사수> 서곡','Opera <Der Freischütz> Overture','song','독일 낭만 오페라의 시대를 연 <마탄의 사수>의 서곡. 숲의 신비로움, 악마의 음산함, 승리의 환희 등 오페라의 핵심 주제가 압축되어 있다.','J. 277',1821,8,10,'https://open.spotify.com/track/4AeeJ33Gwpix6EGbToBb5d','https://music.apple.com/us/album/der-freischutz-j-277-overture/343220220?i=343220227',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:58'),(236,53,'무도에의 권유','Invitation to the Dance','song','무도회에서 신사가 숙녀에게 춤을 권하고 함께 왈츠를 추는 장면을 묘사한 피아노곡. 낭만주의 \'왈츠\'의 시초가 된 작품이다.','Op. 65, J. 260',1819,7,9,'https://open.spotify.com/track/3Kmdp14efUfG09325mJ6Zp','https://music.apple.com/us/album/aufforderung-zum-tanze-op-65-j-260/1452387697?i=1452387714',NULL,'2025-11-17 07:28:28','2025-11-18 12:04:59'),(237,53,'클라리넷 협주곡 1번 F단조','Clarinet Concerto No. 1 in F minor','album','클라리넷의 어두운 음색과 화려한 기교를 극대화한 협주곡. 모차르트 협주곡과 함께 클라리넷 연주자들의 중요 레퍼토리이다.','Op. 73, J. 114',1811,9,21,'https://open.spotify.com/album/5GKem0xDHBff2cuAa2rZzk','https://music.apple.com/us/album/carl-maria-von-weber-clarinet-concerto-no-1-in-f-minor/1320034416',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:00'),(238,54,'라데츠키 행진곡','Radetzky March','song','요한 슈트라우스 1세의 가장 유명한 작품. 빈 신년 음악회의 마지막을 장식하며, 관객들이 박자에 맞춰 박수를 치는 전통으로 유명하다.','Op. 228',1848,5,3,'https://open.spotify.com/track/406kpvGQqOO5tRL4QrwggB','https://music.apple.com/us/album/radetzky-marsch-op-228/1181180643?i=1181181169',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:01'),(239,54,'로렐라이 라인강의 메아리 (왈츠)','Loreley-Rhein-Klänge (Waltz)','song','아들(2세)의 <아름답고 푸른 도나우>와 함께, 아버지 슈트라우스의 왈츠 중 가장 서정적이고 아름다운 작품으로 꼽힌다.','Op. 154',1843,6,9,'https://open.spotify.com/track/5M7aY8ZtUeEzKlRTLp7OBX','https://music.apple.com/us/album/radetzky-march-op-228/339006385?i=339006606',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:02'),(240,55,'발레 <지젤>','Ballet <Giselle>','album','낭만 발레(백색 발레)의 최고 걸작 중 하나. 순박한 시골 처녀 지젤이 귀족의 배신으로 죽어 유령(윌리)이 되는 비극을 그린다.',NULL,1841,8,120,'https://open.spotify.com/album/60ZOboLja5O7zBgNPoJE0e','https://music.apple.com/us/album/delibes-adam-ballet-favourites/250426150',NULL,'2025-11-17 07:28:28','2025-11-18 07:41:07'),(241,55,'오 홀리 나잇 (성탄절 칸티크)','Cantique de Noël (\"O Holy Night\")','song','전 세계에서 가장 널리 불리는 크리스마스 캐럴 중 하나. \'오 홀리 나잇\'이라는 제목으로 더 유명하다.',NULL,1847,4,4,'https://open.spotify.com/track/0WaJ21mqQwv9vI2xiM0YLm','https://music.apple.com/us/album/cantique-de-no%C3%ABl-o-holy-night/161522737?i=161523050',NULL,'2025-11-17 07:28:28','2025-11-18 07:41:10'),(242,56,'아베 마리아 (바흐-구노)','Ave Maria (Bach-Gounod)','song','구노가 바흐의 <평균율 클라비어곡집> 1권 1번 전주곡(C장조)의 화성 위에 라틴어 기도문 멜로디를 붙인 편곡 작품이다.','CG 89a',1859,4,3,'https://open.spotify.com/track/5Xm9aPiFg5PCgsRewbMKk5','https://music.apple.com/us/album/ave-maria-cg-89a-arr-emanuele-vianelli-live-from-duomo/1507709297?i=1507709311',NULL,'2025-11-17 07:28:28','2025-11-18 07:41:12'),(243,56,'오페라 <파우스트>','Opera <Faust>','album','구노의 대표작. 괴테의 <파우스트>를 원작으로, 악마 메피스토펠레스와 영혼을 건 계약을 한 파우스트의 이야기를 다룬다.',NULL,1859,10,200,'https://open.spotify.com/album/2TAI2w0u49GhuJkpvyfUYw','https://music.apple.com/us/album/gounod-scenes-from-faust/303623326',NULL,'2025-11-17 07:28:28','2025-11-18 07:41:14'),(244,56,'오페라 <로미오와 줄리엣>','Opera <Roméo et Juliette>','album','셰익스피어의 동명 비극을 원작으로 한 5막 오페라. 4개의 사랑의 2중창과 \'줄리엣의 왈츠\' 아리아가 유명하다.',NULL,1867,9,180,'https://open.spotify.com/album/0lYRMIrUgWIepVnxeP1HZr','https://music.apple.com/kr/album/gounod-rom%C3%A9o-et-juliette/347499944?l=en-GB',NULL,'2025-11-17 07:28:28','2025-11-18 07:54:20'),(245,57,'<지옥의 오르페> 서곡 (캉캉)','<Orpheus in the Underworld> Overture (Can-can)','song','오펜바흐의 가장 유명한 오페레타(희극 오페라). 그리스 신화를 풍자했으며, 서곡의 마지막에 나오는 \'캉캉(Can-can)\' 춤곡으로 불멸의 명성을 얻었다.',NULL,1858,7,10,'https://open.spotify.com/track/3VU9LCIbccy3dgtJhkpyu1','https://music.apple.com/us/album/robin-hood-men-in-tights-orpheus-in-the-underworld/337544703?i=337544917',NULL,'2025-11-17 07:28:28','2025-11-18 07:41:18'),(246,57,'<호프만의 이야기> 중 \"뱃노래\"','Barcarolle (from <The Tales of Hoffmann>)','song','오펜바흐의 유일한 그랜드 오페라이자 유작. 3막에 나오는 이중창 \'뱃노래(Barcarolle)\'는 환상적이고 아름다운 선율로 유명하다.',NULL,1881,5,4,'https://open.spotify.com/track/4XG6P1pnjB8epm9O0MKaWG','https://music.apple.com/us/album/barcarolle-from-the-tales-of-hoffmann/1554838663?i=1554838667',NULL,'2025-11-17 07:28:28','2025-11-18 07:41:20'),(247,58,'<나의 조국> 중 \"몰다우\"','Má Vlast (\"Vltava\")','song','체코의 역사와 자연을 그린 6곡의 교향시 모음곡 <나의 조국> 중 2번째 곡. 체코의 젖줄인 몰다우(블타바)강의 흐름을 묘사한, 스메타나의 가장 유명한 곡이다.','JB 1:112/2',1874,8,12,'https://open.spotify.com/track/66akHalkLn6pLcHfsBATEN','https://music.apple.com/us/album/m%C3%A1-vlast-jb1-112-2-vltava/1452677075?i=1452677090',NULL,'2025-11-17 07:28:28','2025-11-18 07:41:22'),(248,58,'오페라 <팔려간 신부> 서곡','Opera <The Bartered Bride> Overture','song','체코 국민 오페라의 대표작. 시골 남녀의 사랑 이야기를 유쾌한 춤곡과 함께 그렸다. 특히 서곡은 현악기들이 질주하는 듯한 빠른 패시지로 유명하다.','JB 1:100',1866,8,7,'https://open.spotify.com/track/027t0M7awc3FudWYA4BPgg','https://music.apple.com/us/album/the-bartered-bride-entry-of-the-comediants/320934448?i=320934593',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:04'),(249,59,'<이고르 공> 중 \"폴로베츠인의 춤\"','Polovtsian Dances (from <Prince Igor>)','song','보로딘의 미완성 오페라 <이고르 공> 2막에 나오는 발레 음악. 이국적이고 격렬한 리듬과 매혹적인 선율로 단독으로 자주 연주된다.',NULL,1887,8,14,'https://open.spotify.com/track/7dlMTbloHegihfau1dF9mm','https://music.apple.com/us/album/polovtsian-dances-from-prince-igor/1452545987?i=1452546689',NULL,'2025-11-17 07:28:28','2025-11-18 07:41:26'),(250,59,'교향시 <중앙아시아의 초원에서>','Symphonic Poem <In the Steppes of Central Asia>','song','광활한 중앙아시아의 초원을 배경으로, 러시아의 선율과 동양의 선율이 만나는 모습을 그린 이국적인 교향시이다.',NULL,1880,7,8,'https://open.spotify.com/track/5JjcdzE3ZuFIyqrfWwRG1A',NULL,NULL,'2025-11-17 07:28:28','2025-11-18 07:41:28'),(251,59,'교향곡 2번 B단조','Symphony No. 2 in B minor','album','러시아의 영웅적인 서사시를 연상시키는 힘찬 에너지로 가득 찬, 보로딘의 대표적인 교향곡이다.',NULL,1876,9,28,'https://open.spotify.com/album/4mDA9Y6tsrORhdB5ZBpgCl','https://music.apple.com/us/album/borodin-symphony-no-2-in-b-minor-rimsky-korsakov-suite/260707506',NULL,'2025-11-17 07:28:28','2025-11-18 07:41:30'),(252,60,'동물의 사육제','The Carnival of the Animals','album','14개의 악장으로 사자, 백조, 수족관, 캥거루 등 다양한 동물을 유쾌하게 묘사한 관현악 모음곡. \'백조\' 악장이 특히 유명하다.','R. 125',1886,7,23,'https://open.spotify.com/album/4DRlCuB51rWJhnE1fDFDKC','https://music.apple.com/us/album/saint-sa%C3%ABns-the-carnival-of-the-animals-r-125-other-works/1489000142',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:05'),(253,60,'죽음의 무도','Danse Macabre','song','해골들이 무덤에서 나와 바이올린(죽음의 신)의 연주에 맞춰 춤을 춘다는 전설을 묘사한 교향시. 실로폰으로 뼈 부딪히는 소리를 묘사했다.','Op. 40',1874,8,7,'https://open.spotify.com/track/1IM8x4lxZVOOP9gpQD6c5s','https://music.apple.com/us/album/danse-macabre-op-40/1452505758?i=1452506045',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:06'),(254,60,'교향곡 3번 C단조 \"오르간\"','Symphony No. 3 in C minor \"Organ\"','album','생상스의 마지막 교향곡. 오케스트라에 오르간과 피아노(2대)를 결합하여 장엄하고 화려한 음향을 만들어낸 걸작이다.','Op. 78',1886,9,36,'https://open.spotify.com/album/2biqXEV4QnCBHgvmMlHowu','https://music.apple.com/us/album/camille-saint-saens-symphony-no-3-in-c-minor-op-78/381895196',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:07'),(255,60,'오페라 <삼손과 데릴라> 중 \"그대 음성에 내 마음 열리고\"','\"Mon cœur s\'ouvre à ta voix\" (from <Samson et Dalila>)','song','성서의 이야기를 다룬 오페라 <삼손과 데릴라> 2막에서, 데릴라가 삼손을 유혹하며 부르는 매혹적이고 관능적인 아리아이다.','Op. 47',1877,8,6,'https://open.spotify.com/track/2b1SGrH71dsb8j8Phc0jZq','https://music.apple.com/us/album/samson-et-dalilah-op-47-act-ii-mon-coeur-souvre-a-ta-voix/334895831?i=334895911',NULL,'2025-11-17 07:28:28','2025-11-18 07:41:38'),(256,60,'첼로 협주곡 1번 A단조','Cello Concerto No. 1 in A minor','album','단악장 형식으로, 3개의 부분이 중단 없이 연주되는 독특한 구성의 첼로 협주곡. 첼로의 기교와 서정성을 잘 보여준다.','Op. 33',1872,9,20,'https://open.spotify.com/album/6GlzctZ6JJaopskEr7yQ9t','https://music.apple.com/us/album/saint-sa%C3%ABns-cello-concerto-no-1-op-33-delius-cello-concerto/1790490245',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:08'),(257,61,'바이올린 협주곡 1번 G단조','Violin Concerto No. 1 in G minor','album','브루흐의 모든 작품 중 압도적으로 유명한 곡. 낭만주의 바이올린 협주곡의 최고 걸작 중 하나로, 멘델스존, 브람스의 협주곡과 함께 꼽힌다.','Op. 26',1866,10,25,'https://open.spotify.com/album/0qVXQcxHzXAeUk1c0TFy4o','https://music.apple.com/us/album/bruch-violin-concerto-no-1-in-g-minor-op-26-mozart/463324465',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:09'),(258,61,'스코틀랜드 환상곡','Scottish Fantasy','album','스코틀랜드 민요 선율을 주제로 한 4악장의 바이올린과 오케스트라를 위한 환상곡. 바이올린 협주곡 못지않게 사랑받는 작품이다.','Op. 46',1880,9,30,'https://open.spotify.com/album/3kTLT7uy4hNG2gguytnYGP','https://music.apple.com/us/album/bruch-scottish-fantasy-op-46-violin-concerto-no-1-in/1382362770',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:10'),(259,61,'콜 니드라이','Kol Nidrei','song','유대교의 속죄일(욤 키푸르)에 불리는 성가 \'콜 니드라이\'의 선율을 바탕으로 작곡한 첼로와 오케스트라를 위한 명상적인 소품이다.','Op. 47',1881,7,10,'https://open.spotify.com/track/0EW2NiwS4TIrQIhteLW8nG','https://music.apple.com/us/album/kol-nidrei-op-47/1452581862?i=1452582224',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:12'),(260,62,'<타이스>의 명상곡','Méditation (from <Thaïs>)','song','오페라 <타이스> 2막에 나오는 간주곡. 수도사 아타나엘에 의해 개심한 무희 타이스의 명상을 그리는, 바이올린 독주의 경건하고 아름다운 곡이다.',NULL,1894,6,5,'https://open.spotify.com/track/0XfFRLi9G87t57kqZAzeef','https://music.apple.com/us/album/angie-tha%C3%AFs-meditation-massenet/337777797?i=337777914',NULL,'2025-11-17 07:28:28','2025-11-18 07:41:48'),(261,62,'오페라 <베르테르>','Opera <Werther>','album','괴테의 <젊은 베르테르의 슬픔>을 원작으로 한 프랑스 서정 오페라. 주인공 베르테르의 비극적 사랑을 섬세하게 그렸다.',NULL,1892,9,120,'https://open.spotify.com/album/7M035YhRAQcN5emBFub0BN',NULL,NULL,'2025-11-17 07:28:28','2025-11-18 07:41:50'),(262,63,'치고이너바이젠 (집시의 노래)','Zigeunerweisen','song','사라사테의 대표작. 헝가리 집시(롬족) 음악의 애수 어린 선율(라산)과 점차 격렬해지는 춤곡(프리스카)으로 구성된 바이올린 기교의 극치이다.','Op. 20',1878,10,9,'https://open.spotify.com/track/1Owa3Ic2vpcfRCLSqa73NZ','https://music.apple.com/us/album/zigeunerweisen-op-20/968876474?i=968876485',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:13'),(263,63,'카르멘 환상곡','Carmen Fantasy','song','비제의 오페라 <카르멘>에 나오는 유명한 멜로디(하바네라, 세기디야 등)를 바탕으로, 바이올린의 화려한 기교를 더해 만든 환상곡이다.','Op. 25',1883,10,13,'https://open.spotify.com/track/0gdeydNMMyOuAJm5pJW2ZN','https://music.apple.com/us/album/carmen-fantasy-op-25-after-bizet-ii-lento-assai/1636275777?i=1636276042',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:14'),(264,63,'서주와 타란텔라','Introduction and Tarantella','song','느린 서주에 이어 이탈리아의 격렬한 춤곡인 타란텔라가 이어지는, 바이올린의 빠른 기교를 과시하는 화려한 소품이다.','Op. 43',1899,9,5,'https://open.spotify.com/track/7tD3XCD7gCm5BanIQmTueM','https://music.apple.com/us/album/introduction-and-tarantella-op-43-version-for-violin/719212578?i=719212952',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:15'),(265,64,'위풍당당 행진곡 1번','Pomp and Circumstance March No. 1','song','엘가의 5개의 <위풍당당 행진곡> 중 1번. 중간 부분의 장엄한 선율(Land of Hope and Glory)은 영국의 \'제2 국가\'로 불릴 만큼 유명하다.','Op. 39, No. 1',1901,6,6,'https://open.spotify.com/track/0GXJ6r9aHj0Lx6ADBiCj9E',NULL,NULL,'2025-11-17 07:28:28','2025-11-18 12:05:16'),(266,64,'첼로 협주곡 E단조','Cello Concerto in E minor','album','엘가의 마지막 대작. 1차 세계대전 이후의 상실감과 비애가 담긴 내성적이고 처연한 작품. 첼리스트 자클린 뒤 프레의 연주로 20세기에 재조명되었다.','Op. 85',1919,10,30,'https://open.spotify.com/album/5GRQgouohxuDxhd6ujam3d','https://music.apple.com/us/album/elgar-cello-concerto-op-85-tchaikovsky-variations-on/683126150',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:17'),(267,64,'수수께끼 변주곡','Enigma Variations','album','14개의 변주곡이 각각 엘가 주변의 친구와 지인들을 묘사하고 있는 독특한 작품. \'수수께끼\'의 주제는 아직 풀리지 않았다. 9번 변주 \'님로드(Nimrod)\'가 매우 유명하다.','Op. 36',1899,8,32,'https://open.spotify.com/album/6cgc02t4kZ33xc1tNY4Zjh','https://music.apple.com/us/album/enigma-variations-op-36-ix-nimrod-arr-for-piano-by/1623117518',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:19'),(268,64,'사랑의 인사','Salut d\'Amour','song','엘가가 아내 캐롤라인 앨리스 로버츠와의 약혼을 기념하며 작곡한 감미로운 바이올린(또는 첼로) 소품. 대중적으로 매우 유명하다.','Op. 12',1888,4,3,'https://open.spotify.com/track/265QUGqbU9jtBNtFBKKRqO',NULL,NULL,'2025-11-17 07:28:28','2025-11-18 12:05:20'),(269,65,'오페라 <팔리아치>','Opera <Pagliacci>','album','레온카발로의 유일한 성공작이자 \'베리스모(사실주의)\' 오페라의 대표작. 아내의 불륜을 알게 된 광대가 연극 무대 위에서 아내를 살해한다는 충격적인 내용이다.',NULL,1892,10,75,'https://open.spotify.com/album/5s02EcsuAdGevn8yEBSQrN','https://music.apple.com/us/album/opera-pagliacci/410851003',NULL,'2025-11-17 07:28:28','2025-11-18 07:42:07'),(270,65,'\"의상을 입어라\" (오페라 <팔리아치>)','\"Vesti la giubba\" (from <Pagliacci>)','song','오페라 <팔리아치> 1막의 마지막, 아내의 배신을 알고도 무대에 올라야 하는 광대 카니오가 절규하며 부르는 아리아. 테너의 가장 유명한 아리아 중 하나이다.',NULL,1892,9,3,'https://open.spotify.com/track/5P7GEvTQWi7RmCvl3BBszV','https://music.apple.com/us/album/pagliacci-act-i-intermezzo/1462854667?i=1462854716',NULL,'2025-11-17 07:28:28','2025-11-18 07:42:09'),(271,65,'마티나타 (아침의 노래)','Mattinata','song','레온카발로가 작곡한 이탈리아 가곡(칸초네). 아침의 찬란함을 노래하는 밝고 화려한 선율로 테너들이 즐겨 부른다.',NULL,1904,5,2,'https://open.spotify.com/track/4z2WTEwX66niZjo7v4SFj2','https://music.apple.com/us/album/leoncavallo-mattinata/691648687?i=691650196',NULL,'2025-11-17 07:28:28','2025-11-18 07:42:11'),(272,66,'<스페인 모음곡> 중 \"아스투리아스 (전설)\"','\"Asturias (Leyenda)\" (from Suite Española No. 1)','song','원래 피아노곡이지만, 스페인 기타의 플라멩코 주법을 완벽하게 묘사하여 오늘날 기타 독주곡으로 더 유명해졌다.','Op. 47, No. 5',1886,8,6,'https://open.spotify.com/track/5krDbX5E14dzHESiVZURmj','https://music.apple.com/us/album/suite-espa%C3%B1ola-no-1-op-47-no-5-asturias-arr-j-williams/161725510?i=161725956',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:21'),(273,66,'이베리아 (피아노 모음곡)','Iberia (Suite for piano)','album','알베니스의 최고 걸작이자, 피아노 음악 역사상 가장 난해한 작품 중 하나. 스페인 각 지방의 인상과 정서를 12곡에 담아냈다.','B. 47',1908,10,80,'https://open.spotify.com/album/519lH95tFGWI1UsP6LnXIW','https://music.apple.com/us/album/alb%C3%A9niz-iberia-b-47/1567677930',NULL,'2025-11-17 07:28:28','2025-11-18 07:42:15'),(274,66,'땅고 D장조','Tango in D major','song','<스페인(España)> 모음곡 6곡 중 2번째 곡. 이국적이고 매혹적인 선율로 인해 다양한 악기로 편곡되어 사랑받는 소품이다.','Op. 165, No. 2',1890,5,3,'https://open.spotify.com/track/2U9XJ3YPKRzTPl85EMXti4','https://music.apple.com/us/album/tango-in-d-major-op-165-no-2/1027145565?i=1027146326',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:22'),(275,67,'오페라 <카발레리아 루스티카나>','Opera <Cavalleria Rusticana>','album','단막 오페라 공모전에서 1위를 차지하며 \'베리스모(사실주의)\' 오페라의 시대를 연 작품. 시칠리아를 배경으로 한 평범한 사람들의 치정과 복수극을 그린다.',NULL,1890,10,75,'https://open.spotify.com/album/7nRqbLWqlX4FJpG9YYDsD9','https://music.apple.com/us/album/the-last-dance/258656661',NULL,'2025-11-17 07:28:28','2025-11-18 07:42:19'),(276,67,'\"간주곡\" (오페라 <카발레리아 루스티카나>)','Intermezzo (from <Cavalleria Rusticana>)','song','오페라 중간에 연주되는 비극적이고 아름다운 간주곡. 오페라 자체보다 더 유명해져, 영화 <대부 3> 등 수많은 매체에 삽입되었다.',NULL,1890,5,4,'https://open.spotify.com/track/57z75jRWZhZF8pPk9HLR9n','https://music.apple.com/us/album/intermezzo-from-cavalleria-rusticana-arr-for-cello/1492002990?i=1492003189',NULL,'2025-11-17 07:28:28','2025-11-18 07:42:21'),(277,68,'교향시 <핀란디아>','Symphonic Poem <Finlandia>','song','러시아의 압제에 저항하는 핀란드 국민들의 애국심을 고취시킨 교향시. 중간 부분의 비장하고 아름다운 찬가는 핀란드의 실질적인 국가로 불린다.','Op. 26',1899,8,8,'https://open.spotify.com/track/6HknRM996YMa7VSBFYlnPJ','https://music.apple.com/us/album/finlandia-op-26/339006385?i=339006526',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:23'),(278,68,'바이올린 협주곡 D단조','Violin Concerto in D minor','song','20세기에 작곡된 바이올린 협주곡 중 최고 걸작 중 하나. 북유럽의 차갑고 장엄한 자연과 바이올린의 극한의 기교가 결합되어 있다.','Op. 47',1904,10,32,'https://open.spotify.com/track/7fAFoIehXy4Aou20Z63k8y','https://music.apple.com/us/album/violin-concerto-in-d-minor-op-47-allegro-moderato/458436919?i=458436976',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:24'),(279,68,'슬픈 왈츠','Valse Triste','song','희곡 <쿠올레마>의 부수 음악 중 하나. 죽음을 앞둔 어머니가 유령들과 춤을 춘다는 환영을 묘사한, 으스스하면서도 아름다운 왈츠이다.','Op. 44, No. 1',1903,5,5,'https://open.spotify.com/track/7Br8VQqZs2KJESjzCTfezZ','https://music.apple.com/us/album/valse-triste-op-44-no-1/1524481917?i=1524482211',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:25'),(280,68,'교향곡 2번 D장조','Symphony No. 2 in D major','album','시벨리우스의 교향곡 중 가장 인기가 많고 낭만적인 작품. 북유럽의 자연을 묘사하는 듯한 선율로 시작해, 장엄하고 영웅적인 피날레로 끝난다.','Op. 43',1902,9,44,'https://open.spotify.com/album/3wzRc2a6xrHVBUEmZ6Rvnr','https://music.apple.com/us/album/sibelius-symphony-no-2-in-d-major-op-43-symphony-no/459735023',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:27'),(281,69,'탈리스 주제에 의한 환상곡','Fantasia on a Theme by Thomas Tallis','song','16세기 작곡가 토마스 탈리스의 성가 선율을 바탕으로, 두 개의 현악 오케스트라와 현악 4중주가 신비로운 음향을 만들어내는 걸작이다.',NULL,1910,8,16,'https://open.spotify.com/track/04daeztQJg7lyDDAHJ70rT','https://music.apple.com/us/album/ralph-vaughan-williams-fantasia-on-a-theme-by-thomas-tallis/1108437751?i=1108438173',NULL,'2025-11-17 07:28:28','2025-11-18 07:42:31'),(282,69,'푸른 옷소매 환상곡','Fantasia on Greensleeves','song','영국의 유명한 민요 \'푸른 옷소매(Greensleeves)\' 선율을 바탕으로 한 관현악 환상곡. 서정적이고 목가적인 분위기가 특징이다.',NULL,1934,5,5,'https://open.spotify.com/track/7oHv66EbTrD3zQziGFWxtH','https://music.apple.com/us/album/fantasia-on-greensleeves/693565303?i=693565378',NULL,'2025-11-17 07:28:28','2025-11-18 07:42:33'),(283,69,'종달새의 비상','The Lark Ascending','song','조지 메러디스의 시에서 영감을 받아 작곡한, 바이올린 독주와 오케스트라를 위한 로망스. 하늘로 날아오르는 종달새의 모습을 서정적으로 묘사했다.',NULL,1914,8,15,'https://open.spotify.com/track/1TWh98jsdVDG7Uvdx2BxG3','https://music.apple.com/us/album/the-lark-ascending/1452643335?i=1452643454',NULL,'2025-11-17 07:28:28','2025-11-18 07:42:35'),(284,70,'모음곡 <행성>','Suite <The Planets>','album','7개의 행성(화성, 금성, 수성, 목성, 토성, 천왕성, 해왕성)의 점성술적 성격을 묘사한 7악장의 관현악 모음곡. \'화성(Mars)\'과 \'목성(Jupiter)\'이 특히 유명하다.','Op. 32',1916,9,50,'https://open.spotify.com/album/0V1QCzzE0FtuYsStSaYNFc','https://music.apple.com/us/album/holst-the-planets-op-32/1489436207',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:28'),(285,70,'세인트 폴 모음곡','St. Paul\'s Suite','album','홀스트가 교사로 재직하던 세인트 폴 여학교의 학생 오케스트라를 위해 작곡한 현악 합주곡. 영국 민요 \'그린슬리브스\' 선율이 4악장에 등장한다.','Op. 29, No. 2',1913,7,12,'https://open.spotify.com/album/15h9xCueNKFaE9bCx6oNUR','https://music.apple.com/us/album/holst-hammersmith-op-52-a-moorside-suite-suites-for/995331649',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:29'),(286,71,'정화된 밤','Verklärte Nacht','album','쇤베르크의 초기 후기 낭만주의 걸작. 현악 6중주(이후 현악 오케스트라 편곡)를 위한 교향시로, 바그너풍의 격렬한 반음계와 감정 표현이 특징이다.','Op. 4',1899,9,30,'https://open.spotify.com/album/0YHrFLfeGjkhEhYSCimYdB','https://music.apple.com/us/album/schoenberg-transfigured-night-op-4-ep/1835914599',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:30'),(287,71,'달에 홀린 피에로','Pierrot Lunaire','album','쇤베르크의 \'무조음악\' 시대를 대표하는 작품. \'슈프레히슈티메(말하는 듯한 노래)\'라는 독특한 창법과 기괴한 표현주의적 분위기가 특징이다.','Op. 21',1912,10,35,'https://open.spotify.com/album/3gZqg5NUrXIeg70nt7Cjlx','https://music.apple.com/us/album/schoenberg-pierrot-lunaire-op-21/1258300619',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:31'),(288,71,'바르샤바의 생존자','A Survivor from Warsaw','song','나치 게토에서 살아남은 생존자의 증언을 바탕으로 한 낭독, 합창, 오케스트라를 위한 칸타타. 12음 기법으로 작곡되었으며, 충격적이고 극적인 작품이다.','Op. 46',1947,9,7,'https://open.spotify.com/track/72CUzAVtQmAbUF4PVObfrB','https://music.apple.com/us/album/a-survivor-from-warsaw-op-46/293139715?i=293139736',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:32'),(289,72,'25개의 점진적인 연습곡','25 Progressive Studies','album','피아노 초급자를 위한 필수 연습곡집. \'아라베스크\', \'목가\', \'발라드\' 등 낭만주의적 감수성이 담긴 표제가 붙어 있어 인기가 높다.','Op. 100',1852,4,25,'https://open.spotify.com/album/2FAbzVQJMYYOdadaEjnRkt','https://music.apple.com/us/album/burgm%C3%BCller-twenty-five-easy-and-progressive-studies/567550661',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:33'),(290,72,'18개의 성격 연습곡','18 Characteristic Studies','album','Op. 100의 상위 단계로, \'진주\', \'폭풍\' 등 보다 화려한 기교와 표현력을 요구하는 연습곡집이다.','Op. 109',1858,6,30,'https://open.spotify.com/album/2FAbzVQJMYYOdadaEjnRkt','https://music.apple.com/us/album/friedrich-burgm%C3%BCller-18-characteristic-studies-op-109/1173964734',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:35'),(291,73,'멜로디 F장조','Melody in F','song','루빈스타인의 작품 중 오늘날 유일하게 알려진 피아노 소품. 감미로운 멜로디로 인해 19세기 살롱 음악으로 큰 인기를 끌었다.','Op. 3, No. 1',1852,5,4,'https://open.spotify.com/track/4ekbSAxl9Q71flMdFIwc8A','https://music.apple.com/us/album/melodies-op-3-no-1-in-f-major-arr-popper-for-cello-piano/1446965189?i=1446965296',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:36'),(292,73,'피아노 협주곡 4번 D단조','Piano Concerto No. 4 in D minor','album','당대에는 라흐마니노프 이전, 러시아 피아노 협주곡의 대표작으로 꼽혔으나, 오늘날에는 거의 연주되지 않는 비운의 걸작이다.','Op. 70',1864,9,33,'https://open.spotify.com/album/13aybtkvBokL101ytOzlDJ','https://music.apple.com/us/album/rubinstein-piano-concerto-no-4-in-d-minor-op-70-caprice/1394161861',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:37'),(293,74,'바이올린 협주곡 2번 D단조','Violin Concerto No. 2 in D minor','album','비에니아프스키의 대표작. 바이올린의 화려한 기교와 쇼팽을 연상시키는 폴란드풍의 낭만적인 선율(2악장 로망스)이 조화를 이룬다.','Op. 22',1862,10,24,'https://open.spotify.com/album/5d7u2FsOin2WZoSrfCuqDq','https://music.apple.com/us/album/wieniavski-concerto-no-2-op-22-saint-saens-introduction/1521198188',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:38'),(294,74,'화려한 폴로네즈 1번 D장조','Polonaise Brillante No. 1 in D major','song','폴란드의 춤곡 폴로네즈를 바이올린의 화려한 기교로 표현한 작품. 바이올리니스트의 기량을 뽐내기 위한 앙코르 곡으로 자주 연주된다.','Op. 4',1853,9,5,'https://open.spotify.com/track/3VIvQV05eIUaLgYrv1BEac','https://music.apple.com/us/album/polonaise-brillante-no-1-in-d-major-op-4/321709504?i=321709619',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:39'),(295,74,'전설','Légende','song','신비롭고 애수 어린 선율이 인상적인 바이올린과 오케스트라를 위한 소품. 비에니아프스키의 서정성을 대표하는 곡이다.','Op. 17',1859,7,8,'https://open.spotify.com/track/0QCi4LI2z2e6ZqEuUQVj3a','https://music.apple.com/us/album/l%C3%A9gende-op-17/1676957844?i=1676958110',NULL,'2025-11-17 07:28:28','2025-11-18 12:05:40'),(296,75,'알함브라 궁전의 추억','Recuerdos de la Alhambra','song','기타의 \'트레몰로\' 주법(하나의 현을 빠르게 연속으로 탄현)의 정수를 보여주는 작품. 알함브라 궁전의 분수 소리를 묘사한 듯한 몽환적인 곡이다.',NULL,1896,8,4,'https://open.spotify.com/track/1vH3KARvA6njNXdi8FCmTa','https://music.apple.com/us/album/tarrega-recuerdos-de-la-alhambra/1452875133?i=1452875585',NULL,'2025-11-17 07:31:45','2025-11-18 07:43:02'),(297,75,'아라비아 기상곡','Capricho Árabe','song','타레가가 스페인 남부 안달루시아 지방(아랍 문화의 영향을 받은)을 여행하고 작곡한 곡. 이국적이고 애상적인 멜로디가 특징이다.',NULL,1892,7,5,'https://open.spotify.com/track/2ZpXhxvbt3fpPJX6qjj9AU','https://music.apple.com/us/album/capricho-%C3%A1rabe-remastered-2018/1361663930?i=1361664237',NULL,'2025-11-17 07:31:45','2025-11-18 07:43:04'),(298,76,'뫼리케 가곡집','Mörike-Lieder','album','시인 에두아르트 뫼리케의 시 53편에 곡을 붙인 볼프의 첫 대작 가곡집. \'봄날에\', \'숨어있는 이\' 등이 유명하다.',NULL,1888,9,100,'https://open.spotify.com/album/22cq29JQZsUesAZBDqiZa8','https://music.apple.com/us/album/wolf-m%C3%B6rike-lieder/208231959',NULL,'2025-11-17 07:31:45','2025-11-18 07:43:06'),(299,76,'이탈리아 가곡집','Italienisches Liederbuch','album','파울 하이제의 시집(이탈리아 민요 번역)을 바탕으로 한 46곡의 가곡집. 짧고 압축적인 형식 속에 재치와 깊이가 담긴 볼프 후기의 걸작이다.',NULL,1896,8,80,'https://open.spotify.com/album/1NLjbl7FUZp8KPvLZHmHLE','https://music.apple.com/us/album/wolf-italienisches-liederbuch-live/1443045291',NULL,'2025-11-17 07:31:45','2025-11-18 07:43:08'),(300,77,'교향곡 4번 \"불멸\"','Symphony No. 4 \"The Inextinguishable\"','album','닐센의 교향곡 중 가장 유명한 작품. 1차 세계대전의 혼란 속에서 \'꺼지지 않는 생명의 의지\'를 표현했다. 두 대의 팀파니가 격렬하게 전투를 벌이는 듯한 부분이 인상적이다.','Op. 29, FS 76',1916,9,36,'https://open.spotify.com/album/6fPbOtfb5t89lQFG2OG1l2','https://music.apple.com/us/album/nielsen-symphony-no-2-op-16-the-four-temperaments/459074111',NULL,'2025-11-17 07:31:45','2025-11-18 12:05:41'),(301,77,'클라리넷 협주곡','Clarinet Concerto','album','20세기 클라리넷 협주곡의 최고 걸작 중 하나. 클라리넷의 기교와 표현력을 극한까지 탐구하며, 스네어 드럼(작은 북)과의 날카로운 대립이 특징이다.','Op. 57, FS 129',1928,10,25,'https://open.spotify.com/album/6KzCruzqXUi5SrxNuMXUxJ','https://music.apple.com/us/album/nielsen-clarinet-concerto-op-57-fs-129-live-ep/1750498822',NULL,'2025-11-17 07:31:45','2025-11-18 12:05:43'),(302,78,'바이올린 협주곡 A단조','Violin Concerto in A minor','album','글라주노프의 가장 유명한 작품. 낭만주의 협주곡의 전통을 따르면서도, 중단 없이 연주되는 단악장 구성이 특징이다. 서정적이고 화려한 선율로 사랑받는다.','Op. 82',1904,9,22,'https://open.spotify.com/album/1RV0OANNvWTA2Ag6JNPflM','https://music.apple.com/us/album/glazunov-violin-concerto-in-a-minor-op-82-mozart/463325086',NULL,'2025-11-17 07:31:45','2025-11-18 12:05:44'),(303,78,'발레 <라이몬다>','Ballet <Raymonda>','album','중세 십자군 시대를 배경으로 한 3막 발레. 헝가리풍의 춤곡 등 화려하고 이국적인 멜로디가 가득하며, 고전 발레의 중요 레퍼토리이다.','Op. 57',1897,8,120,'https://open.spotify.com/album/0PQ1N6Tq2RA7UzBiUXPIZe','https://music.apple.com/us/album/glazunov-raymonda-ballet-op-57-act-i-waltz-remastered/680600505',NULL,'2025-11-17 07:31:45','2025-11-18 12:05:45'),(304,79,'모차르트 주제에 의한 변주곡과 푸가','Variations and Fugue on a Theme of Mozart','album','레거의 관현악곡 중 가장 유명한 작품. 모차르트 피아노 소나타 11번(K. 331) 1악장 주제를 바탕으로, 후기 낭만주의의 풍부한 화성과 대위법으로 변주했다.','Op. 132',1914,9,30,'https://open.spotify.com/album/2MkhmrRr3qBCKeOKpEdVQL','https://music.apple.com/us/album/max-reger-mozart-variations-and-fugue-op-132/504897535',NULL,'2025-11-17 07:31:45','2025-11-18 12:05:46'),(305,79,'바흐 이름에 의한 환상곡과 푸가','Fantasy and Fugue on B-A-C-H','album','\'B-A-C-H\'(시♭-라-도-시♮) 음형을 주제로 작곡한 장엄하고 복잡한 오르간 대곡. 바흐에 대한 레거의 존경심과 대위법적 기교가 집약되어 있다.','Op. 46',1900,10,16,'https://open.spotify.com/album/2s1dCSexdwWUVNsHZrMVRq','https://music.apple.com/us/album/reger-piano-concerto-op-114-solo-works/1676106102',NULL,'2025-11-17 07:31:45','2025-11-18 12:05:47'),(306,80,'발레 <사랑은 마술사>','El amor brujo','album','스페인 안달루시아 집시의 전설을 바탕으로 한 발레. \'불의 춤(Danza ritual del fuego)\'이 격렬한 리듬으로 매우 유명하다.','G. 68',1915,8,25,'https://open.spotify.com/album/3r85Aw3DIDErCQEiYHk0lu','https://music.apple.com/us/album/leo-brouwer-de-bach-a-los-beatles/449860916',NULL,'2025-11-17 07:31:45','2025-11-18 12:05:48'),(307,80,'발레 <삼각모자>','The Three-Cornered Hat','album','발레 뤼스(Ballets Russes)를 위해 작곡했으며, 피카소가 무대와 의상을 담당했다. 스페인 민속 춤곡(호타, 판당고 등)을 현대적으로 사용한 걸작이다.','G. 53',1919,9,38,'https://open.spotify.com/album/3r85Aw3DIDErCQEiYHk0lu','https://music.apple.com/us/album/falla-the-three-cornered-hat-nights-in-the-gardens/274821082',NULL,'2025-11-17 07:31:45','2025-11-18 12:05:49'),(308,80,'스페인 정원의 밤','Nights in the Gardens of Spain','album','스페인(안달루시아) 정원의 밤 풍경과 인상을 묘사한, 피아노와 오케스트라를 위한 \'교향적 인상\'. 드뷔시의 인상주의 영향이 짙게 드러난다.','G. 49',1915,9,24,'https://open.spotify.com/album/1d4xZOFDfDpD5Mht2UNjvb','https://music.apple.com/us/album/leo-brouwer-de-bach-a-los-beatles/449860916',NULL,'2025-11-17 07:31:45','2025-11-18 12:05:51'),(309,81,'발레 <봄의 제전>','The Rite of Spring','album','20세기 음악의 시작을 알린 혁명적인 작품. 이교도 러시아의 원시적인 제전을 그렸으며, 파격적인 불협화음과 원시적이고 폭발적인 리듬으로 1913년 파리 초연 당시 스캔들을 일으켰다.','K. 15',1913,10,33,'https://open.spotify.com/album/1sD5zrh53A4fewGOAUNiBO','https://music.apple.com/us/album/stravinsky-p%C3%A9trouchka/1452227794',NULL,'2025-11-17 07:31:45','2025-11-18 07:43:28'),(310,81,'발레 <불새>','The Firebird (L\'Oiseau de feu)','album','스트라빈스키가 발레 뤼스와 함께한 첫 성공작. 스승 림스키코르사코프의 영향이 보이는 화려하고 이국적인 관현악법이 특징이다. \'불새의 춤\', \'지옥의 춤\'이 유명하다.','K. 10',1910,9,45,'https://open.spotify.com/album/6eofEKbK0VkBVnwpswXjxV','https://music.apple.com/us/album/stravinsky-the-firebird/1748165963',NULL,'2025-11-17 07:31:45','2025-11-18 07:43:30'),(311,81,'발레 <페트루슈카>','Petrushka','album','세 명의 인형(페트루슈카, 발레리나, 무어인)의 비극적인 사랑 이야기를 그린 발레. 서로 다른 조성이 동시에 울리는 \'복조(Polytonality)\' 기법이 혁신적이었다.','K. 12',1911,10,35,'https://open.spotify.com/album/4dOX4XtI0uImiO1gRbRcSE','https://music.apple.com/us/album/stravinsky-p%C3%A9trouchka/1452227794',NULL,'2025-11-17 07:31:45','2025-11-18 07:43:32'),(312,81,'시편 교향곡','Symphony of Psalms','album','스트라빈스키의 \'신고전주의\' 시대를 대표하는 종교 합창곡. 시편의 라틴어 가사를 바탕으로, 중세의 장엄함과 현대적 리듬감을 결합시켰다.','K. 51',1930,9,23,'https://open.spotify.com/album/3MkOwTYpK8L40eVUtFcva0','https://music.apple.com/us/album/stravinsky-the-rite-of-spring/881240687',NULL,'2025-11-17 07:31:45','2025-11-18 07:43:34'),(313,82,'정화된 밤','Verklärte Nacht','album','쇤베르크의 초기 후기 낭만주의 걸작. 현악 6중주(이후 현악 오케스트라 편곡)를 위한 교향시로, 바그너풍의 격렬한 반음계와 감정 표현이 특징이다.','Op. 4',1899,9,30,'https://open.spotify.com/album/0YHrFLfeGjkhEhYSCimYdB','https://music.apple.com/us/album/schoenberg-transfigured-night-op-4-ep/1835914599',NULL,'2025-11-17 07:31:45','2025-11-18 12:05:52'),(314,82,'달에 홀린 피에로','Pierrot Lunaire','album','쇤베르크의 \'무조음악\' 시대를 대표하는 작품. \'슈프레히슈티메(말하는 듯한 노래)\'라는 독특한 창법과 기괴한 표현주의적 분위기가 특징이다.','Op. 21',1912,10,35,'https://open.spotify.com/album/3gZqg5NUrXIeg70nt7Cjlx','https://music.apple.com/us/album/schoenberg-pierrot-lunaire-op-21/1258300619',NULL,'2025-11-17 07:31:45','2025-11-18 12:05:53'),(315,82,'바르샤바의 생존자','A Survivor from Warsaw','song','나치 게토에서 살아남은 생존자의 증언을 바탕으로 한 낭독, 합창, 오케스트라를 위한 칸타타. 12음 기법으로 작곡되었으며, 충격적이고 극적인 작품이다.','Op. 46',1947,9,7,'https://open.spotify.com/track/72CUzAVtQmAbUF4PVObfrB','https://music.apple.com/us/album/a-survivor-from-warsaw-op-46/293139715?i=293139736',NULL,'2025-11-17 07:31:45','2025-11-18 12:05:54'),(316,82,'5개의 피아노 소품','Five Piano Pieces','album','쇤베르크가 12음 기법을 확립하기 직전의 작품들로, 5번째 곡 \'왈츠\'에서 최초로 12음 기법이 부분적으로 사용되었다.','Op. 23',1923,10,12,'https://open.spotify.com/album/6n7PBrw40pBLoWIatDYesI','https://music.apple.com/us/album/schoenberg-piano-concerto-op-42-5-piano-pieces-op-23/1216643248',NULL,'2025-11-17 07:31:45','2025-11-18 12:05:55'),(317,83,'교향곡 5번 D단조 \"혁명\"','Symphony No. 5 in D minor','album','스탈린 체제의 비판(<므첸스크의 레이디 맥베스>)으로 숙청 위기에 몰렸던 쇼스타코비치가 \'비판에 대한 예술가의 응답\'으로 작곡한 작품. 표면적으로는 체제 순응적이나, 그 이면에는 강압에 의한 환희(비극)가 담겨있다.','Op. 47',1937,9,45,'https://open.spotify.com/album/00d6wTUJHGsrxPmbETXGWm','https://music.apple.com/us/album/shostakovich-symphony-no-5-in-d-minor-op-47-remastered/1276358812',NULL,'2025-11-17 07:31:45','2025-11-18 12:05:56'),(318,83,'교향곡 7번 C장조 \"레닌그라드\"','Symphony No. 7 in C major \"Leningrad\"','album','나치 독일의 레닌그라드 포위 속에서 작곡된 교향곡. 1악장의 집요하게 반복되는 \'침략의 주제\'가 유명하며, 소련의 저항 정신을 상징하는 작품이 되었다.','Op. 60',1941,9,75,'https://open.spotify.com/album/5C1sWm4XThvQleTYMHn8NP','https://music.apple.com/us/album/shostakovich-symphony-no-7-in-c-major-op-60-leningrad/459074166',NULL,'2025-11-17 07:31:45','2025-11-18 12:05:57'),(319,83,'왈츠 2번 (재즈 모음곡 2번)','Waltz No. 2 (from Jazz Suite No. 2)','song','쇼스타코비치의 작품 중 가장 대중적인 멜로디. 본래 잃어버린 <재즈 모음곡 2번>의 일부로 알려졌으나, 현재는 <다양한 무대를 위한 모음곡 1번>으로 분류된다. 영화 <번지 점프를 하다>에 삽입되었다.',NULL,1950,5,4,'https://open.spotify.com/track/5syx0Q2ZG3mnsPblbbIxKV','https://music.apple.com/us/album/waltz-no-2-dmitri-shostakovich/1665220179?i=1665220180',NULL,'2025-11-17 07:31:45','2025-11-18 07:43:48'),(320,83,'현악 4중주 8번 C단조','String Quartet No. 8 in C minor','album','작곡가의 이니셜인 D-S-C-H(레-미♭-도-시) 음형을 주제로 사용한 자전적인 작품. 파시즘의 희생자들에게 헌정되었으며, 그의 작품 중 가장 격렬하고 비통한 실내악곡이다.','Op. 110',1960,9,20,'https://open.spotify.com/album/61XvJJ1sNDNcGUfVCZ8Ouk','https://music.apple.com/us/album/shostakovich-chamber-symphony-op-110a-strauss-metamorphosen/1250894762',NULL,'2025-11-17 07:31:45','2025-11-18 12:05:59'),(321,83,'첼로 협주곡 1번 E♭장조','Cello Concerto No. 1 in E♭ major','album','로스트로포비치를 위해 작곡된 20세기 첼로 협주곡의 걸작. 첼로의 극한의 기교와 D-S-C-H 음형, 격렬한 리듬이 특징이다.','Op. 107',1959,10,29,'https://open.spotify.com/album/7ECTELJHCmBXDxjrI77aHn','https://music.apple.com/us/album/shostakovich-symphony-no-5-in-d-minor-op-47-remastered/1276358812',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:00'),(322,84,'발레 <로미오와 줄리엣>','Ballet <Romeo and Juliet>','album','셰익스피어의 비극을 바탕으로 한 20세기 최고의 발레 음악. \'기사들의 춤(몬태규가와 캐퓰릿가)\'의 위협적인 멜로디가 특히 유명하다.','Op. 64',1935,9,140,'https://open.spotify.com/album/6MdafMWKnrfVhPIinp5kpG','https://music.apple.com/us/album/prokofiev-romeo-juliet-op-64/1387024022',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:01'),(323,84,'교향곡 1번 D장조 \"고전 교향곡\"','Symphony No. 1 in D major \"Classical\"','album','프로코피예프가 하이든의 스타일을 20세기적으로 재해석하여 작곡한 \'신고전주의\'의 대표작. 재치 있고 경쾌하며, 4악장의 속도감이 압권이다.','Op. 25',1917,8,15,'https://open.spotify.com/album/243y0T5l6b8nWrbcSoLhRS','https://music.apple.com/us/album/prokofiev-symphony-no-1-in-d-major-op-25-bizet-symphony/1276455179',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:02'),(324,84,'음악 동화 <피터와 늑대>','Peter and the Wolf','album','어린이들에게 오케스트라의 악기를 소개하기 위해 작곡한 음악 동화. 피터(현악기), 새(플루트), 늑대(호른) 등 각 등장인물이 특정 악기로 묘사된다.','Op. 67',1936,6,25,'https://open.spotify.com/album/780yIPeiygLraogyrDxXlq','https://music.apple.com/us/album/prokofiev-peter-and-the-wolf-op-67-saint-saens/1439050764',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:03'),(325,84,'피아노 협주곡 3번 C장조','Piano Concerto No. 3 in C major','song','20세기 피아노 협주곡 중 가장 화려하고 인기 있는 작품. 날카로운 리듬과 타악기적인 피아노, 서정적인 멜로디가 결합되어 있다.','Op. 26',1921,10,29,'https://open.spotify.com/track/2V1JvzU1DRDaG7d1lwVqBA','https://music.apple.com/us/album/piano-concerto-no-3-in-c-major-op-26-i-andante-allegro/692811520?i=692811560',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:04'),(326,84,'피아노 소나타 7번 B♭장조 \"전쟁 소나타\"','Piano Sonata No. 7 in B♭ major \"Stalingrad\"','album','2차 세계대전 중에 작곡된 3개의 \'전쟁 소나타\' 중 하나. 기계적이고 폭력적인 7/8박자의 3악장 피날레가 압도적이다.','Op. 83',1942,10,18,'https://open.spotify.com/album/25eQf9ue3mbwSgYDZtSaEO','https://music.apple.com/us/album/scriabin-piano-sonata-no-3-in-f-sharp-minor-op-23-prokofiev/1016548791',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:06'),(327,85,'관현악을 위한 협주곡','Concerto for Orchestra','album','버르토크가 미국 망명 시절 작곡한 최고 걸작. 오케스트라의 모든 악기들이 협주곡의 독주자처럼 화려한 기량을 뽐낸다.','Sz. 116',1943,10,38,'https://open.spotify.com/album/1nGtjcTDLObZqBxtib8vgW','https://music.apple.com/us/album/bart%C3%B3k-concerto-for-orchestra-sz-116/1171508884',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:07'),(328,85,'현악기, 타악기, 첼레스타를 위한 음악','Music for Strings, Percussion and Celesta','album','버르토크의 독창성이 집약된 20세기 관현악의 걸작. 대칭적인 악장 구조(황금분할), 독특한 악기 편성, 민속 리듬이 특징이다. 영화 <샤이닝>에 사용되었다.','Sz. 106',1936,10,30,'https://open.spotify.com/album/1QhGU51MW4BQ0JukW4xewm','https://music.apple.com/us/album/bart%C3%B3k-music-for-strings-percussion-and-celesta-sz/1276458979',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:08'),(329,85,'발레 <이상한 만다린>','Ballet <The Miraculous Mandarin>','album','폭력적이고 선정적인 내용으로 인해 초연 당시 스캔들을 일으킨 1막 발레. 원시주의적이고 격렬한 리듬이 특징이다.','Sz. 73',1924,10,30,'https://open.spotify.com/album/01o87QD8DYXKvP92p2wTJh','https://music.apple.com/us/album/bart%C3%B3k-the-wooden-prince-op-13-sz-60-the/1727105702',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:09'),(330,85,'미크로코스모스 (피아노 연습곡집)','Mikrokosmos','album','버르토크가 아들 페터를 위해 작곡한 153곡의 피아노 연습곡집. 단순한 곡에서 시작해 20세기 현대 음악의 복잡한 기법까지 단계별로 배울 수 있다.','Sz. 107',1939,3,180,'https://open.spotify.com/album/5SWD8q0osjqOgvql5ZBzvP','https://music.apple.com/us/album/bart%C3%B3k-mikrokosmos-sz-107/642587413',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:10'),(331,85,'6개의 현악 4중주','Six String Quartets','album','베토벤 이후 가장 위대한 현악 4중주 연작으로 꼽힌다. 버르토크의 작곡 기법과 민속 음악 연구가 집약된 20세기 실내악의 금자탑이다.','Sz. 40, 67, 85, 91, 102, 114',1939,10,150,'https://open.spotify.com/album/7AETI3SIYGsGQP2PsRdBtl','https://music.apple.com/us/album/holst-the-planets-op-32-schoenberg-verkl%C3%A4rte-nacht-op/1111682576',NULL,'2025-11-17 07:31:45','2025-11-18 07:44:13'),(332,86,'랩소디 인 블루','Rhapsody in Blue','song','클래식과 재즈를 결합시킨 미국 음악의 상징적인 작품. 클라리넷의 유명한 글리산도(미끄러지는 음)로 시작하며, 피아노의 화려한 기교가 돋보인다.',NULL,1924,9,16,'https://open.spotify.com/track/7oB0QBEnGRIJjvlDc8YnM6','https://music.apple.com/us/album/rhapsody-in-blue/594512997?i=594513239',NULL,'2025-11-17 07:31:45','2025-11-18 07:44:15'),(333,86,'오페라 <포기와 베스>','Opera <Porgy and Bess>','album','흑인 빈민가를 배경으로 한 최초의 위대한 미국 오페라. \'Summertime\'을 비롯한 모든 아리아가 재즈/블루스 스탠더드가 되었다.',NULL,1935,10,180,'https://open.spotify.com/album/30p7Hwuab3mMZGTIcwy5sL','https://music.apple.com/us/album/gil-shaham-the-fiddler-of-the-opera/1452161416',NULL,'2025-11-17 07:31:45','2025-11-18 07:44:17'),(334,86,'파리의 미국인','An American in Paris','song','거슈윈이 파리를 여행하며 느낀 인상을 묘사한 교향시. 재즈풍의 블루스 멜로디와 파리의 자동차 경적 소리(택시 경적)가 유쾌하게 어우러진다.',NULL,1928,8,18,'https://open.spotify.com/track/7oB0QBEnGRIJjvlDc8YnM6','https://music.apple.com/us/album/an-american-in-paris/79576591?i=79576585',NULL,'2025-11-17 07:31:45','2025-11-18 07:44:19'),(335,86,'피아노 협주곡 F장조','Piano Concerto in F','album','<랩소디 인 블루>의 성공 이후 작곡한 본격적인 3악장 협주곡. 낭만주의 협주곡의 형식과 재즈의 어법을 결합시켰다.',NULL,1925,9,32,'https://open.spotify.com/album/6LIaye0ez0bfOh7ZGP7UDB','https://music.apple.com/us/album/gershwin-piano-concerto-in-f-rhapsody-in-blue-cuban/586054237',NULL,'2025-11-17 07:31:45','2025-11-18 07:44:21'),(336,87,'뮤지컬 <웨스트 사이드 스토리>','Musical <West Side Story>','album','로미오와 줄리엣을 현대 뉴욕의 푸에르토리코 이민자 집단(샤크파)과 백인 집단(제트파)의 갈등으로 옮겨온 뮤지컬. \'Mambo\', \'Tonight\' 등이 유명하다.',NULL,1957,9,150,'https://open.spotify.com/album/0OBcWPxoNzDvi55luyMAo1','https://music.apple.com/us/album/west-side-story-2021-motion-picture-soundtrack/1597020481',NULL,'2025-11-17 07:31:45','2025-11-18 07:44:23'),(337,87,'<웨스트 사이드 스토리> 중 \"심포닉 댄스\"','Symphonic Dances from West Side Story','album','위 뮤지컬의 주요 춤곡들을 교향악 모음곡으로 편곡한 작품. 재즈, 라틴 리듬과 격렬한 오케스트레이션이 돋보인다.',NULL,1960,9,23,'https://open.spotify.com/album/0HBng63B0j0E4RNt7BIpqK','https://music.apple.com/us/album/bernstein-symphonic-dances-from-west-side-story-symphonic/1207844102',NULL,'2025-11-17 07:31:45','2025-11-18 07:44:25'),(338,87,'오페레타 <캔디드> 서곡','Overture to <Candide>','song','볼테르의 풍자 소설 <캔디드>를 바탕으로 한 오페레타의 서곡. 재치 있고 화려하며, 미국 오케스트라의 단골 연주 레퍼토리이다.',NULL,1956,8,4,'https://open.spotify.com/track/47r7pm0fWKmneTjjbVKlCW','https://music.apple.com/us/album/overture-to-candide/159015473?i=159015479',NULL,'2025-11-17 07:31:45','2025-11-18 07:44:27'),(339,87,'교향곡 2번 \"불안의 시대\"','Symphony No. 2 \"The Age of Anxiety\"','album','W. H. 오든의 시에서 영감을 받은 2부 6악장의 교향곡. 피아노가 협주곡처럼 중요한 역할을 하며, 2차 대전 이후의 현대인의 고독과 믿음을 그렸다.',NULL,1949,9,36,'https://open.spotify.com/album/5Wwm8QJXXPxPcnOeOWIlLG','https://music.apple.com/us/album/bernstein-symphony-no-2-the-age-of-anxiety/1499508266',NULL,'2025-11-17 07:31:45','2025-11-18 07:44:29'),(340,88,'애국가','Aegukga (South Korean National Anthem)','song','대한민국의 국가(國歌). 1935년경 작곡되었으며, 1948년 대한민국 정부 수립과 함께 공식 국가로 채택되었다.',NULL,1935,1,2,'https://open.spotify.com/track/41rymgdxQACRspZYexCGAb','https://music.apple.com/us/album/south-korea-national-anthem-aegukga/1847602459?i=1847602760',NULL,'2025-11-17 07:31:45','2025-11-18 07:44:31'),(341,88,'교향시 <한국 환상곡>','Symphonic Fantasia <Korea>','album','안익태가 리하르트 슈트라우스에게 사사한 후 작곡한 교향시. 후기 낭만주의 관현악법을 바탕으로 \'애국가\'의 선율을 주주제로 사용하여 발전시킨 작품이다.',NULL,1938,9,28,'https://open.spotify.com/album/469LwkJHKRvx5VGVpU1xG5',NULL,NULL,'2025-11-17 07:31:45','2025-11-18 07:44:33'),(342,89,'가곡 <봉선화>','Gagok <Balsam Flower (Bongseonhwa)>','song','1920년 작곡된 한국 최초의 예술 가곡. 일제 강점기 민족의 설움을 봉선화에 빗대어 노래한, 애수 어린 멜로디가 특징이다.',NULL,1920,3,3,'https://open.spotify.com/track/7M3POeMOBCs6pwtDkVhBTi',NULL,NULL,'2025-11-17 07:31:45','2025-11-18 07:44:35'),(343,89,'동요 <고향의 봄>','Children\'s Song <Spring in My Hometown>','song','\'나의 살던 고향은...\'으로 시작하는, 전 국민의 애창 동요. 이원수의 시에 곡을 붙였으며, 한국적 서정의 원형으로 평가받는다.',NULL,1926,1,2,'https://open.spotify.com/track/0N9iR9GYIBji38GKdy4fKN','https://music.apple.com/us/album/spring-breeze-in-my-hometown/1737180747?i=1737180748',NULL,'2025-11-17 07:31:45','2025-11-18 07:44:37'),(344,89,'바이올린 소품 <애수의 곡>','Violin Piece <Sorrow (Aesu-ui Gok)>','song','1921년 작곡된, 현존하는 한국 최초의 바이올린 창작곡. 홍난파 자신의 비극적 사랑 이야기를 담았다는 일화가 있다.',NULL,1921,4,4,'https://open.spotify.com/track/0bKkmQYitcmFT76aVzWO8I',NULL,NULL,'2025-11-17 07:31:45','2025-11-18 07:44:39'),(345,90,'오페라 <심청>','Opera <Sim Tjong>','album','한국의 고전소설 <심청전>을 바탕으로 한 오페라. 1972년 뮌헨 올림픽 문화 축전 개막작으로 초연되어 세계적인 명성을 얻었다.',NULL,1972,10,150,'https://open.spotify.com/album/3jwobJu2gfscIyepVtguSX',NULL,NULL,'2025-11-17 07:31:45','2025-11-18 07:44:41'),(346,90,'첼로 협주곡','Cello Concerto','album','윤이상의 첼로에 대한 깊은 이해가 드러나는 걸작. 동백림 사건으로 옥중에 있을 때 구상했으며, 첼로의 흐느끼는 듯한 \'농현\' 기법이 압권이다.',NULL,1976,10,30,'https://open.spotify.com/album/6OQbwi8FqeBPbi8qPr3rzV','https://music.apple.com/us/album/isang-yun-schumann/1767553479',NULL,'2025-11-17 07:31:45','2025-11-18 07:44:43'),(347,90,'오케스트라를 위한 <예악>','Réak for Orchestra','album','\'예악(禮樂)\' 사상을 바탕으로, 궁중 음악의 장엄하고 느린 호흡을 서양 오케스트라로 구현한 윤이상의 대표적인 관현악곡이다.',NULL,1966,9,16,'https://open.spotify.com/album/3jwobJu2gfscIyepVtguSX','https://music.apple.com/us/album/yun-loyang-gasa-r%C3%A9ak-shao-yang-yin-tuyaux-sonores/1704634992',NULL,'2025-11-17 07:31:45','2025-11-18 07:44:45'),(348,90,'5개의 피아노를 위한 연습곡','5 Etüden für Klavier','album','12음 기법과 국악의 시김새, 꾸밈음 등을 결합하여 독창적인 음향을 만들어낸 피아노 연습곡이다.',NULL,1974,9,15,'https://open.spotify.com/album/65tTkPhfEt17nOy0nxSc3S',NULL,NULL,'2025-11-17 07:31:45','2025-11-18 07:44:47'),(349,91,'카르미나 부라나','Carmina Burana','album','중세 수도원에서 발견된 세속적인 시가(詩歌)를 바탕으로 작곡한 3부작 무대 칸타타 중 첫 번째 작품. 원시적이고 강렬한 리듬이 특징이다.',NULL,1936,9,65,'https://open.spotify.com/album/29PSyE1ZD0XUgqm5yqC33x','https://music.apple.com/us/album/orff-carmina-burana/1387018986',NULL,'2025-11-17 07:31:45','2025-11-18 07:44:49'),(350,91,'<카르미나 부라나> 중 \"오 포르투나\"','O Fortuna (from <Carmina Burana>)','song','<카르미나 부라나>의 시작과 끝을 장식하는 합창곡. 운명의 여신의 변덕을 노래하는 장엄하고 압도적인 멜로디로, 20세기 클래식 곡 중 가장 유명하다.',NULL,1936,7,3,'https://open.spotify.com/track/0V9YfDRxcA8qz2An0o96mz','https://music.apple.com/us/album/o-fortuna-from-carmina-burana-vocal/398976602?i=398976604',NULL,'2025-11-17 07:31:45','2025-11-18 07:44:52'),(351,92,'4분 33초','4\'33\"','song','존 케이지의 가장 유명하고 논쟁적인 작품. 연주자가 4분 33초 동안 악기(주로 피아노) 앞에서 아무것도 연주하지 않는다. \'침묵 속의 소리(객석의 소음 등)\'를 음악으로 제시한 작품이다.',NULL,1952,1,4,'https://open.spotify.com/track/2bNCdW4rLnCTzgqUXTTDO1','https://music.apple.com/us/album/433/406490689?i=406490698',NULL,'2025-11-17 07:31:45','2025-11-18 07:44:54'),(352,92,'조작된 피아노를 위한 소나타와 간주곡','Sonatas and Interludes for Prepared Piano','album','피아노 현에 나사, 고무, 볼트 등을 끼워 넣어 \'조작된 피아노\'를 만들고, 이를 통해 타악기적이고 동양적인 음색을 추구한 작품이다.',NULL,1948,8,65,'https://open.spotify.com/album/5lspjwrZolp8QP2l3Y9mP9','https://music.apple.com/us/album/john-cage-sonatas-and-interludes-for-prepared-piano/570037827',NULL,'2025-11-17 07:31:45','2025-11-18 07:44:56'),(353,93,'오페라 <해변의 아인슈타인>','Opera <Einstein on the Beach>','album','\'미니멀리즘 오페라\'의 시대를 연 4막 5시간의 대작. 줄거리 없이 반복되는 음형과 이미지들로 구성된 혁신적인 작품이다.',NULL,1976,10,270,'https://open.spotify.com/album/7mCDTPGNnDgfnwePAG20d0','https://music.apple.com/us/album/the-essential-philip-glass-deluxe-edition/492686196',NULL,'2025-11-17 07:31:45','2025-11-18 07:44:58'),(354,93,'피아노 연습곡 6번','Piano Etude No. 6','song','필립 글래스의 피아노 연습곡 중 가장 유명한 곡 중 하나. 끊임없이 반복되는 오른손 아르페지오와 변화하는 왼손 화성이 특징이다.',NULL,1994,7,7,'https://open.spotify.com/track/3dzgmH9o9P9Kw4n3P3bWOR','https://music.apple.com/us/album/etude-no-6/1756102360?i=1756102604',NULL,'2025-11-17 07:31:45','2025-11-18 07:45:00'),(355,93,'영화 <디 아워스> 사운드트랙','The Hours (Soundtrack)','album','영화 <디 아워스>를 위해 작곡한 음악. 글래스 특유의 반복적인 피아노 음형이 영화의 우울하고 내성적인 분위기를 효과적으로 그려냈다.',NULL,2002,6,55,'https://open.spotify.com/album/4F0LJueCDliCH7Bg4PPVil','https://music.apple.com/us/album/the-hours-music-from-the-motion-picture/72787578',NULL,'2025-11-17 07:31:45','2025-11-18 07:45:02'),(356,94,'청소년을 위한 관현악 입문','The Young Person\'s Guide to the Orchestra','album','퍼셀의 주제를 바탕으로 한 변주곡과 푸가를 통해, 오케스트라의 모든 악기(목관, 금관, 현악, 타악기)를 소개하는 교육용 걸작이다.','Op. 34',1945,7,18,'https://open.spotify.com/album/7JdOqLEOW2CrT23G7Z55Hl','https://music.apple.com/us/album/britten-the-young-persons-guide-to-the-orchestra-op/1439048738',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:11'),(357,94,'오페라 <피터 그라임스>','Opera <Peter Grimes>','album','20세기 영국 오페라의 최고 걸작. 마을에서 고립된 어부 피터 그라임스의 비극을 그렸다. 특히 4개의 \'바다 간주곡\'이 유명하다.','Op. 33',1945,10,145,'https://open.spotify.com/album/7JdOqLEOW2CrT23G7Z55Hl','https://music.apple.com/us/album/britten-peter-grimes-op-33/1761633810',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:12'),(358,94,'전쟁 레퀴엠','War Requiem','album','2차 세계대전으로 파괴된 코벤트리 대성당 재건을 위해 작곡된 20세기 최고의 레퀴엠. 전통 라틴어 미사곡 가사와 1차 대전 시인 윌프레드 오웬의 반전(反戰) 시를 교차시켰다.','Op. 66',1962,10,85,'https://open.spotify.com/album/1mL2RgeEjXi1C4TvWPvKSX','https://music.apple.com/us/album/britten-war-requiem-op-66/1587718321',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:14'),(359,94,'첼로 모음곡 1번','Cello Suite No. 1','album','바흐의 무반주 첼로 모음곡에 영감을 받아 첼리스트 로스트로포비치를 위해 작곡한 3개의 첼로 모음곡 중 첫 번째 작품이다.','Op. 72',1964,10,25,'https://open.spotify.com/album/7h6cIMDi5W7kSAwWaUtIWm','https://music.apple.com/us/album/enescu-string-octet-op-7-britten-lachrymae-op-48a-version/1831077634',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:15'),(360,95,'시간의 종말을 위한 4중주','Quatuor pour la fin du Temps','album','2차 대전 당시 독일군 포로수용소에서 작곡, 초연된 실내악곡. 바이올린, 첼로, 클라리넷, 피아노라는 독특한 편성으로, 요한계시록의 \'시간의 종말\'을 신비주의적으로 그렸다.',NULL,1941,10,50,'https://open.spotify.com/album/5oXym4QwF8Kd8VdS4E0q5s','https://music.apple.com/us/album/messiaen-quatuor-pour-la-fin-du-temps/403979396',NULL,'2025-11-17 07:31:45','2025-11-18 07:45:12'),(361,95,'20개의 시선으로 아기 예수를 바라보다','Vingt regards sur l\'Enfant-Jésus','album','아기 예수의 탄생을 20개의 다른 시선(성모 마리아, 천사, 별 등)으로 바라본 20개의 피아노 모음곡. 메시앙의 피아노 음악의 정수이다.',NULL,1944,10,120,'https://open.spotify.com/album/0Ct9USguv7YF6sw1EvoxB2','https://music.apple.com/us/album/olivier-messiaen-vingt-regards-sur-lenfant-j%C3%A9sus/306198983',NULL,'2025-11-17 07:31:45','2025-11-18 07:45:14'),(362,95,'투랑갈릴라 교향곡','Turangalîla-Symphonie','album','산스크리트어로 \'사랑, 시간, 생명\' 등을 뜻하는 10악장의 거대한 교향곡. 피아노와 \'옹드 마르트노\'(초기 전자악기)가 독주악기로 사용된다.',NULL,1948,10,80,'https://open.spotify.com/album/3qUqILNEQNWMhBikgiGt4u','https://music.apple.com/us/album/olivier-messiaen-turangal%C3%AEla-symphonie/1467956324',NULL,'2025-11-17 07:31:45','2025-11-18 07:45:16'),(363,95,'새의 카탈로그','Catalogue d\'oiseaux','album','메시앙이 채보한 프랑스 전역의 새소리를 바탕으로 작곡한 13개의 피아노 모음곡. 새소리를 피아노로 재현한 독창적인 작품이다.',NULL,1958,10,160,'https://open.spotify.com/album/1i5w2fgvVlS86LUtHF6t1O','https://music.apple.com/us/album/olivier-messiaen-catalogue-doiseaux/1741074544',NULL,'2025-11-17 07:31:45','2025-11-18 07:45:18'),(364,96,'오페라 <보체크>','Opera <Wozzeck>','album','20세기 표현주의 오페라의 최고 걸작. 가난한 병사 보체크가 사회의 억압 속에 점차 미쳐가다 살인을 저지르고 파멸하는 과정을 무조음악으로 그렸다.','Op. 7',1922,10,95,'https://open.spotify.com/album/1MaE1wcPr9hjnE90EIk4xD','https://music.apple.com/us/album/berg-wozzeck-op-7-live/1179533985',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:16'),(365,96,'바이올린 협주곡 \"어느 천사를 추억하며\"','Violin Concerto \"To the Memory of an Angel\"','album','베르크의 마지막 작품이자 유작. 12음 기법을 사용했음에도 불구하고, 바흐의 코랄과 낭만적인 서정성을 결합시켜 깊은 슬픔과 아름다움을 표현했다.',NULL,1935,10,26,'https://open.spotify.com/album/4rCx7dnAgXhes9ckGrMXA4','https://music.apple.com/us/album/berg-violin-concerto-ep/1591394880',NULL,'2025-11-17 07:31:45','2025-11-18 07:45:22'),(366,96,'서정 모음곡','Lyric Suite','album','현악 4중주를 위한 6악장의 모음곡. 12음 기법으로 작곡되었으나, 베르크의 비밀스러운 사랑의 고백이 담긴 격정적이고 서정적인 작품이다.',NULL,1926,10,28,'https://open.spotify.com/album/2PE4TFD7wdBTqbWoWIDT0X','https://music.apple.com/us/album/berg-lyric-suite-webern-5-movements-for-string-quartet/1166115569',NULL,'2025-11-17 07:31:45','2025-11-18 07:45:24'),(367,97,'교향곡','Symphony','album','베베른의 12음 기법이 정점에 달한 작품. 9개의 악기만으로 연주되며, 극도로 절제된 \'점묘주의\' 음향과 대칭 구조가 특징이다. 연주 시간은 약 10분이다.','Op. 21',1928,10,10,'https://open.spotify.com/album/2QhgmkBQ6sKqpQ7dbNW8P2','https://music.apple.com/us/album/webern-symphony-op-21-remastered-single/1047011134',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:17'),(368,97,'현악 4중주를 위한 5개의 악장','Five Movements for String Quartet','album','베베른의 초기 \'무조음악\' 시대 작품. 5개의 극도로 짧은(Aphoristic) 악장으로 구성되며, 전통적인 화성과 형식을 파괴한 급진적인 소품이다.','Op. 5',1909,9,12,'https://open.spotify.com/album/58tjRK9J48kSCPERmQ4L8y','https://music.apple.com/us/album/schumann-symphony-fr%C3%BChlingssymphonie-no-1-op-38-webern/2523010',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:18'),(369,97,'오케스트라를 위한 6개의 소품','Six Pieces for Orchestra','album','무조음악 시대의 관현악곡. 각 악장이 매우 짧으며, 음색(Klangfarbenmelodie) 그 자체를 음악의 중요 요소로 다루었다.','Op. 6',1909,9,11,'https://open.spotify.com/album/4qNAJqXCoOPnPKxXnlFfSx','https://music.apple.com/us/album/webern-6-pieces-for-large-orchestra-op-6-remastered-ep/1047011887',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:19'),(370,98,'대답 없는 질문','The Unanswered Question','song','아이브스의 가장 유명하고 철학적인 작품. 조용한 현악기(침묵) 위에서 트럼펫이 \'존재에 대한 질문\'을 던지고, 목관악기들이 혼란스럽게 대답(조롱)하는 모습을 그렸다.','K. 1C23',1908,8,6,'https://open.spotify.com/track/6UgAGxz1vh1VJGMLGdEYmz','https://music.apple.com/us/album/in-the-hall-of-the-mountain-king-from-peer-gynt-suite-no-1/347537633?i=347537719',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:20'),(371,98,'교향곡 4번','Symphony No. 4','album','복잡한 리듬, 복조, 콜라주 기법이 총동원된 아이브스의 가장 실험적인 대작. 너무 복잡하여 작곡 후 50년이 지난 1965년에야 전곡 초연되었다.','K. 1A4',1916,10,30,'https://open.spotify.com/album/1MaE1wcPr9hjnE90EIk4xD',NULL,NULL,'2025-11-17 07:31:45','2025-11-18 12:06:22'),(372,98,'피아노 소나타 2번 \"콩코드\"','Piano Sonata No. 2 \"Concord, Mass.\"','album','미국 초월주의 사상가(에머슨, 호손, 올컷, 소로)들을 묘사한 4악장의 피아노 소나타. 극도로 난해하고 실험적인 기법(불협화음, 무조)으로 가득 차 있다.','K. 3A2',1915,10,45,'https://open.spotify.com/album/1sD5zrh53A4fewGOAUNiBO',NULL,NULL,'2025-11-17 07:31:45','2025-11-18 12:06:23'),(373,98,'<뉴잉글랜드의 세 장소>','Three Places in New England','album','미국 뉴잉글랜드 지방의 세 장소(독립전쟁 기념비, 퍼트넘 캠프, 허사토닉 강)를 그린 관현악 모음곡. 여러 멜로디가 동시에 울리는 \'콜라주\' 기법이 유명하다.','K. 1A7',1914,9,19,'https://open.spotify.com/album/1MaE1wcPr9hjnE90EIk4xD',NULL,NULL,'2025-11-17 07:31:45','2025-11-18 12:06:24'),(374,99,'리베르탱고','Libertango','song','피아졸라의 \'누에보 탱고\'를 전 세계에 알린 대표작. \'자유(Libertad)\'와 \'탱고\'의 합성어로, 전통 탱고에서 벗어난 새로운 스타일을 선언한 곡이다.',NULL,1974,8,3,'https://open.spotify.com/track/1IIydYQ6LTzZpgLXYpNlNy','https://music.apple.com/us/album/libertango/376141813?i=376141820',NULL,'2025-11-17 07:31:45','2025-11-18 07:45:41'),(375,99,'망각','Oblivion','song','피아졸라의 작품 중 가장 서정적이고 애상적인 멜로디로 사랑받는 곡. 영화 <엔리코 4세>의 사운드트랙으로 사용되었다.',NULL,1982,6,4,'https://open.spotify.com/track/56i4MBbcPhYBvn4yc76m20','https://music.apple.com/us/album/oblivion/73585031?i=73585004',NULL,'2025-11-17 07:31:45','2025-11-18 07:45:43'),(376,99,'아디오스 노니노','Adiós Nonino','song','아버지의 죽음을 추모하며 작곡한 곡으로, 피아졸라 자신도 \'최고의 작품\'으로 꼽았다. 격렬한 리듬과 비통한 멜로디가 교차한다.',NULL,1959,8,5,'https://open.spotify.com/track/5118yUwKxuaOLOPrDYUWls','https://music.apple.com/us/album/adi%C3%B3s-nonino/78502030?i=78501807',NULL,'2025-11-17 07:31:45','2025-11-18 07:45:45'),(377,99,'부에노스 아이레스의 사계','The Four Seasons of Buenos Aires (Estaciones Porteñas)','album','비발디의 <사계>에 대한 탱고 버전의 응답. 부에노스 아이레스의 사계절을 4개의 탱고 작품으로 그렸다. (\'겨울\', \'봄\', \'여름\', \'가을\')',NULL,1970,9,25,'https://open.spotify.com/album/7EvInJWRWic8K2GvmfcJrF','https://music.apple.com/us/album/piazzolla-en-suite/73585031',NULL,'2025-11-17 07:31:45','2025-11-18 07:45:48'),(378,100,'짐노페디 1번','Gymnopédie No. 1','song','사티의 가장 유명한 피아노곡. 고대 그리스의 축제(짐노페디)를 상상하며 쓴 3개의 소품 중 첫 곡. 단순하고 몽환적이며, 미니멀리즘의 시초로 평가받는다.',NULL,1888,3,3,'https://open.spotify.com/track/1GOEFPNFBqPKCEFpQj4rn8','https://music.apple.com/us/album/gymnop%C3%A9die-no-1/1834399557?i=1834399573',NULL,'2025-11-17 07:31:45','2025-11-18 07:45:50'),(379,100,'그노시엔 1번','Gnossienne No. 1','song','고대 크레타의 궁전(크노소스)에서 영감을 받은 6개의 피아노 소품 중 하나. 짐노페디와 유사하게, 신비롭고 이국적인 분위기를 자아낸다.',NULL,1890,3,4,'https://open.spotify.com/track/0Seumg0NAq7KS1r0Yso52H','https://music.apple.com/us/album/satie-gnossienne-no-1/1610557866?i=1610557867',NULL,'2025-11-17 07:31:45','2025-11-18 07:45:52'),(380,100,'난 그대를 원해요','Je te veux (I Want You)','song','사티가 카바레 가수를 위해 작곡한 대중적인 샹송(왈츠). 사티의 유쾌하고 감상적인 면모를 보여준다.',NULL,1903,4,4,'https://open.spotify.com/track/3CqjhIgb7DaDNbdLuz1b9y','https://music.apple.com/us/album/satie-je-te-veux/1610557866?i=1610557873',NULL,'2025-11-17 07:31:45','2025-11-18 07:45:54'),(381,101,'<가야네> 중 \"칼춤\"','Sabre Dance (from <Gayane>)','song','발레 <가야네>의 마지막 막에 나오는 아르메니아 전사들의 격렬한 춤곡. 20세기 클래식 곡 중 \'볼레로\', \'오 포르투나\'와 함께 가장 유명한 히트곡 중 하나이다.',NULL,1942,7,3,'https://open.spotify.com/track/64Ljpz63XjSF8EWmjx48FI','https://music.apple.com/us/album/sabre-dance-from-gayane-suite-no-2/1717607393?i=1717607412',NULL,'2025-11-17 07:31:45','2025-11-18 07:45:56'),(382,101,'발레 <스파르타쿠스>','Ballet <Spartacus>','album','로마의 검투사 스파르타쿠스의 반란을 그린 3막 발레. \'스파르타쿠스와 프리기아의 아다지오\'는 관능적이고 장대한 멜로디로 유명하다.',NULL,1954,9,150,'https://open.spotify.com/album/1DSECbUuomWOMgZEak0GDv',NULL,NULL,'2025-11-17 07:31:45','2025-11-18 07:45:58'),(383,101,'바이올린 협주곡 D단조','Violin Concerto in D minor','song','아르메니아 민속 음악의 이국적인 선율과 리듬이 넘치는 화려한 바이올린 협주곡. 20세기 주요 협주곡 레퍼토리 중 하나이다.',NULL,1940,10,35,'https://open.spotify.com/track/67oGA9H4E7IY9dMPK5ZDeg','https://music.apple.com/us/album/violin-concerto-in-d-minor-arr-for-flute-orchestra/1725562866?i=1725562872',NULL,'2025-11-17 07:31:45','2025-11-18 07:46:00'),(384,101,'가면무도회 모음곡','Masquerade Suite','album','레르몬토프의 희곡 <가면무도회>를 위한 부수 음악을 모음곡으로 편곡한 것. \'왈츠\' 악장이 특히 유명하다.',NULL,1941,7,17,'https://open.spotify.com/album/55J1DF9Q5xYZ9gy5HfogOL','https://music.apple.com/us/album/khachaturian-masquerade-suite-1-5-ep/514015346',NULL,'2025-11-17 07:31:45','2025-11-18 07:46:02'),(385,102,'존 케이지를 위한 교향곡','Symphony for John Cage','album','백남준의 초기 전위 음악. 악보 대신 여러 지시문으로 이루어져 있으며, 피아노를 부수거나 소리를 지르는 등의 행위로 구성된다.',NULL,1961,10,20,'https://open.spotify.com/album/28DeGPXSSRdjhx9hba3aKm',NULL,NULL,'2025-11-17 07:31:45','2025-11-18 07:46:04'),(386,102,'행위 음악 \"바이올린 솔로\"','Action Music \"One for Violin Solo\"','song','플럭서스(Fluxus) 시절의 대표적인 행위 예술. 연주자가 바이올린을 천천히 들어 올려 연주하는 대신, 탁자에 내리쳐 부수는 퍼포먼스이다.',NULL,1962,10,5,'https://open.spotify.com/track/3MnNNfqijV7k4Dj7yrSQ4g',NULL,NULL,'2025-11-17 07:31:45','2025-11-18 07:46:06'),(387,102,'조작된 피아노를 위한 에튀드','Etude for Prepared Piano','album','존 케이지의 \'조작된 피아노\'에서 영향을 받아 작곡한 초기 피아노 작품.',NULL,1959,9,10,'https://open.spotify.com/album/65tTkPhfEt17nOy0nxSc3S',NULL,NULL,'2025-11-17 07:31:45','2025-11-18 07:46:08'),(388,103,'가곡 <가고파>','Gagok <Gagopa>','song','이은상의 시에 곡을 붙인, 한국인이 가장 사랑하는 가곡 중 하나. 고향(마산)을 그리워하는 마음을 낭만주의적이고 웅장한 선율로 그렸다.',NULL,1933,5,4,'https://open.spotify.com/track/6QefDQ46v8gdUNxOhTfh1Q',NULL,NULL,'2025-11-17 07:31:45','2025-11-18 07:46:10'),(389,103,'가곡 <목련화>','Gagok <Magnolia (Mongnyeonhwa)>','song','조영출의 시에 곡을 붙인 가곡. \'오 내 사랑 목련화야\'로 시작하는, 봄의 정취와 사랑을 노래한 화려하고 열정적인 곡이다.',NULL,1949,6,3,'https://open.spotify.com/track/6QefDQ46v8gdUNxOhTfh1Q',NULL,NULL,'2025-11-17 07:31:45','2025-11-18 07:46:12'),(390,103,'가곡 <내 마음은>','Gagok <My Heart is (Nae Maeumeun)>','song','김동환의 시에 곡을 붙인 가곡. \'내 마음은 호수요\'라는 가사로 시작하며, 잔잔한 호수와 같은 사랑을 노래한 서정적인 곡이다.',NULL,1948,5,3,'https://open.spotify.com/track/6MuDeFE9izwnBIYeuA32RI',NULL,NULL,'2025-11-17 07:31:45','2025-11-18 07:46:14'),(391,103,'신포니에타 (교향곡 1번)','Sinfonietta (Symphony No. 1)','album','김동진의 대표적인 관현악 작품. 1968년 작곡되었으며, 한국적 선율과 낭만주의 관현악법이 결합되어 있다.',NULL,1968,8,25,'https://open.spotify.com/album/2I4Npa3S0lc14yerFPlLOj','https://music.apple.com/us/album/arnold-beckus-the-dandipratt-dances-sinfonietta-no-1/1460056397',NULL,'2025-11-17 07:31:45','2025-11-18 07:46:16'),(392,104,'신포니에타','Sinfonietta','album','야나체크의 가장 유명한 관현악곡. 9대의 트럼펫이 팡파르를 울리는 화려한 1악장이 특징이며, 체코 군대의 위용과 브르노의 자유를 상징한다.','JW VI/18',1926,9,23,'https://open.spotify.com/album/66alfTn7jkgoVfLFkggXIg','https://music.apple.com/us/album/jan%C3%A1%C4%8Dek-sinfonietta-jw-vi-18-dvo%C5%99%C3%A1k-symphony-no-6-in/1150170047',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:25'),(393,104,'오페라 <예누파>','Opera <Jenůfa>','album','야나체크를 세계적인 작곡가 반열에 오르게 한 오페라. 모라비아 지방의 \'말의 억양\'을 선율에 접목시킨 \'리얼리즘\' 오페라의 걸작이다.','JW I/4',1903,10,120,'https://open.spotify.com/album/2pACZH9nLzJVyBVkxvcJG6','https://music.apple.com/us/album/jan%C3%A1%C4%8Dek-jen%C5%AFfa-jw-i-4/1016626007',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:26'),(394,104,'오페라 <영리한 암여우>','Opera <The Cunning Little Vixen>','album','숲 속 동물들과 인간의 세계가 교차하는, 동화적이고 철학적인 오페라. 야나체크의 자연에 대한 사랑과 생명의 순환 사상이 담겨있다.','JW I/9',1923,9,100,'https://open.spotify.com/album/472SW5Sz8u0JaWGjGzdWTb','https://music.apple.com/us/album/jan%C3%A1%C4%8Dek-jen%C5%AFfa-jw-i-4/1016626007',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:27'),(395,104,'글라골 미사','Glagolitic Mass','album','전통 라틴어 미사 대신, 고대 슬라브어(글라골) 가사를 사용한 독창적인 미사곡. 야나체크의 범슬라브주의와 강렬한 표현력이 돋보인다.','JW III/9',1926,9,40,'https://open.spotify.com/album/5OiBwhnJ5B8yi13uvvPN0C','https://music.apple.com/us/album/brahms-dvor%C3%A1k-jan%C3%A1cek-dances-sonatas-for-violin-viola/1452614039',NULL,'2025-11-17 07:31:45','2025-11-18 12:06:28'),(396,105,'브라질풍의 바흐 5번','Bachianas Brasileiras No. 5','album','9개의 <브라질풍의 바흐> 연작 중 가장 유명한 곡. 8대의 첼로 앙상블과 소프라노 독창이라는 독특한 편성으로, 1악장 \'아리아(칸틸레나)\'가 유명하다.','W 389-391',1938,8,11,'https://open.spotify.com/album/48Sda9GJnyVZsRLsxktsed','https://music.apple.com/us/album/heitor-villa-lobos-bachianas-brasileiras-no-5-w-389/1690169862',NULL,'2025-11-17 07:33:20','2025-11-18 07:46:26'),(397,105,'기타 연습곡 1번','Guitar Etude No. 1','song','12개의 기타 연습곡(W 235) 중 첫 번째 곡. 기타리스트 안드레스 세고비아에게 헌정되었으며, 기타 전공자의 필수 레퍼토리이다.','W 235',1929,8,2,'https://open.spotify.com/track/0Prl7SoIHizJTJbdtEJAc3','https://music.apple.com/us/album/12-estudos-w235-1928-version-no-5-andantino/1174622974?i=1174623282',NULL,'2025-11-17 07:33:20','2025-11-18 07:46:28'),(398,105,'쇼로스 1번 (기타를 위한)','Chôros No. 1 (for Guitar)','song','14개의 쇼로스(Chôros) 연작 중 첫 곡. 브라질 토착 민속 음악의 특징을 담은 기타 독주곡이다.','W 161',1920,7,5,'https://open.spotify.com/track/1nUJK1VPQMQz4bsTyk0zuS','https://music.apple.com/us/album/ch%C3%B4ros-no-1-w161-ch%C3%B4ro-t%C3%ADpico/1174622974?i=1174623273',NULL,'2025-11-17 07:33:20','2025-11-18 07:46:30'),(399,105,'<브라질풍의 바흐 2번> 중 \"시골의 작은 기차\"','\"O Trenzinho do Caipira\" (from Bachianas Brasileiras No. 2)','song','관현악을 위한 4악장 모음곡 <브라질풍의 바흐 2번>의 마지막 4악장. 시골의 작은 증기 기관차 소리를 유쾌하게 묘사했다.','W 246-249',1930,7,5,'https://open.spotify.com/track/7padhK8jinHE5Fqup9iVgW',NULL,NULL,'2025-11-17 07:33:20','2025-11-18 07:46:32'),(400,106,'교향곡 <화가 마티스>','Symphony: Mathis der Maler','album','힌데미트의 동명 오페라 <화가 마티스>의 음악을 바탕으로 재구성한 3악장 교향곡. 르네상스 화가 마티아스 그뤼네발트의 작품에서 영감을 받았다.',NULL,1934,9,28,'https://open.spotify.com/album/5VsdWIhXuXHyHzt2ZjA7kN','https://music.apple.com/us/album/hindemith-symphonic-metamorphosis-mathis-der-maler/1610390655',NULL,'2025-11-17 07:33:20','2025-11-18 07:46:34'),(401,106,'베버 주제에 의한 교향적 변용','Symphonic Metamorphosis of Themes by Carl Maria von Weber','album','카를 마리아 폰 베버의 잊혔던 피아노 듀엣곡 주제들을 바탕으로, 힌데미트 특유의 신고전주의적 기법으로 화려하게 변주한 관현악곡이다.',NULL,1943,9,22,'https://open.spotify.com/album/0EYjK2A9adxwA4qqZOIEYs','https://music.apple.com/us/album/hindemith-symphonic-metamorphosis-of-themes-by-carl/1363575587',NULL,'2025-11-17 07:33:20','2025-11-18 07:46:36'),(402,106,'비올라 소나타 Op. 11, No. 4','Viola Sonata','album','비올리스트이기도 했던 힌데미트가 남긴 3개의 비올라 소나타 중 가장 유명한 작품. 20세기 비올라 레퍼토리의 핵심이다.','Op. 11, No. 4',1919,9,16,'https://open.spotify.com/album/5B5wmckkgMBpqxH3L7ywYi','https://music.apple.com/us/album/sonata-no-4-for-viola-and-piano-op-11-live-ep/1482235476',NULL,'2025-11-17 07:33:20','2025-11-18 12:06:30'),(403,107,'오페라 <카르멜회 수녀들의 대화>','Opera <Dialogues des Carmélites>','album','풀랑크의 가장 위대한 걸작 오페라. 프랑스 혁명 당시 순교를 택한 카르멜회 수녀들의 실화를 다룬다. 마지막 단두대 장면의 합창이 충격적이다.','FP 159',1956,10,150,'https://open.spotify.com/album/1wuDEkqo7hR06VieUrIGeB','https://music.apple.com/us/album/poulenc-dialogues-des-carm%C3%A9lites/691780508',NULL,'2025-11-17 07:33:20','2025-11-18 12:06:31'),(404,107,'글로리아','Gloria','album','소프라노 독창, 합창, 오케스트라를 위한 종교 음악. 20세기 합창 음악의 걸작 중 하나로, 경건함과 프랑스 특유의 재치가 공존한다.','FP 177',1959,9,25,'https://open.spotify.com/album/1fhxaF89VHijm8WnqV39Up','https://music.apple.com/us/album/poulenc-gloria-fp-177-stravinsky-symphony-of-psalms/1276457416',NULL,'2025-11-17 07:33:20','2025-11-18 12:06:32'),(405,107,'3개의 무궁동','Trois Mouvements Perpétuels','album','사티의 영향을 받은 풀랑크 초기의 피아노 소품. 단순하고 재치 있는 멜로디가 끝없이 반복되는(무궁동) 매력적인 곡이다.','FP 14',1918,6,5,'https://open.spotify.com/album/0vaXaRacgewajOyETlQOvK','https://music.apple.com/us/album/poulenc-piano-works/1452221892',NULL,'2025-11-17 07:33:20','2025-11-18 12:06:33'),(406,107,'플루트 소나타','Flute Sonata','album','20세기 플루트 소나타 중 가장 중요하고 많이 연주되는 작품. 플루트의 서정성과 풀랑크 특유의 경쾌함, 우수가 완벽하게 조화를 이룬다.','FP 164',1957,9,12,'https://open.spotify.com/album/3etZ2DNU9APxPIGoR7rfEP','https://music.apple.com/us/album/poulenc-flute-sonata/1207062896',NULL,'2025-11-17 07:33:20','2025-11-18 12:06:34'),(407,108,'소년의 노래','Gesang der Jünglinge','song','전자 음악의 역사에서 가장 중요한 작품. 소년의 변조된 목소리(구체 음악)와 순수 전자음(신시사이저)을 5개의 스피커로 결합시킨 최초의 \'공간 음악\'이다.','Nr. 8',1956,10,13,'https://open.spotify.com/track/0fOdc9YmphoSuJol5FPOaQ','https://music.apple.com/us/album/klavierst%C3%BCck-vii-nr-4/1412097909?i=1412099745',NULL,'2025-11-17 07:33:20','2025-11-18 12:06:35'),(408,108,'슈팀뭉','Stimmung','album','6명의 보컬 앙상블을 위한 \'명상 음악\'. 가수들은 낮은 \'시b\'음을 배음(Overtone) 기법으로 노래하며 신비로운 음향을 만들어낸다.','Nr. 24',1968,9,75,'https://open.spotify.com/album/3x7xEpUSk2U84Jb9M31vPI','https://music.apple.com/us/album/stockhausen-klavierst%C3%BCcke-beethoven-sonaten/990479962',NULL,'2025-11-17 07:33:20','2025-11-18 12:06:36'),(409,108,'헬리콥터 현악 4중주','Helikopter-Streichquartett (aus Mittwoch aus Licht)','album','오페라 <빛에서 온 수요일>의 3장. 4명의 현악 4중주단원이 각각 4대의 헬리콥터를 타고 상공에서 연주하며, 이 소리가 지상으로 전송되는 전위적인 작품이다.','Nr. 63',1993,10,32,'https://open.spotify.com/album/3x7xEpUSk2U84Jb9M31vPI','https://music.apple.com/us/album/stockhausen-klavierst%C3%BCcke-beethoven-sonaten/990479962',NULL,'2025-11-17 07:33:20','2025-11-18 07:46:53'),(410,109,'신포니아','Sinfonia','album','20세기 후반 \'포스트모더니즘\' 음악의 대표작. 8명의 목소리와 오케스트라를 위한 5악장 교향곡. 특히 3악장은 말러 교향곡 2번 위에 수많은 음악(바흐, 베토벤, 드뷔시 등)과 텍스트를 콜라주(Collage) 기법으로 덧붙였다.',NULL,1969,10,34,'https://open.spotify.com/album/0pjIOrvVw6NeQbxAmAlFJY','https://music.apple.com/us/album/berio-sinfonia-concerto-for-two-pianos/643899207',NULL,'2025-11-17 07:33:20','2025-11-18 07:46:55'),(411,109,'세쿠엔차 III (여성 솔로를 위한)','Sequenza III (for female voice)','song','독주 악기의 기교를 탐구한 14개의 <세쿠엔차> 연작 중 3번. 여성의 목소리가 낼 수 있는 모든 소리(웃음, 속삭임, 기침, 비명 등)를 극적으로 표현한 행위 예술적 작품이다.',NULL,1966,10,8,'https://open.spotify.com/track/6mRtWRd5breco5mYGOizzV','https://music.apple.com/us/album/sequenza-iii-for-female-voice-1966/152703569?i=152703626',NULL,'2025-11-17 07:33:20','2025-11-18 07:46:57'),(412,109,'포크 송즈 (민요)','Folk Songs','album','미국, 아르메니아, 프랑스, 이탈리아 등 전 세계의 민요 11곡을 메조소프라노와 실내악 앙상블을 위해 편곡한, 베리오의 가장 대중적인 작품집이다.',NULL,1964,7,22,'https://open.spotify.com/album/7evE0YiW6Z4kVanRhEpfp4','https://music.apple.com/us/album/folk-songs/1705310004',NULL,'2025-11-17 07:33:20','2025-11-18 07:46:59'),(413,110,'관현악을 위한 협주곡','Concerto for Orchestra','album','루토스와프스키의 초기 걸작이자 가장 유명한 작품. 버르토크의 동명 작품처럼, 폴란드 민요를 바탕으로 오케스트라의 모든 악기들이 화려한 기교를 뽐낸다.',NULL,1954,9,30,'https://open.spotify.com/album/5y9f8lxTXTzEkPjLyxLXPA','https://music.apple.com/us/album/lutos%C5%82awski-concerto-for-orchestra-jan%C3%A1%C4%8Dek-sinfonietta/1463603543',NULL,'2025-11-17 07:33:20','2025-11-18 07:47:01'),(414,110,'파가니니 주제에 의한 변주곡','Variations on a Theme by Paganini','song','파가니니 카프리스 24번을 주제로 한 두 대의 피아노를 위한 변주곡. 2차 대전 중 카페에서 연주하기 위해 작곡되었으며, 20세기 편곡의 걸작으로 꼽힌다.',NULL,1941,9,6,'https://open.spotify.com/track/0fyv7yxGxCvaeJPFevpHuG','https://music.apple.com/us/album/variations-on-a-theme-by-paganini/1063802146?i=1063802685',NULL,'2025-11-17 07:33:20','2025-11-18 07:47:03'),(415,110,'교향곡 3번','Symphony No. 3','album','작곡가 후기 \'제한된 우연성\' 기법이 집약된 걸작. 지휘자가 큰 틀만 제시하고 연주자가 세부 리듬을 즉흥적으로 연주하는 부분이 특징이다.',NULL,1983,10,32,'https://open.spotify.com/album/1sD5zrh53A4fewGOAUNiBO','https://music.apple.com/us/album/lutos%C5%82awski-symphony-no-3-chain-3-concerto-for-orchestra/1761699539',NULL,'2025-11-17 07:33:20','2025-11-18 07:47:05'),(416,111,'영화 <대부> 사운드트랙 (사랑의 테마)','The Godfather Soundtrack (Love Theme)','song','프랜시스 포드 코폴라 감독의 <대부> 3부작의 메인 테마. 시칠리아의 애수와 마피아의 비정함을 동시에 담아낸 불멸의 영화 음악이다.',NULL,1972,5,3,'https://open.spotify.com/track/0OJ0eNR9c53PkfXuwX3DJ0','https://music.apple.com/us/album/love-theme-from-the-godfather/1440844661?i=1440844677',NULL,'2025-11-17 07:33:20','2025-11-18 07:47:07'),(417,111,'영화 <로미오와 줄리엣 (1968)> 사운드트랙','Romeo and Juliet (1968) Soundtrack (A Time for Us)','album','프랑코 제피렐리 감독의 영화 <로미오와 줄리엣>의 메인 테마. \'A Time for Us\'라는 제목의 노래로도 유명하며, 낭만적인 멜로디의 극치를 보여준다.',NULL,1968,5,3,'https://open.spotify.com/album/0LoueoX2tw94FCWpZBqdWV','https://music.apple.com/us/album/romeo-juliet-original-1968-soundtrack/716314739',NULL,'2025-11-17 07:33:20','2025-11-18 07:47:09'),(418,111,'영화 <라 스트라다> 사운드트랙','La Strada Soundtrack','album','페데리코 펠리니 감독의 영화 <라 스트라다>의 주제곡. 트럼펫으로 연주되는 서글픈 멜로디가 영화의 페이소스를 완벽하게 대변한다.',NULL,1954,6,3,'https://open.spotify.com/album/3bM3ReC0nI7SZgpzUCHOlK','https://music.apple.com/us/album/fellini-rota-la-doce-vita/1657146455',NULL,'2025-11-17 07:33:20','2025-11-18 07:47:11'),(419,112,'영화 <사이코> 사운드트랙','Psycho Soundtrack','album','앨프리드 히치콕 감독의 <사이코>를 위해 현악 앙상블만으로 작곡한 혁신적인 음악. 샤워 장면의 \'칼 찌르는 소리(바이올린 글리산도)\'는 영화 음악의 전설이 되었다.',NULL,1960,8,30,'https://open.spotify.com/album/7hlFxhoaAWJ0WTRdgWURmb','https://music.apple.com/us/album/psycho-the-complete-original-motion-picture-score/1440795706',NULL,'2025-11-17 07:33:20','2025-11-18 07:47:13'),(420,112,'영화 <현기증> 사운드트랙','Vertigo Soundtrack','album','히치콕의 <현기증>을 위한 음악. 끊임없이 맴도는 듯한 아르페지오와 불안정한 화성을 통해 주인공의 현기증과 집착을 완벽하게 묘사했다.',NULL,1958,8,45,'https://open.spotify.com/album/1TbuwdZdsSuvfrL6YKozgU','https://music.apple.com/us/album/vertigo-original-motion-picture-soundtrack/1444008053',NULL,'2025-11-17 07:33:20','2025-11-18 07:47:15'),(421,112,'영화 <택시 드라이버> 사운드트랙','Taxi Driver Soundtrack','album','마틴 스콜세지 감독의 <택시 드라이버>를 위한 허먼의 유작. 재즈풍의 색소폰 솔로가 도시의 밤거리와 주인공의 고독, 광기를 표현한다.',NULL,1976,7,35,'https://open.spotify.com/album/0Su23YyUD0OyafVwOP22HP','https://music.apple.com/us/album/taxi-driver-original-soundtrack-recording/174892411',NULL,'2025-11-17 07:33:20','2025-11-18 07:47:17'),(422,113,'원색의 향연','Feast of Primary Colors (Wonssaegui Hyangyeon)','song','1966년 발표된 한국 최초의 전자 음악(Musique Concrète). 일상적인 소리(물방울, 기계음 등)를 녹음, 변조하여 작곡한 실험적인 작품이다.',NULL,1966,9,10,'https://open.spotify.com/track/0IOQeFJxurYc2oVmluRTSr',NULL,NULL,'2025-11-17 07:33:20','2025-11-18 07:47:19'),(423,113,'부루','Buru','song','플루트, 피아노, 타악기를 위한 실내악곡. 윤이상, 슈토크하우젠 등의 영향을 받은 한국 아방가르드 음악의 초기 대표작 중 하나이다.',NULL,1969,9,12,'https://open.spotify.com/track/6HPLmLtQx689u6gxvVjDDI',NULL,NULL,'2025-11-17 07:33:20','2025-11-18 07:47:22'),(424,114,'가곡 <달밤>','Gagok <Moonlit Night (Dalbam)>','song','나운영의 대표적인 예술 가곡. 김태오의 시에 곡을 붙였으며, 달밤의 서정을 한국적인 5음계 선율로 그려냈다.',NULL,1949,4,3,'https://open.spotify.com/track/1yfE8EiSe81szXR7hOBrvM',NULL,NULL,'2025-11-17 07:33:20','2025-11-18 07:47:24'),(425,114,'여호와는 나의 목자시니 (시편 23편)','Psalm 23 (Yeohowaneun Naui Mokjasini)','song','한국 교회 음악의 대표적인 성가곡. 시편 23편의 가사를 바탕으로 작곡되었으며, 4부 합창으로 널리 불린다.',NULL,1955,5,4,'https://open.spotify.com/track/7kuRvjpeUcn6qNV9IBXC2C',NULL,NULL,'2025-11-17 07:33:20','2025-11-18 07:47:26'),(426,115,'동요 <섬집 아기>','Children\'s Song <Island Home Baby (Seomjip Agi)>','song','한인현의 시에 곡을 붙인 동요. \'엄마가 섬 그늘에~\'로 시작하는 서정적이고 애상적인 멜로디는 동요를 넘어 전 국민의 애창곡이 되었다.',NULL,1951,2,2,'https://open.spotify.com/track/5ANZA5vkkW05xoEjY9pdJY',NULL,NULL,'2025-11-17 07:33:20','2025-11-18 07:47:28'),(427,115,'가곡 <바위고개>','Gagok <Rocky Hill Pass (Bawigogae)>','song','이흥렬의 대표적인 예술 가곡. 힘겨운 바위고개를 넘는 모습을 통해 민족의 한(恨)을 표현한 비장한 멜로디가 특징이다.',NULL,1933,5,3,'https://open.spotify.com/track/5r9K7uwvDMVXClR2zdNV0z',NULL,NULL,'2025-11-17 07:33:20','2025-11-18 07:47:30'),(428,115,'가곡 <어머니의 마음>','Gagok <A Mother\'s Heart (Eomeoni-ui Maeum)>','song','\'낳실제 괴로움 다 잊으시고\'로 시작하는, 어버이날을 상징하는 노래. 어머니의 희생적인 사랑을 그린 경건한 가곡이다.',NULL,1940,3,3,'https://open.spotify.com/track/1IMjL9r9q38DFpqbgCN7Mi',NULL,NULL,'2025-11-17 07:33:20','2025-11-18 07:47:32'),(429,116,'가곡 <선구자>','Gagok <The Pioneer (Seonguja)>','song','\'일송정 푸른 솔은~\'으로 시작하는, 조두남의 가장 유명한 가곡. 만주 벌판의 독립군을 그렸다고 알려졌으나, 작사/작곡 배경(친일)에 대한 논란이 있다.',NULL,1933,4,3,'https://open.spotify.com/track/3HIFsflH45wvMgHY4ctkSu',NULL,NULL,'2025-11-17 07:33:20','2025-11-18 07:47:34'),(430,116,'가곡 <그리움>','Gagok <Longing (Geurium)>','song','\'어느 때고 너를 보면~\'으로 시작하는 서정 가곡. 고향과 첫사랑을 그리워하는 애틋한 멜로디가 특징이다.',NULL,1932,4,3,'https://open.spotify.com/track/6CslgWAxtKAyzQIAgZJqP7',NULL,NULL,'2025-11-17 07:33:20','2025-11-18 07:47:36'),(431,4,'관현악 모음곡 3번 D장조 중 \"G선상의 아리아\"','Air on the G String (from Orchestral Suite No. 3)','song','바흐의 관현악 모음곡 3번의 2악장 \'에어(Air)\'를 바이올린의 가장 낮은 G현으로만 연주하도록 편곡한 버전이다. 고요하고 숭고한 선율이 특징이다.','BWV 1068',1730,4,5,'https://open.spotify.com/track/5HvvFm1YbJJrdS70qc62RS','https://music.apple.com/us/album/orchestral-suite-no-3-in-d-major-bwv-1068-ii-air/339006385?i=339006462',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(432,4,'칸타타 BWV 147 \"예수, 인류의 소망의 기쁨\"','Jesu, Joy of Man\'s Desiring (from Cantata BWV 147)','song','바흐의 교회 칸타타 중 가장 유명한 합창곡이다. 흐르는 듯한 셋잇단음표의 반주와 평온한 합창 선율이 어우러져 결혼식 축가로도 많이 쓰인다.','BWV 147',1723,5,4,'https://open.spotify.com/track/03A3gdRaL0yyVSCUSERxIZ','https://music.apple.com/us/album/bwv-147-jesu-joy-of-mans-desiring/1451741507?i=1451741510',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(433,6,'하프시코드 모음곡 4번 D단조 중 \"사라방드\"','Sarabande (from Keyboard Suite in D minor)','song','영화와 드라마의 비장한 장면에 자주 등장하는 곡이다. 장중하고 엄숙한 바로크 춤곡 리듬과 강렬한 화음 진행이 인상적이다.','HWV 437',1706,3,4,'https://open.spotify.com/track/1upQiytDIEZfl9ItruoXuC','https://music.apple.com/us/album/suite-no-11-in-d-minor-hwv-437-sarabande/1794093287?i=1794093489',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(434,14,'호른 협주곡 4번 E♭장조','Horn Concerto No. 4','song','모차르트의 호른 협주곡 중 가장 규모가 크고 유명하다. 사냥 나팔을 연상시키는 경쾌한 3악장 론도 주제가 널리 알려져 있다.','K. 495',1786,7,16,'https://open.spotify.com/track/6lahDdvnop8ywxGtohMVEm','https://music.apple.com/us/album/horn-concerto-in-e-flat-major-k-495-iii-rondo-allegro-vivace/1689787721?i=1689788002',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(435,14,'피아노 소나타 16번 C장조 \"쉬운 소나타\"','Piano Sonata No. 16 \"Sonata Facile\"','song','모차르트가 초심자를 위해 작곡한 소나타로, \'쉬운 소나타\'라는 부제가 붙었다. 맑고 순수한 1악장 도입부는 누구나 한 번쯤 들어본 멜로디다.','K. 545',1788,4,11,'https://open.spotify.com/track/3xhJSIp3yy7AjSrACgNamQ','https://music.apple.com/us/album/piano-sonata-no-16-in-c-major-k-545-sonata-facile-i-allegro/936874680?i=936874683',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(436,14,'\"아! 어머니께 말씀드리죠\" 주제에 의한 변주곡','Variations on \"Ah! vous dirai-je, maman\"','song','일명 \'반짝반짝 작은 별 변주곡\'이다. 프랑스 민요 주제를 바탕으로 12가지의 다양한 기교적 변주가 펼쳐지는 사랑스러운 곡이다.','K. 265',1781,6,12,'https://open.spotify.com/track/1sDjNUmPiffXaJrfnBaLcI','https://music.apple.com/us/album/12-variations-in-c-major-on-ah-vous-dirai-je-maman/1448483849?i=1448484743',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(437,15,'교향곡 6번 F장조 \"전원\"','Symphony No. 6 \"Pastoral\"','song','베토벤이 자연에서 느낀 감정을 묘사한 표제 음악이다. 시냇물 소리, 새소리, 폭풍우 등이 오케스트라로 생생하게 표현된다.','Op. 68',1808,9,40,'https://open.spotify.com/track/1WexuAvH2fbrBqpRo9YjJ1','https://music.apple.com/us/album/symphony-no-6-in-f-major-op-68-pastoral-ii-szene-am/1673773470?i=1673773473',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(438,15,'교향곡 7번 A장조','Symphony No. 7','song','바그너가 \'춤의 성역\'이라 극찬했을 만큼 리듬감이 돋보이는 곡이다. 장엄하고 신비로운 분위기의 2악장이 특히 대중적으로 유명하다.','Op. 92',1812,9,38,'https://open.spotify.com/track/6tVcdMbDua1aAop9Ex93pr','https://music.apple.com/us/album/symphony-no-7-in-a-major-op-92-ii-allegretto/1734466057?i=1734466059',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(439,15,'바이올린 소나타 5번 F장조 \"봄\"','Violin Sonata No. 5 \"Spring\"','song','베토벤의 바이올린 소나타 중 가장 화사하고 따뜻한 곡이다. 봄의 생동감 넘치는 기운이 느껴지는 아름다운 선율이 특징이다.','Op. 24',1801,7,24,'https://open.spotify.com/track/3XD6jtPylhzFW9dWoXK9NV','https://music.apple.com/us/album/violin-sonata-no-5-in-f-major-op-24-spring-ii-adagio/1497717383?i=1497717487',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(440,15,'피아노 소나타 23번 F단조 \"열정\"','Piano Sonata No. 23 \"Appassionata\"','song','베토벤 중기 소나타의 걸작으로, 격정적이고 폭풍 같은 감정이 휘몰아친다. 고도의 테크닉과 강인한 타건이 요구된다.','Op. 57',1805,9,23,'https://open.spotify.com/track/4YVdlDcS7eK5CVhep29vnd','https://music.apple.com/us/album/sonata-no-23-in-f-minor-op-57-appassionata/433264289?i=433264319',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(441,15,'피아노 3중주 7번 B♭장조 \"대공\"','Piano Trio No. 7 \"Archduke\"','song','베토벤이 후원자인 루돌프 대공에게 헌정한 곡이다. 피아노 3중주 역사상 가장 웅장하고 기품 있는 명작으로 꼽힌다.','Op. 97',1811,8,40,'https://open.spotify.com/track/2tTGcRH0xsIOulHZxBlf3J','https://music.apple.com/us/album/piano-trio-no-7-in-b-flat-major-op-97-archduke-iii/1725363052?i=1725363449',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(442,20,'현악 5중주 E장조 중 \"미뉴에트\"','Minuet (from String Quintet in E major)','song','보케리니의 작품 중 가장 유명한 곡이다. 우아하고 귀족적인 로코코 양식의 전형을 보여주며, 섬세한 현악기의 떨림이 아름답다.','Op. 11 No. 5',1771,4,4,'https://open.spotify.com/track/6e85fziCk6MwZUxWyG6Ijm','https://music.apple.com/us/album/string-quintet-in-e-major-op-11-no-5-g-275-iii-minuet/339006385?i=339006517',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(443,26,'가곡 \"아베 마리아\" (엘렌의 노래 3번)','Ave Maria (Ellens dritter Gesang)','song','슈베르트가 발터 스콧의 서사시를 바탕으로 작곡한 가곡이다. 경건하고 아름다운 선율 덕분에 종교적인 맥락에서도 자주 연주된다.','D. 839',1825,5,6,'https://open.spotify.com/track/00nLUlINJ71I4mCHXsy2JI','https://music.apple.com/us/album/ave-maria-d-839-arr-for-guitar-by-xuefei-yang/1712747782?i=1712747786',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(444,26,'악흥의 순간 3번 F단조','Moments Musicaux No. 3','song','슈베르트의 짧은 피아노 소품 중 가장 사랑받는 곡이다. 경쾌한 반주 위에 얹힌 소박하고 민요적인 멜로디가 매력적이다.','D. 780',1823,5,2,'https://open.spotify.com/track/5CaZmCgT5j4QQSSlgh68Fs','https://music.apple.com/us/album/moments-musicaux-d-780-iii-allegro-moderato/1554894490?i=1554894501',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(445,28,'녹턴 20번 C#단조 (유작)','Nocturne No. 20 in C-sharp minor','song','쇼팽 사후에 출판된 곡으로, 영화 \'피아니스트\'의 주제곡으로 유명하다. 애절하고 슬픈 멜로디가 심금을 울린다.','B. 49',1830,6,4,'https://open.spotify.com/track/2tOQMjJHmDDnEVqBjeEU1X','https://music.apple.com/us/album/nocturne-no-20-in-c-sharp-minor-b-49-arr-for-cello/1589042452?i=1589043126',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(446,28,'전주곡 15번 D♭장조 \"빗방울\"','Prelude Op. 28 No. 15 \"Raindrop\"','song','쇼팽의 전주곡 중 가장 긴 곡이다. 곡 전반에 걸쳐 반복되는 A♭음이 마치 처마 끝에 떨어지는 빗방울 소리를 연상시킨다.','Op. 28 No. 15',1838,5,5,'https://open.spotify.com/track/6pYMPUhrAtpm219wfdl40w','https://music.apple.com/us/album/preludes-op-28-no-4-in-e-minor-largo/1764844357?i=1764844464',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(447,28,'연습곡 Op. 10, No. 3 \"이별의 곡\"','Etude Op. 10 No. 3 \"Tristesse\"','song','쇼팽 스스로 \'이보다 아름다운 선율을 써본 적이 없다\'고 말한 곡이다. 서정적인 멜로디와 대조적인 격정적 중반부가 특징이다.','Op. 10 No. 3',1830,8,4,'https://open.spotify.com/track/4rf4g3MiC9N9F72img05CF','https://music.apple.com/us/album/etude-op-10-no-3-tristesse-in-e-major/346460845?i=346460883',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(448,29,'피아노 5중주 E♭장조','Piano Quintet in E-flat major','song','슈만의 실내악 중 최고 걸작으로 꼽힌다. 피아노와 현악 4중주의 조화가 완벽하며, 낭만적인 열정과 에너지가 넘친다.','Op. 44',1842,8,30,'https://open.spotify.com/track/1xeNlRwv278r9r54kIPL5K','https://music.apple.com/us/album/piano-quintet-in-e-flat-major-op-44-ii-in-modo-duna/1727073366?i=1727073375',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(449,27,'피아노 3중주 1번 D단조','Piano Trio No. 1 in D minor','song','멘델스존 특유의 유려한 선율과 균형 잡힌 형식이 돋보이는 곡이다. 특히 첼로가 연주하는 1악장의 서정적인 주제가 유명하다.','Op. 49',1839,8,28,'https://open.spotify.com/track/3sKfUcPjB2cQoeF0mOu4Dn','https://music.apple.com/us/album/piano-trio-no-1-in-d-minor-op-49-ii-andante-con-moto-tranquillo/1760589995?i=1760590001',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(450,30,'피아노 협주곡 1번 E♭장조','Piano Concerto No. 1','song','리스트의 화려한 기교가 집약된 협주곡이다. 오케스트라에 트라이앵글을 적극적으로 사용하여 \'트라이앵글 협주곡\'이라는 별명도 있다.','S. 124',1849,9,19,'https://open.spotify.com/track/5yzujBWo2YHklgIxtDRFYu','https://music.apple.com/us/album/piano-concerto-no-1-in-e-flat-s-124-1-allegro-maestoso/1452578860?i=1452578947',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(451,33,'자장가','Lullaby (Wiegenlied)','song','전 세계에서 가장 유명한 자장가 선율이다. 브람스가 친구의 아이를 위해 작곡했으며, 소박하고 따뜻한 감성이 묻어난다.','Op. 49 No. 4',1868,3,2,'https://open.spotify.com/track/59cPOVxrn3Yjwydl1pullI','https://music.apple.com/us/album/wiegenlied-op-49-no-4-lullaby-arr-for-cello-and-piano/1009467298?i=1009467584',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(452,33,'교향곡 4번 E단조','Symphony No. 4','song','브람스의 마지막 교향곡으로, 고전적인 형식미와 낭만적인 비극성이 결합된 걸작이다. 바로크 양식인 파사칼리아를 도입한 4악장이 압권이다.','Op. 98',1885,10,40,'https://open.spotify.com/track/6xVrx5YZpcdNMtME9TArF2','https://music.apple.com/us/album/symphony-no-4-in-e-minor-op-98-i-allegro-non-troppo/1618345305?i=1618345307',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(453,34,'교향곡 5번 E단조','Symphony No. 5','song','차이콥스키의 교향곡 중 대중적으로 가장 인기 있는 곡이다. 운명에 대한 투쟁과 승리를 묘사하며, 2악장의 호른 솔로가 매우 아름답다.','Op. 64',1888,9,46,'https://open.spotify.com/track/7MrRFi6swb5Jwef9esaJIF','https://music.apple.com/us/album/violin-concerto-in-e-minor-op-64-ii-andante/489213640?i=489213703',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(454,34,'현을 위한 세레나데 C장조','Serenade for Strings','song','차이콥스키가 모차르트를 동경하며 작곡한 곡이다. 우아한 왈츠 악장과 현악기들의 풍성한 울림이 돋보이는 명곡이다.','Op. 48',1880,7,30,'https://open.spotify.com/track/7uf3aFC1msj0t5cYImgOWy','https://music.apple.com/us/album/serenade-for-strings-in-c-major-op-48-th-48-%C4%8Dw-45-iii/1504284843?i=1504285252',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(455,51,'전주곡 G단조','Prelude in G minor','song','라흐마니노프의 피아노 곡 중 가장 널리 알려진 곡 중 하나다. 행진곡 풍의 강렬한 리듬과 서정적인 중간부의 대비가 훌륭하다.','Op. 23 No. 5',1901,8,4,'https://open.spotify.com/track/4RUKTGXjyRM3wdksLgC6Ca','https://music.apple.com/us/album/pr%C3%A9lude-in-g-minor-op-23-no-5/1440566024?i=1440566050',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(456,50,'꿈','Rêverie','song','드뷔시 초기의 피아노 소품으로, 제목처럼 꿈을 꾸는 듯한 몽환적이고 부드러운 분위기의 곡이다.','L. 68',1890,5,4,'https://open.spotify.com/track/43bSKCMWHIuBsUVmQcDX1J','https://music.apple.com/us/album/r%C3%AAverie-l-68/1411407226?i=1411407249',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(457,52,'치건','Tzigane','song','라벨이 헝가리 집시 음악(치건) 스타일을 차용해 만든 바이올린 곡이다. 바이올리니스트에게 최고의 기교를 요구하는 화려한 난곡이다.','M. 76',1924,10,10,'https://open.spotify.com/track/4ZmV6IRdDOxtNUrDPBi2I7','https://music.apple.com/us/album/pavane-pour-une-infante-d%C3%A9funte-m-19/1068269518?i=1068269726',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(458,83,'피아노 협주곡 2번 F장조','Piano Concerto No. 2','song','쇼스타코비치가 아들의 생일 선물로 작곡한 밝고 경쾌한 곡이다. 디즈니 영화 \'환타지아 2000\'에 사용되어 더욱 유명해졌다.','Op. 102',1957,7,20,'https://open.spotify.com/track/7faWy3kAy0GkTqAzkUBhCf','https://music.apple.com/us/album/piano-concerto-no-2-in-f-major-op-102-ii-andante/1393946030?i=1393947336',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(459,64,'현을 위한 세레나데 E단조','Serenade for Strings','song','엘가의 초기 대표작으로, 영국적인 기품과 서정성이 가득하다. 부드럽고 따뜻한 현악기의 조화가 마음을 편안하게 해준다.','Op. 20',1892,6,12,'https://open.spotify.com/track/0CBGGSrDeV04sypyBI7vcB','https://music.apple.com/us/album/piano-sonatina-in-c-major-op-20-no-1-ii-andante/1481992380?i=1481993696',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53'),(460,103,'신아리랑','Sin-Arirang (New Arirang)','song','한국의 대표 민요 아리랑을 현대적인 가곡 형식으로 재해석한 곡이다. 피아노 반주와 어우러진 한국적인 정서와 웅장함이 특징이다.','N/A',1930,5,4,'https://open.spotify.com/track/3IZJsbyWEA3eY1ojEIibtH','https://music.apple.com/us/album/forgot-about-dre-feat-eminem/1440782221?i=1440783376',NULL,'2025-11-26 08:32:53','2025-11-26 08:32:53');
