DROP TABLE IF EXISTS `popular_comparisons`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `popular_comparisons` (
  `id` int NOT NULL AUTO_INCREMENT,
  `piece_id` int NOT NULL,
  `comparison_title` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '비교 제목 (예: 아르헤리치 vs 임윤찬)',
  `view_count` int DEFAULT '0' COMMENT '조회수',
  `is_featured` tinyint(1) DEFAULT '0' COMMENT '메인 노출 여부',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `piece_id` (`piece_id`),
  KEY `idx_view_count` (`view_count`),
  KEY `idx_featured` (`is_featured`),
  CONSTRAINT `popular_comparisons_ibfk_1` FOREIGN KEY (`piece_id`) REFERENCES `pieces` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

