--
-- Table structure for table `recordings`
--

DROP TABLE IF EXISTS `recordings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `recordings` (
  `id` int NOT NULL AUTO_INCREMENT,
  `artist_id` int NOT NULL,
  `title` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '음반 제목',
  `year` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '발매 연도 (레거시, release_date 권장)',
  `release_date` date DEFAULT NULL COMMENT '발매일',
  `label` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '레이블',
  `cover_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '커버 이미지 URL',
  `upc` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Universal Product Code',
  `apple_music_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Apple Music 앨범 ID',
  `track_count` int DEFAULT NULL COMMENT '트랙 수',
  `is_single` tinyint(1) DEFAULT '0' COMMENT '싱글 여부',
  `is_compilation` tinyint(1) DEFAULT '0' COMMENT '컴필레이션 여부',
  `genre_names` json DEFAULT NULL COMMENT '장르 목록',
  `copyright` text COLLATE utf8mb4_unicode_ci COMMENT '저작권 정보',
  `editorial_notes` text COLLATE utf8mb4_unicode_ci COMMENT '앨범 설명',
  `artwork_width` int DEFAULT NULL COMMENT '아트워크 너비',
  `artwork_height` int DEFAULT NULL COMMENT '아트워크 높이',
  `spotify_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Spotify 링크',
  `apple_music_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Apple Music 링크',
  `youtube_music_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'YouTube Music 링크',
  `external_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '기타 외부 링크',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_artist_id` (`artist_id`),
  KEY `idx_year` (`year`),
  KEY `idx_release_date` (`release_date`),
  KEY `idx_apple_music_id` (`apple_music_id`),
  KEY `idx_upc` (`upc`),
  CONSTRAINT `recordings_ibfk_1` FOREIGN KEY (`artist_id`) REFERENCES `artists` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9023 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

