/*!50001 CREATE ALGORITHM=UNDEFINED */
/*!50013 DEFINER=`root`@`%` SQL SECURITY DEFINER */
/*!50001 VIEW `v_artists_full` AS select `a`.`id` AS `id`,`a`.`name` AS `name`,`a`.`english_name` AS `english_name`,`a`.`category` AS `category`,`a`.`tier` AS `tier`,`a`.`rating` AS `rating`,`a`.`image_url` AS `image_url`,`a`.`cover_image_url` AS `cover_image_url`,`a`.`birth_year` AS `birth_year`,`a`.`nationality` AS `nationality`,`a`.`bio` AS `bio`,`a`.`style` AS `style`,`a`.`concert_count` AS `concert_count`,`a`.`album_count` AS `album_count`,`a`.`top_award_id` AS `top_award_id`,`a`.`created_at` AS `created_at`,`a`.`updated_at` AS `updated_at`,group_concat(distinct concat(`aw`.`year`,':',`aw`.`award_name`) order by `aw`.`display_order` ASC separator '|') AS `awards`,`top_aw`.`award_name` AS `top_award_name`,`top_aw`.`year` AS `top_award_year`,`top_aw`.`ranking` AS `top_award_ranking` from ((`artists` `a` left join `artist_awards` `aw` on((`a`.`id` = `aw`.`artist_id`))) left join `artist_awards` `top_aw` on((`a`.`top_award_id` = `top_aw`.`id`))) group by `a`.`id` */;
